export const HIZB = [{"manzil":1,"day":"Saturday","dayAr":"يوم السبت","duas":[{"n":1,"ar":"أَعُوذُ بِاللّٰهِ مِنَ الشَّيْطٰنِ الرَّجِيمِ. بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيمِ ۝ اَلْحَمْدُ لِلّٰهِ رَبِّ الْعٰلَمِينَ ۝ الرَّحْمٰنِ الرَّحِيمِ ۝ مٰلِكِ يَوْمِ الدِّينِ ۝ إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ۝ اِهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ ۝ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ ۝ آمِينَ.","tr":"A'udhu billahi minash-shaytanir-rajim. Bismillahir-rahmanir-rahim. Al-hamdu lillahi rabbil-'alamin. Ar-rahmanir-rahim. Maliki yawmid-din. Iyyaka na'budu wa iyyaka nasta'in. Ihdinas-siratal-mustaqim. Siratal-ladhina an'amta 'alayhim, ghayril-maghdubi 'alayhim wa lad-dallin. Amin.","en":"I seek refuge in Allah from Satan, the outcast. Then: Qurʾān translation from Pickthall. \"Āmīn\" means \"O Allah, accept.\"","ref":"al-Fātiḥa 1:1–7, preceded by the taʿawwudh and followed by \"Āmīn\"","q":null,"source":"ʿAbd al-Razzaq (Musannaf), Ibn al-Mundhir (for the taʿawwudh); al-Daylami (for the Fatiha with Āmīn)","page":"pp. 16–17","status":"draft"},
{"n":2,"ar":"أَعُوذُ بِاللّٰهِ أَنْ أَكُونَ مِنَ الْجٰهِلِينَ.","tr":"A'udhu billahi an akuna minal-jahilin.","en":"Qurʾān translation from Pickthall","ref":"al-Baqara 2:67 (only Musa's words)","q":null,"source":null,"page":"p. 17","status":"draft"},
{"n":3,"ar":"رَبَّنَا تَقَبَّلْ مِنَّا إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ، وَتُبْ عَلَيْنَا إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ.","tr":"Rabbana taqabbal minna innaka antas-sami'ul-'alim, wa tub 'alayna innaka antat-tawwabur-rahim.","en":"Qurʾān translation from Pickthall","ref":"al-Baqara 2:127 (end) and 2:128 (end)","q":null,"source":"al-Daraqutni","page":"p. 17","status":"draft"},
{"n":4,"ar":"رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَّفِي الْآخِرَةِ حَسَنَةً وَّقِنَا عَذَابَ النَّارِ.","tr":"Rabbana atina fid-dunya hasanatan wa fil-akhirati hasanatan wa qina 'adhaban-nar.","en":"Qurʾān translation from Pickthall","ref":"al-Baqara 2:201 (from رَبَّنَا)","q":null,"source":"Ibn Abi Shayba, Bukhari, Muslim, Abu Dawud, Nasaʾi, Abu Yaʿla, and others","page":"p. 17","status":"draft"},
{"n":5,"ar":"رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا وَّثَبِّتْ أَقْدَامَنَا وَانْصُرْنَا عَلَى الْقَوْمِ الْكٰفِرِينَ.","tr":"Rabbana afrigh 'alayna sabran wa thabbit aqdamana wansurna 'alal-qawmil-kafirin.","en":"Qurʾān translation from Pickthall","ref":"al-Baqara 2:250 (from رَبَّنَا)","q":null,"source":null,"page":"p. 18","status":"draft"},
{"n":6,"ar":"سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ.","tr":"Sami'na wa ata'na ghufranaka rabbana wa ilaykal-masir.","en":"Qurʾān translation from Pickthall","ref":"al-Baqara 2:285 (part)","q":null,"source":"Ahmad, Muslim, Tirmidhi, Nasaʾi, and the tafsir collections","page":"p. 18","status":"draft"},
{"n":7,"ar":"رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَّسِينَا أَوْ أَخْطَأْنَا، رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا، رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ، وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا، أَنْتَ مَوْلٰىنَا فَانْصُرْنَا عَلَى الْقَوْمِ الْكٰفِرِينَ.","tr":"Rabbana la tu'akhidhna in nasina aw akhta'na. Rabbana wa la tahmil 'alayna isran kama hamaltahu 'alal-ladhina min qablina. Rabbana wa la tuhammilna ma la taqata lana bih. Wa'fu 'anna waghfir lana warhamna, anta mawlana fansurna 'alal-qawmil-kafirin.","en":"Qurʾān translation from Pickthall","ref":"al-Baqara 2:286 (from رَبَّنَا لَا تُؤَاخِذْنَا to the end of the verse)","q":null,"source":"Nomani's footnote to no. 6 covers this passage too (the same hadith). Nomani gives no separate footnote.","page":"pp. 18–19","status":"draft"},
{"n":8,"ar":"رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَّدُنْكَ رَحْمَةً إِنَّكَ أَنْتَ الْوَهَّابُ.","tr":"Rabbana la tuzigh qulubana ba'da idh hadaytana wa hab lana min ladunka rahmah, innaka antal-wahhab.","en":"Qurʾān translation from Pickthall","ref":"Āl ʿImrān 3:8","q":{"s":3,"from":8,"to":8},"source":"Ibn Jarir, Ibn Abi Hatim; Ibn Abi Shayba, Ahmad, Tirmidhi, Tabarani; Abu Dawud, Nasaʾi","page":"p. 19","status":"draft"},
{"n":9,"ar":"رَبَّنَا إِنَّكَ جَامِعُ النَّاسِ لِيَوْمٍ لَّا رَيْبَ فِيهِ، إِنَّ اللّٰهَ لَا يُخْلِفُ الْمِيعَادَ.","tr":"Rabbana innaka jami'un-nasi li-yawmin la rayba fih, innallaha la yukhliful-mi'ad.","en":"Qurʾān translation from Pickthall","ref":"Āl ʿImrān 3:9","q":{"s":3,"from":9,"to":9},"source":"Ibn al-Najjar (Tarikh)","page":"p. 19","status":"draft"},
{"n":10,"ar":"رَبَّنَا إِنَّنَا آمَنَّا فَاغْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ النَّارِ.","tr":"Rabbana innana amanna faghfir lana dhunubana wa qina 'adhaban-nar.","en":"Qurʾān translation from Pickthall","ref":"Āl ʿImrān 3:16 (from رَبَّنَا)","q":null,"source":null,"page":"p. 20","status":"draft"},
{"n":11,"ar":"قُلِ اللّٰهُمَّ مٰلِكَ الْمُلْكِ تُؤْتِي الْمُلْكَ مَنْ تَشَاءُ وَتَنْزِعُ الْمُلْكَ مِمَّنْ تَشَاءُ، وَتُعِزُّ مَنْ تَشَاءُ وَتُذِلُّ مَنْ تَشَاءُ، بِيَدِكَ الْخَيْرُ، إِنَّكَ عَلٰى كُلِّ شَيْءٍ قَدِيرٌ ۝ تُولِجُ اللَّيْلَ فِي النَّهَارِ وَتُولِجُ النَّهَارَ فِي اللَّيْلِ، وَتُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَتُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ، وَتَرْزُقُ مَنْ تَشَاءُ بِغَيْرِ حِسَابٍ.","tr":"Qulil-lahumma malikal-mulki tu'til-mulka man tasha'u wa tanzi'ul-mulka mimman tasha', wa tu'izzu man tasha'u wa tudhillu man tasha', biyadikal-khayr, innaka 'ala kulli shay'in qadir. Tulijul-layla fin-nahari wa tulijun-nahara fil-layl, wa tukhrijul-hayya minal-mayyiti wa tukhrijul-mayyita minal-hayy, wa tarzuqu man tasha'u bighayri hisab.","en":"Qurʾān translation from Pickthall","ref":"Āl ʿImrān 3:26–27","q":{"s":3,"from":26,"to":27},"source":"ʿAbd b. Humayd, Ibn Jarir, Ibn Abi Hatim; Ibn al-Mundhir; Tabarani; Ibn Abi al-Dunya","page":"p. 20","status":"draft"},
{"n":12,"ar":"رَبِّ هَبْ لِي مِنْ لَّدُنْكَ ذُرِّيَّةً طَيِّبَةً، إِنَّكَ سَمِيعُ الدُّعَاءِ.","tr":"Rabbi hab li min ladunka dhurriyyatan tayyibah, innaka sami'ud-du'a'.","en":"Qurʾān translation from Pickthall","ref":"Āl ʿImrān 3:38 (Zakariyya's words)","q":null,"source":"Ishaq b. Bishr, Ibn ʿAsakir","page":"p. 21","status":"draft"},
{"n":13,"ar":"رَبَّنَا آمَنَّا بِمَا أَنْزَلْتَ وَاتَّبَعْنَا الرَّسُولَ فَاكْتُبْنَا مَعَ الشّٰهِدِينَ.","tr":"Rabbana amanna bima anzalta wattaba'nar-rasula faktubna ma'ash-shahidin.","en":"Qurʾān translation from Pickthall","ref":"Āl ʿImrān 3:53","q":{"s":3,"from":53,"to":53},"source":"Ibn Mardawayh (reading uncertain: see the uncertain readings)","page":"p. 21","status":"draft"},
{"n":14,"ar":"رَبَّنَا اغْفِرْ لَنَا ذُنُوبَنَا وَإِسْرَافَنَا فِي أَمْرِنَا وَثَبِّتْ أَقْدَامَنَا وَانْصُرْنَا عَلَى الْقَوْمِ الْكٰفِرِينَ.","tr":"Rabbanagh-fir lana dhunubana wa israfana fi amrina wa thabbit aqdamana wansurna 'alal-qawmil-kafirin.","en":"Qurʾān translation from Pickthall","ref":"Āl ʿImrān 3:147 (from رَبَّنَا)","q":null,"source":null,"page":"p. 21","status":"draft"},
{"n":15,"ar":"رَبَّنَا مَا خَلَقْتَ هٰذَا بَاطِلًا، سُبْحٰنَكَ فَقِنَا عَذَابَ النَّارِ.","tr":"Rabbana ma khalaqta hadha batila, subhanaka faqina 'adhaban-nar.","en":"Qurʾān translation from Pickthall","ref":"Āl ʿImrān 3:191 (from رَبَّنَا; the verse begins الَّذِينَ يَذْكُرُونَ اللّٰهَ…)","q":null,"source":"Bukhari, Muslim, Abu Dawud, Nasaʾi, Ibn Majah, Bayhaqi (reciting the last verses of Āl ʿImrān at night); also Ibn Abi Shayba and Ibn al-Sunni. The footnote covers nos. 15–18.","page":"p. 21","status":"draft"},
{"n":16,"ar":"رَبَّنَا إِنَّكَ مَنْ تُدْخِلِ النَّارَ فَقَدْ أَخْزَيْتَهُ، وَمَا لِلظّٰلِمِينَ مِنْ أَنْصَارٍ.","tr":"Rabbana innaka man tudkhilin-nara faqad akhzaytah, wa ma lidh-dhalimina min ansar.","en":"Qurʾān translation from Pickthall","ref":"Āl ʿImrān 3:192","q":{"s":3,"from":192,"to":192},"source":"see no. 15","page":"p. 22","status":"draft"},
{"n":17,"ar":"رَبَّنَا إِنَّنَا سَمِعْنَا مُنَادِيًا يُّنَادِي لِلْإِيمَانِ أَنْ آمِنُوا بِرَبِّكُمْ فَآمَنَّا، رَبَّنَا فَاغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّئَاتِنَا وَتَوَفَّنَا مَعَ الْأَبْرَارِ.","tr":"Rabbana innana sami'na munadiyan yunadi lil-imani an aminu birabbikum fa-amanna. Rabbana faghfir lana dhunubana wa kaffir 'anna sayyi'atina wa tawaffana ma'al-abrar.","en":"Qurʾān translation from Pickthall","ref":"Āl ʿImrān 3:193","q":{"s":3,"from":193,"to":193},"source":"see no. 15","page":"p. 22","status":"draft"},
{"n":18,"ar":"رَبَّنَا وَآتِنَا مَا وَعَدْتَّنَا عَلٰى رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ الْقِيٰمَةِ، إِنَّكَ لَا تُخْلِفُ الْمِيعَادَ.","tr":"Rabbana wa atina ma wa'adtana 'ala rusulika wa la tukhzina yawmal-qiyamah, innaka la tukhliful-mi'ad.","en":"Qurʾān translation from Pickthall","ref":"Āl ʿImrān 3:194","q":{"s":3,"from":194,"to":194},"source":"see no. 15","page":"p. 22","status":"draft"},
{"n":19,"ar":"رَبَّنَا أَخْرِجْنَا مِنْ هٰذِهِ الْقَرْيَةِ الظَّالِمِ أَهْلُهَا، وَاجْعَلْ لَّنَا مِنْ لَّدُنْكَ وَلِيًّا، وَاجْعَلْ لَّنَا مِنْ لَّدُنْكَ نَصِيرًا.","tr":"Rabbana akhrijna min hadhihil-qaryatidh-dhalimi ahluha, waj'al lana min ladunka waliyya, waj'al lana min ladunka nasira.","en":"Qurʾān translation from Pickthall","ref":"al-Nisāʾ 4:75 (from رَبَّنَا)","q":null,"source":null,"page":"p. 22","status":"draft"},
{"n":20,"ar":"رَبَّنَا أَنْزِلْ عَلَيْنَا مَائِدَةً مِّنَ السَّمَاءِ تَكُونُ لَنَا عِيدًا لِّأَوَّلِنَا وَآخِرِنَا وَآيَةً مِّنْكَ، وَارْزُقْنَا وَأَنْتَ خَيْرُ الرّٰزِقِينَ.","tr":"Rabbana anzil 'alayna ma'idatan minas-sama'i takunu lana 'idan li-awwalina wa akhirina wa ayatan mink, warzuqna wa anta khayrur-raziqin.","en":"Qurʾān translation from Pickthall","ref":"al-Māʾida 5:114 (part). The mushaf has «اللّٰهُمَّ رَبَّنَا أَنْزِلْ…». Nomani, like Dawud, starts at «رَبَّنَا».","q":null,"source":"— (Nomani adds a short note of his own here. It is not a source citation.)","page":"p. 23","status":"draft"},
{"n":21,"ar":"رَبَّنَا آمَنَّا فَاكْتُبْنَا مَعَ الشّٰهِدِينَ ۝ وَنَطْمَعُ أَنْ يُّدْخِلَنَا رَبُّنَا مَعَ الْقَوْمِ الصّٰلِحِينَ.","tr":"Rabbana amanna faktubna ma'ash-shahidin. Wa natma'u an yudkhilana rabbuna ma'al-qawmis-salihin.","en":"Qurʾān translation from Pickthall","ref":"al-Māʾida 5:83 (end) and 5:84 (end). The middle of 5:84 («وَمَا لَنَا لَا نُؤْمِنُ بِاللّٰهِ وَمَا جَاءَنَا مِنَ الْحَقِّ») is left out. Note that this comes after 5:114 in Nomani, and Dawud has the same order.","q":null,"source":null,"page":"p. 23","status":"draft"},
{"n":22,"ar":"رَبَّنَا لَا تَجْعَلْنَا مَعَ الْقَوْمِ الظّٰلِمِينَ ۝ أَنْتَ وَلِيُّنَا فَاغْفِرْ لَنَا وَارْحَمْنَا وَأَنْتَ خَيْرُ الْغٰفِرِينَ ۝ وَاكْتُبْ لَنَا فِي هٰذِهِ الدُّنْيَا حَسَنَةً وَّفِي الْآخِرَةِ إِنَّا هُدْنَا إِلَيْكَ.","tr":"Rabbana la taj'alna ma'al-qawmidh-dhalimin. Anta waliyyuna faghfir lana warhamna wa anta khayrul-ghafirin. Waktub lana fi hadhihid-dunya hasanatan wa fil-akhirati inna hudna ilayk.","en":"Qurʾān translation from Pickthall","ref":"al-Aʿrāf 7:47 (end); 7:155 (end); 7:156 (beginning, up to إِلَيْكَ)","q":null,"source":null,"page":"p. 23","status":"draft"},
{"n":23,"ar":"رَبَّنَا إِنَّكَ تَعْلَمُ مَا نُخْفِي وَمَا نُعْلِنُ، وَمَا يَخْفٰى عَلَى اللّٰهِ مِنْ شَيْءٍ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ.","tr":"Rabbana innaka ta'lamu ma nukhfi wa ma nu'lin, wa ma yakhfa 'alallahi min shay'in fil-ardi wa la fis-sama'.","en":"Qurʾān translation from Pickthall","ref":"Ibrāhīm 14:38. Placed here, out of mushaf order, in both Nomani and Dawud.","q":null,"source":null,"page":"p. 23","status":"draft"},
{"n":24,"ar":"رَبَّنَا ظَلَمْنَا أَنْفُسَنَا، وَإِنْ لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخٰسِرِينَ.","tr":"Rabbana dhalamna anfusana, wa in lam taghfir lana wa tarhamna lanakunanna minal-khasirin.","en":"Qurʾān translation from Pickthall","ref":"al-Aʿrāf 7:23","q":{"s":7,"from":23,"to":23},"source":null,"page":"p. 23","status":"draft"},
{"n":25,"ar":"رَبَّنَا افْتَحْ بَيْنَنَا وَبَيْنَ قَوْمِنَا بِالْحَقِّ وَأَنْتَ خَيْرُ الْفٰتِحِينَ.","tr":"Rabbanaf-tah baynana wa bayna qawmina bil-haqqi wa anta khayrul-fatihin.","en":"Qurʾān translation from Pickthall","ref":"al-Aʿrāf 7:89 (end)","q":null,"source":null,"page":"p. 23","status":"draft"},
{"n":26,"ar":"رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا وَّتَوَفَّنَا مُسْلِمِينَ.","tr":"Rabbana afrigh 'alayna sabran wa tawaffana muslimin.","en":"Qurʾān translation from Pickthall","ref":"al-Aʿrāf 7:126 (end)","q":null,"source":null,"page":"p. 23","status":"draft"},
{"n":27,"ar":"رَبِّ اغْفِرْ لِي وَلِأَخِي وَأَدْخِلْنَا فِي رَحْمَتِكَ، وَأَنْتَ أَرْحَمُ الرّٰحِمِينَ.","tr":"Rabbigh-fir li wa li-akhi wa adkhilna fi rahmatik, wa anta arhamur-rahimin.","en":"Qurʾān translation from Pickthall","ref":"al-Aʿrāf 7:151","q":{"s":7,"from":151,"to":151},"source":null,"page":"p. 24","status":"draft"},
{"n":28,"ar":"عَلَى اللّٰهِ تَوَكَّلْنَا، رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلْقَوْمِ الظّٰلِمِينَ ۝ وَنَجِّنَا بِرَحْمَتِكَ مِنَ الْقَوْمِ الْكٰفِرِينَ.","tr":"'Alallahi tawakkalna, rabbana la taj'alna fitnatan lil-qawmidh-dhalimin. Wa najjina birahmatika minal-qawmil-kafirin.","en":"Qurʾān translation from Pickthall","ref":"Yūnus 10:85–86","q":{"s":10,"from":85,"to":86},"source":null,"page":"p. 24","status":"draft"},
{"n":29,"ar":"رَبِّ إِنِّي أَعُوذُ بِكَ أَنْ أَسْأَلَكَ مَا لَيْسَ لِي بِهِ عِلْمٌ، وَإِلَّا تَغْفِرْ لِي وَتَرْحَمْنِي أَكُنْ مِّنَ الْخٰسِرِينَ.","tr":"Rabbi inni a'udhu bika an as'alaka ma laysa li bihi 'ilm, wa illa taghfir li wa tarhamni akun minal-khasirin.","en":"Qurʾān translation from Pickthall","ref":"Hūd 11:47 (from رَبِّ)","q":null,"source":null,"page":"p. 24","status":"draft"},
{"n":30,"ar":"فَاطِرَ السَّمٰوٰتِ وَالْأَرْضِ، أَنْتَ وَلِيِّ فِي الدُّنْيَا وَالْآخِرَةِ، تَوَفَّنِي مُسْلِمًا وَّأَلْحِقْنِي بِالصّٰلِحِينَ. إِنَّ رَبِّي لَسَمِيعُ الدُّعَاءِ.","tr":"Fatiras-samawati wal-ard, anta waliyyi fid-dunya wal-akhirah, tawaffani muslimaw-wa alhiqni bis-salihin. Inna rabbi lasami'ud-du'a'.","en":"Qurʾān translation from Pickthall","ref":"Yūsuf 12:101 (from فَاطِرَ), followed by Ibrāhīm 14:39 (end: إِنَّ رَبِّي لَسَمِيعُ الدُّعَاءِ)","q":null,"source":null,"page":"p. 24","status":"draft"},
{"n":31,"ar":"رَبِّ اجْعَلْنِي مُقِيمَ الصَّلٰوةِ وَمِنْ ذُرِّيَّتِي، رَبَّنَا وَتَقَبَّلْ دُعَاءِ ۝ رَبَّنَا اغْفِرْ لِي وَلِوَالِدَيَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ الْحِسَابُ.","tr":"Rabbij-'alni muqimas-salati wa min dhurriyyati, rabbana wa taqabbal du'a'. Rabbanagh-fir li wa liwalidayya wa lil-mu'minina yawma yaqumul-hisab.","en":"Qurʾān translation from Pickthall","ref":"Ibrāhīm 14:40–41","q":{"s":14,"from":40,"to":41},"source":null,"page":"p. 24","status":"draft"},
{"n":32,"ar":"رَبِّ ارْحَمْهُمَا كَمَا رَبَّيٰنِي صَغِيرًا.","tr":"Rabbir-hamhuma kama rabbayani saghira.","en":"Qurʾān translation from Pickthall","ref":"al-Isrāʾ 17:24 (end)","q":null,"source":null,"page":"p. 24","status":"draft"},
{"n":33,"ar":"رَبِّ أَدْخِلْنِي مُدْخَلَ صِدْقٍ وَّأَخْرِجْنِي مُخْرَجَ صِدْقٍ، وَّاجْعَلْ لِّي مِنْ لَّدُنْكَ سُلْطٰنًا نَّصِيرًا.","tr":"Rabbi adkhilni mudkhala sidqin wa akhrijni mukhraja sidq, waj'al li min ladunka sultanan nasira.","en":"Qurʾān translation from Pickthall","ref":"al-Isrāʾ 17:80 (from رَبِّ)","q":null,"source":null,"page":"p. 24","status":"draft"},
{"n":34,"ar":"رَبَّنَا آتِنَا مِنْ لَّدُنْكَ رَحْمَةً وَّهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا.","tr":"Rabbana atina min ladunka rahmatan wa hayyi' lana min amrina rashada.","en":"Qurʾān translation from Pickthall","ref":"al-Kahf 18:10 (from رَبَّنَا)","q":null,"source":null,"page":"p. 24","status":"draft"},
{"n":35,"ar":"رَبِّ اشْرَحْ لِي صَدْرِي ۝ وَيَسِّرْ لِي أَمْرِي.","tr":"Rabbish-rah li sadri, wa yassir li amri.","en":"Qurʾān translation from Pickthall","ref":"Ṭā Hā 20:25–26","q":{"s":20,"from":25,"to":26},"source":"Ibn Mardawayh, al-Khatib, Ibn ʿAsakir","page":"p. 25","status":"draft"},
{"n":36,"ar":"رَبِّ زِدْنِي عِلْمًا.","tr":"Rabbi zidni 'ilma.","en":"Qurʾān translation from Pickthall","ref":"Ṭā Hā 20:114 (end)","q":null,"source":"Tirmidhi, Ibn Majah","page":"p. 25","status":"draft"},
{"n":37,"ar":"رَبِّ أَنِّي مَسَّنِيَ الضُّرُّ وَأَنْتَ أَرْحَمُ الرّٰحِمِينَ.","tr":"Rabbi anni massaniyad-durru wa anta arhamur-rahimin.","en":"Qurʾān translation from Pickthall","ref":"al-Anbiyāʾ 21:83 (Ayyub's words). «رَبِّ» is added before the Qurʾānic wording; Dawud does the same.","q":null,"source":null,"page":"p. 25","status":"draft"},
{"n":38,"ar":"لَا إِلٰهَ إِلَّا أَنْتَ سُبْحٰنَكَ إِنِّي كُنْتُ مِنَ الظّٰلِمِينَ.","tr":"La ilaha illa anta subhanaka inni kuntu minadh-dhalimin.","en":"Qurʾān translation from Pickthall","ref":"al-Anbiyāʾ 21:87 (end)","q":null,"source":"Ahmad, Tirmidhi, Nasaʾi, al-Hakim, and others","page":"p. 25","status":"draft"},
{"n":39,"ar":"رَبِّ لَا تَذَرْنِي فَرْدًا وَّأَنْتَ خَيْرُ الْوٰرِثِينَ.","tr":"Rabbi la tadharni fardan wa anta khayrul-warithin.","en":"Qurʾān translation from Pickthall","ref":"al-Anbiyāʾ 21:89 (from رَبِّ)","q":null,"source":null,"page":"p. 25","status":"draft"},
{"n":40,"ar":"رَبِّ احْكُمْ بِالْحَقِّ، وَرَبُّنَا الرَّحْمٰنُ الْمُسْتَعَانُ عَلٰى مَا تَصِفُونَ. رَبِّ أَنْزِلْنِي مُنْزَلًا مُّبٰرَكًا وَّأَنْتَ خَيْرُ الْمُنْزِلِينَ. رَبِّ فَلَا تَجْعَلْنِي فِي الْقَوْمِ الظّٰلِمِينَ. رَبِّ أَعُوذُ بِكَ مِنْ هَمَزٰتِ الشَّيٰطِينِ ۝ وَأَعُوذُ بِكَ رَبِّ أَنْ يَّحْضُرُونِ.","tr":"Rabbih-kum bil-haqq, wa rabbunar-rahmanul-musta'anu 'ala ma tasifun. Rabbi anzilni munzalan mubarakan wa anta khayrul-munzilin. Rabbi fala taj'alni fil-qawmidh-dhalimin. Rabbi a'udhu bika min hamazatish-shayatin, wa a'udhu bika rabbi an yahdurun.","en":"Qurʾān translation from Pickthall","ref":"al-Anbiyāʾ 21:112; al-Muʾminūn 23:29 (from رَبِّ); 23:94 (end); 23:97–98. Nomani has four passages under the single number 40.","q":null,"source":"ʿAbd al-Razzaq, ʿAbd b. Humayd, Ibn Jarir (21:112); Ibn Abi Shayba, ʿAbd b. Humayd, Ibn Jarir (23:29); Ibn Abi Shayba, Ahmad, Abu Dawud, Tirmidhi, Nasaʾi, Bayhaqi (23:97–98)","page":"p. 26","status":"draft"},
{"n":41,"ar":"رَبَّنَا آمَنَّا فَاغْفِرْ لَنَا وَارْحَمْنَا وَأَنْتَ خَيْرُ الرّٰحِمِينَ.","tr":"Rabbana amanna faghfir lana warhamna wa anta khayrur-rahimin.","en":"Qurʾān translation from Pickthall","ref":"al-Muʾminūn 23:109 (from رَبَّنَا)","q":null,"source":null,"page":"p. 27","status":"draft"},
{"n":42,"ar":"رَبِّ اغْفِرْ وَارْحَمْ وَأَنْتَ خَيْرُ الرّٰحِمِينَ.","tr":"Rabbigh-fir warham wa anta khayrur-rahimin.","en":"Qurʾān translation from Pickthall","ref":"al-Muʾminūn 23:118 (from رَبِّ)","q":null,"source":"Ibn Abi Shayba, Ahmad, Bukhari, Muslim, Tirmidhi, Nasaʾi, Ibn Majah, and others","page":"p. 27","status":"draft"},
{"n":43,"ar":"رَبَّنَا اصْرِفْ عَنَّا عَذَابَ جَهَنَّمَ، إِنَّ عَذَابَهَا كَانَ غَرَامًا ۝ إِنَّهَا سَاءَتْ مُسْتَقَرًّا وَّمُقَامًا.","tr":"Rabbanas-rif 'anna 'adhaba jahannam, inna 'adhabaha kana gharama. Innaha sa'at mustaqarran wa muqama.","en":"Qurʾān translation from Pickthall","ref":"al-Furqān 25:65–66 (from رَبَّنَا)","q":null,"source":null,"page":"p. 27","status":"draft"},
{"n":44,"ar":"رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيّٰتِنَا قُرَّةَ أَعْيُنٍ وَّاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا.","tr":"Rabbana hab lana min azwajina wa dhurriyyatina qurrata a'yunin waj'alna lil-muttaqina imama.","en":"Qurʾān translation from Pickthall","ref":"al-Furqān 25:74 (from رَبَّنَا)","q":null,"source":"Ahmad, Bukhari (al-Adab al-Mufrad), Ibn Jarir, Ibn Abi Hatim, Tabarani, Ibn Mardawayh, Abu Nuʿaym (Hilya)","page":"p. 27","status":"draft"},
{"n":45,"ar":"رَبِّ هَبْ لِي حُكْمًا وَّأَلْحِقْنِي بِالصّٰلِحِينَ ۝ وَاجْعَلْ لِّي لِسَانَ صِدْقٍ فِي الْآخِرِينَ ۝ وَاجْعَلْنِي مِنْ وَّرَثَةِ جَنَّةِ النَّعِيمِ ۝ وَاغْفِرْ لِأَبِي إِنَّهُ كَانَ مِنَ الضَّالِّينَ ۝ وَلَا تُخْزِنِي يَوْمَ يُبْعَثُونَ ۝ يَوْمَ لَا يَنْفَعُ مَالٌ وَّلَا بَنُونَ ۝ إِلَّا مَنْ أَتَى اللّٰهَ بِقَلْبٍ سَلِيمٍ.","tr":"Rabbi hab li hukman wa alhiqni bis-salihin. Waj'al li lisana sidqin fil-akhirin. Waj'alni min warathati jannatin-na'im. Waghfir li-abi innahu kana minad-dallin. Wa la tukhzini yawma yub'athun. Yawma la yanfa'u malun wa la banun. Illa man atallaha biqalbin salim.","en":"Qurʾān translation from Pickthall","ref":"al-Shuʿarāʾ 26:83–89","q":{"s":26,"from":83,"to":89},"source":"Ibn Abi al-Dunya (al-Dhikr), Ibn Mardawayh; Ibn Jarir, al-Hakim","page":"pp. 27–28","status":"draft"},
{"n":46,"ar":"رَبِّ نَجِّنِي وَأَهْلِي مِمَّا يَعْمَلُونَ. رَبِّ إِنَّ قَوْمِي كَذَّبُونِ ۝ فَافْتَحْ بَيْنِي وَبَيْنَهُمْ فَتْحًا وَّنَجِّنِي وَمَنْ مَّعِيَ مِنَ الْمُؤْمِنِينَ.","tr":"Rabbi najjini wa ahli mimma ya'malun. Rabbi inna qawmi kadhdhabun. Faftah bayni wa baynahum fathan wa najjini wa man ma'iya minal-mu'minin.","en":"Qurʾān translation from Pickthall","ref":"al-Shuʿarāʾ 26:169, then 26:117–118. Verse 169 comes first, against mushaf order; Dawud has the same order.","q":null,"source":null,"page":"p. 28","status":"draft"},
{"n":47,"ar":"رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ وَعَلٰى وَالِدَيَّ وَأَنْ أَعْمَلَ صَالِحًا تَرْضٰهُ، وَأَدْخِلْنِي بِرَحْمَتِكَ فِي عِبَادِكَ الصّٰلِحِينَ.","tr":"Rabbi awzi'ni an ashkura ni'matakal-lati an'amta 'alayya wa 'ala walidayya wa an a'mala salihan tardah, wa adkhilni birahmatika fi 'ibadikas-salihin.","en":"Qurʾān translation from Pickthall","ref":"al-Naml 27:19 (from رَبِّ)","q":null,"source":null,"page":"pp. 28–29","status":"draft"},
{"n":48,"ar":"رَبِّ إِنِّي ظَلَمْتُ نَفْسِي فَاغْفِرْ لِي.","tr":"Rabbi inni dhalamtu nafsi faghfir li.","en":"Qurʾān translation from Pickthall","ref":"al-Qaṣaṣ 28:16 (part)","q":null,"source":null,"page":"p. 29","status":"draft"},
{"n":49,"ar":"رَبِّ نَجِّنِي مِنَ الْقَوْمِ الظّٰلِمِينَ.","tr":"Rabbi najjini minal-qawmidh-dhalimin.","en":"Qurʾān translation from Pickthall","ref":"al-Qaṣaṣ 28:21 (end)","q":null,"source":null,"page":"p. 29","status":"draft"},
{"n":50,"ar":"رَبِّ إِنِّي لِمَا أَنْزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيرٌ.","tr":"Rabbi inni lima anzalta ilayya min khayrin faqir.","en":"Qurʾān translation from Pickthall","ref":"al-Qaṣaṣ 28:24 (end)","q":null,"source":"Ibn Mardawayh","page":"p. 29","status":"draft"},
{"n":51,"ar":"رَبِّ انْصُرْنِي عَلَى الْقَوْمِ الْمُفْسِدِينَ.","tr":"Rabbin-surni 'alal-qawmil-mufsidin.","en":"Qurʾān translation from Pickthall","ref":"al-ʿAnkabūt 29:30 (from رَبِّ)","q":null,"source":null,"page":"p. 29","status":"draft"},
{"n":52,"ar":"فَسُبْحٰنَ اللّٰهِ حِينَ تُمْسُونَ وَحِينَ تُصْبِحُونَ ۝ وَلَهُ الْحَمْدُ فِي السَّمٰوٰتِ وَالْأَرْضِ وَعَشِيًّا وَّحِينَ تُظْهِرُونَ ۝ يُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَيُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ وَيُحْيِ الْأَرْضَ بَعْدَ مَوْتِهَا، وَكَذٰلِكَ تُخْرَجُونَ.","tr":"Fa subhanallahi hina tumsuna wa hina tusbihun. Wa lahul-hamdu fis-samawati wal-ardi wa 'ashiyyan wa hina tudhhirun. Yukhrijul-hayya minal-mayyiti wa yukhrijul-mayyita minal-hayyi wa yuhyil-arda ba'da mawtiha, wa kadhalika tukhrajun.","en":"Qurʾān translation from Pickthall","ref":"al-Rūm 30:17–19","q":{"s":30,"from":17,"to":19},"source":"Ahmad, Ibn Jarir, Ibn al-Mundhir, Ibn Abi Hatim, Ibn al-Sunni, Tabarani, Ibn Mardawayh, Bayhaqi (al-Daʿawat); Abu Dawud","page":"pp. 29–30","status":"draft"},
{"n":53,"ar":"رَبِّ هَبْ لِي مِنَ الصّٰلِحِينَ.","tr":"Rabbi hab li minas-salihin.","en":"Qurʾān translation from Pickthall","ref":"al-Ṣāffāt 37:100","q":{"s":37,"from":100,"to":100},"source":null,"page":"p. 30","status":"draft"},
{"n":54,"ar":"قُلِ اللّٰهُمَّ فَاطِرَ السَّمٰوٰتِ وَالْأَرْضِ عٰلِمَ الْغَيْبِ وَالشَّهَادَةِ، أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِي مَا كَانُوا فِيهِ يَخْتَلِفُونَ.","tr":"Qulil-lahumma fatiras-samawati wal-ardi 'alimal-ghaybi wash-shahadah, anta tahkumu bayna 'ibadika fi ma kanu fihi yakhtalifun.","en":"Qurʾān translation from Pickthall","ref":"al-Zumar 39:46","q":{"s":39,"from":46,"to":46},"source":"Muslim, Abu Dawud, Bayhaqi (al-Asmaʾ wa al-Sifat)","page":"p. 30","status":"draft"},
{"n":55,"ar":"رَبَّنَا وَسِعْتَ كُلَّ شَيْءٍ رَّحْمَةً وَّعِلْمًا فَاغْفِرْ لِلَّذِينَ تَابُوا وَاتَّبَعُوا سَبِيلَكَ وَقِهِمْ عَذَابَ الْجَحِيمِ ۝ رَبَّنَا وَأَدْخِلْهُمْ جَنّٰتِ عَدْنِ الَّتِي وَعَدْتَّهُمْ وَمَنْ صَلَحَ مِنْ آبَائِهِمْ وَأَزْوَاجِهِمْ وَذُرِّيّٰتِهِمْ، إِنَّكَ أَنْتَ الْعَزِيزُ الْحَكِيمُ ۝ وَقِهِمُ السَّيِّئَاتِ، وَمَنْ تَقِ السَّيِّئَاتِ يَوْمَئِذٍ فَقَدْ رَحِمْتَهُ، وَذٰلِكَ هُوَ الْفَوْزُ الْعَظِيمُ.","tr":"Rabbana wasi'ta kulla shay'in rahmatan wa 'ilman faghfir lilladhina tabu wattaba'u sabilaka wa qihim 'adhabal-jahim. Rabbana wa adkhilhum jannati 'adninil-lati wa'adtahum wa man salaha min aba'ihim wa azwajihim wa dhurriyyatihim, innaka antal-'azizul-hakim. Wa qihimus-sayyi'at, wa man taqis-sayyi'ati yawma'idhin faqad rahimtah, wa dhalika huwal-fawzul-'adhim.","en":"Qurʾān translation from Pickthall","ref":"Ghāfir 40:7 (from رَبَّنَا) to 40:9","q":null,"source":null,"page":"p. 30","status":"draft"},
{"n":56,"ar":"رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ وَعَلٰى وَالِدَيَّ وَأَنْ أَعْمَلَ صَالِحًا تَرْضٰهُ وَأَصْلِحْ لِي فِي ذُرِّيَّتِي، إِنِّي تُبْتُ إِلَيْكَ وَإِنِّي مِنَ الْمُسْلِمِينَ.","tr":"Rabbi awzi'ni an ashkura ni'matakal-lati an'amta 'alayya wa 'ala walidayya wa an a'mala salihan tardahu wa aslih li fi dhurriyyati, inni tubtu ilayka wa inni minal-muslimin.","en":"Qurʾān translation from Pickthall","ref":"al-Aḥqāf 46:15, from رَبِّ أَوْزِعْنِي only. Dawud quotes the whole verse from «وَوَصَّيْنَا الْإِنْسَانَ…».","q":null,"source":"Ibn Mardawayh; Ibn Abi Hatim","page":"p. 31","status":"draft"},
{"n":57,"ar":"رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالْإِيمَانِ وَلَا تَجْعَلْ فِي قُلُوبِنَا غِلًّا لِّلَّذِينَ آمَنُوا، رَبَّنَا إِنَّكَ رَءُوفٌ رَّحِيمٌ.","tr":"Rabbanagh-fir lana wa li-ikhwaninal-ladhina sabaquna bil-imani wa la taj'al fi qulubina ghillan lilladhina amanu, rabbana innaka ra'ufun rahim.","en":"Qurʾān translation from Pickthall","ref":"al-Ḥashr 59:10 (from رَبَّنَا)","q":null,"source":"ʿAbd b. Humayd, Ibn al-Mundhir, Ibn Abi Hatim, Ibn al-Anbari (al-Masahif), Ibn Mardawayh","page":"p. 31","status":"draft"},
{"n":58,"ar":"رَبَّنَا عَلَيْكَ تَوَكَّلْنَا وَإِلَيْكَ أَنَبْنَا وَإِلَيْكَ الْمَصِيرُ.","tr":"Rabbana 'alayka tawakkalna wa ilayka anabna wa ilaykal-masir.","en":"Qurʾān translation from Pickthall","ref":"al-Mumtaḥana 60:4 (end)","q":null,"source":null,"page":"p. 31","status":"draft"},
{"n":59,"ar":"رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلَّذِينَ كَفَرُوا وَاغْفِرْ لَنَا رَبَّنَا، إِنَّكَ أَنْتَ الْعَزِيزُ الْحَكِيمُ.","tr":"Rabbana la taj'alna fitnatan lilladhina kafaru waghfir lana rabbana, innaka antal-'azizul-hakim.","en":"Qurʾān translation from Pickthall","ref":"al-Mumtaḥana 60:5","q":{"s":60,"from":5,"to":5},"source":null,"page":"p. 31","status":"draft"},
{"n":60,"ar":"رَبَّنَا أَتْمِمْ لَنَا نُورَنَا وَاغْفِرْ لَنَا، إِنَّكَ عَلٰى كُلِّ شَيْءٍ قَدِيرٌ.","tr":"Rabbana atmim lana nurana waghfir lana, innaka 'ala kulli shay'in qadir.","en":"Qurʾān translation from Pickthall","ref":"al-Taḥrīm 66:8 (end)","q":null,"source":null,"page":"p. 31","status":"draft"},
{"n":61,"ar":"رَبِّ اغْفِرْ لِي وَلِوَالِدَيَّ وَلِمَنْ دَخَلَ بَيْتِيَ مُؤْمِنًا وَّلِلْمُؤْمِنِينَ وَالْمُؤْمِنٰتِ.","tr":"Rabbigh-fir li wa liwalidayya wa liman dakhala baytiya mu'minan wa lil-mu'minina wal-mu'minat.","en":"Qurʾān translation from Pickthall","ref":"Nūḥ 71:28. Nomani stops at «وَالْمُؤْمِنٰتِ». The verse goes on «وَلَا تَزِدِ الظّٰلِمِينَ إِلَّا تَبَارًا». Dawud stops at the same place.","q":null,"source":null,"page":"p. 32","status":"draft"},
{"n":62,"ar":"بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيمِ. قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ۝ مِنْ شَرِّ مَا خَلَقَ ۝ وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ۝ وَمِنْ شَرِّ النَّفّٰثٰتِ فِي الْعُقَدِ ۝ وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ.","tr":"Bismillahir-rahmanir-rahim. Qul a'udhu birabbil-falaq. Min sharri ma khalaq. Wa min sharri ghasiqin idha waqab. Wa min sharrin-naffathati fil-'uqad. Wa min sharri hasidin idha hasad.","en":"Qurʾān translation from Pickthall","ref":"al-Falaq 113:1–5, with the basmala","q":null,"source":"Ibn al-Durays, Ibn al-Anbari, al-Hakim, Ibn Mardawayh, Bayhaqi (Shuʿab); Ibn Saʿd, Nasaʾi, al-Baghawi; Tirmidhi; ʿAbd b. Humayd. The footnote covers nos. 62–63.","page":"pp. 32–33","status":"draft"},
{"n":63,"ar":"بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيمِ. قُلْ أَعُوذُ بِرَبِّ النَّاسِ ۝ مَلِكِ النَّاسِ ۝ إِلٰهِ النَّاسِ ۝ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ۝ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ۝ مِنَ الْجِنَّةِ وَالنَّاسِ.","tr":"Bismillahir-rahmanir-rahim. Qul a'udhu birabbin-nas. Malikin-nas. Ilahin-nas. Min sharril-waswasil-khannas. Alladhi yuwaswisu fi sudurin-nas. Minal-jinnati wan-nas.","en":"Qurʾān translation from Pickthall","ref":"al-Nās 114:1–6, with the basmala","q":null,"source":"see no. 62","page":"p. 33","status":"draft"},
{"n":64,"ar":"سُبْحٰنَكَ اللّٰهُمَّ، وَتَحِيَّتُهُمْ فِيهَا سَلٰمٌ، وَآخِرُ دَعْوٰىهُمْ أَنِ الْحَمْدُ لِلّٰهِ رَبِّ الْعٰلَمِينَ.","tr":"Subhanakal-lahumma, wa tahiyyatuhum fiha salam, wa akhiru da'wahum anil-hamdu lillahi rabbil-'alamin.","en":"Qurʾān translation from Pickthall","ref":"Yūnus 10:10, from «سُبْحٰنَكَ اللّٰهُمَّ». The verse begins «دَعْوٰىهُمْ فِيهَا».","q":null,"source":"Ibn Mardawayh; Ibn Jarir, Ibn al-Mundhir, Abu al-Shaykh","page":"p. 33","status":"draft"},
{"n":65,"ar":"قَالَ اللّٰهُ تَعَالٰى: ﴿وَلِلّٰهِ الْأَسْمَاءُ الْحُسْنٰى فَادْعُوهُ بِهَا﴾، وَقَالَ النَّبِيُّ صَلَّى اللّٰهُ عَلَيْهِ وَسَلَّمَ: «إِنَّ لِلّٰهِ تَعَالٰى تِسْعَةً وَّتِسْعِينَ اسْمًا، مَنْ أَحْصَاهَا دَخَلَ الْجَنَّةَ»، وَفِي رِوَايَةٍ: «مَنْ حَفِظَهَا».","tr":"Qalallahu ta'ala: \"Wa lillahil-asma'ul-husna fad'uhu biha.\" Wa qalan-nabiyyu sallallahu 'alayhi wa sallam: \"Inna lillahi ta'ala tis'atan wa tis'ina isman, man ahsaha dakhalal-jannah.\" Wa fi riwayah: \"man hafidhaha.\"","en":"Allah the Exalted said: (the verse: Qurʾān translation from Pickthall). And the Prophet (peace and blessings be upon him) said: \"Allah has ninety-nine names; whoever counts them (learns them and lives by them) will enter Paradise.\" In another narration: \"whoever memorises them.\"","ref":"al-Aʿrāf 7:180 (opening phrase), followed by a hadith","q":null,"source":"Tirmidhi, Ibn Hibban, al-Hakim, Bayhaqi (Shuʿab al-Iman); Ibn Majah. Nomani cites them through al-Suyuti's Jamʿ al-Jawamiʿ and Kanz al-ʿUmmal.","page":"pp. 33–34","status":"draft"},
{"n":66,"ar":"هُوَ اللّٰهُ الَّذِي لَا إِلٰهَ إِلَّا هُوَ: الرَّحْمٰنُ، الرَّحِيمُ، الْمَلِكُ، الْقُدُّوسُ، السَّلَامُ، الْمُؤْمِنُ، الْمُهَيْمِنُ، الْعَزِيزُ، الْجَبَّارُ، الْمُتَكَبِّرُ، الْخَالِقُ، الْبَارِئُ، الْمُصَوِّرُ، الْغَفَّارُ، الْقَهَّارُ، الْوَهَّابُ، الرَّزَّاقُ، الْفَتَّاحُ، الْعَلِيمُ، الْقَابِضُ، الْبَاسِطُ، الْخَافِضُ، الرَّافِعُ، الْمُعِزُّ، الْمُذِلُّ، السَّمِيعُ، الْبَصِيرُ، الْحَكَمُ، الْعَدْلُ، اللَّطِيفُ، الْخَبِيرُ، الْحَلِيمُ، الْعَظِيمُ، الْغَفُورُ، الشَّكُورُ، الْعَلِيُّ، الْكَبِيرُ، الْحَفِيظُ، الْمُقِيتُ، الْحَسِيبُ، الْجَلِيلُ، الْكَرِيمُ، الرَّقِيبُ، الْمُجِيبُ، الْوَاسِعُ، الْحَكِيمُ، الْوَدُودُ، الْمَجِيدُ، الْبَاعِثُ، الشَّهِيدُ، الْحَقُّ، الْوَكِيلُ، الْقَوِيُّ، الْمَتِينُ، الْوَلِيُّ، الْحَمِيدُ، الْمُحْصِي، الْمُبْدِئُ، الْمُعِيدُ، الْمُحْيِي، الْمُمِيتُ، الْحَيُّ، الْقَيُّومُ، الْوَاجِدُ، الْمَاجِدُ، الْوَاحِدُ، الْأَحَدُ، الصَّمَدُ، الْقَادِرُ، الْمُقْتَدِرُ، الْمُقَدِّمُ، الْمُؤَخِّرُ، الْأَوَّلُ، الْآخِرُ، الظَّاهِرُ، الْبَاطِنُ، الْوَالِي، الْمُتَعَالِي، الْبَرُّ، التَّوَّابُ، الْمُنْعِمُ، الْمُنْتَقِمُ، الْعَفُوُّ، الرَّءُوفُ، مَالِكُ الْمُلْكِ، ذُو الْجَلَالِ وَالْإِكْرَامِ، الرَّبُّ، الْمُقْسِطُ، الْجَامِعُ، الْغَنِيُّ، الْمُغْنِي، الْمُعْطِي، الْمَانِعُ، الضَّارُّ، النَّافِعُ، النُّورُ، الْهَادِي، الْبَدِيعُ، الْبَاقِي، الْوَارِثُ، الرَّشِيدُ، الصَّبُورُ.","tr":"Huwallahul-ladhi la ilaha illa huw: ar-Rahman, ar-Rahim, al-Malik, al-Quddus, as-Salam, al-Mu'min, al-Muhaymin, al-'Aziz, al-Jabbar, al-Mutakabbir, al-Khaliq, al-Bari', al-Musawwir, al-Ghaffar, al-Qahhar, al-Wahhab, ar-Razzaq, al-Fattah, al-'Alim, al-Qabid, al-Basit, al-Khafid, ar-Rafi', al-Mu'izz, al-Mudhill, as-Sami', al-Basir, al-Hakam, al-'Adl, al-Latif, al-Khabir, al-Halim, al-'Adhim, al-Ghafur, ash-Shakur, al-'Aliyy, al-Kabir, al-Hafidh, al-Muqit, al-Hasib, al-Jalil, al-Karim, ar-Raqib, al-Mujib, al-Wasi', al-Hakim, al-Wadud, al-Majid, al-Ba'ith, ash-Shahid, al-Haqq, al-Wakil, al-Qawiyy, al-Matin, al-Waliyy, al-Hamid, al-Muhsi, al-Mubdi', al-Mu'id, al-Muhyi, al-Mumit, al-Hayy, al-Qayyum, al-Wajid, al-Majid, al-Wahid, al-Ahad, as-Samad, al-Qadir, al-Muqtadir, al-Muqaddim, al-Mu'akhkhir, al-Awwal, al-Akhir, adh-Dhahir, al-Batin, al-Wali, al-Muta'ali, al-Barr, at-Tawwab, al-Mun'im, al-Muntaqim, al-'Afuww, ar-Ra'uf, Malikul-Mulk, Dhul-Jalali wal-Ikram, ar-Rabb, al-Muqsit, al-Jami', al-Ghaniyy, al-Mughni, al-Mu'ti, al-Mani', ad-Darr, an-Nafi', an-Nur, al-Hadi, al-Badi', al-Baqi, al-Warith, ar-Rashid, as-Sabur.","en":"He is Allah, besides whom there is no god: the Most Merciful, the Most Compassionate, the King, the Most Holy, the Source of Peace, the Giver of Security, the Guardian over all, the Almighty, the Compeller, the Supreme in greatness, the Creator, the Maker, the Fashioner, the Ever-Forgiving, the All-Subduing, the Bestower, the Provider, the Opener (and Judge), the All-Knowing, the Withholder, the Expander, the Abaser, the Exalter, the Giver of honour, the Giver of disgrace, the All-Hearing, the All-Seeing, the Judge, the Just, the Subtle and Kind, the All-Aware, the Forbearing, the Magnificent, the All-Forgiving, the Appreciative, the Most High, the Most Great, the Preserver, the Sustainer, the Reckoner, the Majestic, the Generous, the Watchful, the Responsive, the All-Embracing, the All-Wise, the Loving, the Glorious, the Resurrector, the Witness, the Truth, the Trustee, the Strong, the Firm, the Protecting Friend, the Praiseworthy, the One who counts all things, the Originator, the Restorer, the Giver of life, the Giver of death, the Ever-Living, the Self-Subsisting Sustainer of all, the Finder (who lacks nothing), the Noble, the One, the Unique, the Eternal Refuge, the All-Powerful, the Determiner of all, the Bringer-forward, the Delayer, the First, the Last, the Manifest, the Hidden, the Governor, the Supremely Exalted, the Source of goodness, the Accepter of repentance, the Giver of blessings, the Avenger, the Pardoner, the Most Kind, the Owner of all sovereignty, the Lord of majesty and honour, the Lord, the Equitable, the Gatherer, the Self-Sufficient, the Enricher, the Giver, the Preventer, the Bringer of harm, the Bringer of benefit, the Light, the Guide, the Originator without precedent, the Everlasting, the Inheritor, the Guide to the right course, the Most Patient.","ref":"none (the list of names in the hadith of no. 65). Nomani prints the names five to a row in boxes. The list includes «الْمُنْعِمُ» and «الرَّبُّ», and has 102 entries after «هُوَ اللّٰهُ الَّذِي لَا إِلٰهَ إِلَّا هُوَ». Dawud has the same list in the same order.","q":null,"source":"the same footnote as no. 65","page":"pp. 34–35","status":"draft"},
{"n":67,"ar":"وَاسْمُ اللّٰهِ الْأَعْظَمُ الَّذِي إِذَا دُعِيَ بِهِ أَجَابَ، وَإِذَا سُئِلَ بِهِ أَعْطٰى: لَا إِلٰهَ إِلَّا أَنْتَ سُبْحٰنَكَ إِنِّي كُنْتُ مِنَ الظّٰلِمِينَ.","tr":"Wasmullahil-a'dhamul-ladhi idha du'iya bihi ajab, wa idha su'ila bihi a'ta: La ilaha illa anta subhanaka inni kuntu minadh-dhalimin.","en":"And Allah's Greatest Name, by which He answers when called and gives when asked: \"There is no god but You; glory be to You; I have been among the wrongdoers.\"","ref":"contains al-Anbiyāʾ 21:87 (end)","q":null,"source":"al-Hakim (Mustadrak), cited through Ibn al-Jazari's al-Hisn al-Hasin","page":"p. 35","status":"draft"},
{"n":68,"ar":"اَللّٰهُمَّ إِنِّي أَسْأَلُكَ بِأَنِّي أَشْهَدُ أَنَّكَ أَنْتَ اللّٰهُ لَا إِلٰهَ إِلَّا أَنْتَ الْأَحَدُ الصَّمَدُ الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَّهُ كُفُوًا أَحَدٌ.","tr":"Allahumma inni as'aluka bi-anni ashhadu annaka antallahu la ilaha illa antal-ahadus-samadul-ladhi lam yalid wa lam yulad wa lam yakun lahu kufuwan ahad.","en":"O Allah, I ask You by my bearing witness that You are Allah; there is no god but You, the One, the Eternal Refuge, who neither begets nor was begotten, and to whom no one is equal.","ref":"none (ends with words from al-Ikhlāṣ 112:3–4)","q":null,"source":"Abu Dawud, Tirmidhi, Nasaʾi, Ibn Majah (the four Sunan), Ibn Hibban, al-Hakim, Ahmad","page":"p. 36","status":"draft"},
{"n":69,"ar":"اَللّٰهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الْحَمْدَ، لَا إِلٰهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ، الْحَنَّانُ الْمَنَّانُ، بَدِيعُ السَّمٰوٰتِ وَالْأَرْضِ، يَا ذَا الْجَلَالِ وَالْإِكْرَامِ، يَا حَيُّ يَا قَيُّومُ، يَا أَرْحَمَ الرّٰحِمِينَ.","tr":"Allahumma inni as'aluka bi-anna lakal-hamd, la ilaha illa anta wahdaka la sharika lak, al-Hannanul-Mannan, badi'us-samawati wal-ard, ya dhal-jalali wal-ikram, ya hayyu ya qayyum, ya arhamar-rahimin.","en":"O Allah, I ask You because all praise is Yours. There is no god but You alone, with no partner; the Most Tender, the Bestower of favours, Originator of the heavens and the earth. O Lord of majesty and honour, O Ever-Living, O Self-Subsisting, O Most Merciful of the merciful.","ref":null,"q":null,"source":"Ibn Majah; the four Sunan, Ibn Hibban, al-Hakim, Ahmad, Ibn Abi Shayba; al-Hakim. Nomani gives separate footnotes for separate phrases, all through Ibn al-Jazari.","page":"p. 36","status":"draft"},
{"n":70,"ar":"سُبْحَانَ رَبِّيَ الْعَلِيِّ الْأَعْلَى الْوَهَّابِ. أَعُوذُ بِكَلِمَاتِ اللّٰهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ. بِسْمِ اللّٰهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ. أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلّٰهِ، وَالْحَمْدُ لِلّٰهِ، لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلٰى كُلِّ شَيْءٍ قَدِيرٌ.","tr":"Subhana rabbiyal-'aliyyil-a'lal-wahhab. A'udhu bikalimatil-lahit-tammati min sharri ma khalaq. Bismillahil-ladhi la yadurru ma'as-mihi shay'un fil-ardi wa la fis-sama'i wa huwas-sami'ul-'alim. Asbahna wa asbahal-mulku lillah, wal-hamdu lillah, la ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamdu wa huwa 'ala kulli shay'in qadir.","en":"Glory be to my Lord, the High, the Most High, the Bestower. I seek refuge in the perfect words of Allah from the evil of what He has created. In the name of Allah, with whose name nothing on earth or in heaven can cause harm, and He is the All-Hearing, the All-Knowing. We have entered the morning, and the whole kingdom belongs to Allah. Praise be to Allah. There is no god but Allah alone, with no partner. His is the kingdom and His is the praise, and He has power over all things.","ref":null,"q":null,"source":"Ahmad, al-Hakim (the first sentence); Tabarani (al-Awsat) (أعوذ بكلمات); the four Sunan, Ibn Hibban, al-Hakim, Ibn Abi Shayba (بسم الله الذي…); Muslim, Abu Dawud, Tirmidhi, Nasaʾi, Ibn Abi Shayba (أصبحنا…, which continues into nos. 71–73)","page":"pp. 36–37","status":"draft"},
{"n":71,"ar":"رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هٰذَا الْيَوْمِ وَخَيْرَ مَا بَعْدَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هٰذَا الْيَوْمِ وَشَرِّ مَا بَعْدَهُ.","tr":"Rabbi as'aluka khayra ma fi hadhal-yawmi wa khayra ma ba'dah, wa a'udhu bika min sharri ma fi hadhal-yawmi wa sharri ma ba'dah.","en":"My Lord, I ask You for the good of this day and the good of what comes after it, and I seek refuge in You from the evil of this day and the evil of what comes after it.","ref":null,"q":null,"source":"see the end of no. 70 (Muslim and others)","page":"p. 37","status":"draft"},
{"n":72,"ar":"رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ.","tr":"Rabbi a'udhu bika minal-kasali wa su'il-kibar.","en":"My Lord, I seek refuge in You from laziness and from the troubles of old age.","ref":null,"q":null,"source":"see no. 70","page":"p. 37","status":"draft"},
{"n":73,"ar":"رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ.","tr":"Rabbi a'udhu bika min 'adhabin fin-nari wa 'adhabin fil-qabr.","en":"My Lord, I seek refuge in You from punishment in the Fire and punishment in the grave.","ref":null,"q":null,"source":"see no. 70","page":"p. 37","status":"draft"},
{"n":74,"ar":"اَللّٰهُمَّ فَاطِرَ السَّمٰوٰتِ وَالْأَرْضِ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، رَبَّ كُلِّ شَيْءٍ وَّمَلِيكَهُ، أَشْهَدُ أَنْ لَّا إِلٰهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي وَمِنْ شَرِّ الشَّيْطٰنِ وَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلٰى نَفْسِي سُوءًا أَوْ أَجُرَّهُ إِلٰى مُسْلِمٍ.","tr":"Allahumma fatiras-samawati wal-ardi 'alimal-ghaybi wash-shahadah, rabba kulli shay'in wa malikah, ashhadu an la ilaha illa anta wahdaka la sharika lak, a'udhu bika min sharri nafsi wa min sharrish-shaytani wa shirkih, wa an aqtarifa 'ala nafsi su'an aw ajurrahu ila muslim.","en":"O Allah, Originator of the heavens and the earth, Knower of the unseen and the seen, Lord and Owner of all things: I bear witness that there is no god but You alone, with no partner. I seek refuge in You from the evil of my own self, from the evil of Satan and his call to associate partners with You, and from doing wrong against myself or bringing it upon a Muslim.","ref":null,"q":null,"source":"Abu Dawud, Tirmidhi, Nasaʾi, Ibn Hibban, al-Hakim, Ibn Abi Shayba; also Ahmad, Ibn Maniʿ, al-Shashi, Abu Yaʿla, Ibn al-Sunni, Saʿid b. Mansur","page":"p. 38","status":"draft"},
{"n":75,"ar":"اَللّٰهُمَّ إِنِّي أَصْبَحْتُ أُشْهِدُكَ وَأُشْهِدُ حَمَلَةَ عَرْشِكَ وَمَلَائِكَتَكَ وَجَمِيعَ خَلْقِكَ بِأَنَّكَ لَا إِلٰهَ إِلَّا أَنْتَ وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ.","tr":"Allahumma inni asbahtu ushhiduka wa ushhidu hamalata 'arshika wa mala'ikataka wa jami'a khalqika bi-annaka la ilaha illa anta wa anna Muhammadan 'abduka wa rasuluk.","en":"O Allah, this morning I call You to witness, and I call the bearers of Your Throne, Your angels and all Your creation to witness, that You are Allah, there is no god but You, and that Muhammad is Your servant and Your Messenger.","ref":null,"q":null,"source":"Tabarani (al-Awsat); Tirmidhi","page":"p. 38","status":"draft"},
{"n":76,"ar":"اَللّٰهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ.","tr":"Allahumma inni as'alukal-'afiyata fid-dunya wal-akhirah.","en":"O Allah, I ask You for well-being in this world and the next.","ref":null,"q":null,"source":"Abu Dawud, Ibn Majah, Nasaʾi, Ibn Hibban, al-Hakim, Ibn Abi Shayba (this footnote also covers nos. 77–79)","page":"p. 39","status":"draft"},
{"n":77,"ar":"اَللّٰهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي.","tr":"Allahumma inni as'alukal-'afwa wal-'afiyata fi dini wa dunyaya wa ahli wa mali.","en":"O Allah, I ask You for pardon and well-being in my religion, my worldly life, my family and my wealth.","ref":null,"q":null,"source":"see no. 76","page":"p. 39","status":"draft"},
{"n":78,"ar":"اَللّٰهُمَّ اسْتُرْ عَوْرَاتِي وَآمِنْ رَوْعَاتِي.","tr":"Allahummas-tur 'awrati wa amin raw'ati.","en":"O Allah, cover my faults and calm my fears.","ref":null,"q":null,"source":"see no. 76","page":"p. 39","status":"draft"},
{"n":79,"ar":"اَللّٰهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ وَمِنْ خَلْفِي وَعَنْ يَمِينِي وَعَنْ شِمَالِي وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي. رَضِينَا بِاللّٰهِ رَبًّا وَّبِالْإِسْلَامِ دِينًا وَّبِمُحَمَّدٍ صَلَّى اللّٰهُ عَلَيْهِ وَسَلَّمَ رَسُولًا وَّنَبِيًّا.","tr":"Allahummah-fadhni min bayni yadayya wa min khalfi wa 'an yamini wa 'an shimali wa min fawqi, wa a'udhu bi'adhamatika an ughtala min tahti. Radina billahi rabban wa bil-islami dinan wa bi-Muhammadin sallallahu 'alayhi wa sallama rasulan wa nabiyya.","en":"O Allah, guard me from in front of me and behind me, from my right and my left, and from above me; and I seek refuge in Your greatness from being taken unawares from beneath me. We are pleased with Allah as Lord, with Islam as religion, and with Muhammad (peace and blessings be upon him) as Messenger and Prophet.","ref":null,"q":null,"source":"see no. 76 (first part); the four Sunan, al-Hakim, Ahmad, Tabarani (al-Kabir) (رضينا…)","page":"p. 39","status":"draft"},
{"n":80,"ar":"اَللّٰهُمَّ مَا أَصْبَحَ بِي مِنْ نِّعْمَةٍ أَوْ بِأَحَدٍ مِّنْ خَلْقِكَ فَمِنْكَ وَحْدَكَ لَا شَرِيكَ لَكَ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ.","tr":"Allahumma ma asbaha bi min ni'matin aw bi-ahadin min khalqika fa-minka wahdaka la sharika lak, falakal-hamdu wa lakash-shukr.","en":"O Allah, whatever blessing has come to me or to any of Your creation this morning is from You alone, with no partner. So Yours is the praise and Yours is the thanks.","ref":null,"q":null,"source":"Abu Dawud, Nasaʾi, Ibn Hibban, Ibn al-Sunni","page":"p. 39","status":"draft"},
{"n":81,"ar":"اَللّٰهُمَّ عَافِنِي فِي بَدَنِي، اَللّٰهُمَّ عَافِنِي فِي سَمْعِي، اَللّٰهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلٰهَ إِلَّا أَنْتَ (ثَلَاثَ مَرَّاتٍ).","tr":"Allahumma 'afini fi badani, Allahumma 'afini fi sam'i, Allahumma 'afini fi basari, la ilaha illa ant. (three times)","en":"O Allah, grant me well-being in my body. O Allah, grant me well-being in my hearing. O Allah, grant me well-being in my sight. There is no god but You. (Three times.)","ref":null,"q":null,"source":"Abu Dawud, Nasaʾi, Ibn al-Sunni","page":"p. 40","status":"draft"},
{"n":82,"ar":"اَللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، اَللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلٰهَ إِلَّا أَنْتَ (ثَلَاثَ مَرَّاتٍ).","tr":"Allahumma inni a'udhu bika minal-kufri wal-faqr, Allahumma inni a'udhu bika min 'adhabil-qabr, la ilaha illa ant. (three times)","en":"O Allah, I seek refuge in You from disbelief and poverty. O Allah, I seek refuge in You from the punishment of the grave. There is no god but You. (Three times.)","ref":null,"q":null,"source":"see no. 81","page":"p. 40","status":"draft"},
{"n":83,"ar":"سُبْحَانَ اللّٰهِ وَبِحَمْدِهِ، لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللّٰهِ، مَا شَاءَ اللّٰهُ كَانَ وَمَا لَمْ يَشَأْ لَمْ يَكُنْ، أَعْلَمُ أَنَّ اللّٰهَ عَلٰى كُلِّ شَيْءٍ قَدِيرٌ، وَأَنَّ اللّٰهَ قَدْ أَحَاطَ بِكُلِّ شَيْءٍ عِلْمًا.","tr":"Subhanallahi wa bihamdih, la hawla wa la quwwata illa billah, ma sha'allahu kana wa ma lam yasha' lam yakun, a'lamu annallaha 'ala kulli shay'in qadir, wa annallaha qad ahata bikulli shay'in 'ilma.","en":"Glory be to Allah and praise be to Him. There is no power and no strength except through Allah. What Allah wills happens, and what He does not will does not happen. I know that Allah has power over all things, and that Allah encompasses all things in knowledge.","ref":null,"q":null,"source":"Abu Dawud, Nasaʾi, Ibn al-Sunni; al-Suyuti (Zawaʾid al-Jamiʿ al-Saghir)","page":"p. 40","status":"draft"},
{"n":84,"ar":"يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ، أَصْلِحْ لِي شَأْنِي كُلَّهُ، وَلَا تَكِلْنِي إِلٰى نَفْسِي طَرْفَةَ عَيْنٍ.","tr":"Ya hayyu ya qayyumu birahmatika astaghith, aslih li sha'ni kullah, wa la takilni ila nafsi tarfata 'ayn.","en":"O Ever-Living, O Self-Subsisting, by Your mercy I call for help. Set right all my affairs, and do not leave me to myself even for the blink of an eye.","ref":null,"q":null,"source":"Nasaʾi, al-Hakim, al-Bazzar","page":"p. 40","status":"draft"},
{"n":85,"ar":"سَيِّدُ الْاِسْتِغْفَارِ: اَللّٰهُمَّ أَنْتَ رَبِّي لَا إِلٰهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلٰى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي، فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ.","tr":"(Sayyidul-istighfar:) Allahumma anta rabbi la ilaha illa ant, khalaqtani wa ana 'abduk, wa ana 'ala 'ahdika wa wa'dika mastata't, a'udhu bika min sharri ma sana't, abu'u laka bini'matika 'alayya, wa abu'u bidhanbi, faghfir li fa-innahu la yaghfirudh-dhunuba illa ant.","en":"(The best way of asking forgiveness:) O Allah, You are my Lord; there is no god but You. You created me and I am Your servant, and I keep to Your covenant and promise as far as I can. I seek refuge in You from the evil of what I have done. I acknowledge Your blessing upon me, and I acknowledge my sin. So forgive me, for no one forgives sins but You.","ref":null,"q":null,"source":"al-Bazzar; Bukhari, Nasaʾi; Abu Dawud, Ibn al-Sunni","page":"p. 41","status":"draft"},
{"n":86,"ar":"اَللّٰهُمَّ أَنْتَ أَحَقُّ مَنْ ذُكِرَ، وَأَحَقُّ مَنْ عُبِدَ، وَأَنْصَرُ مَنِ ابْتُغِيَ، وَأَرْأَفُ مَنْ مَلَكَ، وَأَجْوَدُ مَنْ سُئِلَ، وَأَوْسَعُ مَنْ أَعْطٰى.","tr":"Allahumma anta ahaqqu man dhukir, wa ahaqqu man 'ubid, wa ansaru manib-tughi, wa ar'afu man malak, wa ajwadu man su'il, wa awsa'u man a'ta.","en":"O Allah, You are the most deserving of those remembered and the most deserving of those worshipped, the best helper of those whose help is sought, the most kind of those who rule, the most generous of those who are asked, and the most bountiful of those who give.","ref":null,"q":null,"source":"Tabarani (al-Muʿjam al-Kabir, and Kitab al-Duʿaʾ) (this footnote covers nos. 86–87)","page":"p. 41","status":"draft"},
{"n":87,"ar":"اَللّٰهُمَّ أَنْتَ الْمَلِكُ لَا شَرِيكَ لَكَ، وَالْفَرْدُ لَا نِدَّ لَكَ، كُلُّ شَيْءٍ هَالِكٌ إِلَّا وَجْهَكَ، لَنْ تُطَاعَ إِلَّا بِإِذْنِكَ، وَلَنْ تُعْصٰى إِلَّا بِعِلْمِكَ، تُطَاعُ فَتَشْكُرُ، وَتُعْصٰى فَتَغْفِرُ، أَقْرَبُ شَهِيدٍ، وَأَدْنٰى حَفِيظٍ، حُلْتَ دُونَ النُّفُوسِ، وَأَخَذْتَ بِالنَّوَاصِي، وَكَتَبْتَ الْآثَارَ، وَنَسَخْتَ الْآجَالَ، الْقُلُوبُ لَكَ مُفْضِيَةٌ، وَالسِّرُّ عِنْدَكَ عَلَانِيَةٌ، الْحَلَالُ مَا أَحْلَلْتَ، وَالْحَرَامُ مَا حَرَّمْتَ، وَالدِّينُ مَا شَرَعْتَ، وَالْأَمْرُ مَا قَضَيْتَ، وَالْخَلْقُ خَلْقُكَ، وَالْعَبْدُ عَبْدُكَ، وَأَنْتَ اللّٰهُ الرَّءُوفُ الرَّحِيمُ، أَسْأَلُكَ بِنُورِ وَجْهِكَ الَّذِي أَشْرَقَتْ لَهُ السَّمٰوٰتُ وَالْأَرْضُ، وَبِكُلِّ حَقٍّ هُوَ لَكَ، وَبِحَقِّ السَّائِلِينَ عَلَيْكَ، أَنْ تُقِيلَنِي فِي هٰذِهِ الْغَدَاةِ أَوْ فِي هٰذِهِ الْعَشِيَّةِ، وَأَنْ تُجِيرَنِي مِنَ النَّارِ بِقُدْرَتِكَ.","tr":"Allahumma antal-maliku la sharika lak, wal-fardu la nidda lak, kullu shay'in halikun illa wajhak, lan tuta'a illa bi-idhnik, wa lan tu'sa illa bi'ilmik, tuta'u fatashkur, wa tu'sa fataghfir, aqrabu shahid, wa adna hafidh, hulta dunan-nufus, wa akhadhta bin-nawasi, wa katabtal-athar, wa nasakhtal-ajal, al-qulubu laka mufdiyah, wal-sirru 'indaka 'alaniyah, al-halalu ma ahlalt, wal-haramu ma harramt, wad-dinu ma shara't, wal-amru ma qadayt, wal-khalqu khalquk, wal-'abdu 'abduk, wa antallahur-ra'ufur-rahim, as'aluka binuri wajhikal-ladhi ashraqat lahus-samawatu wal-ard, wa bikulli haqqin huwa lak, wa bihaqqis-sa'ilina 'alayk, an tuqilani fi hadhihil-ghadati aw fi hadhihil-'ashiyyah, wa an tujirani minan-nari biqudratik.","en":"O Allah, You are the King with no partner, the Single One with no equal. Everything perishes except Your Face. You are never obeyed except by Your leave, and never disobeyed except with Your knowledge. You are obeyed and You reward it; You are disobeyed and You forgive. You are the nearest witness and the closest guardian. You stand between souls and their desires, You hold every forelock, You have recorded all deeds and fixed every lifespan. Hearts are open to You, and what is secret is plain before You. The lawful is what You made lawful, the unlawful is what You forbade, the religion is what You laid down, and the command is what You decreed. The creation is Your creation and the servant is Your servant, and You are Allah, the Most Kind, the Most Merciful. I ask You by the light of Your Face, by which the heavens and the earth shine, and by every right that is Yours, and by the right of those who ask of You, to forgive my lapses this morning (or: this evening) and to protect me from the Fire by Your power.","ref":"none (contains al-Qaṣaṣ 28:88, «كُلُّ شَيْءٍ هَالِكٌ إِلَّا وَجْهَهُ», adapted to the second person)","q":null,"source":"see no. 86","page":"pp. 41–42","status":"draft"},
{"n":88,"ar":"اَللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ، وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَقَهْرِ الرِّجَالِ.","tr":"Allahumma inni a'udhu bika minal-hammi wal-hazan, wa a'udhu bika minal-'ajzi wal-kasal, wa a'udhu bika minal-jubni wal-bukhl, wa a'udhu bika min ghalabatid-dayni wa qahrir-rijal.","en":"O Allah, I seek refuge in You from worry and grief, from helplessness and laziness, from cowardice and miserliness, and from being overcome by debt and overpowered by men.","ref":null,"q":null,"source":"Abu Dawud","page":"pp. 42–43","status":"draft"},
{"n":89,"ar":"لَبَّيْكَ اللّٰهُمَّ لَبَّيْكَ، لَبَّيْكَ وَسَعْدَيْكَ، وَالْخَيْرُ فِي يَدَيْكَ، وَمِنْكَ وَإِلَيْكَ.","tr":"Labbayka Allahumma labbayk, labbayka wa sa'dayk, wal-khayru fi yadayk, wa minka wa ilayk.","en":"Here I am, O Allah, here I am, at Your service and ready to obey. All good is in Your hands. From You, and to You.","ref":null,"q":null,"source":"Ibn al-Sunni, al-Hakim, Ahmad, Tabarani (al-Kabir)","page":"p. 43","status":"draft"},
{"n":90,"ar":"اَللّٰهُمَّ مَا قُلْتُ مِنْ قَوْلٍ أَوْ حَلَفْتُ مِنْ حَلِفٍ أَوْ نَذَرْتُ مِنْ نَّذْرٍ فَمَشِيئَتُكَ بَيْنَ يَدَيْ ذٰلِكَ كُلِّهِ، مَا شِئْتَ كَانَ وَمَا لَمْ تَشَأْ لَا يَكُونُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِكَ، إِنَّكَ عَلٰى كُلِّ شَيْءٍ قَدِيرٌ.","tr":"Allahumma ma qultu min qawlin aw halaftu min halfin aw nadhartu min nadhrin fa-mashi'atuka bayna yaday dhalika kullih, ma shi'ta kana wa ma lam tasha' la yakun, wa la hawla wa la quwwata illa bik, innaka 'ala kulli shay'in qadir.","en":"O Allah, whatever I have said, whatever oath I have sworn and whatever vow I have made, Your will comes before all of it. What You will happens, and what You do not will does not happen. There is no power and no strength except through You. You have power over all things.","ref":null,"q":null,"source":"see no. 89 (Nomani gives no separate footnote)","page":"p. 43","status":"draft"},
{"n":91,"ar":"اَللّٰهُمَّ مَا صَلَّيْتُ مِنْ صَلَاةٍ فَعَلٰى مَنْ صَلَّيْتَ، وَمَا لَعَنْتُ مِنْ لَعْنٍ فَعَلٰى مَنْ لَعَنْتَ، أَنْتَ وَلِيِّي فِي الدُّنْيَا وَالْآخِرَةِ، تَوَفَّنِي مُسْلِمًا وَّأَلْحِقْنِي بِالصّٰلِحِينَ.","tr":"Allahumma ma sallaytu min salatin fa'ala man sallayt, wa ma la'antu min la'nin fa'ala man la'ant, anta waliyyi fid-dunya wal-akhirah, tawaffani muslimaw-wa alhiqni bis-salihin.","en":"O Allah, whatever blessing I have invoked, let it fall on those You bless; and whatever curse I have uttered, let it fall on those You curse. You are my protector in this world and the next. Let me die a Muslim and join me with the righteous.","ref":"none (ends with words from Yūsuf 12:101)","q":null,"source":"see no. 89 (Nomani gives no separate footnote)","page":"p. 43","status":"draft"},
{"n":92,"ar":"اَللّٰهُمَّ إِنِّي أَسْأَلُكَ الرِّضَاءَ بَعْدَ الْقَضَاءِ، وَبَرْدَ الْعَيْشِ بَعْدَ الْمَوْتِ، وَلَذَّةَ النَّظَرِ إِلٰى وَجْهِكَ، وَشَوْقًا إِلٰى لِقَائِكَ فِي غَيْرِ ضَرَّاءَ مُضِرَّةٍ وَّلَا فِتْنَةٍ مُّضِلَّةٍ، وَأَعُوذُ بِكَ أَنْ أَظْلِمَ أَوْ أُظْلَمَ، أَوْ أَعْتَدِيَ أَوْ يُعْتَدٰى عَلَيَّ، أَوْ أَكْسِبَ خَطِيئَةً أَوْ ذَنْبًا لَّا تَغْفِرُهُ.","tr":"Allahumma inni as'alukar-rida'a ba'dal-qada', wa bardal-'ayshi ba'dal-mawt, wa ladhdhatan-nadhari ila wajhik, wa shawqan ila liqa'ika fi ghayri darra'a mudirratin wa la fitnatin mudillah, wa a'udhu bika an adhlima aw udhlam, aw a'tadiya aw yu'tada 'alayy, aw aksiba khati'atan aw dhanban la taghfiruh.","en":"O Allah, I ask You for contentment after Your decree, for an easy life after death, for the joy of looking at Your Face, and for longing to meet You, without any harmful hardship or misleading trial. I seek refuge in You from wronging others or being wronged, from transgressing or being transgressed against, and from committing a sin or a wrong that You will not forgive.","ref":null,"q":null,"source":"al-Hakim, Ahmad, Tabarani (al-Kabir)","page":"pp. 43–44","status":"draft"},
{"n":93,"ar":"اَللّٰهُمَّ زَيِّنَّا بِزِينَةِ الْإِيمَانِ، وَاجْعَلْنَا هُدَاةً مُّهْتَدِينَ.","tr":"Allahumma zayyinna bizinatil-iman, waj'alna hudatan muhtadin.","en":"O Allah, adorn us with the beauty of faith, and make us guides who are themselves rightly guided.","ref":null,"q":null,"source":"— (Nomani prints this line but notes that it is missing from an older printed copy and from al-Hisn. Dawud has it.)","page":"p. 44","status":"draft"},
{"n":94,"ar":"اَللّٰهُمَّ فَاطِرَ السَّمٰوٰتِ وَالْأَرْضِ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ ذَا الْجَلَالِ وَالْإِكْرَامِ، فَإِنِّي أَعْهَدُ إِلَيْكَ فِي هٰذِهِ الْحَيٰوةِ الدُّنْيَا، وَأُشْهِدُكَ وَكَفٰى بِكَ شَهِيدًا، أَنِّي أَشْهَدُ أَنْ لَّا إِلٰهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ، لَكَ الْمُلْكُ وَلَكَ الْحَمْدُ وَأَنْتَ عَلٰى كُلِّ شَيْءٍ قَدِيرٌ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ، وَأَشْهَدُ أَنَّ وَعْدَكَ حَقٌّ، وَلِقَاءَكَ حَقٌّ، وَالسَّاعَةَ آتِيَةٌ لَّا رَيْبَ فِيهَا، وَأَنَّكَ تَبْعَثُ مَنْ فِي الْقُبُورِ، وَأَنَّكَ إِنْ تَكِلْنِي إِلٰى نَفْسِي تَكِلْنِي إِلٰى ضَعْفٍ وَّعَوْرَةٍ وَّذَنْبٍ وَّخَطِيئَةٍ، وَإِنِّي لَا أَثِقُ إِلَّا بِرَحْمَتِكَ، فَاغْفِرْ لِي ذُنُوبِي كُلَّهَا، إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ.","tr":"Allahumma fatiras-samawati wal-ardi 'alimal-ghaybi wash-shahadati dhal-jalali wal-ikram, fa-inni a'hadu ilayka fi hadhihil-hayatid-dunya, wa ushhiduka wa kafa bika shahida, anni ashhadu an la ilaha illa anta wahdaka la sharika lak, lakal-mulku wa lakal-hamdu wa anta 'ala kulli shay'in qadir, wa ashhadu anna Muhammadan 'abduka wa rasuluk, wa ashhadu anna wa'daka haqq, wa liqa'aka haqq, was-sa'ata atiyatun la rayba fiha, wa annaka tab'athu man fil-qubur, wa annaka in takilni ila nafsi takilni ila da'fin wa 'awratin wa dhanbin wa khati'ah, wa inni la athiqu illa birahmatik, faghfir li dhunubi kullaha, innahu la yaghfirudh-dhunuba illa ant, wa tub 'alayya innaka antat-tawwabur-rahim.","en":"O Allah, Originator of the heavens and the earth, Knower of the unseen and the seen, Lord of majesty and honour: I make this pledge to You in this worldly life, and I call You to witness, and You are enough as a witness, that I bear witness that there is no god but You alone, with no partner. Yours is the kingdom and Yours is the praise, and You have power over all things. I bear witness that Muhammad is Your servant and Messenger. I bear witness that Your promise is true and that meeting You is true, that the Hour is coming without any doubt, and that You will raise those in the graves. If You leave me to myself, You leave me to weakness, exposure, sin and error. I trust only in Your mercy, so forgive me all my sins, for no one forgives sins but You, and accept my repentance; You are the Accepter of repentance, the Most Merciful.","ref":null,"q":null,"source":null,"page":"pp. 44–45","status":"draft"},
{"n":95,"ar":"اَللّٰهُمَّ إِنِّي أَسْأَلُكَ صِحَّةً فِي إِيمَانٍ، وَإِيمَانًا فِي حُسْنِ خُلُقٍ، وَنَجَاةً يَّتْبَعُهَا فَلَاحٌ، وَرَحْمَةً مِّنْكَ وَعَافِيَةً، وَمَغْفِرَةً مِّنْكَ وَرِضْوَانًا.","tr":"Allahumma inni as'aluka sihhatan fi iman, wa imanan fi husni khuluq, wa najatan yatba'uha falah, wa rahmatan minka wa 'afiyah, wa maghfiratan minka wa ridwana.","en":"O Allah, I ask You for soundness in faith, faith joined with good character, a rescue followed by lasting success, mercy and well-being from You, and forgiveness and good pleasure from You.","ref":null,"q":null,"source":"Tabarani (al-Awsat)","page":"p. 45","status":"draft"},
{"n":96,"ar":"اَللّٰهُمَّ إِنِّي أَعُوذُ بِوَجْهِكَ الْكَرِيمِ وَبِكَلِمَاتِكَ التَّامَّةِ مِنْ شَرِّ مَا أَنْتَ آخِذٌ بِنَاصِيَتِهِ.","tr":"Allahumma inni a'udhu biwajhikal-karimi wa bikalimatikat-tammati min sharri ma anta akhidhun binasiyatih.","en":"O Allah, I seek refuge in Your noble Face and Your perfect words from the evil of every creature whose forelock You hold.","ref":null,"q":null,"source":"Abu Dawud, Nasaʾi, Ibn Abi Shayba (the bedtime adhkar). Nomani gives no separate footnote for nos. 97–98, which continue the same narration.","page":"p. 45","status":"draft"},
{"n":97,"ar":"اَللّٰهُمَّ أَنْتَ تَكْشِفُ الْمَغْرَمَ وَالْمَأْثَمَ.","tr":"Allahumma anta takshiful-maghrama wal-ma'tham.","en":"O Allah, You are the one who removes debt and sin.","ref":null,"q":null,"source":"see no. 96","page":"p. 45","status":"draft"},
{"n":98,"ar":"اَللّٰهُمَّ لَا يُهْزَمُ جُنْدُكَ، وَلَا يُخْلَفُ وَعْدُكَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ، سُبْحَانَكَ وَبِحَمْدِكَ، لَا إِلٰهَ إِلَّا أَنْتَ لَا شَرِيكَ لَكَ، سُبْحَانَكَ.","tr":"Allahumma la yuhzamu junduk, wa la yukhlafu wa'duk, wa la yanfa'u dhal-jaddi minkal-jadd, subhanaka wa bihamdik, la ilaha illa anta la sharika lak, subhanak.","en":"O Allah, Your army is never defeated and Your promise is never broken. No one's fortune avails him against You. Glory be to You and praise be to You. There is no god but You, with no partner. Glory be to You.","ref":null,"q":null,"source":"see no. 96","page":"pp. 45–46","status":"draft"},
{"n":99,"ar":"اَللّٰهُمَّ أَسْتَغْفِرُكَ لِذَنْبِي، وَأَسْأَلُكَ رَحْمَتَكَ.","tr":"Allahumma astaghfiruka lidhanbi, wa as'aluka rahmatak.","en":"O Allah, I ask Your forgiveness for my sin, and I ask You for Your mercy.","ref":null,"q":null,"source":"Abu Dawud, Tirmidhi, Nasaʾi, Ibn Hibban, al-Hakim (on waking at night). The footnote covers nos. 99–100.","page":"p. 46","status":"draft"},
{"n":100,"ar":"اَللّٰهُمَّ زِدْنِي عِلْمًا، وَلَا تُزِغْ قَلْبِي بَعْدَ إِذْ هَدَيْتَنِي، وَهَبْ لِي مِنْ لَّدُنْكَ رَحْمَةً، إِنَّكَ أَنْتَ الْوَهَّابُ.","tr":"Allahumma zidni 'ilma, wa la tuzigh qalbi ba'da idh hadaytani, wa hab li min ladunka rahmah, innaka antal-wahhab.","en":"O Allah, increase me in knowledge. Do not let my heart swerve after You have guided me, and grant me mercy from Yourself. You are the Bestower.","ref":"none (echoes Ṭā Hā 20:114 and Āl ʿImrān 3:8, in the first person singular)","q":null,"source":"see no. 99","page":"p. 46","status":"draft"},
{"n":101,"ar":"اَللّٰهُمَّ اغْفِرْ لِي ذَنْبِي، وَوَسِّعْ لِي فِي دَارِي، وَبَارِكْ لِي فِي رِزْقِي.","tr":"Allahummagh-fir li dhanbi, wa wassi' li fi dari, wa barik li fi rizqi.","en":"O Allah, forgive my sin, give me room in my home, and bless me in my provision.","ref":null,"q":null,"source":"Nasaʾi, Ibn al-Sunni (adhkar of wudu)","page":"p. 46","status":"draft"},
{"n":102,"ar":"اَللّٰهُمَّ اجْعَلْنِي مِنَ التَّوَّابِينَ، وَاجْعَلْنِي مِنَ الْمُتَطَهِّرِينَ.","tr":"Allahummaj-'alni minat-tawwabin, waj'alni minal-mutatahhirin.","en":"O Allah, make me one of those who turn to You in repentance, and one of those who keep themselves pure.","ref":null,"q":null,"source":"Tirmidhi","page":"p. 46","status":"draft"},
{"n":103,"ar":"اَللّٰهُمَّ رَبَّ السَّمٰوٰتِ وَرَبَّ الْأَرْضِ وَرَبَّ الْعَرْشِ الْعَظِيمِ، رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، فَالِقَ الْحَبِّ وَالنَّوٰى، وَمُنْزِلَ التَّوْرٰىةِ وَالْإِنْجِيلِ وَالْفُرْقَانِ، أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أَنْتَ آخِذٌ بِنَاصِيَتِهِ.","tr":"Allahumma rabbas-samawati wa rabbal-ardi wa rabbal-'arshil-'adhim, rabbana wa rabba kulli shay', faliqal-habbi wan-nawa, wa munzilat-tawrati wal-injili wal-furqan, a'udhu bika min sharri kulli shay'in anta akhidhun binasiyatih.","en":"O Allah, Lord of the heavens, Lord of the earth and Lord of the mighty Throne, our Lord and Lord of all things, who splits the grain and the date-stone, who sent down the Torah, the Gospel and the Criterion: I seek refuge in You from the evil of everything whose forelock You hold.","ref":null,"q":null,"source":"Muslim, the four Sunan, Ibn Abi Shayba, Abu Yaʿla (bedtime adhkar). The footnote covers nos. 103–104.","page":"pp. 46–47","status":"draft"},
{"n":104,"ar":"اَللّٰهُمَّ أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الْآخِرُ فَلَيْسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اِقْضِ عَنَّا الدَّيْنَ، وَأَغْنِنَا عَنِ الْفَقْرِ.","tr":"Allahumma antal-awwalu falaysa qablaka shay', wa antal-akhiru falaysa ba'daka shay', wa antadh-dhahiru falaysa fawqaka shay', wa antal-batinu falaysa dunaka shay', iqdi 'annad-dayna wa aghnina 'anil-faqr.","en":"O Allah, You are the First, and there is nothing before You. You are the Last, and there is nothing after You. You are the Manifest, and there is nothing above You. You are the Hidden, and there is nothing beyond You. Settle our debts for us, and free us from poverty.","ref":null,"q":null,"source":"see no. 103","page":"p. 47","status":"draft"},
{"n":105,"ar":"اَللّٰهُمَّ رَبَّ السَّمٰوٰتِ السَّبْعِ وَمَا أَظَلَّتْ، وَرَبَّ الْأَرَضِينَ وَمَا أَقَلَّتْ، وَرَبَّ الشَّيٰطِينِ وَمَا أَضَلَّتْ، كُنْ لِّي جَارًا مِّنْ شَرِّ خَلْقِكَ أَجْمَعِينَ أَنْ يَّفْرُطَ عَلَيَّ أَحَدٌ مِّنْهُمْ أَوْ أَنْ يَّطْغٰى، عَزَّ جَارُكَ، وَتَبَارَكَ اسْمُكَ.","tr":"Allahumma rabbas-samawatis-sab'i wa ma adhallat, wa rabbal-aradina wa ma aqallat, wa rabbash-shayatini wa ma adallat, kun li jaran min sharri khalqika ajma'in an yafruta 'alayya ahadun minhum aw an yatgha, 'azza jaruk, wa tabarakas-muk.","en":"O Allah, Lord of the seven heavens and all they shade, Lord of the earths and all they carry, Lord of the devils and all they lead astray: be my protector against the evil of all Your creation, so that none of them rushes at me or oppresses me. Mighty is the one You protect, and blessed is Your name.","ref":null,"q":null,"source":"Tabarani (al-Awsat), Ibn Abi Shayba (Musannaf)","page":"p. 47","status":"draft"},
{"n":106,"ar":"اَللّٰهُمَّ لَكَ الْحَمْدُ، أَنْتَ قَيِّمُ السَّمٰوٰتِ وَالْأَرْضِ وَمَنْ فِيهِنَّ، وَلَكَ الْحَمْدُ، أَنْتَ مَلِكُ السَّمٰوٰتِ وَالْأَرْضِ وَمَنْ فِيهِنَّ، وَلَكَ الْحَمْدُ، أَنْتَ نُورُ السَّمٰوٰتِ وَالْأَرْضِ وَمَنْ فِيهِنَّ، وَلَكَ الْحَمْدُ، أَنْتَ الْحَقُّ، وَوَعْدُكَ حَقٌّ، وَلِقَاؤُكَ حَقٌّ، وَقَوْلُكَ حَقٌّ، وَالْجَنَّةُ حَقٌّ، وَالنَّارُ حَقٌّ، وَالنَّبِيُّونَ حَقٌّ، وَمُحَمَّدٌ رَّسُولُ اللّٰهِ حَقٌّ، وَالسَّاعَةُ حَقٌّ.","tr":"Allahumma lakal-hamd, anta qayyimus-samawati wal-ardi wa man fihinn, wa lakal-hamd, anta malikus-samawati wal-ardi wa man fihinn, wa lakal-hamd, anta nurus-samawati wal-ardi wa man fihinn, wa lakal-hamd, antal-haqq, wa wa'duka haqq, wa liqa'uka haqq, wa qawluka haqq, wal-jannatu haqq, wan-naru haqq, wan-nabiyyuna haqq, wa Muhammadun rasulullahi haqq, was-sa'atu haqq.","en":"O Allah, to You belongs all praise. You are the Sustainer of the heavens and the earth and all within them. To You belongs all praise; You are the King of the heavens and the earth and all within them. To You belongs all praise; You are the Light of the heavens and the earth and all within them. To You belongs all praise; You are the Truth. Your promise is true, meeting You is true, Your word is true, Paradise is true, the Fire is true, the prophets are true, Muhammad the Messenger of Allah is true, and the Hour is true.","ref":null,"q":null,"source":"Abu ʿAwana","page":"pp. 47–48","status":"draft"},
{"n":107,"ar":"اَللّٰهُمَّ لَكَ أَسْلَمْتُ، وَبِكَ آمَنْتُ، وَعَلَيْكَ تَوَكَّلْتُ، وَإِلَيْكَ أَنَبْتُ، وَبِكَ خَاصَمْتُ، وَإِلَيْكَ حَاكَمْتُ، وَأَنْتَ رَبُّنَا وَإِلَيْكَ الْمَصِيرُ، فَاغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ، وَمَا أَسْرَفْتُ، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ، لَا إِلٰهَ إِلَّا أَنْتَ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللّٰهِ.","tr":"Allahumma laka aslamt, wa bika amant, wa 'alayka tawakkalt, wa ilayka anabt, wa bika khasamt, wa ilayka hakamt, wa anta rabbuna wa ilaykal-masir, faghfir li ma qaddamtu wa ma akhkhart, wa ma asrartu wa ma a'lant, wa ma asraft, wa ma anta a'lamu bihi minni, antal-muqaddimu wa antal-mu'akhkhir, la ilaha illa ant, wa la hawla wa la quwwata illa billah.","en":"O Allah, to You I have submitted, in You I have believed, on You I have relied, to You I have turned, by Your help I have argued, and to You I have brought my case for judgement. You are our Lord, and to You is the return. So forgive me what I have done before and what I have left for later, what I have hidden and what I have done openly, where I have gone too far, and what You know better than I do. You are the one who brings forward and the one who holds back. There is no god but You, and there is no power and no strength except through Allah.","ref":null,"q":null,"source":"Bukhari; Muslim, Abu Dawud, Tirmidhi, Ibn Hibban, Nasaʾi (for «وَمَا أَسْرَفْتُ»); the collections (al-Jamaʿa) and Abu ʿAwana (for «لَا إِلٰهَ إِلَّا أَنْتَ»); Bukhari (for «وَلَا حَوْلَ…»)","page":"pp. 48–49","status":"draft"},
{"n":108,"ar":"اَللّٰهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَعَافِنِي وَاهْدِنِي وَارْزُقْنِي وَاجْبُرْنِي وَارْفَعْنِي، إِنِّي لِمَا أَنْزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيرٌ.","tr":"Allahummagh-fir li warhamni wa 'afini wahdini warzuqni wajburni warfa'ni, inni lima anzalta ilayya min khayrin faqir.","en":"O Allah, forgive me, have mercy on me, grant me well-being, guide me, provide for me, mend what is broken in me and raise me up. I am in need of whatever good You send down to me.","ref":"none (ends with al-Qaṣaṣ 28:24, end)","q":null,"source":"Abu Dawud, Tirmidhi, Ibn Majah, al-Hakim, Bayhaqi (al-Sunan al-Kubra) (the dua between the two prostrations)","page":"p. 49","status":"draft"},
{"n":109,"ar":"اَللّٰهُمَّ رَبَّ جِبْرَئِيلَ وَمِيكَائِيلَ وَإِسْرَافِيلَ، فَاطِرَ السَّمٰوٰتِ وَالْأَرْضِ، عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ، اِهْدِنِي لِمَا اخْتُلِفَ فِيهِ مِنَ الْحَقِّ بِإِذْنِكَ، إِنَّكَ تَهْدِي مَنْ تَشَاءُ إِلٰى صِرَاطٍ مُّسْتَقِيمٍ.","tr":"Allahumma rabba Jibra'ila wa Mika'ila wa Israfil, fatiras-samawati wal-ard, 'alimal-ghaybi wash-shahadah, anta tahkumu bayna 'ibadika fima kanu fihi yakhtalifun, ihdini limakh-tulifa fihi minal-haqqi bi-idhnik, innaka tahdi man tasha'u ila siratin mustaqim.","en":"O Allah, Lord of Jibril, Mika'il and Israfil, Originator of the heavens and the earth, Knower of the unseen and the seen: You judge between Your servants in what they used to differ about. Guide me, by Your leave, to the truth in whatever has been disputed. You guide whom You will to a straight path.","ref":"none (echoes al-Zumar 39:46 and al-Baqara 2:213)","q":null,"source":"Muslim, the four Sunan, Ibn Hibban (the opening dua of the night prayer)","page":"p. 49","status":"draft"}]},{"manzil":2,"day":"Sunday","dayAr":"يوم الأحد","duas":[{"n":1,"ar":"اَللّٰهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ، وَعَافِنِي فِيمَنْ عَافَيْتَ، وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لِي فِيمَا أَعْطَيْتَ، وَقِنِي شَرَّ مَا قَضَيْتَ، فَإِنَّكَ تَقْضِي وَلَا يُقْضٰى عَلَيْكَ، إِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ، تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ، نَسْتَغْفِرُكَ وَنَتُوبُ إِلَيْكَ، وَصَلَّى اللّٰهُ عَلَى النَّبِيِّ.","tr":"Allāhumma-hdinī fīman hadayt, wa ʿāfinī fīman ʿāfayt, wa tawallanī fīman tawallayt, wa bārik lī fīmā aʿṭayt, wa qinī sharra mā qaḍayt, fa-innaka taqḍī wa lā yuqḍā ʿalayk, innahū lā yadhillu man wālayt, wa lā yaʿizzu man ʿādayt, tabārakta rabbanā wa taʿālayt, nastaghfiruka wa natūbu ilayk, wa ṣalla-llāhu ʿala-n-nabiyy.","en":"O Allah, guide me among those You have guided. Grant me well-being among those You have granted well-being. Take me into Your care among those You have taken into Your care. Bless me in what You have given, and shield me from the evil of what You have decreed. For You decree, and no one decrees over You. Whoever You befriend is never humbled, and whoever You oppose is never honoured. Blessed are You, our Lord, and exalted. We ask Your forgiveness and turn to You in repentance. And may Allah send blessings upon the Prophet.","ref":null,"q":null,"source":"the four Sunan, Ibn Ḥibbān, al-Ḥākim, Ibn Abī Shayba; the closing blessing: al-Nasāʾī.","page":null,"status":"draft"},
{"n":2,"ar":"اَللّٰهُمَّ اغْفِرْ لِي وَلِلْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ وَالْمُسْلِمِينَ وَالْمُسْلِمَاتِ، وَأَلِّفْ بَيْنَ قُلُوبِهِمْ، وَأَصْلِحْ ذَاتَ بَيْنِهِمْ، وَانْصُرْهُمْ عَلَى عَدُوِّكَ وَعَدُوِّهِمْ، اَللّٰهُمَّ الْعَنِ الْكَفَرَةَ الَّذِينَ يَصُدُّونَ عَنْ سَبِيلِكَ، وَيُكَذِّبُونَ رُسُلَكَ، وَيُقَاتِلُونَ أَوْلِيَاءَكَ، اَللّٰهُمَّ خَالِفْ بَيْنَ كَلِمَتِهِمْ، وَزَلْزِلْ أَقْدَامَهُمْ، وَأَنْزِلْ بِهِمْ بَأْسَكَ الَّذِي لَا تَرُدُّهُ عَنِ الْقَوْمِ الْمُجْرِمِينَ.","tr":"Allāhumma-ghfir lī wa lil-mu'minīna wal-mu'mināti wal-muslimīna wal-muslimāt, wa allif bayna qulūbihim, wa aṣliḥ dhāta baynihim, wanṣurhum ʿalā ʿaduwwika wa ʿaduwwihim. Allāhumma-lʿani-l-kafarata-lladhīna yaṣuddūna ʿan sabīlik, wa yukadhdhibūna rusulak, wa yuqātilūna awliyā'ak. Allāhumma khālif bayna kalimatihim, wa zalzil aqdāmahum, wa anzil bihim ba'saka-lladhī lā taruddu-hū ʿani-l-qawmi-l-mujrimīn.","en":"O Allah, forgive me and the believing men and women and the Muslim men and women. Bring their hearts together, set right what is between them, and help them against Your enemy and theirs. O Allah, curse the disbelievers who bar others from Your path, deny Your messengers and fight Your friends. O Allah, divide their word, shake their footing, and send down on them Your punishment, which You do not turn back from the criminal people.","ref":null,"q":null,"source":"al-Bayhaqī, al-Sunan al-Kubrā (from ʿUmar).","page":null,"status":"draft"},
{"n":3,"ar":"بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيمِ، اَللّٰهُمَّ إِنَّا نَسْتَعِينُكَ وَنَسْتَغْفِرُكَ وَنَسْتَهْدِيكَ وَنُؤْمِنُ بِكَ وَنَتُوبُ إِلَيْكَ وَنَتَوَكَّلُ عَلَيْكَ وَنُثْنِي عَلَيْكَ الْخَيْرَ وَنَشْكُرُكَ وَلَا نَكْفُرُكَ، وَنَخْلَعُ وَنَتْرُكُ مَنْ يَفْجُرُكَ، اَللّٰهُمَّ إِيَّاكَ نَعْبُدُ، وَلَكَ نُصَلِّي وَنَسْجُدُ، وَإِلَيْكَ نَسْعٰى وَنَحْفِدُ، وَنَرْجُو رَحْمَتَكَ وَنَخْشٰى عَذَابَكَ الْجِدَّ، إِنَّ عَذَابَكَ الْجِدَّ بِالْكُفَّارِ مُلْحِقٌ.","tr":"Bismi-llāhi-r-raḥmāni-r-raḥīm. Allāhumma innā nastaʿīnuka wa nastaghfiruka wa nastahdīka wa nu'minu bika wa natūbu ilayka wa natawakkalu ʿalayka wa nuthnī ʿalayka-l-khayra wa nashkuruka wa lā nakfuruk, wa nakhlaʿu wa natruku man yafjuruk. Allāhumma iyyāka naʿbud, wa laka nuṣallī wa nasjud, wa ilayka nasʿā wa naḥfid, wa narjū raḥmataka wa nakhshā ʿadhābaka-l-jidd, inna ʿadhābaka-l-jidda bil-kuffāri mulḥiq.","en":"In the name of Allah, the Most Merciful, the Most Kind. O Allah, we ask Your help, Your forgiveness and Your guidance. We believe in You, turn to You in repentance and rely on You. We praise You with good, we thank You and we are not ungrateful to You. We cast off and leave whoever disobeys You. O Allah, You alone we worship; to You we pray and bow down; to You we hasten and strive. We hope for Your mercy and fear Your real punishment. Your real punishment will surely overtake the disbelievers.","ref":null,"q":null,"source":"al-Bayhaqī (al-Sunan al-Kubrā), Ibn Abī Shayba, al-Ṭaḥāwī; al-Suyūṭī (al-Durr al-Manthūr).","page":null,"status":"draft"},
{"n":4,"ar":"اَللّٰهُمَّ إِنِّي أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ، وَأَعُوذُ بِكَ مِنْكَ، لَا أُحْصِي ثَنَاءً عَلَيْكَ، أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ.","tr":"Allāhumma innī aʿūdhu bi-riḍāka min sakhaṭik, wa bi-muʿāfātika min ʿuqūbatik, wa aʿūdhu bika mink, lā uḥṣī thanā'an ʿalayk, anta kamā athnayta ʿalā nafsik.","en":"O Allah, I take refuge in Your pleasure from Your anger, and in Your pardon from Your punishment. I take refuge in You from You. I cannot count Your praises; You are as You have praised Yourself.","ref":null,"q":null,"source":"Muslim and the four Sunan.","page":null,"status":"draft"},
{"n":5,"ar":"اَللّٰهُمَّ رَبَّ جِبْرَئِيلَ وَمِيكَائِيلَ وَإِسْرَافِيلَ وَمُحَمَّدٍ صَلَّى اللّٰهُ عَلَيْهِ وَسَلَّمَ، أَعُوذُ بِكَ مِنَ النَّارِ.","tr":"Allāhumma rabba Jibra'īla wa Mīkā'īla wa Isrāfīla wa Muḥammadin ṣalla-llāhu ʿalayhi wa sallam, aʿūdhu bika mina-n-nār.","en":"O Allah, Lord of Jibrīl, Mīkāʾīl and Isrāfīl, and of Muhammad (Allah bless him and give him peace), I take refuge in You from the Fire.","ref":null,"q":null,"source":"al-Ḥākim, Ibn al-Sunnī.","page":null,"status":"draft"},
{"n":6,"ar":"اَللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ أَنْ أَضِلَّ أَوْ أُضَلَّ، أَوْ أَزِلَّ أَوْ أُزَلَّ، أَوْ أَظْلِمَ أَوْ أُظْلَمَ، أَوْ أَجْهَلَ أَوْ يُجْهَلَ عَلَيَّ.","tr":"Allāhumma innī aʿūdhu bika min an aḍilla aw uḍall, aw azilla aw uzall, aw aẓlima aw uẓlam, aw ajhala aw yujhala ʿalayy.","en":"O Allah, I take refuge in You from going astray or being led astray, from slipping or being made to slip, from wronging or being wronged, and from acting foolishly or being treated foolishly.","ref":null,"q":null,"source":"Abū Dāwūd, Ibn Mājah.","page":null,"status":"draft"},
{"n":7,"ar":"اَللّٰهُمَّ اجْعَلْ فِي قَلْبِي نُورًا، وَفِي بَصَرِي نُورًا، وَفِي سَمْعِي نُورًا، وَعَنْ يَمِينِي نُورًا، وَعَنْ شِمَالِي نُورًا، وَمِنْ خَلْفِي نُورًا، وَمِنْ أَمَامِي نُورًا، وَاجْعَلْ مِنْ فَوْقِي نُورًا، وَمِنْ تَحْتِي نُورًا، اَللّٰهُمَّ أَعْطِنِي نُورًا، وَاجْعَلْ لِي نُورًا، وَفِي عَصَبِي نُورًا، وَفِي لَحْمِي نُورًا، وَفِي دَمِي نُورًا، وَفِي شَعْرِي نُورًا، وَفِي بَشَرِي نُورًا، وَفِي لِسَانِي نُورًا، وَاجْعَلْ فِي نَفْسِي نُورًا، وَأَعْظِمْ لِي نُورًا، وَاجْعَلْنِي نُورًا.","tr":"Allāhumma-jʿal fī qalbī nūrā, wa fī baṣarī nūrā, wa fī samʿī nūrā, wa ʿan yamīnī nūrā, wa ʿan shimālī nūrā, wa min khalfī nūrā, wa min amāmī nūrā, wa-jʿal min fawqī nūrā, wa min taḥtī nūrā. Allāhumma aʿṭinī nūrā, wa-jʿal lī nūrā, wa fī ʿaṣabī nūrā, wa fī laḥmī nūrā, wa fī damī nūrā, wa fī shaʿrī nūrā, wa fī basharī nūrā, wa fī lisānī nūrā, wa-jʿal fī nafsī nūrā, wa aʿẓim lī nūrā, wa-jʿalnī nūrā.","en":"O Allah, place light in my heart, light in my sight and light in my hearing. Place light on my right, light on my left, light behind me and light before me. Place light above me and light beneath me. O Allah, give me light and make light for me: light in my sinews, my flesh, my blood, my hair and my skin, and light on my tongue. Place light in my soul, make my light great, and make me light.","ref":null,"q":null,"source":"al-Bukhārī, Muslim, Abū Dāwūd, al-Nasāʾī, Ibn Mājah; some of the added phrases: Muslim, al-Ḥākim.","page":null,"status":"draft"},
{"n":8,"ar":"اَللّٰهُمَّ افْتَحْ لَنَا أَبْوَابَ رَحْمَتِكَ، وَسَهِّلْ لَنَا أَبْوَابَ رِزْقِكَ.","tr":"Allāhumma-ftaḥ lanā abwāba raḥmatik, wa sahhil lanā abwāba rizqik.","en":"O Allah, open for us the doors of Your mercy, and make easy for us the doors of Your provision.","ref":null,"q":null,"source":"Ibn Mājah, Abū ʿAwāna.","page":null,"status":"draft"},
{"n":9,"ar":"اَللّٰهُمَّ اعْصِمْنِي مِنَ الشَّيْطَانِ الرَّجِيمِ.","tr":"Allāhumma-ʿṣimnī mina-sh-shayṭāni-r-rajīm.","en":"O Allah, protect me from Satan, the outcast.","ref":null,"q":null,"source":"al-Nasāʾī, Ibn Mājah, Ibn Ḥibbān, al-Ḥākim, Ibn al-Sunnī.","page":null,"status":"draft"},
{"n":10,"ar":"اَللّٰهُمَّ اهْدِنِي لِأَحْسَنِ الْأَخْلَاقِ، لَا يَهْدِي لِأَحْسَنِهَا إِلَّا أَنْتَ، وَاصْرِفْ عَنِّي سَيِّئَهَا، لَا يَصْرِفُ عَنِّي سَيِّئَهَا إِلَّا أَنْتَ.","tr":"Allāhumma-hdinī li-aḥsani-l-akhlāq, lā yahdī li-aḥsanihā illā ant, waṣrif ʿannī sayyi'ahā, lā yaṣrifu ʿannī sayyi'ahā illā ant.","en":"O Allah, guide me to the best of character; no one guides to the best of it but You. Turn its bad away from me; no one turns its bad away from me but You.","ref":null,"q":null,"source":"Muslim, the four Sunan, Ibn Ḥibbān, al-Ṭabarānī.","page":null,"status":"draft"},
{"n":11,"ar":"اَللّٰهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ.","tr":"Allāhumma bāʿid baynī wa bayna khaṭāyāya kamā bāʿadta bayna-l-mashriqi wal-maghrib.","en":"O Allah, put a distance between me and my sins, as You have put a distance between the East and the West.","ref":null,"q":null,"source":"al-Bukhārī, Muslim, Abū Dāwūd, al-Nasāʾī, Ibn Mājah.","page":null,"status":"draft"},
{"n":12,"ar":"اَللّٰهُمَّ اغْسِلْ خَطَايَايَ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ، وَنَقِّنِي مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنَ الدَّنَسِ.","tr":"Allāhumma-ghsil khaṭāyāya bil-mā'i wa-th-thalji wal-barad, wa naqqinī mina-l-khaṭāyā kamā naqqayta-th-thawba-l-abyaḍa mina-d-danas.","en":"O Allah, wash away my sins with water, snow and hail. Cleanse me of sins as You have cleansed a white garment of dirt.","ref":null,"q":null,"source":"al-Ṭabarānī (al-Muʿjam al-Kabīr and al-Awsaṭ).","page":null,"status":"draft"},
{"n":13,"ar":"اَللّٰهُمَّ لَكَ الْحَمْدُ مِلْءَ السَّمٰوٰتِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا بَيْنَهُمَا وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ، أَهْلُ الثَّنَاءِ وَالْكِبْرِيَاءِ وَالْمَجْدِ، أَحَقُّ مَا قَالَ الْعَبْدُ، وَكُلُّنَا لَكَ عَبْدٌ، لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا رَادَّ لِمَا قَضَيْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ.","tr":"Allāhumma laka-l-ḥamdu mil'a-s-samāwāti wa mil'a-l-arḍi wa mil'a mā baynahumā wa mil'a mā shi'ta min shay'in baʿd, ahlu-th-thanā'i wal-kibriyā'i wal-majd, aḥaqqu mā qāla-l-ʿabd, wa kullunā laka ʿabd. Lā māniʿa limā aʿṭayt, wa lā muʿṭiya limā manaʿt, wa lā rādda limā qaḍayt, wa lā yanfaʿu dha-l-jaddi minka-l-jadd.","en":"O Allah, to You belongs praise filling the heavens, filling the earth, filling all that is between them, and filling whatever else You will. You are worthy of praise, majesty and glory. This is the truest thing a servant has said, and we are all Your servants. No one can hold back what You give, no one can give what You hold back, and no one can turn back what You decree. A man's wealth or standing is of no use to him against You.","ref":null,"q":null,"source":"Muslim, Abū Dāwūd, al-Tirmidhī, al-Nasāʾī, Ibn Mājah; the phrase «ولا رادّ لما قضيت»: al-Bazzār.","page":null,"status":"draft"},
{"n":14,"ar":"اَللّٰهُمَّ اغْفِرْ لِي ذَنْبِي كُلَّهُ، دِقَّهُ وَجِلَّهُ، وَأَوَّلَهُ وَآخِرَهُ، وَعَلَانِيَتَهُ وَسِرَّهُ.","tr":"Allāhumma-ghfir lī dhanbī kullah, diqqahū wa jillah, wa awwalahū wa ākhirah, wa ʿalāniyatahū wa sirrah.","en":"O Allah, forgive me all my sins: the small and the great, the first and the last, the open and the secret.","ref":null,"q":null,"source":"Muslim, Abū Dāwūd.","page":null,"status":"draft"},
{"n":15,"ar":"رَبِّ أَعْطِ نَفْسِي تَقْوَاهَا، وَزَكِّهَا أَنْتَ خَيْرُ مَنْ زَكَّاهَا، أَنْتَ وَلِيُّهَا وَمَوْلَاهَا.","tr":"Rabbi aʿṭi nafsī taqwāhā, wa zakkihā anta khayru man zakkāhā, anta waliyyuhā wa mawlāhā.","en":"My Lord, give my soul its God-consciousness and purify it, for You are the best to purify it. You are its Guardian and its Master.","ref":null,"q":null,"source":"Aḥmad.","page":null,"status":"draft"},
{"n":16,"ar":"اَللّٰهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا، وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ، وَارْحَمْنِي، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ.","tr":"Allāhumma innī ẓalamtu nafsī ẓulman kathīrā, wa lā yaghfiru-dh-dhunūba illā ant, fa-ghfir lī maghfiratan min ʿindik, warḥamnī, innaka anta-l-ghafūru-r-raḥīm.","en":"O Allah, I have wronged myself greatly, and no one forgives sins but You. So forgive me with forgiveness from You, and have mercy on me. You are the Forgiving, the Merciful.","ref":null,"q":null,"source":"al-Bukhārī, Muslim, al-Tirmidhī, al-Nasāʾī, Ibn Mājah.","page":null,"status":"draft"},
{"n":17,"ar":"اَللّٰهُمَّ حَاسِبْنِي حِسَابًا يَسِيرًا. اَللّٰهُمَّ إِنِّي أَسْأَلُكَ مِنَ الْخَيْرِ كُلِّهِ مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ، وَأَعُوذُ بِكَ مِنَ الشَّرِّ كُلِّهِ مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ.","tr":"Allāhumma ḥāsibnī ḥisāban yasīrā. Allāhumma innī as'aluka mina-l-khayri kullihī mā ʿalimtu minhu wa mā lam aʿlam, wa aʿūdhu bika mina-sh-sharri kullihī mā ʿalimtu minhu wa mā lam aʿlam.","en":"O Allah, make my reckoning an easy one. O Allah, I ask You for all good, what I know of it and what I do not know, and I take refuge in You from all evil, what I know of it and what I do not know.","ref":null,"q":null,"source":"first sentence: al-Ḥākim; the rest: al-Ṭayālisī, al-Ṭabarānī (al-Kabīr).","page":null,"status":"draft"},
{"n":18,"ar":"اَللّٰهُمَّ إِنِّي أَسْأَلُكَ مِنْ خَيْرِ مَا سَأَلَكَ بِهِ عِبَادُكَ الصَّالِحُونَ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا اسْتَعَاذَكَ مِنْهُ عِبَادُكَ الصَّالِحُونَ.","tr":"Allāhumma innī as'aluka min khayri mā sa'alaka bihī ʿibāduka-ṣ-ṣāliḥūn, wa aʿūdhu bika min sharri ma-staʿādhaka minhu ʿibāduka-ṣ-ṣāliḥūn.","en":"O Allah, I ask You for the best of what Your righteous servants have asked You for, and I take refuge in You from the evil of what Your righteous servants have sought refuge in You from.","ref":null,"q":null,"source":"Ibn Abī Shayba.","page":null,"status":"draft"},
{"n":19,"ar":"رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ.","tr":"Rabbanā ātinā fi-d-dunyā ḥasanatan wa fi-l-ākhirati ḥasanatan wa qinā ʿadhāba-n-nār.","en":"Qurʾān translation from Pickthall.","ref":"al-Baqara 2:201","q":{"s":2,"from":201,"to":201},"source":null,"page":null,"status":"draft"},
{"n":20,"ar":"رَبَّنَا إِنَّنَا آمَنَّا فَاغْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ النَّارِ.","tr":"Rabbanā innanā āmannā fa-ghfir lanā dhunūbanā wa qinā ʿadhāba-n-nār.","en":"Qurʾān translation from Pickthall.","ref":"Āl ʿImrān 3:16","q":{"s":3,"from":16,"to":16},"source":null,"page":null,"status":"draft"},
{"n":21,"ar":"رَبَّنَا وَآتِنَا مَا وَعَدْتَنَا عَلَى رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ الْقِيٰمَةِ، إِنَّكَ لَا تُخْلِفُ الْمِيعَادَ.","tr":"Rabbanā wa ātinā mā waʿattanā ʿalā rusulika wa lā tukhzinā yawma-l-qiyāmah, innaka lā tukhlifu-l-mīʿād.","en":"Qurʾān translation from Pickthall.","ref":"Āl ʿImrān 3:194","q":{"s":3,"from":194,"to":194},"source":null,"page":null,"status":"draft"},
{"n":22,"ar":"اَللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَأَعُوذُ بِكَ مِنَ الْمَأْثَمِ وَالْمَغْرَمِ.","tr":"Allāhumma innī aʿūdhu bika min ʿadhābi jahannam, wa aʿūdhu bika min ʿadhābi-l-qabr, wa aʿūdhu bika min fitnati-l-masīḥi-d-dajjāl, wa aʿūdhu bika min fitnati-l-maḥyā wal-mamāt, wa aʿūdhu bika mina-l-ma'thami wal-maghram.","en":"O Allah, I take refuge in You from the punishment of Hell and from the punishment of the grave. I take refuge in You from the trial of the False Messiah, and from the trials of life and death. I take refuge in You from sin and from debt.","ref":null,"q":null,"source":"Muslim; the final part: al-Bukhārī, Muslim, Abū Dāwūd, al-Nasāʾī.","page":null,"status":"draft"},
{"n":23,"ar":"اَللّٰهُمَّ أَعِنِّي عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ.","tr":"Allāhumma aʿinnī ʿalā dhikrika wa shukrika wa ḥusni ʿibādatik.","en":"O Allah, help me to remember You, to thank You, and to worship You well.","ref":null,"q":null,"source":"Abū Dāwūd, al-Nasāʾī, Ibn Ḥibbān, al-Ḥākim, Ibn al-Sunnī.","page":null,"status":"draft"},
{"n":24,"ar":"اَللّٰهُمَّ رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، أَنَا شَهِيدٌ أَنَّكَ أَنْتَ الرَّبُّ وَحْدَكَ لَا شَرِيكَ لَكَ.","tr":"Allāhumma rabbanā wa rabba kulli shay', ana shahīdun annaka anta-r-rabbu waḥdaka lā sharīka lak.","en":"O Allah, our Lord and Lord of all things, I bear witness that You alone are the Lord; You have no partner.","ref":null,"q":null,"source":"Abū Dāwūd, al-Nasāʾī, Ibn al-Sunnī. One note covers entries 24–27.","page":null,"status":"draft"},
{"n":25,"ar":"اَللّٰهُمَّ رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، أَنَا شَهِيدٌ أَنَّ مُحَمَّدًا صَلَّى اللّٰهُ عَلَيْهِ وَسَلَّمَ عَبْدُكَ وَرَسُولُكَ.","tr":"Allāhumma rabbanā wa rabba kulli shay', ana shahīdun anna Muḥammadan ṣalla-llāhu ʿalayhi wa sallama ʿabduka wa rasūluk.","en":"O Allah, our Lord and Lord of all things, I bear witness that Muhammad (Allah bless him and give him peace) is Your servant and Your messenger.","ref":null,"q":null,"source":"as 24.","page":null,"status":"draft"},
{"n":26,"ar":"اَللّٰهُمَّ رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، أَنَا شَهِيدٌ أَنَّ الْعِبَادَ كُلَّهُمْ إِخْوَةٌ.","tr":"Allāhumma rabbanā wa rabba kulli shay', ana shahīdun anna-l-ʿibāda kullahum ikhwah.","en":"O Allah, our Lord and Lord of all things, I bear witness that all Your servants are brothers.","ref":null,"q":null,"source":"as 24.","page":null,"status":"draft"},
{"n":27,"ar":"اَللّٰهُمَّ رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، اجْعَلْنِي مُخْلِصًا لَكَ وَأَهْلِي فِي كُلِّ سَاعَةٍ فِي الدُّنْيَا وَالْآخِرَةِ، ذَا الْجَلَالِ وَالْإِكْرَامِ، اسْمَعْ وَاسْتَجِبْ، اَللّٰهُ أَكْبَرُ الْأَكْبَرُ، اَللّٰهُ نُورُ السَّمٰوٰتِ وَالْأَرْضِ، اَللّٰهُ أَكْبَرُ الْأَكْبَرُ، حَسْبِيَ اللّٰهُ وَنِعْمَ الْوَكِيلُ، اَللّٰهُ أَكْبَرُ الْأَكْبَرُ.","tr":"Allāhumma rabbanā wa rabba kulli shay'ini-jʿalnī mukhliṣan laka wa ahlī fī kulli sāʿatin fi-d-dunyā wal-ākhirah, dha-l-jalāli wal-ikrām, ismaʿ wa-stajib. Allāhu akbaru-l-akbar. Allāhu nūru-s-samāwāti wal-arḍ. Allāhu akbaru-l-akbar. Ḥasbiya-llāhu wa niʿma-l-wakīl. Allāhu akbaru-l-akbar.","en":"O Allah, our Lord and Lord of all things, make me and my family devoted to You alone at every hour, in this world and the next. O Lord of majesty and generosity, hear and answer. Allah is the Greatest of the great. Allah is the Light of the heavens and the earth. Allah is the Greatest of the great. Allah is enough for me, and He is the best Guardian. Allah is the Greatest of the great.","ref":null,"q":null,"source":"as 24.","page":null,"status":"draft"},
{"n":28,"ar":"اَللّٰهُمَّ أَصْلِحْ لِي دِينِيَ الَّذِي هُوَ عِصْمَةُ أَمْرِي، وَأَصْلِحْ لِي دُنْيَايَ الَّتِي فِيهَا مَعَاشِي، وَأَصْلِحْ لِي آخِرَتِيَ الَّتِي فِيهَا مَعَادِي، وَأَحْيِنِي مَا كَانَتِ الْحَيٰوةُ خَيْرًا لِي، وَتَوَفَّنِي إِذَا كَانَتِ الْوَفَاةُ خَيْرًا لِي، وَاجْعَلِ الْحَيٰوةَ زِيَادَةً لِي فِي كُلِّ خَيْرٍ، وَاجْعَلِ الْمَوْتَ رَاحَةً لِي مِنْ كُلِّ شَرٍّ.","tr":"Allāhumma aṣliḥ lī dīniya-lladhī huwa ʿiṣmatu amrī, wa aṣliḥ lī dunyāya-llatī fīhā maʿāshī, wa aṣliḥ lī ākhiratiya-llatī fīhā maʿādī, wa aḥyinī mā kānati-l-ḥayātu khayran lī, wa tawaffanī idhā kānati-l-wafātu khayran lī, wa-jʿali-l-ḥayāta ziyādatan lī fī kulli khayr, wa-jʿali-l-mawta rāḥatan lī min kulli sharr.","en":"O Allah, set right my religion for me, which is what keeps my affairs safe. Set right my worldly life, in which I make my living, and my Hereafter, to which I return. Keep me alive as long as life is good for me, and take me when death is good for me. Make life an increase for me in every good, and make death a rest for me from every evil.","ref":null,"q":null,"source":"Muslim; the «أحيني… توفني» part: al-Bukhārī, Muslim, Abū Dāwūd, Ibn al-Sunnī.","page":null,"status":"draft"},
{"n":29,"ar":"اَللّٰهُمَّ إِنِّي أَسْأَلُكَ رِزْقًا طَيِّبًا، وَعِلْمًا نَافِعًا، وَعَمَلًا مُتَقَبَّلًا.","tr":"Allāhumma innī as'aluka rizqan ṭayyibā, wa ʿilman nāfiʿā, wa ʿamalan mutaqabbalā.","en":"O Allah, I ask You for good, lawful provision, beneficial knowledge, and deeds that are accepted.","ref":null,"q":null,"source":"al-Ṭabarānī (al-Ṣaghīr), Ibn al-Sunnī.","page":null,"status":"draft"},
{"n":30,"ar":"اَللّٰهُمَّ أَشْبَعْتَ وَأَرْوَيْتَ فَهَنِّئْنَا، وَرَزَقْتَنَا فَأَكْثَرْتَ وَأَطَبْتَ فَزِدْنَا.","tr":"Allāhumma ashbaʿta wa arwayta fa-hanni'nā, wa razaqtanā fa-aktharta wa aṭabta fa-zidnā.","en":"O Allah, You have fed us and given us drink, so let it do us good. You have provided for us generously and well, so give us more.","ref":null,"q":null,"source":"Ibn Abī Shayba.","page":null,"status":"draft"},
{"n":31,"ar":"اَللّٰهُمَّ قَنِّعْنِي بِمَا رَزَقْتَنِي، وَبَارِكْ لِي فِيهِ، وَاخْلُفْ عَلَى كُلِّ غَائِبَةٍ لِي بِخَيْرٍ.","tr":"Allāhumma qanniʿnī bimā razaqtanī, wa bārik lī fīh, wakhluf ʿalā kulli ghā'ibatin lī bi-khayr.","en":"O Allah, make me content with what You have provided for me and bless me in it. Look after with good everything of mine that is out of my reach.","ref":null,"q":null,"source":"al-Ḥākim; Ibn Abī Shayba.","page":null,"status":"draft"},
{"n":32,"ar":"رَبِّ اغْفِرْ وَارْحَمْ، إِنَّكَ أَنْتَ الْأَعَزُّ الْأَكْرَمُ.","tr":"Rabbi-ghfir warḥam, innaka anta-l-aʿazzu-l-akram.","en":"My Lord, forgive and have mercy. You are the Most Mighty, the Most Generous.","ref":null,"q":null,"source":"Ibn Abī Shayba.","page":null,"status":"draft"},
{"n":33,"ar":"اَللّٰهُمَّ اشْرَحْ لِي صَدْرِي، وَيَسِّرْ لِي أَمْرِي، وَأَعُوذُ بِكَ مِنْ وَسَاوِسِ الصَّدْرِ، وَشَتَاتِ الْأَمْرِ، وَفِتْنَةِ الْقَبْرِ.","tr":"Allāhumma-shraḥ lī ṣadrī, wa yassir lī amrī, wa aʿūdhu bika min wasāwisi-ṣ-ṣadr, wa shatāti-l-amr, wa fitnati-l-qabr.","en":"O Allah, open my heart for me and make my affairs easy for me. I take refuge in You from the whisperings of the heart, from scattered affairs, and from the trial of the grave.","ref":null,"q":null,"source":"Ibn Abī Shayba; al-Bayhaqī.","page":null,"status":"draft"},
{"n":34,"ar":"اَللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا يَلِجُ فِي اللَّيْلِ، وَمِنْ شَرِّ مَا يَلِجُ فِي النَّهَارِ، وَمِنْ شَرِّ مَا تَهُبُّ بِهِ الرِّيَاحُ.","tr":"Allāhumma innī aʿūdhu bika min sharri mā yaliju fi-l-layl, wa min sharri mā yaliju fi-n-nahār, wa min sharri mā tahubbu bihi-r-riyāḥ.","en":"O Allah, I take refuge in You from the evil of what enters into the night, the evil of what enters into the day, and the evil of what the winds blow in.","ref":null,"q":null,"source":"this entry has no note of its own; it continues the narration cited at 33.","page":null,"status":"draft"},
{"n":35,"ar":"اَللّٰهُمَّ اهْدِنِي بِالْهُدٰى، وَنَقِّنِي بِالتَّقْوٰى، وَاغْفِرْ لِي فِي الْآخِرَةِ وَالْأُولٰى.","tr":"Allāhumma-hdinī bil-hudā, wa naqqinī bit-taqwā, wa-ghfir lī fi-l-ākhirati wal-ūlā.","en":"O Allah, guide me with guidance, cleanse me with God-consciousness, and forgive me in the Hereafter and in this world.","ref":null,"q":null,"source":"Ibn Abī Shayba.","page":null,"status":"draft"},
{"n":36,"ar":"اَللّٰهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا، وَرِزْقًا وَاسِعًا، وَشِفَاءً مِنْ كُلِّ دَاءٍ.","tr":"Allāhumma innī as'aluka ʿilman nāfiʿā, wa rizqan wāsiʿā, wa shifā'an min kulli dā'.","en":"O Allah, I ask You for beneficial knowledge, ample provision, and healing from every illness.","ref":null,"q":null,"source":"al-Ḥākim.","page":null,"status":"draft"},
{"n":37,"ar":"اَللّٰهُمَّ أَنْتَ عَضُدِي وَنَصِيرِي، بِكَ أَحُولُ، وَبِكَ أَصُولُ، وَبِكَ أُقَاتِلُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِكَ.","tr":"Allāhumma anta ʿaḍudī wa naṣīrī, bika aḥūl, wa bika aṣūl, wa bika uqātil, wa lā ḥawla wa lā quwwata illā bik.","en":"O Allah, You are my support and my helper. By You I move, by You I advance, and by You I fight. There is no power and no strength except through You.","ref":null,"q":null,"source":"Abū Dāwūd, al-Tirmidhī, al-Nasāʾī, Ibn Ḥibbān, Ibn Abī Shayba, Abū ʿAwāna; the closing phrase: al-Nasāʾī.","page":null,"status":"draft"},
{"n":38,"ar":"اَللّٰهُمَّ لَكَ الْحَمْدُ كُلُّهُ، لَا قَابِضَ لِمَا بَسَطْتَ، وَلَا بَاسِطَ لِمَا قَبَضْتَ، وَلَا هَادِيَ لِمَنْ أَضْلَلْتَ، وَلَا مُضِلَّ لِمَنْ هَدَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُقَرِّبَ لِمَا بَاعَدْتَ، وَلَا مُبَاعِدَ لِمَا قَرَّبْتَ.","tr":"Allāhumma laka-l-ḥamdu kulluh, lā qābiḍa limā basaṭt, wa lā bāsiṭa limā qabaḍt, wa lā hādiya liman aḍlalt, wa lā muḍilla liman hadayt, wa lā muʿṭiya limā manaʿt, wa lā māniʿa limā aʿṭayt, wa lā muqarriba limā bāʿadt, wa lā mubāʿida limā qarrabt.","en":"O Allah, all praise belongs to You. No one can withhold what You spread out, and no one can spread out what You withhold. No one can guide whom You send astray, and no one can send astray whom You guide. No one can give what You hold back, and no one can hold back what You give. No one can bring near what You keep far, and no one can keep far what You bring near.","ref":null,"q":null,"source":"al-Nasāʾī, Ibn Ḥibbān, al-Ḥākim. One note covers 38–44, a single narration.","page":null,"status":"draft"},
{"n":39,"ar":"اَللّٰهُمَّ ابْسُطْ عَلَيْنَا مِنْ بَرَكَاتِكَ وَرَحْمَتِكَ وَفَضْلِكَ وَرِزْقِكَ.","tr":"Allāhumma-bsuṭ ʿalaynā min barakātika wa raḥmatika wa faḍlika wa rizqik.","en":"O Allah, spread over us Your blessings, Your mercy, Your favour and Your provision.","ref":null,"q":null,"source":"as 38.","page":null,"status":"draft"},
{"n":40,"ar":"اَللّٰهُمَّ إِنِّي أَسْأَلُكَ النَّعِيمَ الْمُقِيمَ الَّذِي لَا يَحُولُ وَلَا يَزُولُ.","tr":"Allāhumma innī as'aluka-n-naʿīma-l-muqīma-lladhī lā yaḥūlu wa lā yazūl.","en":"O Allah, I ask You for lasting bliss that neither changes nor fades away.","ref":null,"q":null,"source":"as 38.","page":null,"status":"draft"},
{"n":41,"ar":"اَللّٰهُمَّ إِنِّي أَسْأَلُكَ الْأَمْنَ يَوْمَ الْخَوْفِ، اَللّٰهُمَّ إِنِّي عَائِذٌ بِكَ مِنْ شَرِّ مَا أَعْطَيْتَنَا وَمِنْ شَرِّ مَا مَنَعْتَنَا.","tr":"Allāhumma innī as'aluka-l-amna yawma-l-khawf. Allāhumma innī ʿā'idhun bika min sharri mā aʿṭaytanā wa min sharri mā manaʿtanā.","en":"O Allah, I ask You for safety on the Day of Fear. O Allah, I take refuge in You from the evil of what You have given us and the evil of what You have kept from us.","ref":null,"q":null,"source":"as 38.","page":null,"status":"draft"},
{"n":42,"ar":"اَللّٰهُمَّ حَبِّبْ إِلَيْنَا الْإِيمَانَ وَزَيِّنْهُ فِي قُلُوبِنَا، وَكَرِّهْ إِلَيْنَا الْكُفْرَ وَالْفُسُوقَ وَالْعِصْيَانَ، وَاجْعَلْنَا مِنَ الرَّاشِدِينَ.","tr":"Allāhumma ḥabbib ilayna-l-īmāna wa zayyinhu fī qulūbinā, wa karrih ilayna-l-kufra wal-fusūqa wal-ʿiṣyān, wa-jʿalnā mina-r-rāshidīn.","en":"O Allah, make faith beloved to us and beautify it in our hearts. Make disbelief, wickedness and disobedience hateful to us, and make us among the rightly guided.","ref":null,"q":null,"source":"as 38.","page":null,"status":"draft"},
{"n":43,"ar":"اَللّٰهُمَّ تَوَفَّنَا مُسْلِمِينَ، وَأَلْحِقْنَا بِالصَّالِحِينَ، غَيْرَ خَزَايَا وَلَا مَفْتُونِينَ.","tr":"Allāhumma tawaffanā muslimīn, wa alḥiqnā biṣ-ṣāliḥīn, ghayra khazāyā wa lā maftūnīn.","en":"O Allah, let us die as Muslims and join us with the righteous, neither disgraced nor led into trial.","ref":null,"q":null,"source":"as 38.","page":null,"status":"draft"},
{"n":44,"ar":"اَللّٰهُمَّ قَاتِلِ الْكَفَرَةَ الَّذِينَ يُكَذِّبُونَ رُسُلَكَ، وَيَصُدُّونَ عَنْ سَبِيلِكَ، وَاجْعَلْ عَلَيْهِمْ رِجْزَكَ وَعَذَابَكَ، إِلٰهَ الْحَقِّ، آمِينَ.","tr":"Allāhumma qātili-l-kafarata-lladhīna yukadhdhibūna rusulak, wa yaṣuddūna ʿan sabīlik, wa-jʿal ʿalayhim rijzaka wa ʿadhābak, ilāha-l-ḥaqq, āmīn.","en":"O Allah, fight the disbelievers who deny Your messengers and bar others from Your path, and bring Your torment and punishment upon them, O God of truth. Amen.","ref":null,"q":null,"source":"as 38.","page":null,"status":"draft"},
{"n":45,"ar":"اَللّٰهُمَّ مُنْزِلَ الْكِتَابِ، وَمُجْرِيَ السَّحَابِ، وَهَازِمَ الْأَحْزَابِ، اهْزِمْهُمْ وَانْصُرْنَا عَلَيْهِمْ.","tr":"Allāhumma munzila-l-kitāb, wa mujriya-s-saḥāb, wa hāzima-l-aḥzāb, ihzimhum wanṣurnā ʿalayhim.","en":"O Allah, Sender of the Book, Mover of the clouds, Defeater of the confederates, defeat them and give us victory over them.","ref":null,"q":null,"source":"al-Bukhārī, Muslim, Abū Dāwūd.","page":null,"status":"draft"},
{"n":46,"ar":"اَللّٰهُمَّ إِنَّا نَجْعَلُكَ فِي نُحُورِهِمْ، وَنَعُوذُ بِكَ مِنْ شُرُورِهِمْ.","tr":"Allāhumma innā najʿaluka fī nuḥūrihim, wa naʿūdhu bika min shurūrihim.","en":"O Allah, we put You before them as our shield, and we take refuge in You from their evils.","ref":null,"q":null,"source":"Abū Dāwūd, al-Nasāʾī, Ibn Ḥibbān, al-Ḥākim.","page":null,"status":"draft"},
{"n":47,"ar":"اَللّٰهُمَّ رَحْمَتَكَ أَرْجُو، فَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ، لَا إِلٰهَ إِلَّا أَنْتَ، يَا حَيُّ يَا قَيُّومُ، بِرَحْمَتِكَ أَسْتَغِيثُ.","tr":"Allāhumma raḥmataka arjū, fa-lā takilnī ilā nafsī ṭarfata ʿayn, wa aṣliḥ lī sha'nī kullah, lā ilāha illā ant. Yā Ḥayyu yā Qayyūm, bi-raḥmatika astaghīth.","en":"O Allah, it is Your mercy I hope for, so do not leave me to myself even for the blink of an eye. Set right all my affairs for me. There is no god but You. O Ever-Living, O Self-Sustaining, I call on Your mercy for help.","ref":null,"q":null,"source":"Abū Dāwūd, Ibn Ḥibbān, al-Ṭabarānī, Ibn Abī Shayba, Ibn al-Sunnī; «يا حي يا قيوم…»: al-Nasāʾī, al-Ḥākim.","page":null,"status":"draft"},
{"n":48,"ar":"اَللّٰهُمَّ إِنِّي عَبْدُكَ، وَابْنُ عَبْدِكَ، وَابْنُ أَمَتِكَ، نَاصِيَتِي بِيَدِكَ، مَاضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قَضَاؤُكَ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ، سَمَّيْتَ بِهِ نَفْسَكَ، أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ، أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ، أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ، أَنْ تَجْعَلَ الْقُرْآنَ الْعَظِيمَ رَبِيعَ قَلْبِي، وَنُورَ بَصَرِي، وَجَلَاءَ حُزْنِي، وَذَهَابَ هَمِّي.","tr":"Allāhumma innī ʿabduk, wabnu ʿabdik, wabnu amatik, nāṣiyatī bi-yadik, māḍin fiyya ḥukmuk, ʿadlun fiyya qaḍā'uk. As'aluka bi-kulli-smin huwa lak, sammayta bihī nafsak, aw anzaltahū fī kitābik, aw ʿallamtahū aḥadan min khalqik, awi-sta'tharta bihī fī ʿilmi-l-ghaybi ʿindak, an tajʿala-l-Qur'āna-l-ʿaẓīma rabīʿa qalbī, wa nūra baṣarī, wa jalā'a ḥuznī, wa dhahāba hammī.","en":"O Allah, I am Your servant, son of Your servant, son of Your maidservant. My forelock is in Your hand. Your command over me is carried out, and Your decree about me is just. I ask You by every name that is Yours: names You have called Yourself by, sent down in Your Book, taught to any of Your creation, or kept to Yourself in the knowledge of the unseen. Make the Mighty Qurʾān the spring of my heart, the light of my eyes, the removal of my sorrow and the departure of my worry.","ref":null,"q":null,"source":"Aḥmad, Ibn Ḥibbān, al-Ḥākim, Abū Yaʿlā, al-Bazzār, Ibn Abī Shayba, al-Ṭabarānī.","page":null,"status":"draft"},
{"n":49,"ar":"اَللّٰهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا، وَأَنْتَ تَجْعَلُ الْحَزْنَ سَهْلًا إِذَا شِئْتَ.","tr":"Allāhumma lā sahla illā mā jaʿaltahū sahlā, wa anta tajʿalu-l-ḥazna sahlan idhā shi't.","en":"O Allah, nothing is easy except what You make easy, and You make the hard ground easy when You will.","ref":null,"q":null,"source":"Ibn Ḥibbān, Ibn al-Sunnī.","page":null,"status":"draft"},
{"n":50,"ar":"لَا إِلٰهَ إِلَّا اللّٰهُ الْحَلِيمُ الْكَرِيمُ، سُبْحَانَ اللّٰهِ رَبِّ الْعَرْشِ الْعَظِيمِ، اَلْحَمْدُ لِلّٰهِ رَبِّ الْعٰلَمِينَ، أَسْأَلُكَ مُوجِبَاتِ رَحْمَتِكَ، وَعَزَائِمَ مَغْفِرَتِكَ، وَالْعِصْمَةَ مِنْ كُلِّ ذَنْبٍ، وَالْغَنِيمَةَ مِنْ كُلِّ بِرٍّ، وَالسَّلَامَةَ مِنْ كُلِّ إِثْمٍ، لَا تَدَعْ لِي ذَنْبًا إِلَّا غَفَرْتَهُ، وَلَا هَمًّا إِلَّا فَرَّجْتَهُ، وَلَا كَرْبًا إِلَّا نَفَّسْتَهُ، وَلَا ضُرًّا إِلَّا كَشَفْتَهُ، وَلَا حَاجَةً هِيَ لَكَ رِضًا إِلَّا قَضَيْتَهَا، يَا أَرْحَمَ الرَّاحِمِينَ.","tr":"Lā ilāha illa-llāhu-l-ḥalīmu-l-karīm, subḥāna-llāhi rabbi-l-ʿarshi-l-ʿaẓīm, al-ḥamdu lillāhi rabbi-l-ʿālamīn. As'aluka mūjibāti raḥmatik, wa ʿazā'ima maghfiratik, wal-ʿiṣmata min kulli dhanb, wal-ghanīmata min kulli birr, was-salāmata min kulli ithm. Lā tadaʿ lī dhanban illā ghafartah, wa lā hamman illā farrajtah, wa lā karban illā naffastah, wa lā ḍurran illā kashaftah, wa lā ḥājatan hiya laka riḍan illā qaḍaytahā, yā arḥama-r-rāḥimīn.","en":"There is no god but Allah, the Forbearing, the Generous. Glory be to Allah, Lord of the Mighty Throne. Praise be to Allah, Lord of the worlds. I ask You for what brings Your mercy and what makes Your forgiveness certain. I ask You for protection from every sin, a share of every good deed, and safety from every wrong. Leave me no sin You have not forgiven, no worry You have not lifted, no distress You have not relieved, and no harm You have not removed. Leave no need that pleases You unfulfilled, O Most Merciful of the merciful.","ref":null,"q":null,"source":"al-Tirmidhī, al-Ḥākim; Ibn Mājah.","page":null,"status":"draft"}]},{"manzil":3,"day":"Monday","dayAr":"يوم الاثنين","duas":[{"n":1,"ar":"اللّٰهُمَّ ارْحَمْنِي بِتَرْكِ الْمَعَاصِي أَبَدًا مَا أَبْقَيْتَنِي، وَارْحَمْنِي أَنْ أَتَكَلَّفَ مَا لَا يَعْنِينِي، وَارْزُقْنِي حُسْنَ النَّظَرِ فِيمَا يُرْضِيكَ عَنِّي.","tr":"Allahumma-rhamni bi-tarkil-ma'asi abadan ma abqaytani, warhamni an atakallafa ma la ya'nini, warzuqni husnan-nazari fima yurdika 'anni.","en":"O Allah, have mercy on me by helping me leave sins for good, for as long as You keep me alive. Have mercy on me so that I do not take on what does not concern me. Grant me good judgement in what makes You pleased with me.","ref":null,"q":null,"source":"Ḥiṣn (du'a for memorising the Qurʾān); Tirmidhī, al-Ḥākim.","page":null,"status":"draft"},
{"n":2,"ar":"اللّٰهُمَّ بَدِيعَ السَّمٰوٰتِ وَالْأَرْضِ، ذَا الْجَلَالِ وَالْإِكْرَامِ، وَالْعِزَّةِ الَّتِي لَا تُرَامُ، أَسْأَلُكَ يَا اَللّٰهُ يَا رَحْمٰنُ بِجَلَالِكَ وَنُورِ وَجْهِكَ أَنْ تُلْزِمَ قَلْبِي حِفْظَ كِتَابِكَ كَمَا عَلَّمْتَنِي، وَارْزُقْنِي أَنْ أَتْلُوَهُ عَلَى النَّحْوِ الَّذِي يُرْضِيكَ عَنِّي.","tr":"Allahumma badi'as-samawati wal-ard, dhal-jalali wal-ikram, wal-'izzatil-lati la turam, as'aluka ya Allahu ya Rahmanu bi-jalalika wa nuri wajhika an tulzima qalbi hifza kitabika kama 'allamtani, warzuqni an atluwahu 'alan-nahwil-ladhi yurdika 'anni.","en":"O Allah, Originator of the heavens and the earth, Lord of majesty and generosity, and of a might that no one can reach: I ask You, O Allah, O Most Merciful, by Your majesty and the light of Your Face, to make my heart hold fast to Your Book as You have taught it to me. Grant that I recite it in the way that makes You pleased with me.","ref":null,"q":null,"source":"same narration as 1.","page":null,"status":"draft"},
{"n":3,"ar":"اللّٰهُمَّ بَدِيعَ السَّمٰوٰتِ وَالْأَرْضِ، ذَا الْجَلَالِ وَالْإِكْرَامِ، وَالْعِزَّةِ الَّتِي لَا تُرَامُ، أَسْأَلُكَ يَا اَللّٰهُ يَا رَحْمٰنُ بِجَلَالِكَ وَنُورِ وَجْهِكَ أَنْ تُنَوِّرَ بِكِتَابِكَ بَصَرِي، وَأَنْ تُطْلِقَ بِهِ لِسَانِي، وَأَنْ تُفَرِّجَ بِهِ عَنْ قَلْبِي، وَأَنْ تَشْرَحَ بِهِ صَدْرِي، وَأَنْ تَسْتَعْمِلَ بِهِ بَدَنِي، فَإِنَّهُ لَا يُعِينُنِي عَلَى الْحَقِّ غَيْرُكَ، وَلَا يُؤْتِيهِ إِلَّا أَنْتَ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللّٰهِ الْعَلِيِّ الْعَظِيمِ.","tr":"Allahumma badi'as-samawati wal-ard, dhal-jalali wal-ikram, wal-'izzatil-lati la turam, as'aluka ya Allahu ya Rahmanu bi-jalalika wa nuri wajhika an tunawwira bi-kitabika basari, wa an tutliqa bihi lisani, wa an tufarrija bihi 'an qalbi, wa an tashraha bihi sadri, wa an tasta'mila bihi badani, fa-innahu la yu'inuni 'alal-haqqi ghayruk, wa la yu'tihi illa ant, wa la hawla wa la quwwata illa billahil-'aliyyil-'azim.","en":"O Allah, Originator of the heavens and the earth, Lord of majesty and generosity, and of a might that no one can reach: I ask You, O Allah, O Most Merciful, by Your majesty and the light of Your Face, to light up my sight with Your Book. Free my tongue with it, lift the distress from my heart with it, open my chest with it, and put my body to work by it. No one but You helps me to the truth, and no one but You gives it. There is no power and no strength except through Allah, the Most High, the Tremendous.","ref":null,"q":null,"source":"same narration as 1.","page":null,"status":"draft"},
{"n":4,"ar":"اللّٰهُمَّ إِنِّي أَتُوبُ إِلَيْكَ مِنَ الْمَعَاصِي، لَا أَرْجِعُ إِلَيْهَا أَبَدًا.","tr":"Allahumma inni atubu ilayka minal-ma'asi, la arji'u ilayha abada.","en":"O Allah, I turn to You in repentance from sins, and I will never go back to them.","ref":null,"q":null,"source":"Ḥiṣn; al-Ḥākim.","page":null,"status":"draft"},
{"n":5,"ar":"اللّٰهُمَّ مَغْفِرَتُكَ أَوْسَعُ مِنْ ذُنُوبِي، وَرَحْمَتُكَ أَرْجَى عِنْدِي مِنْ عَمَلِي.","tr":"Allahumma maghfiratuka awsa'u min dhunubi, wa rahmatuka arja 'indi min 'amali.","en":"O Allah, Your forgiveness is wider than my sins, and I place more hope in Your mercy than in my own deeds.","ref":null,"q":null,"source":"Ḥiṣn; al-Ḥākim.","page":null,"status":"draft"},
{"n":6,"ar":"اللّٰهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنَّا.","tr":"Allahumma innaka 'afuwwun tuhibbul-'afwa fa'fu 'anna.","en":"O Allah, You are the One who pardons, and You love to pardon, so pardon us.","ref":null,"q":null,"source":"Ḥiṣn (du'a of Laylat al-Qadr); Tirmidhī, Nasāʾī, Ibn Mājah, al-Ḥākim.","page":null,"status":"draft"},
{"n":7,"ar":"اللّٰهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ، وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ.","tr":"Allahumma-kfini bi-halalika 'an haramik, wa aghnini bi-fadlika 'amman siwak.","en":"O Allah, let what You have made lawful be enough for me, so that I need nothing You have forbidden. By Your bounty, make me free of need for anyone but You.","ref":null,"q":null,"source":"Ḥiṣn; Tirmidhī, al-Ḥākim.","page":null,"status":"draft"},
{"n":8,"ar":"اللّٰهُمَّ فَارِجَ الْهَمِّ، كَاشِفَ الْغَمِّ، مُجِيبَ دَعْوَةِ الْمُضْطَرِّينَ، رَحْمٰنَ الدُّنْيَا وَالْآخِرَةِ وَرَحِيمَهُمَا، أَنْتَ تَرْحَمُنِي، فَارْحَمْنِي بِرَحْمَةٍ تُغْنِينِي بِهَا عَنْ رَحْمَةِ مَنْ سِوَاكَ.","tr":"Allahumma farijal-hamm, kashifal-ghamm, mujiba da'watil-mudtarrin, Rahmanad-dunya wal-akhirati wa Rahimahuma, anta tarhamuni, farhamni bi-rahmatin tughnini biha 'an rahmati man siwak.","en":"O Allah, who relieves worry, who removes grief, who answers the call of those in desperate need, Most Merciful and Most Kind in this world and the next: it is You who has mercy on me. So have mercy on me with a mercy that frees me from needing the mercy of anyone besides You.","ref":null,"q":null,"source":"Ḥiṣn; al-Ḥākim, Ibn Marduwayh.","page":null,"status":"draft"},
{"n":9,"ar":"اللّٰهُمَّ رَبَّ السَّمٰوٰتِ وَالْأَرْضِ، عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، إِنِّي أَعْهَدُ إِلَيْكَ فِي هٰذِهِ الْحَيٰوةِ الدُّنْيَا أَنِّي أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ، وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ، فَلَا تَكِلْنِي إِلَى نَفْسِي، فَإِنَّكَ إِنْ تَكِلْنِي إِلَى نَفْسِي تُقَرِّبْنِي مِنَ الشَّرِّ وَتُبَاعِدْنِي مِنَ الْخَيْرِ، وَإِنِّي لَا أَثِقُ إِلَّا بِرَحْمَتِكَ، فَاجْعَلْ لِي عِنْدَكَ عَهْدًا تُوَفِّينِيهِ يَوْمَ الْقِيٰمَةِ، إِنَّكَ لَا تُخْلِفُ الْمِيعَادَ.","tr":"Allahumma rabbas-samawati wal-ard, 'alimal-ghaybi wash-shahadah, inni a'hadu ilayka fi hadhihil-hayatid-dunya anni ashhadu an la ilaha illa anta wahdaka la sharika lak, wa anna Muhammadan 'abduka wa rasuluk, fa-la takilni ila nafsi, fa-innaka in takilni ila nafsi tuqarribni minash-sharri wa tuba'idni minal-khayr, wa inni la athiqu illa bi-rahmatik, faj'al li 'indaka 'ahdan tuwaffinihi yawmal-qiyamah, innaka la tukhliful-mi'ad.","en":"O Allah, Lord of the heavens and the earth, Knower of the unseen and the seen: in this worldly life I give You my pledge that I bear witness that there is no god but You alone, with no partner, and that Muhammad is Your servant and Your Messenger. So do not leave me to myself. If You leave me to myself, You bring me nearer to evil and further from good, and I trust in nothing but Your mercy. So make a covenant for me with You that You will fulfil for me on the Day of Resurrection. You never break Your promise.","ref":null,"q":null,"source":"Ḥiṣn; Aḥmad.","page":null,"status":"draft"},
{"n":10,"ar":"أَسْتَغْفِرُ اللّٰهَ الَّذِي لَا إِلٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ وَأَتُوبُ إِلَيْهِ.","tr":"Astaghfirullahal-ladhi la ilaha illa huwal-Hayyul-Qayyumu wa atubu ilayh.","en":"I ask forgiveness of Allah, besides whom there is no god, the Ever-Living, the Self-Sustaining, and I turn to Him in repentance.","ref":null,"q":null,"source":"Ḥiṣn; Abū Dāwūd, Tirmidhī.","page":null,"status":"draft"},
{"n":11,"ar":"رَبِّ اغْفِرْ لِي وَتُبْ عَلَيَّ، إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ.","tr":"Rabbigh-fir li wa tub 'alayy, innaka antat-Tawwabur-Rahim.","en":"My Lord, forgive me and accept my repentance. You are the One who accepts repentance, the Merciful.","ref":null,"q":null,"source":"Ḥiṣn; the four Sunan, Ibn Ḥibbān.","page":null,"status":"draft"},
{"n":12,"ar":"اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَالْجُبْنِ وَالْهَرَمِ، وَالْمَغْرَمِ وَالْمَأْثَمِ.","tr":"Allahumma inni a'udhu bika minal-'ajzi wal-kasal, wal-jubni wal-haram, wal-maghrami wal-ma'tham.","en":"O Allah, I seek refuge in You from helplessness and laziness, from cowardice and the frailty of old age, and from debt and sin.","ref":null,"q":null,"source":"Ḥiṣn; the six books (al-Jamāʿa).","page":null,"status":"draft"},
{"n":13,"ar":"اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ النَّارِ، وَفِتْنَةِ النَّارِ، وَفِتْنَةِ الْقَبْرِ، وَعَذَابِ الْقَبْرِ، وَشَرِّ فِتْنَةِ الْغِنَى، وَشَرِّ فِتْنَةِ الْفَقْرِ، وَأَعُوذُ بِكَ مِنَ الْقَسْوَةِ وَالْغَفْلَةِ وَالْعَيْلَةِ وَالذِّلَّةِ وَالْمَسْكَنَةِ، وَأَعُوذُ بِكَ مِنَ الْفَقْرِ وَالْكُفْرِ وَالْفُسُوقِ وَالشِّقَاقِ وَالسُّمْعَةِ وَالرِّيَاءِ، وَأَعُوذُ بِكَ مِنَ الصَّمَمِ وَالْبَكَمِ وَالْبَرَصِ وَالْجُنُونِ وَالْجُذَامِ وَسَيِّئِ الْأَسْقَامِ.","tr":"Allahumma inni a'udhu bika min 'adhabin-nar, wa fitnatin-nar, wa fitnatil-qabr, wa 'adhabil-qabr, wa sharri fitnatil-ghina, wa sharri fitnatil-faqr, wa a'udhu bika minal-qaswati wal-ghaflati wal-'aylati wadh-dhillati wal-maskanah, wa a'udhu bika minal-faqri wal-kufri wal-fusuqi wash-shiqaqi was-sum'ati war-riya', wa a'udhu bika minas-samami wal-bakami wal-barasi wal-jununi wal-judhami wa sayyi'il-asqam.","en":"O Allah, I seek refuge in You from the punishment of the Fire and the trial of the Fire, from the trial of the grave and the punishment of the grave, from the evil of the trial of wealth, and from the evil of the trial of poverty. I seek refuge in You from hardness of heart, heedlessness, want, humiliation and wretchedness. I seek refuge in You from poverty, unbelief, wrongdoing, discord, seeking fame and showing off. I seek refuge in You from deafness, muteness, leprosy, madness, elephantiasis and all evil diseases.","ref":null,"q":null,"source":"Ḥiṣn; Ibn Ḥibbān, al-Ḥākim, al-Ṭabarānī (al-Muʿjam al-Ṣaghīr). For the leprosy clause he also cites al-Suyūṭī's al-Jāmiʿ al-Ṣaghīr (al-Ḥākim, al-Bayhaqī).","page":null,"status":"draft"},
{"n":14,"ar":"اللّٰهُمَّ إِنِّي أَعُوذُ بِعِزَّتِكَ، لَا إِلٰهَ إِلَّا أَنْتَ، أَنْ تُضِلَّنِي، أَنْتَ الْحَيُّ الَّذِي لَا يَمُوتُ، وَالْجِنُّ وَالْإِنْسُ يَمُوتُونَ.","tr":"Allahumma inni a'udhu bi-'izzatik, la ilaha illa ant, an tudillani, antal-Hayyul-ladhi la yamut, wal-jinnu wal-insu yamutun.","en":"O Allah, I seek refuge in Your might (there is no god but You) from Your letting me go astray. You are the Ever-Living who does not die, while jinn and humans die.","ref":null,"q":null,"source":"Ḥiṣn; Bukhārī, Muslim, Nasāʾī.","page":null,"status":"draft"},
{"n":15,"ar":"اللّٰهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ جُهْدِ الْبَلَاءِ، وَدَرَكِ الشَّقَاءِ، وَسُوءِ الْقَضَاءِ، وَشَمَاتَةِ الْأَعْدَاءِ.","tr":"Allahumma inna na'udhu bika min juhdil-bala', wa darakish-shaqa', wa su'il-qada', wa shamatatil-a'da'.","en":"O Allah, we seek refuge in You from crushing trials, from being overtaken by misery, from an evil decree, and from enemies gloating over us.","ref":null,"q":null,"source":"Ḥiṣn; Bukhārī.","page":null,"status":"draft"},
{"n":16,"ar":"اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا عَلِمْتُ، وَمِنْ شَرِّ مَا لَمْ أَعْلَمْ.","tr":"Allahumma inni a'udhu bika min sharri ma 'alimtu, wa min sharri ma lam a'lam.","en":"O Allah, I seek refuge in You from the evil of what I know and from the evil of what I do not know.","ref":null,"q":null,"source":"Ḥiṣn; Nasāʾī, Ibn Abī Shayba.","page":null,"status":"draft"},
{"n":17,"ar":"اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا عَمِلْتُ، وَمِنْ شَرِّ مَا لَمْ أَعْمَلْ.","tr":"Allahumma inni a'udhu bika min sharri ma 'amiltu, wa min sharri ma lam a'mal.","en":"O Allah, I seek refuge in You from the evil of what I have done and from the evil of what I have not done.","ref":null,"q":null,"source":"Ḥiṣn; Muslim, Abū Dāwūd, Nasāʾī, Ibn Mājah.","page":null,"status":"draft"},
{"n":18,"ar":"اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ، وَتَحَوُّلِ عَافِيَتِكَ، وَفُجَاءَةِ نِقْمَتِكَ، وَجَمِيعِ سَخَطِكَ.","tr":"Allahumma inni a'udhu bika min zawali ni'matik, wa tahawwuli 'afiyatik, wa fuja'ati niqmatik, wa jami'i sakhatik.","en":"O Allah, I seek refuge in You from the loss of Your blessing, from the turning away of the well-being You give, from Your sudden punishment, and from everything that angers You.","ref":null,"q":null,"source":"Ḥiṣn; Muslim, Abū Dāwūd, Nasāʾī.","page":null,"status":"draft"},
{"n":19,"ar":"اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ سَمْعِي، وَمِنْ شَرِّ بَصَرِي، وَمِنْ شَرِّ لِسَانِي، وَمِنْ شَرِّ قَلْبِي، وَمِنْ شَرِّ مَنِيِّي.","tr":"Allahumma inni a'udhu bika min sharri sam'i, wa min sharri basari, wa min sharri lisani, wa min sharri qalbi, wa min sharri maniyyi.","en":"O Allah, I seek refuge in You from the evil of my hearing, of my sight, of my tongue, of my heart, and of my desire.","ref":null,"q":null,"source":"Ḥiṣn; Tirmidhī, Abū Dāwūd, Nasāʾī, al-Ḥākim.","page":null,"status":"draft"},
{"n":20,"ar":"اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَدْمِ، وَأَعُوذُ بِكَ مِنَ التَّرَدِّي، وَأَعُوذُ بِكَ مِنَ الْغَرَقِ وَالْحَرَقِ وَالْهَرَمِ، وَأَعُوذُ بِكَ مِنْ أَنْ يَتَخَبَّطَنِيَ الشَّيْطَانُ عِنْدَ الْمَوْتِ، وَأَعُوذُ بِكَ مِنْ أَنْ أَمُوتَ فِي سَبِيلِكَ مُدْبِرًا، وَأَعُوذُ بِكَ مِنْ أَنْ أَمُوتَ لَدِيغًا.","tr":"Allahumma inni a'udhu bika minal-hadm, wa a'udhu bika minat-taraddi, wa a'udhu bika minal-gharaqi wal-haraqi wal-haram, wa a'udhu bika min an yatakhabbataniyash-shaytanu 'indal-mawt, wa a'udhu bika min an amuta fi sabilika mudbira, wa a'udhu bika min an amuta ladigha.","en":"O Allah, I seek refuge in You from being crushed under a collapsing building, and from falling from a height. I seek refuge in You from drowning, from burning, and from the frailty of old age. I seek refuge in You from Satan confusing me at the time of death. I seek refuge in You from dying in Your path while running from battle, and from dying of a venomous sting.","ref":null,"q":null,"source":"Ḥiṣn; Abū Dāwūd, Nasāʾī, al-Ḥākim.","page":null,"status":"draft"},
{"n":21,"ar":"اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ مُنْكَرَاتِ الْأَخْلَاقِ وَالْأَعْمَالِ وَالْأَهْوَاءِ وَالْأَدْوَاءِ.","tr":"Allahumma inni a'udhu bika min munkaratil-akhlaqi wal-a'mali wal-ahwa'i wal-adwa'.","en":"O Allah, I seek refuge in You from evil character, evil deeds, evil desires and evil diseases.","ref":null,"q":null,"source":"Ḥiṣn; Tirmidhī, Ibn Ḥibbān, al-Ḥākim.","page":null,"status":"draft"},
{"n":22,"ar":"اللّٰهُمَّ إِنِّي أَسْأَلُكَ مِنْ خَيْرِ مَا سَأَلَكَ مِنْهُ نَبِيُّكَ مُحَمَّدٌ صَلَّى اللّٰهُ عَلَيْهِ وَسَلَّمَ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا اسْتَعَاذَ مِنْهُ نَبِيُّكَ مُحَمَّدٌ صَلَّى اللّٰهُ عَلَيْهِ وَسَلَّمَ، وَأَنْتَ الْمُسْتَعَانُ، وَعَلَيْكَ الْبَلَاغُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللّٰهِ الْعَلِيِّ الْعَظِيمِ.","tr":"Allahumma inni as'aluka min khayri ma sa'alaka minhu nabiyyuka Muhammadun sallallahu 'alayhi wa sallam, wa a'udhu bika min sharri mas-ta'adha minhu nabiyyuka Muhammadun sallallahu 'alayhi wa sallam, wa antal-musta'an, wa 'alaykal-balagh, wa la hawla wa la quwwata illa billahil-'aliyyil-'azim.","en":"O Allah, I ask You for the good that Your Prophet Muhammad ﷺ asked You for, and I seek refuge in You from the evil that Your Prophet Muhammad ﷺ sought refuge from. You are the One whose help is sought, and it is for You to bring us to our goal. There is no power and no strength except through Allah, the Most High, the Tremendous.","ref":null,"q":null,"source":"Ḥiṣn; Tirmidhī.","page":null,"status":"draft"},
{"n":23,"ar":"اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ جَارِ السُّوءِ فِي دَارِ الْمُقَامَةِ، فَإِنَّ جَارَ الْبَادِيَةِ يَتَحَوَّلُ، وَمِنَ الْجُوعِ فَإِنَّهُ بِئْسَ الضَّجِيعُ، وَمِنَ الْخِيَانَةِ فَإِنَّهَا بِئْسَتِ الْبِطَانَةُ.","tr":"Allahumma inni a'udhu bika min jaris-su'i fi daril-muqamah, fa-inna jaral-badiyati yatahawwal, wa minal-ju'i fa-innahu bi'sad-daji', wa minal-khiyanati fa-innaha bi'satil-bitanah.","en":"O Allah, I seek refuge in You from a bad neighbour where I settle, because a neighbour met on a journey moves on. I seek refuge in You from hunger, for it is a wretched bedfellow, and from betraying trust, for it is a wretched inner companion.","ref":null,"q":null,"source":"Ḥiṣn; Nasāʾī, Ibn Ḥibbān, al-Ḥākim. For the hunger and betrayal clauses: Abū Dāwūd.","page":null,"status":"draft"},
{"n":24,"ar":"اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ، وَقَلْبٍ لَا يَخْشَعُ، وَدُعَاءٍ لَا يُسْمَعُ، وَنَفْسٍ لَا تَشْبَعُ، وَمِنْ هٰؤُلَاءِ الْأَرْبَعِ.","tr":"Allahumma inni a'udhu bika min 'ilmin la yanfa', wa qalbin la yakhsha', wa du'a'in la yusma', wa nafsin la tashba', wa min ha'ula'il-arba'.","en":"O Allah, I seek refuge in You from knowledge that does not benefit, a heart that is not humble, a prayer that is not heard, and a soul that is never satisfied. I seek refuge in You from these four.","ref":null,"q":null,"source":"Ḥiṣn; al-Ḥākim, Ibn Abī Shayba. Via al-Suyūṭī: Tirmidhī, Nasāʾī, Abū Dāwūd, Ibn Mājah, al-Ḥākim.","page":null,"status":"draft"},
{"n":25,"ar":"اللّٰهُمَّ إِنَّا نَعُوذُ بِكَ أَنْ نَرْجِعَ عَلَى أَعْقَابِنَا، أَوْ نُفْتَنَ عَنْ دِينِنَا.","tr":"Allahumma inna na'udhu bika an narji'a 'ala a'qabina, aw nuftana 'an dinina.","en":"O Allah, we seek refuge in You from turning back on our heels, or being tempted away from our religion.","ref":null,"q":null,"source":"Ḥiṣn; Bukhārī, Muslim (as a saying of a Companion).","page":null,"status":"draft"},
{"n":26,"ar":"اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ يَوْمِ السُّوءِ، وَمِنْ لَيْلَةِ السُّوءِ، وَمِنْ سَاعَةِ السُّوءِ، وَمِنْ صَاحِبِ السُّوءِ، وَمِنْ جَارِ السُّوءِ فِي دَارِ الْمُقَامَةِ.","tr":"Allahumma inni a'udhu bika min yawmis-su', wa min laylatis-su', wa min sa'atis-su', wa min sahibis-su', wa min jaris-su'i fi daril-muqamah.","en":"O Allah, I seek refuge in You from an evil day, an evil night, an evil hour, an evil companion, and an evil neighbour where I settle.","ref":null,"q":null,"source":"Ḥiṣn; al-Ṭabarānī (al-Muʿjam al-Kabīr).","page":null,"status":"draft"},
{"n":27,"ar":"اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الشِّقَاقِ وَالنِّفَاقِ وَسُوءِ الْأَخْلَاقِ.","tr":"Allahumma inni a'udhu bika minash-shiqaqi wan-nifaqi wa su'il-akhlaq.","en":"O Allah, I seek refuge in You from discord, hypocrisy and bad character.","ref":null,"q":null,"source":"Ḥiṣn; Abū Dāwūd. Via al-Suyūṭī: Abū Dāwūd, Nasāʾī.","page":null,"status":"draft"},
{"n":28,"ar":"اللّٰهُمَّ اغْفِرْ لِي جِدِّي وَهَزْلِي، وَخَطَئِي وَعَمْدِي، وَكُلُّ ذٰلِكَ عِنْدِي.","tr":"Allahummagh-fir li jiddi wa hazli, wa khata'i wa 'amdi, wa kullu dhalika 'indi.","en":"O Allah, forgive me what I did in earnest and what I did in jest, what I did by mistake and what I did on purpose. All of that is in me.","ref":null,"q":null,"source":"Ḥiṣn; Bukhārī, Muslim.","page":null,"status":"draft"},
{"n":29,"ar":"اللّٰهُمَّ مُصَرِّفَ الْقُلُوبِ، صَرِّفْ قُلُوبَنَا عَلَى طَاعَتِكَ.","tr":"Allahumma musarrifal-qulub, sarrif qulubana 'ala ta'atik.","en":"O Allah, Turner of hearts, turn our hearts to obeying You.","ref":null,"q":null,"source":"Ḥiṣn; Muslim, Nasāʾī.","page":null,"status":"draft"},
{"n":30,"ar":"اللّٰهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى. رَبِّ أَعِنِّي وَلَا تُعِنْ عَلَيَّ، وَانْصُرْنِي وَلَا تَنْصُرْ عَلَيَّ، وَامْكُرْ لِي وَلَا تَمْكُرْ عَلَيَّ، وَاهْدِنِي الْهُدَى وَيَسِّرِ الْهُدَى لِي، وَانْصُرْنِي عَلَى مَنْ بَغَى عَلَيَّ، رَبِّ اجْعَلْنِي لَكَ ذَكَّارًا، لَكَ شَكَّارًا، لَكَ رَهَّابًا، لَكَ مِطْوَاعًا، لَكَ مُخْبِتًا، إِلَيْكَ أَوَّاهًا مُنِيبًا، رَبِّ تَقَبَّلْ تَوْبَتِي، وَاغْسِلْ حَوْبَتِي، وَأَجِبْ دَعْوَتِي، وَثَبِّتْ حُجَّتِي، وَسَدِّدْ لِسَانِي، وَاهْدِ قَلْبِي، وَاسْلُلْ سَخِيمَةَ صَدْرِي.","tr":"Allahumma inni as'alukal-huda wat-tuqa wal-'afafa wal-ghina. Rabbi a'inni wa la tu'in 'alayy, wansurni wa la tansur 'alayy, wamkur li wa la tamkur 'alayy, wahdinil-huda wa yassiril-huda li, wansurni 'ala man bagha 'alayy, Rabbij-'alni laka dhakkara, laka shakkara, laka rahhaba, laka mitwa'a, laka mukhbita, ilayka awwahan muniba, Rabbi taqabbal tawbati, waghsil hawbati, wa ajib da'wati, wa thabbit hujjati, wa saddid lisani, wahdi qalbi, waslul sakhimata sadri.","en":"O Allah, I ask You for guidance, mindfulness of You, chastity and freedom from need.\nMy Lord, help me and do not help others against me. Give me victory and do not give others victory over me. Plan for me and do not plan against me. Guide me, and make guidance easy for me. Give me victory over whoever wrongs me. My Lord, make me one who remembers You much, thanks You much, fears You much, and obeys You readily; humble before You, and turning to You with sighs and repentance. My Lord, accept my repentance, wash away my sin, answer my prayer, make my proof firm, keep my tongue true, guide my heart, and draw out the rancour from my chest.","ref":null,"q":null,"source":"Ḥiṣn; Muslim, Tirmidhī, Ibn Mājah. For «رَبِّ أَعِنِّي…»: Ḥiṣn; the four Sunan, Ibn Ḥibbān, al-Ḥākim, Ibn Abī Shayba.","page":null,"status":"draft"},
{"n":31,"ar":"اللّٰهُمَّ اغْفِرْ لَنَا وَارْحَمْنَا، وَارْضَ عَنَّا، وَتَقَبَّلْ مِنَّا، وَأَدْخِلْنَا الْجَنَّةَ، وَنَجِّنَا مِنَ النَّارِ، وَأَصْلِحْ لَنَا شَأْنَنَا كُلَّهُ.","tr":"Allahummagh-fir lana warhamna, wardha 'anna, wa taqabbal minna, wa adkhilnal-jannah, wa najjina minan-nar, wa aslih lana sha'nana kullah.","en":"O Allah, forgive us and have mercy on us. Be pleased with us and accept from us. Admit us to the Garden, save us from the Fire, and set all our affairs right.","ref":null,"q":null,"source":"Ḥiṣn; Ibn Mājah, Abū Dāwūd.","page":null,"status":"draft"},
{"n":32,"ar":"اللّٰهُمَّ إِنِّي أَسْأَلُكَ الثَّبَاتَ فِي الْأَمْرِ، وَأَسْأَلُكَ عَزِيمَةَ الرُّشْدِ، وَأَسْأَلُكَ شُكْرَ نِعْمَتِكَ، وَحُسْنَ عِبَادَتِكَ، وَأَسْأَلُكَ لِسَانًا صَادِقًا، (وَقَلْبًا سَلِيمًا، وَخُلُقًا مُسْتَقِيمًا)، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا تَعْلَمُ، وَأَسْأَلُكَ مِنْ خَيْرِ مَا تَعْلَمُ، وَأَسْتَغْفِرُكَ مِمَّا تَعْلَمُ، إِنَّكَ أَنْتَ عَلَّامُ الْغُيُوبِ.","tr":"Allahumma inni as'alukath-thabata fil-amr, wa as'aluka 'azimatar-rushd, wa as'aluka shukra ni'matik, wa husna 'ibadatik, wa as'aluka lisanan sadiqa, wa qalban salima, wa khuluqan mustaqima, wa a'udhu bika min sharri ma ta'lam, wa as'aluka min khayri ma ta'lam, wa astaghfiruka mimma ta'lam, innaka anta 'allamul-ghuyub.","en":"O Allah, I ask You for steadfastness in the matter of religion and for firm resolve on the right course. I ask You to let me thank You for Your blessing and to worship You well. I ask You for a truthful tongue, a sound heart and upright character. I seek refuge in You from the evil of what You know, I ask You for the good of what You know, and I ask Your forgiveness for what You know. You are the Knower of all that is hidden.","ref":null,"q":null,"source":"Ḥiṣn; Tirmidhī, Ibn Ḥibbān, al-Ḥākim, Ibn Abī Shayba.","page":null,"status":"draft"},
{"n":33,"ar":"اللّٰهُمَّ أَلِّفْ بَيْنَ قُلُوبِنَا، وَأَصْلِحْ ذَاتَ بَيْنِنَا، وَاهْدِنَا سُبُلَ السَّلَامِ، وَنَجِّنَا مِنَ الظُّلُمَاتِ إِلَى النُّورِ، وَجَنِّبْنَا الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ، وَبَارِكْ لَنَا فِي أَسْمَاعِنَا وَأَبْصَارِنَا وَقُلُوبِنَا وَأَزْوَاجِنَا وَذُرِّيَّاتِنَا، وَتُبْ عَلَيْنَا إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ، وَاجْعَلْنَا شَاكِرِينَ لِنِعْمَتِكَ، (مُثْنِينَ) بِهَا، قَابِلِيهَا، وَأَتِمَّهَا عَلَيْنَا.","tr":"Allahumma allif bayna qulubina, wa aslih dhata baynina, wahdina subulas-salam, wa najjina minaz-zulumati ilan-nur, wa jannibnal-fawahisha ma zahara minha wa ma batan, wa barik lana fi asma'ina wa absarina wa qulubina wa azwajina wa dhurriyyatina, wa tub 'alayna innaka antat-Tawwabur-Rahim, waj'alna shakirina li-ni'matik, muthnina biha, qabiliha, wa atimmaha 'alayna.","en":"O Allah, join our hearts together and set right what is between us. Guide us to the paths of peace, and bring us out of darkness into light. Keep us away from shameful deeds, open and hidden. Bless us in our hearing, our sight, our hearts, our spouses and our children. Turn to us in mercy; You are the One who accepts repentance, the Merciful. Make us grateful for Your blessing, praising You for it and receiving it gladly, and complete it for us.","ref":null,"q":null,"source":"Ḥiṣn; Abū Dāwūd, Ibn Ḥibbān, al-Ḥākim, al-Ṭabarānī (al-Muʿjam al-Kabīr).","page":null,"status":"draft"},
{"n":34,"ar":"اللّٰهُمَّ اقْسِمْ لَنَا مِنْ خَشْيَتِكَ مَا تَحُولُ بِهِ بَيْنَنَا وَبَيْنَ مَعَاصِيكَ، وَمِنْ طَاعَتِكَ مَا تُبَلِّغُنَا بِهِ جَنَّتَكَ، وَمِنَ الْيَقِينِ مَا تُهَوِّنُ بِهِ عَلَيْنَا مَصَائِبَ الدُّنْيَا، وَمَتِّعْنَا بِأَسْمَاعِنَا وَأَبْصَارِنَا وَقُوَّتِنَا مَا أَحْيَيْتَنَا، وَاجْعَلْهُ الْوَارِثَ مِنَّا، وَاجْعَلْ ثَأْرَنَا عَلَى مَنْ ظَلَمَنَا، وَانْصُرْنَا عَلَى مَنْ عَادَانَا، وَلَا تَجْعَلْ مُصِيبَتَنَا فِي دِينِنَا، وَلَا تَجْعَلِ الدُّنْيَا أَكْبَرَ هَمِّنَا، وَلَا مَبْلَغَ عِلْمِنَا، وَلَا تُسَلِّطْ عَلَيْنَا مَنْ لَا يَرْحَمُنَا.","tr":"Allahummaq-sim lana min khashyatika ma tahulu bihi baynana wa bayna ma'asik, wa min ta'atika ma tuballighuna bihi jannatak, wa minal-yaqini ma tuhawwinu bihi 'alayna masa'ibad-dunya, wa matti'na bi-asma'ina wa absarina wa quwwatina ma ahyaytana, waj'alhul-waritha minna, waj'al tha'rana 'ala man zalamana, wansurna 'ala man 'adana, wa la taj'al musibatana fi dinina, wa la taj'alid-dunya akbara hammina, wa la mablagha 'ilmina, wa la tusallit 'alayna man la yarhamuna.","en":"O Allah, give us a share of fear of You that will stand between us and disobeying You, and a share of obedience to You that will bring us to Your Garden. Give us a share of certainty that will make the misfortunes of this world light for us. Let us enjoy our hearing, our sight and our strength for as long as You keep us alive, and let them remain with us to the end. Let our retribution fall on those who wronged us, and help us against those who are hostile to us. Do not let our misfortune be in our religion. Do not make this world our greatest concern or the limit of our knowledge. Do not give power over us to anyone who will not show us mercy.","ref":null,"q":null,"source":"Ḥiṣn; Tirmidhī, Nasāʾī, al-Ḥākim.","page":null,"status":"draft"},
{"n":35,"ar":"اللّٰهُمَّ زِدْنَا وَلَا تَنْقُصْنَا، وَأَكْرِمْنَا وَلَا تُهِنَّا، وَأَعْطِنَا وَلَا تَحْرِمْنَا، وَآثِرْنَا وَلَا تُؤْثِرْ عَلَيْنَا، وَأَرْضِنَا عَنْكَ وَارْضَ عَنَّا.","tr":"Allahumma zidna wa la tanqusna, wa akrimna wa la tuhinna, wa a'tina wa la tahrimna, wa athirna wa la tu'thir 'alayna, wa ardina 'anka wardha 'anna.","en":"O Allah, give us more and do not give us less. Honour us and do not humiliate us. Give to us and do not deprive us. Favour us, and do not favour others over us. Make us content with You, and be pleased with us.","ref":null,"q":null,"source":"Ḥiṣn; Tirmidhī, Nasāʾī, al-Ḥākim.","page":null,"status":"draft"},
{"n":36,"ar":"اللّٰهُمَّ أَلْهِمْنِي رُشْدِي، وَأَعِذْنِي مِنْ شَرِّ نَفْسِي.","tr":"Allahumma alhimni rushdi, wa a'idhni min sharri nafsi.","en":"O Allah, inspire me with what is right for me, and protect me from the evil of my own self.","ref":null,"q":null,"source":"Ḥiṣn; Tirmidhī.","page":null,"status":"draft"},
{"n":37,"ar":"اللّٰهُمَّ إِنِّي أَسْأَلُكَ فِعْلَ الْخَيْرَاتِ، وَتَرْكَ الْمُنْكَرَاتِ، وَحُبَّ الْمَسَاكِينِ، وَأَنْ تَغْفِرَ لِي وَتَرْحَمَنِي، وَإِذَا أَرَدْتَ بِقَوْمٍ فِتْنَةً فَتَوَفَّنِي غَيْرَ مَفْتُونٍ.","tr":"Allahumma inni as'aluka fi'lal-khayrat, wa tarkal-munkarat, wa hubbal-masakin, wa an taghfira li wa tarhamani, wa idha aradta bi-qawmin fitnatan fa-tawaffani ghayra maftun.","en":"O Allah, I ask You that I may do good deeds, leave evil deeds, and love the poor. I ask that You forgive me and have mercy on me. When You intend a trial for a people, take my soul without my being caught up in it.","ref":null,"q":null,"source":"Ḥiṣn; Tirmidhī, al-Ḥākim.","page":null,"status":"draft"},
{"n":38,"ar":"اللّٰهُمَّ إِنِّي أَسْأَلُكَ حُبَّكَ، وَحُبَّ مَنْ يُحِبُّكَ، وَالْعَمَلَ الَّذِي يُبَلِّغُنِي حُبَّكَ.","tr":"Allahumma inni as'aluka hubbak, wa hubba man yuhibbuk, wal-'amalal-ladhi yuballighuni hubbak.","en":"O Allah, I ask You for Your love, for the love of those who love You, and for the deeds that will bring me to Your love.","ref":null,"q":null,"source":"Ḥiṣn; Tirmidhī, al-Ḥākim.","page":null,"status":"draft"},
{"n":39,"ar":"اللّٰهُمَّ اجْعَلْ حُبَّكَ أَحَبَّ إِلَيَّ مِنْ نَفْسِي وَأَهْلِي وَمِنَ الْمَاءِ الْبَارِدِ.","tr":"Allahummaj-'al hubbaka ahabba ilayya min nafsi wa ahli wa minal-ma'il-barid.","en":"O Allah, make love of You dearer to me than myself, my family, and cool water.","ref":null,"q":null,"source":"no footnote of its own; same narration as 38.","page":null,"status":"draft"},
{"n":40,"ar":"اللّٰهُمَّ ارْزُقْنِي حُبَّكَ، وَحُبَّ مَنْ يَنْفَعُنِي حُبُّهُ عِنْدَكَ.","tr":"Allahummar-zuqni hubbak, wa hubba man yanfa'uni hubbuhu 'indak.","en":"O Allah, grant me Your love, and the love of those whose love will benefit me with You.","ref":null,"q":null,"source":"Ḥiṣn; Tirmidhī.","page":null,"status":"draft"},
{"n":41,"ar":"اللّٰهُمَّ فَكَمَا رَزَقْتَنِي مِمَّا أُحِبُّ فَاجْعَلْهُ قُوَّةً لِي فِيمَا تُحِبُّ.","tr":"Allahumma fa-kama razaqtani mimma uhibbu faj'alhu quwwatan li fima tuhibb.","en":"O Allah, as You have given me some of what I love, make it a strength for me in what You love.","ref":null,"q":null,"source":"no footnote of its own; continues the narration of 40.","page":null,"status":"draft"},
{"n":42,"ar":"اللّٰهُمَّ وَمَا زَوَيْتَ عَنِّي مِمَّا أُحِبُّ فَاجْعَلْهُ فَرَاغًا لِي فِيمَا تُحِبُّ، يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ.","tr":"Allahumma wa ma zawayta 'anni mimma uhibbu faj'alhu faraghan li fima tuhibb, ya muqallibal-qulubi thabbit qalbi 'ala dinik.","en":"O Allah, whatever You have kept from me of what I love, let it free me for what You love. O Turner of hearts, keep my heart firm on Your religion.","ref":null,"q":null,"source":"the first part continues the narration of 40. For «يَا مُقَلِّبَ الْقُلُوبِ»: Ḥiṣn; Tirmidhī, Nasāʾī, al-Ḥākim, Aḥmad, Abū Yaʿlā.","page":null,"status":"draft"},
{"n":43,"ar":"اللّٰهُمَّ إِنِّي أَسْأَلُكَ إِيمَانًا لَا يَرْتَدُّ، وَنَعِيمًا لَا يَنْفَدُ، وَمُرَافَقَةَ نَبِيِّنَا مُحَمَّدٍ صَلَّى اللّٰهُ عَلَيْهِ وَسَلَّمَ فِي أَعْلَى دَرَجَةِ الْجَنَّةِ، جَنَّةِ الْخُلْدِ.","tr":"Allahumma inni as'aluka imanan la yartadd, wa na'iman la yanfad, wa murafaqata nabiyyina Muhammadin sallallahu 'alayhi wa sallam fi a'la darajatil-jannah, jannatil-khuld.","en":"O Allah, I ask You for faith that never turns back, bliss that never runs out, and the company of our Prophet Muhammad ﷺ in the highest rank of the Garden, the Garden of Eternity.","ref":null,"q":null,"source":"Ḥiṣn; Nasāʾī, Ibn Ḥibbān, al-Ḥākim.","page":null,"status":"draft"},
{"n":44,"ar":"اللّٰهُمَّ انْفَعْنِي بِمَا عَلَّمْتَنِي، وَعَلِّمْنِي مَا يَنْفَعُنِي، وَزِدْنِي عِلْمًا، الْحَمْدُ لِلّٰهِ عَلَى كُلِّ حَالٍ، وَأَعُوذُ بِاللّٰهِ مِنْ حَالِ أَهْلِ النَّارِ.","tr":"Allahumman-fa'ni bima 'allamtani, wa 'allimni ma yanfa'uni, wa zidni 'ilma, al-hamdu lillahi 'ala kulli hal, wa a'udhu billahi min hali ahlin-nar.","en":"O Allah, benefit me by what You have taught me, teach me what will benefit me, and increase me in knowledge. Praise be to Allah in every state. I seek refuge in Allah from the state of the people of the Fire.","ref":null,"q":null,"source":"Ḥiṣn; Tirmidhī, Ibn Mājah, al-Ḥākim.","page":null,"status":"draft"},
{"n":45,"ar":"اللّٰهُمَّ بِعِلْمِكَ الْغَيْبَ، وَقُدْرَتِكَ عَلَى الْخَلْقِ، أَحْيِنِي مَا عَلِمْتَ الْحَيٰوةَ خَيْرًا لِي، وَتَوَفَّنِي إِذَا عَلِمْتَ الْوَفَاةَ خَيْرًا لِي، وَأَسْأَلُكَ خَشْيَتَكَ فِي الْغَيْبِ وَالشَّهَادَةِ، وَكَلِمَةَ الْحَقِّ فِي الرِّضَا وَالْغَضَبِ، وَأَسْأَلُكَ الْقَصْدَ فِي الْفَقْرِ وَالْغِنَى، وَأَسْأَلُكَ نَعِيمًا لَا يَنْفَدُ، وَقُرَّةَ عَيْنٍ لَا تَنْقَطِعُ، وَأَسْأَلُكَ الرِّضَا بِالْقَضَاءِ، وَبَرْدَ الْعَيْشِ بَعْدَ الْمَوْتِ، وَلَذَّةَ النَّظَرِ إِلَى وَجْهِكَ، وَالشَّوْقَ إِلَى لِقَائِكَ، وَأَعُوذُ بِكَ مِنْ ضَرَّاءَ مُضِرَّةٍ، وَفِتْنَةٍ مُضِلَّةٍ، اللّٰهُمَّ زَيِّنَّا بِزِينَةِ الْإِيمَانِ، وَاجْعَلْنَا هُدَاةً مُهْتَدِينَ.","tr":"Allahumma bi-'ilmikal-ghayb, wa qudratika 'alal-khalq, ahyini ma 'alimtal-hayata khayran li, wa tawaffani idha 'alimtal-wafata khayran li, wa as'aluka khashyataka fil-ghaybi wash-shahadah, wa kalimatal-haqqi fir-rida wal-ghadab, wa as'alukal-qasda fil-faqri wal-ghina, wa as'aluka na'iman la yanfad, wa qurrata 'aynin la tanqati', wa as'alukar-rida bil-qada', wa bardal-'ayshi ba'dal-mawt, wa ladhdhatan-nazari ila wajhik, wash-shawqa ila liqa'ik, wa a'udhu bika min darra'a mudirrah, wa fitnatin mudillah, Allahumma zayyinna bi-zinatil-iman, waj'alna hudatan muhtadin.","en":"O Allah, by Your knowledge of the unseen and Your power over creation, keep me alive as long as You know life is good for me, and take my soul when You know death is good for me. I ask You for fear of You in private and in public, and for a word of truth when I am pleased and when I am angry. I ask You for moderation in poverty and in wealth. I ask You for bliss that never runs out, and a joy that never ends. I ask You for contentment with what You decree, a cool and easy life after death, the delight of looking at Your Face, and longing to meet You. I seek refuge in You from harmful hardship and from a trial that leads astray. O Allah, adorn us with the adornment of faith, and make us guides who are themselves rightly guided.","ref":null,"q":null,"source":"Ḥiṣn; Nasāʾī, al-Ḥākim, Aḥmad, al-Ṭabarānī (al-Muʿjam al-Kabīr). Nomani also traces the clause «وَأَسْأَلُكَ الْقَصْدَ فِي الْفَقْرِ وَالْغِنَى» through al-Suyūṭī's al-Jāmiʿ al-Ṣaghīr.","page":null,"status":"draft"},
{"n":46,"ar":"اللّٰهُمَّ إِنِّي أَسْأَلُكَ مِنَ الْخَيْرِ كُلِّهِ، عَاجِلِهِ وَآجِلِهِ، مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ، وَأَعُوذُ بِكَ مِنَ الشَّرِّ كُلِّهِ، عَاجِلِهِ وَآجِلِهِ، مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ.","tr":"Allahumma inni as'aluka minal-khayri kullih, 'ajilihi wa ajilih, ma 'alimtu minhu wa ma lam a'lam, wa a'udhu bika minash-sharri kullih, 'ajilihi wa ajilih, ma 'alimtu minhu wa ma lam a'lam.","en":"O Allah, I ask You for all good, sooner and later, what I know of it and what I do not know. I seek refuge in You from all evil, sooner and later, what I know of it and what I do not know.","ref":null,"q":null,"source":"Ḥiṣn; Ibn Mājah, Ibn Ḥibbān, al-Ḥākim.","page":null,"status":"draft"},
{"n":47,"ar":"اللّٰهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ، وَأَعُوذُ بِكَ مِنَ النَّارِ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ، وَأَسْأَلُكَ أَنْ تَجْعَلَ كُلَّ قَضَاءٍ لِي خَيْرًا، وَأَسْأَلُكَ مَا قَضَيْتَ لِي مِنْ أَمْرٍ أَنْ تَجْعَلَ عَاقِبَتَهُ رَشَدًا.","tr":"Allahumma inni as'alukal-jannata wa ma qarraba ilayha min qawlin aw 'amal, wa a'udhu bika minan-nari wa ma qarraba ilayha min qawlin aw 'amal, wa as'aluka an taj'ala kulla qada'in li khayra, wa as'aluka ma qadayta li min amrin an taj'ala 'aqibatahu rashada.","en":"O Allah, I ask You for the Garden and for whatever word or deed brings one near to it. I seek refuge in You from the Fire and from whatever word or deed brings one near to it. I ask You to make every decree of Yours for me good. Whatever matter You have decreed for me, I ask You to make its outcome right.","ref":null,"q":null,"source":"same narration as 46. Nomani adds a further note citing al-Ḥākim.","page":null,"status":"draft"},
{"n":48,"ar":"اللّٰهُمَّ أَحْسِنْ عَاقِبَتَنَا فِي الْأُمُورِ كُلِّهَا، وَأَجِرْنَا مِنْ خِزْيِ الدُّنْيَا وَعَذَابِ الْآخِرَةِ.","tr":"Allahumma ahsin 'aqibatana fil-umuri kulliha, wa ajirna min khizyid-dunya wa 'adhabil-akhirah.","en":"O Allah, make the outcome of all our affairs good, and protect us from disgrace in this world and punishment in the next.","ref":null,"q":null,"source":"Ḥiṣn; Ibn Ḥibbān, al-Ḥākim. Via al-Suyūṭī: Aḥmad, Ibn Ḥibbān, al-Ḥākim.","page":null,"status":"draft"},
{"n":49,"ar":"اللّٰهُمَّ احْفَظْنِي بِالْإِسْلَامِ قَائِمًا، وَاحْفَظْنِي بِالْإِسْلَامِ قَاعِدًا، وَاحْفَظْنِي بِالْإِسْلَامِ رَاقِدًا، وَلَا تُشْمِتْ بِي عَدُوًّا وَلَا حَاسِدًا.","tr":"Allahummah-fazni bil-islami qa'ima, wahfazni bil-islami qa'ida, wahfazni bil-islami raqida, wa la tushmit bi 'aduwwan wa la hasida.","en":"O Allah, guard me through Islam when I stand, guard me through Islam when I sit, and guard me through Islam when I sleep. Do not let any enemy or envier gloat over me.","ref":null,"q":null,"source":"Ḥiṣn; al-Ḥākim, Ibn Ḥibbān.","page":null,"status":"draft"},
{"n":50,"ar":"اللّٰهُمَّ إِنِّي أَسْأَلُكَ مِنْ كُلِّ خَيْرٍ خَزَائِنُهُ بِيَدِكَ، وَأَعُوذُ بِكَ مِنْ كُلِّ شَرٍّ خَزَائِنُهُ بِيَدِكَ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا أَنْتَ آخِذٌ بِنَاصِيَتِهِ.","tr":"Allahumma inni as'aluka min kulli khayrin khaza'inuhu bi-yadik, wa a'udhu bika min kulli sharrin khaza'inuhu bi-yadik, wa a'udhu bika min sharri ma anta akhidhun bi-nasiyatih.","en":"O Allah, I ask You for every good whose treasuries are in Your hand. I seek refuge in You from every evil whose treasuries are in Your hand, and from the evil of every creature You hold by the forelock.","ref":null,"q":null,"source":"Ḥiṣn; Ibn Ḥibbān. Nomani traces the clause «وَأَعُوذُ بِكَ مِنْ كُلِّ شَرٍّ خَزَائِنُهُ بِيَدِكَ» through al-Suyūṭī's al-Jāmiʿ al-Ṣaghīr (al-Ḥākim).","page":null,"status":"draft"},
{"n":51,"ar":"اللّٰهُمَّ إِنِّي أَسْأَلُكَ عِيشَةً نَقِيَّةً، وَمِيتَةً سَوِيَّةً، وَمَرَدًّا غَيْرَ مُخْزٍ وَلَا فَاضِحٍ. اللّٰهُمَّ إِنِّي ضَعِيفٌ فَقَوِّ فِي رِضَاكَ ضَعْفِي، وَخُذْ إِلَى الْخَيْرِ بِنَاصِيَتِي، وَاجْعَلِ الْإِسْلَامَ مُنْتَهَى رِضَائِي.","tr":"Allahumma inni as'aluka 'ishatan naqiyyah, wa mitatan sawiyyah, wa maraddan ghayra mukhzin wa la fadih. Allahumma inni da'ifun fa-qawwi fi ridaka da'fi, wa khudh ilal-khayri bi-nasiyati, waj'alil-islama muntaha rida'i.","en":"O Allah, I ask You for a pure life, an upright death, and a return to You that brings no disgrace or shame. O Allah, I am weak, so turn my weakness into strength in seeking what pleases You. Take me by the forelock towards good, and make Islam the utmost of what pleases me.","ref":null,"q":null,"source":"Ḥiṣn; al-Ḥākim. Via al-Suyūṭī: al-Bazzār, al-Ṭabarānī (al-Kabīr), al-Ḥākim. For «اللّٰهُمَّ إِنِّي ضَعِيفٌ…»: Ḥiṣn; al-Ḥākim, Ibn Abī Shayba. Via Kanz al-ʿUmmāl: al-Ṭabarānī (al-Kabīr), Abū Yaʿlā, al-Ḥākim.","page":null,"status":"draft"},
{"n":52,"ar":"اللّٰهُمَّ إِنِّي ضَعِيفٌ فَقَوِّنِي، وَإِنِّي ذَلِيلٌ فَأَعِزَّنِي، وَإِنِّي فَقِيرٌ فَارْزُقْنِي.","tr":"Allahumma inni da'ifun fa-qawwini, wa inni dhalilun fa-a'izzani, wa inni faqirun farzuqni.","en":"O Allah, I am weak, so strengthen me. I am lowly, so raise me in honour. I am poor, so provide for me.","ref":null,"q":null,"source":"no footnote of its own; continues the second narration of 51.","page":null,"status":"draft"}]},{"manzil":4,"day":"Tuesday","dayAr":"يوم الثلاثاء","duas":[{"n":1,"ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ الْمَسْأَلَةِ، وَخَيْرَ الدُّعَاءِ، وَخَيْرَ النَّجَاحِ، وَخَيْرَ الْعَمَلِ، وَخَيْرَ الثَّوَابِ، وَخَيْرَ الْحَيَاةِ، وَخَيْرَ الْمَمَاتِ، وَثَبِّتْنِي، وَثَقِّلْ مَوَازِينِي، وَحَقِّقْ إِيمَانِي، وَارْفَعْ دَرَجَتِي، وَتَقَبَّلْ صَلَاتِي، وَاغْفِرْ خَطِيئَتِي، وَأَسْأَلُكَ الدَّرَجَاتِ الْعُلَى مِنَ الْجَنَّةِ، آمِينَ.","tr":"Allahumma inni as'aluka khayra l-mas'alah, wa khayra d-du'a', wa khayra n-najah, wa khayra l-'amal, wa khayra th-thawab, wa khayra l-hayah, wa khayra l-mamat; wa thabbitni, wa thaqqil mawazini, wa haqqiq imani, warfa' darajati, wa taqabbal salati, waghfir khati'ati, wa as'aluka d-darajati l-'ula mina l-jannah. Amin.","en":"O Allah, I ask You for the best of asking, the best of supplication, the best success, the best deeds, the best reward, the best life and the best death. Make me firm, make my scales heavy, make my faith true, raise my rank, accept my prayer and forgive my sin. And I ask You for the highest ranks of Paradise. Amin.","ref":null,"q":null,"source":"al-Hakim (al-Mustadrak); al-Tabarani (al-Kabir, al-Awsat), from Umm Salama. The note covers nos. 1–3.","page":"79","status":"draft"},
{"n":2,"ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ فَوَاتِحَ الْخَيْرِ وَخَوَاتِمَهُ وَجَوَامِعَهُ وَكَوَامِلَهُ، وَأَوَّلَهُ وَآخِرَهُ، وَظَاهِرَهُ وَبَاطِنَهُ، وَالدَّرَجَاتِ الْعُلَى مِنَ الْجَنَّةِ، آمِينَ.","tr":"Allahumma inni as'aluka fawatiha l-khayri wa khawatimahu wa jawami'ahu wa kawamilahu, wa awwalahu wa akhirahu, wa zahirahu wa batinahu, wa d-darajati l-'ula mina l-jannah. Amin.","en":"O Allah, I ask You for the openings of good and its endings, its sum and its fullness, its first and its last, its outward and its inward, and the highest ranks of Paradise. Amin.","ref":null,"q":null,"source":"see no. 1.","page":"79","status":"draft"},
{"n":3,"ar":"اللَّهُمَّ نَجِّنِي مِنَ النَّارِ، وَاغْفِرْ لِي مَغْفِرَةً بِاللَّيْلِ وَالنَّهَارِ، وَالْمَنْزِلَ الصَّالِحَ مِنَ الْجَنَّةِ، آمِينَ.","tr":"Allahumma najjini mina n-nar, waghfir li maghfiratan bil-layli wan-nahar, wal-manzila s-saliha mina l-jannah. Amin.","en":"O Allah, save me from the Fire, forgive me with a forgiveness by night and by day, and [grant me] a good dwelling in Paradise. Amin.","ref":null,"q":null,"source":"see no. 1.","page":"79","status":"draft"},
{"n":4,"ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ خَلَاصًا مِنَ النَّارِ سَالِمًا، وَأَنْ تُدْخِلَنِي الْجَنَّةَ آمِنًا.","tr":"Allahumma inni as'aluka khalasan mina n-nari saliman, wa an tudkhilani l-jannata aminan.","en":"O Allah, I ask You for release from the Fire, safe and sound, and that You admit me into Paradise in security.","ref":null,"q":null,"source":"no separate note (continues the hadith of nos. 1–3).","page":"80","status":"draft"},
{"n":5,"ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ مَا آتِي، وَخَيْرَ مَا أَفْعَلُ، وَخَيْرَ مَا أَعْمَلُ، وَخَيْرَ مَا بَطَنَ، وَخَيْرَ مَا ظَهَرَ، وَالدَّرَجَاتِ الْعُلَى مِنَ الْجَنَّةِ، آمِينَ.","tr":"Allahumma inni as'aluka khayra ma ati, wa khayra ma af'alu, wa khayra ma a'malu, wa khayra ma batan, wa khayra ma zahar, wa d-darajati l-'ula mina l-jannah. Amin.","en":"O Allah, I ask You for the good of what I undertake, the good of what I do, the good of what I work at, the good of what is hidden and the good of what is open, and the highest ranks of Paradise. Amin.","ref":null,"q":null,"source":"no separate note (same hadith).","page":"80","status":"draft"},
{"n":6,"ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ أَنْ تَرْفَعَ ذِكْرِي، وَتَضَعَ وِزْرِي، وَتُصْلِحَ أَمْرِي، وَتُطَهِّرَ قَلْبِي، وَتُحَصِّنَ فَرْجِي، وَتُنَوِّرَ لِي فِي قَبْرِي، وَتَغْفِرَ لِي ذَنْبِي، وَأَسْأَلُكَ الدَّرَجَاتِ الْعُلَى مِنَ الْجَنَّةِ، آمِينَ.","tr":"Allahumma inni as'aluka an tarfa'a dhikri, wa tada'a wizri, wa tusliha amri, wa tutahhira qalbi, wa tuhassina farji, wa tunawwira li fi qabri, wa taghfira li dhanbi, wa as'aluka d-darajati l-'ula mina l-jannah. Amin.","en":"O Allah, I ask You to raise my mention, take away my burden of sin, set my affairs right, purify my heart, guard my chastity, give me light in my grave and forgive my sin. And I ask You for the highest ranks of Paradise. Amin.","ref":null,"q":null,"source":"no separate note (same hadith).","page":"80","status":"draft"},
{"n":7,"ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ أَنْ تُبَارِكَ لِي فِي سَمْعِي، وَفِي بَصَرِي، وَفِي رُوحِي، وَفِي خَلْقِي، وَفِي خُلُقِي، وَفِي أَهْلِي، وَفِي مَالِي، وَفِي مَحْيَايَ، وَفِي مَمَاتِي، وَفِي عَمَلِي.","tr":"Allahumma inni as'aluka an tubarika li fi sam'i, wa fi basari, wa fi ruhi, wa fi khalqi, wa fi khuluqi, wa fi ahli, wa fi mali, wa fi mahyaya, wa fi mamati, wa fi 'amali.","en":"O Allah, I ask You to bless me in my hearing, my sight, my soul, my body, my character, my family, my wealth, my life, my death and my deeds.","ref":null,"q":null,"source":"no separate note (same hadith).","page":"80","status":"draft"},
{"n":8,"ar":"اللَّهُمَّ وَتَقَبَّلْ حَسَنَاتِي، وَأَسْأَلُكَ الدَّرَجَاتِ الْعُلَى مِنَ الْجَنَّةِ، آمِينَ.","tr":"Allahumma wa taqabbal hasanati, wa as'aluka d-darajati l-'ula mina l-jannah. Amin.","en":"O Allah, accept my good deeds. And I ask You for the highest ranks of Paradise. Amin.","ref":null,"q":null,"source":"no separate note (same hadith).","page":"80","status":"draft"},
{"n":9,"ar":"اللَّهُمَّ اجْعَلْ أَوْسَعَ رِزْقِكَ عَلَيَّ عِنْدَ كِبَرِ سِنِّي، وَانْقِطَاعِ عُمُرِي.\nيَا مَنْ لَا تَرَاهُ الْعُيُونُ، وَلَا تُخَالِطُهُ الظُّنُونُ، وَلَا يَصِفُهُ الْوَاصِفُونَ، وَلَا تُغَيِّرُهُ الْحَوَادِثُ، وَلَا يَخْشَى الدَّوَائِرَ، يَعْلَمُ مَثَاقِيلَ الْجِبَالِ، وَمَكَائِيلَ الْبِحَارِ، وَعَدَدَ قَطْرِ الْأَمْطَارِ، وَعَدَدَ وَرَقِ الْأَشْجَارِ، وَعَدَدَ مَا أَظْلَمَ عَلَيْهِ اللَّيْلُ وَأَشْرَقَ عَلَيْهِ النَّهَارُ، وَلَا تُوَارِي مِنْهُ سَمَاءٌ سَمَاءً، وَلَا أَرْضٌ أَرْضًا، وَلَا بَحْرٌ مَا فِي قَعْرِهِ، وَلَا جَبَلٌ مَا فِي وَعْرِهِ، اجْعَلْ خَيْرَ عُمُرِي آخِرَهُ، وَخَيْرَ عَمَلِي خَوَاتِيمَهُ، وَخَيْرَ أَيَّامِي يَوْمَ أَلْقَاكَ فِيهِ.\nيَا وَلِيَّ الْإِسْلَامِ وَأَهْلِهِ، ثَبِّتْنِي بِهِ حَتَّى أَلْقَاكَ.","tr":"Allahumma j'al awsa'a rizqika 'alayya 'inda kibari sinni, wanqita'i 'umuri.\nYa man la tarahu l-'uyun, wa la tukhalituhu z-zunun, wa la yasifuhu l-wasifun, wa la tughayyiruhu l-hawadith, wa la yakhsha d-dawa'ir; ya'lamu mathaqila l-jibal, wa maka'ila l-bihar, wa 'adada qatri l-amtar, wa 'adada waraqi l-ashjar, wa 'adada ma azlama 'alayhi l-laylu wa ashraqa 'alayhi n-nahar; wa la tuwari minhu sama'un sama'an, wa la ardun ardan, wa la bahrun ma fi qa'rih, wa la jabalun ma fi wa'rih: ij'al khayra 'umuri akhirah, wa khayra 'amali khawatimah, wa khayra ayyami yawma alqaka fih.\nYa waliyya l-islami wa ahlih, thabbitni bihi hatta alqak.","en":"O Allah, make Your provision most abundant for me when I am old and my life is coming to its end.\nO You whom eyes do not see, whom thoughts cannot reach, whom no describer can describe, whom events do not change, and who does not fear the turns of fortune. You know the weight of the mountains, the measure of the seas, the number of raindrops, the number of leaves on the trees, and the number of all that the night darkens and the day lights up. No heaven hides another heaven from You, no earth another earth, no sea what lies at its bottom, and no mountain what lies in its rugged places. Make the best of my life its end, the best of my deeds the last of them, and the best of my days the day I meet You.\nO Guardian of Islam and its people, keep me firm in it until I meet You.","ref":null,"q":null,"source":"first paragraph: al-Hakim (from ʿA'isha) and al-Tabarani (al-Awsat). \"يا من لا تراه العيون…\": al-Tabarani (al-Awsat). \"يا ولي الإسلام…\": al-Tabarani (al-Kabir).","page":"80–81","status":"draft"},
{"n":10,"ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ غِنَايَ وَغِنَى مَوْلَايَ.","tr":"Allahumma inni as'aluka ghinaya wa ghina mawlay.","en":"O Allah, I ask You to make me free of need, and those close to me as well.","ref":null,"q":null,"source":"Ahmad; al-Tabarani (al-Kabir), from Abu Sirma.","page":"81","status":"draft"},
{"n":11,"ar":"اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَأَدْخِلْنِي الْجَنَّةَ.","tr":"Allahumma ghfir li, warhamni, wa adkhilni l-jannah.","en":"O Allah, forgive me, have mercy on me and admit me into Paradise.","ref":null,"q":null,"source":"al-Tabarani (al-Kabir).","page":"82","status":"draft"},
{"n":12,"ar":"اللَّهُمَّ اجْعَلْنِي صَبُورًا، وَاجْعَلْنِي شَكُورًا، وَاجْعَلْنِي فِي عَيْنِي صَغِيرًا، وَفِي أَعْيُنِ النَّاسِ كَبِيرًا.","tr":"Allahumma j'alni saburan, waj'alni shakuran, waj'alni fi 'ayni saghiran, wa fi a'yuni n-nasi kabiran.","en":"O Allah, make me very patient, make me very grateful, and make me small in my own eyes and great in the eyes of people.","ref":null,"q":null,"source":"al-Bazzar.","page":"82","status":"draft"},
{"n":13,"ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا، وَعَمَلًا مُتَقَبَّلًا، وَرِزْقًا حَلَالًا طَيِّبًا.","tr":"Allahumma inni as'aluka 'ilman nafi'an, wa 'amalan mutaqabbalan, wa rizqan halalan tayyiban.","en":"O Allah, I ask You for knowledge that benefits, deeds that are accepted, and provision that is lawful and good.","ref":null,"q":null,"source":"al-Tabarani (al-Awsat).","page":"82","status":"draft"},
{"n":14,"ar":"اللَّهُمَّ إِنِّي أَسْتَغْفِرُكَ لِذَنْبِي، وَأَسْتَهْدِيكَ لِمَرَاشِدِ أَمْرِي، وَأَسْتَجِيرُكَ مِنْ شَرِّ نَفْسِي، وَأَتُوبُ إِلَيْكَ فَتُبْ عَلَيَّ، إِنَّكَ أَنْتَ رَبِّي.","tr":"Allahumma inni astaghfiruka li-dhanbi, wa astahdika li-marashidi amri, wa astajiruka min sharri nafsi, wa atubu ilayka fa-tub 'alayya, innaka anta rabbi.","en":"O Allah, I ask Your forgiveness for my sin. I ask You to guide me to what is right in my affairs. I seek Your protection from the evil of my own self. I turn to You in repentance, so accept my repentance; You are my Lord.","ref":null,"q":null,"source":"Ibn Abi Shayba (al-Musannaf).","page":"82","status":"draft"},
{"n":15,"ar":"اللَّهُمَّ فَاجْعَلْ رَغْبَتِي إِلَيْكَ، وَاجْعَلْ غِنَايَ فِي صَدْرِي، وَبَارِكْ لِي فِيمَا رَزَقْتَنِي، وَتَقَبَّلْ مِنِّي، إِنَّكَ أَنْتَ رَبِّي.\nيَا مَنْ أَظْهَرَ الْجَمِيلَ، وَسَتَرَ عَلَيَّ الْقَبِيحَ، يَا مَنْ لَا يُؤَاخِذُ بِالْجَرِيرَةِ، وَلَا يَهْتِكُ السِّتْرَ، يَا عَظِيمَ الْعَفْوِ، يَا حَسَنَ التَّجَاوُزِ، يَا وَاسِعَ الْمَغْفِرَةِ، يَا بَاسِطَ الْيَدَيْنِ بِالرَّحْمَةِ، يَا صَاحِبَ كُلِّ نَجْوَى، يَا مُنْتَهَى كُلِّ شَكْوَى، يَا كَرِيمَ الصَّفْحِ، يَا عَظِيمَ الْمَنِّ، يَا مُبْدِئَ النِّعَمِ قَبْلَ اسْتِحْقَاقِهَا، يَا رَبَّنَا وَيَا سَيِّدَنَا وَيَا مَوْلَانَا وَيَا غَايَةَ رَغْبَتِنَا، أَسْأَلُكَ يَا اللهُ أَنْ لَا تَشْوِيَ خَلْقِي بِالنَّارِ.","tr":"Allahumma fa-j'al raghbati ilayk, waj'al ghinaya fi sadri, wa barik li fima razaqtani, wa taqabbal minni, innaka anta rabbi.\nYa man azhara l-jamil, wa satara 'alayya l-qabih; ya man la yu'akhidhu bil-jarirah, wa la yahtiku s-sitr; ya 'azima l-'afw, ya hasana t-tajawuz, ya wasi'a l-maghfirah, ya basita l-yadayni bir-rahmah, ya sahiba kulli najwa, ya muntaha kulli shakwa, ya karima s-safh, ya 'azima l-mann, ya mubdi'a n-ni'ami qabla stihqaqiha; ya rabbana wa ya sayyidana wa ya mawlana wa ya ghayata raghbatina, as'aluka ya Allahu an la tashwiya khalqi bin-nar.","en":"O Allah, make my longing be for You. Put my sufficiency in my heart, bless me in what You have provided me, and accept from me; You are my Lord.\nO You who made the beautiful appear and covered the ugly for me. O You who does not punish every offence and does not tear the veil away. O You whose pardon is great, whose overlooking is fine, and whose forgiveness is vast. O You whose hands are spread open with mercy. O Companion of every private plea, and final Recourse of every complaint. O You who forgive generously, whose favour is great, and who begin blessings before they are deserved. O our Lord, our Master and our Protector, the goal of all our longing: I ask You, O Allah, not to let the Fire burn my body.","ref":null,"q":null,"source":"first paragraph: no separate note (continues no. 14). \"يا من أظهر الجميل…\": al-Hakim (al-Mustadrak).","page":"82–83","status":"draft"},
{"n":16,"ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ وَرَحْمَتِكَ، فَإِنَّهُ لَا يَمْلِكُهَا إِلَّا أَنْتَ.\nاللَّهُمَّ أَحْسَنْتَ خَلْقِي فَأَحْسِنْ خُلُقِي.\nرَبِّ اغْفِرْ وَارْحَمْ، وَاهْدِنِي السَّبِيلَ الْأَقْوَمَ.","tr":"Allahumma inni as'aluka min fadlika wa rahmatik, fa-innahu la yamlikuha illa ant.\nAllahumma ahsanta khalqi fa-ahsin khuluqi.\nRabbi ghfir warham, wahdini s-sabila l-aqwam.","en":"O Allah, I ask You of Your bounty and Your mercy, for no one owns them but You.\nO Allah, You made my form beautiful, so make my character beautiful.\nMy Lord, forgive and have mercy, and guide me to the most upright way.","ref":null,"q":null,"source":"first paragraph: al-Tabarani (al-Kabir). Second and third: Ahmad and Abu Ya'la.","page":"83","status":"draft"},
{"n":17,"ar":"اللَّهُمَّ رَبَّ النَّبِيِّ سَيِّدِنَا مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، اغْفِرْ لِي ذَنْبِي، وَأَذْهِبْ عَنِّي غَيْظَ قَلْبِي، وَأَجِرْنِي مِنْ مُضِلَّاتِ الْفِتَنِ مَا أَحْيَيْتَنَا.","tr":"Allahumma rabba n-nabiyyi sayyidina Muhammadin salla llahu 'alayhi wa sallam, ighfir li dhanbi, wa adhhib 'anni ghayza qalbi, wa ajirni min mudillati l-fitani ma ahyaytana.","en":"O Allah, Lord of the Prophet, our master Muhammad (Allah bless him and give him peace), forgive me my sin, take the anger out of my heart, and protect me from the trials that lead astray for as long as You keep us alive.","ref":null,"q":null,"source":"Ahmad.","page":"84","status":"draft"},
{"n":18,"ar":"اللَّهُمَّ ارْزُقْنِي طَيِّبًا، وَاسْتَعْمِلْنِي طَيِّبًا.","tr":"Allahumma rzuqni tayyiban, wasta'milni tayyiban.","en":"O Allah, provide me with what is good and pure, and use me for what is good and pure.","ref":null,"q":null,"source":"al-Hakim al-Tirmidhi.","page":"84","status":"draft"},
{"n":19,"ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فُجَاءَةِ الْخَيْرِ، وَأَعُوذُ بِكَ مِنْ فُجَاءَةِ الشَّرِّ.","tr":"Allahumma inni as'aluka min fuja'ati l-khayr, wa a'udhu bika min fuja'ati sh-sharr.","en":"O Allah, I ask You for good that comes suddenly, and I seek refuge in You from evil that comes suddenly.","ref":null,"q":null,"source":"Abu Ya'la; Ibn al-Sunni.","page":"84","status":"draft"},
{"n":20,"ar":"اللَّهُمَّ أَنْتَ السَّلَامُ، وَمِنْكَ السَّلَامُ، وَإِلَيْكَ يَعُودُ السَّلَامُ، أَسْأَلُكَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ أَنْ تَسْتَجِيبَ لَنَا دَعْوَتَنَا، وَأَنْ تُعْطِيَنَا رَغْبَتَنَا، وَأَنْ تُغْنِيَنَا عَمَّنْ أَغْنَيْتَهُ عَنَّا مِنْ خَلْقِكَ.\nرَبِّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ.","tr":"Allahumma anta s-salam, wa minka s-salam, wa ilayka ya'udu s-salam; as'aluka ya dha l-jalali wal-ikram an tastajiba lana da'watana, wa an tu'tiyana raghbatana, wa an tughniyana 'amman aghnaytahu 'anna min khalqik.\nRabbi qini 'adhabaka yawma tab'athu 'ibadak.","en":"O Allah, You are Peace, from You comes peace, and to You peace returns. I ask You, O Possessor of Majesty and Honour, to answer our prayer, to give us what we long for, and to make us free of need of those of Your creation whom You have made free of need of us.\nMy Lord, shield me from Your punishment on the day You raise Your servants.","ref":null,"q":null,"source":"first paragraph: Ibn al-Sunni; al-Bazzar. \"رب قني عذابك…\": Muslim and the four Sunan.","page":"84–85","status":"draft"},
{"n":21,"ar":"اللَّهُمَّ خِرْ لِي وَاخْتَرْ لِي.","tr":"Allahumma khir li wakhtar li.","en":"O Allah, choose what is good for me and make the choice for me.","ref":null,"q":null,"source":"al-Tirmidhi.","page":"85","status":"draft"},
{"n":22,"ar":"اللَّهُمَّ رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ.\nبِسْمِ اللهِ عَلَى نَفْسِي وَمَالِي وَدِينِي.","tr":"Allahumma rabbana atina fi d-dunya hasanatan wa fi l-akhirati hasanatan wa qina 'adhaba n-nar.\nBismi llahi 'ala nafsi wa mali wa dini.","en":"\"O Allah,\" then Qurʾān translation from Pickthall (2:201).\nIn the name of Allah, over my self, my wealth and my religion.","ref":"al-Baqara 2:201 (رَبَّنَا آتِنَا … عَذَابَ النَّارِ), standard mushaf wording. Nomani quotes it in the hadith form, with «اللَّهُمَّ» before «رَبَّنَا». Otherwise the extent is the same as the full ayah.","q":null,"source":"first paragraph: al-Bukhari and Muslim (from Anas). \"بسم الله على نفسي…\": Ibn al-Sunni.","page":"85","status":"draft"},
{"n":23,"ar":"اللَّهُمَّ أَرْضِنِي بِقَضَائِكَ، وَبَارِكْ لِي فِيمَا قُدِّرَ لِي، حَتَّى لَا أُحِبَّ تَعْجِيلَ مَا أَخَّرْتَ، وَلَا تَأْخِيرَ مَا عَجَّلْتَ.","tr":"Allahumma ardini bi-qada'ik, wa barik li fima quddira li, hatta la uhibba ta'jila ma akhkharta, wa la ta'khira ma 'ajjalt.","en":"O Allah, make me content with Your decree and bless me in what has been decreed for me, so that I do not wish to hasten what You have delayed, or to delay what You have hastened.","ref":null,"q":null,"source":"no separate marker. Nomani's Ibn al-Sunni note at no. 22 quotes the start of this wording.","page":"85","status":"draft"},
{"n":24,"ar":"اللَّهُمَّ لَا عَيْشَ إِلَّا عَيْشُ الْآخِرَةِ.","tr":"Allahumma la 'aysha illa 'ayshu l-akhirah.","en":"O Allah, there is no life except the life of the Hereafter.","ref":null,"q":null,"source":"Ahmad, al-Bukhari, Muslim and others (from Anas and Sahl ibn Saʿd).","page":"86","status":"draft"},
{"n":25,"ar":"اللَّهُمَّ أَحْيِنِي مِسْكِينًا، وَأَمِتْنِي مِسْكِينًا، وَاحْشُرْنِي فِي زُمْرَةِ الْمَسَاكِينِ.","tr":"Allahumma ahyini miskinan, wa amitni miskinan, wahshurni fi zumrati l-masakin.","en":"O Allah, keep me alive humble, let me die humble, and raise me among the company of the humble.","ref":null,"q":null,"source":"ʿAbd ibn Humayd; Ibn Majah; al-Tabarani (al-Kabir); al-Diya' al-Maqdisi.","page":"86","status":"draft"},
{"n":26,"ar":"اللَّهُمَّ اجْعَلْنِي مِنَ الَّذِينَ إِذَا أَحْسَنُوا اسْتَبْشَرُوا، وَإِذَا أَسَاءُوا اسْتَغْفَرُوا.","tr":"Allahumma j'alni mina lladhina idha ahsanu stabsharu, wa idha asa'u staghfaru.","en":"O Allah, make me one of those who are glad when they do good and ask forgiveness when they do wrong.","ref":null,"q":null,"source":"Ibn Majah; al-Bayhaqi (Shuʿab al-Iman).","page":"86","status":"draft"},
{"n":27,"ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ رَحْمَةً مِنْ عِنْدِكَ تَهْدِي بِهَا قَلْبِي، وَتَجْمَعُ بِهَا أَمْرِي، وَتَلُمُّ بِهَا شَعَثِي، وَتُصْلِحُ بِهَا دِينِي، وَتَقْضِي بِهَا دَيْنِي، وَتَحْفَظُ بِهَا غَائِبِي، وَتَرْفَعُ بِهَا شَاهِدِي، وَتُبَيِّضُ بِهَا وَجْهِي، وَتُزَكِّي بِهَا عَمَلِي، وَتُلْهِمُنِي بِهَا رُشْدِي، وَتَرُدُّ بِهَا أُلْفَتِي، وَتَعْصِمُنِي بِهَا مِنْ كُلِّ سُوءٍ.","tr":"Allahumma inni as'aluka rahmatan min 'indika tahdi biha qalbi, wa tajma'u biha amri, wa talummu biha sha'athi, wa tuslihu biha dini, wa taqdi biha dayni, wa tahfazu biha gha'ibi, wa tarfa'u biha shahidi, wa tubayyidu biha wajhi, wa tuzakki biha 'amali, wa tulhimuni biha rushdi, wa taruddu biha ulfati, wa ta'simuni biha min kulli su'.","en":"O Allah, I ask You for a mercy from You by which You will:\n- guide my heart and bring my affairs together;\n- gather what is scattered in me;\n- set my religion right and pay off my debt;\n- protect what is hidden of me and raise what is seen of me;\n- make my face shine and purify my deeds;\n- inspire me with right guidance;\n- give back to me the things I love and am used to;\n- protect me from every evil.","ref":null,"q":null,"source":"al-Tirmidhi; Muhammad ibn Nasr al-Marwazi; al-Tabarani (al-Kabir); al-Bayhaqi (al-Daʿawat); al-Hakim (from Ibn ʿAbbas). Nos. 28–35 continue this hadith.","page":"86–87","status":"draft"},
{"n":28,"ar":"اللَّهُمَّ أَعْطِنِي إِيمَانًا لَا يَرْتَدُّ، وَيَقِينًا لَيْسَ بَعْدَهُ كُفْرٌ، وَرَحْمَةً أَنَالُ بِهَا شَرَفَ كَرَامَتِكَ فِي الدُّنْيَا وَالْآخِرَةِ.","tr":"Allahumma a'tini imanan la yartadd, wa yaqinan laysa ba'dahu kufr, wa rahmatan analu biha sharafa karamatika fi d-dunya wal-akhirah.","en":"O Allah, give me faith that does not turn back, certainty that no disbelief follows, and a mercy by which I reach the honour of Your generosity in this world and the Hereafter.","ref":null,"q":null,"source":"no separate note (continues no. 27).","page":"87","status":"draft"},
{"n":29,"ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ الْفَوْزَ فِي الْقَضَاءِ، وَنُزُلَ الشُّهَدَاءِ، وَعَيْشَ السُّعَدَاءِ، وَمُرَافَقَةَ الْأَنْبِيَاءِ، وَالنَّصْرَ عَلَى الْأَعْدَاءِ، إِنَّكَ سَمِيعُ الدُّعَاءِ.","tr":"Allahumma inni as'aluka l-fawza fi l-qada', wa nuzula sh-shuhada', wa 'aysha s-su'ada', wa murafaqata l-anbiya', wan-nasra 'ala l-a'da', innaka sami'u d-du'a'.","en":"O Allah, I ask You for success in what You decree, the welcome given to the martyrs, the life of the blessed, the company of the prophets, and victory over enemies. You hear every prayer.","ref":null,"q":null,"source":"no separate note (continues no. 27).","page":"87","status":"draft"},
{"n":30,"ar":"اللَّهُمَّ إِنِّي أُنْزِلُ بِكَ حَاجَتِي، وَإِنْ قَصُرَ رَأْيِي، وَضَعُفَ عَمَلِي، افْتَقَرْتُ إِلَى رَحْمَتِكَ، فَأَسْأَلُكَ يَا قَاضِيَ الْأُمُورِ، وَيَا شَافِيَ الصُّدُورِ، كَمَا تُجِيرُ بَيْنَ الْبُحُورِ، أَنْ تُجِيرَنِي مِنْ عَذَابِ السَّعِيرِ، وَمِنْ دَعْوَةِ الثُّبُورِ، وَمِنْ فِتْنَةِ الْقُبُورِ.","tr":"Allahumma inni unzilu bika hajati, wa in qasura ra'yi, wa da'ufa 'amali, iftaqartu ila rahmatik; fa-as'aluka ya qadiya l-umur, wa ya shafiya s-sudur, kama tujiru bayna l-buhur, an tujirani min 'adhabi s-sa'ir, wa min da'wati th-thubur, wa min fitnati l-qubur.","en":"O Allah, I bring my need to You. Even though my judgement falls short and my deeds are weak, I am in need of Your mercy. So I ask You, O Decider of all affairs and Healer of hearts: just as You keep the seas apart, keep me apart from the punishment of the Blaze, from the cry of ruin, and from the trial of the graves.","ref":null,"q":null,"source":"no separate note (continues no. 27).","page":"87–88","status":"draft"},
{"n":31,"ar":"اللَّهُمَّ مَا قَصُرَ عَنْهُ رَأْيِي، وَضَعُفَ عَنْهُ عَمَلِي، وَلَمْ تَبْلُغْهُ مُنْيَتِي وَمَسْأَلَتِي، مِنْ خَيْرٍ وَعَدْتَهُ أَحَدًا مِنْ خَلْقِكَ، أَوْ خَيْرٍ أَنْتَ مُعْطِيهِ أَحَدًا مِنْ عِبَادِكَ، فَإِنِّي أَرْغَبُ إِلَيْكَ فِيهِ، وَأَسْأَلُكَ بِرَحْمَتِكَ رَبَّ الْعَالَمِينَ.","tr":"Allahumma ma qasura 'anhu ra'yi, wa da'ufa 'anhu 'amali, wa lam tablughhu munyati wa mas'alati, min khayrin wa'adtahu ahadan min khalqik, aw khayrin anta mu'tihi ahadan min 'ibadik, fa-inni arghabu ilayka fih, wa as'aluka bi-rahmatika rabba l-'alamin.","en":"O Allah, there may be good that my judgement fell short of, that my deeds were too weak to reach, and that my wishes and requests never reached. It may be good You have promised to someone of Your creation, or good You are giving to one of Your servants. I long to You for it, and I ask You by Your mercy, Lord of the worlds.","ref":null,"q":null,"source":"no separate note (continues no. 27).","page":"88","status":"draft"},
{"n":32,"ar":"اللَّهُمَّ ذَا الْحَبْلِ الشَّدِيدِ، وَالْأَمْرِ الرَّشِيدِ، أَسْأَلُكَ الْأَمْنَ يَوْمَ الْوَعِيدِ، وَالْجَنَّةَ يَوْمَ الْخُلُودِ، مَعَ الْمُقَرَّبِينَ الشُّهُودِ، الرُّكَّعِ السُّجُودِ، الْمُوفِينَ بِالْعُهُودِ، إِنَّكَ رَحِيمٌ وَدُودٌ، إِنَّكَ تَفْعَلُ مَا تُرِيدُ.","tr":"Allahumma dha l-habli sh-shadid, wal-amri r-rashid, as'aluka l-amna yawma l-wa'id, wal-jannata yawma l-khulud, ma'a l-muqarrabina sh-shuhud, ar-rukka'i s-sujud, al-mufina bil-'uhud; innaka rahimun wadud, innaka taf'alu ma turid.","en":"O Allah, Possessor of the strong rope and the right command, I ask You for safety on the Day of the Threat, and Paradise on the Day of Eternity, with those brought near who bear witness, who bow and prostrate, and who keep their covenants. You are Merciful and Loving; You do whatever You will.","ref":null,"q":null,"source":"no separate note (continues no. 27).","page":"88","status":"draft"},
{"n":33,"ar":"اللَّهُمَّ اجْعَلْنَا هَادِينَ مُهْتَدِينَ، غَيْرَ ضَالِّينَ وَلَا مُضِلِّينَ، سِلْمًا لِأَوْلِيَائِكَ، وَحَرْبًا لِأَعْدَائِكَ، نُحِبُّ بِحُبِّكَ مَنْ أَحَبَّكَ، وَنُعَادِي بِعَدَاوَتِكَ مَنْ خَالَفَكَ مِنْ خَلْقِكَ.","tr":"Allahumma j'alna hadina muhtadin, ghayra dallina wa la mudillin, silman li-awliya'ik, wa harban li-a'da'ik, nuhibbu bi-hubbika man ahabbak, wa nu'adi bi-'adawatika man khalafaka min khalqik.","en":"O Allah, make us guides who are guided ourselves, neither astray nor leading others astray. Make us at peace with Your friends and at war with Your enemies, loving with Your love whoever loves You, and opposing with Your enmity whoever of Your creation opposes You.","ref":null,"q":null,"source":"no separate note (continues no. 27).","page":"88","status":"draft"},
{"n":34,"ar":"اللَّهُمَّ هَذَا الدُّعَاءُ وَعَلَيْكَ الْإِجَابَةُ، وَهَذَا الْجُهْدُ وَعَلَيْكَ التُّكْلَانُ.","tr":"Allahumma hadha d-du'a'u wa 'alayka l-ijabah, wa hadha l-juhdu wa 'alayka t-tuklan.","en":"O Allah, this is the prayer, and the answer is Yours to give; this is the effort, and our trust is in You.","ref":null,"q":null,"source":"no separate note (continues no. 27).","page":"88","status":"draft"},
{"n":35,"ar":"اللَّهُمَّ اجْعَلْ لِي نُورًا فِي قَلْبِي، وَنُورًا فِي قَبْرِي، وَنُورًا مِنْ بَيْنِ يَدَيَّ، وَنُورًا مِنْ خَلْفِي، وَنُورًا عَنْ يَمِينِي، وَنُورًا عَنْ شِمَالِي، وَنُورًا مِنْ فَوْقِي، وَنُورًا مِنْ تَحْتِي، وَنُورًا فِي سَمْعِي، وَنُورًا فِي بَصَرِي، وَنُورًا فِي شَعْرِي، وَنُورًا فِي بَشَرِي، وَنُورًا فِي لَحْمِي، وَنُورًا فِي دَمِي، وَنُورًا فِي مُخِّي، وَنُورًا فِي عِظَامِي. اللَّهُمَّ أَعْظِمْ لِي نُورًا، وَأَعْطِنِي نُورًا، وَاجْعَلْ لِي نُورًا، وَزِدْنِي نُورًا، وَزِدْنِي نُورًا.\nسُبْحَانَ الَّذِي تَعَطَّفَ بِالْعِزِّ وَقَالَ بِهِ، سُبْحَانَ الَّذِي لَبِسَ الْمَجْدَ وَتَكَرَّمَ بِهِ، سُبْحَانَ الَّذِي لَا يَنْبَغِي التَّسْبِيحُ إِلَّا لَهُ، سُبْحَانَ مَنْ أَحْصَى كُلَّ شَيْءٍ بِعِلْمِهِ، سُبْحَانَ ذِي الْفَضْلِ وَالطَّوْلِ، سُبْحَانَ ذِي الْمَنِّ وَالنِّعَمِ، سُبْحَانَ ذِي الْمَجْدِ وَالْكَرَمِ، سُبْحَانَ ذِي الْجَلَالِ وَالْإِكْرَامِ.","tr":"Allahumma j'al li nuran fi qalbi, wa nuran fi qabri, wa nuran min bayni yadayya, wa nuran min khalfi, wa nuran 'an yamini, wa nuran 'an shimali, wa nuran min fawqi, wa nuran min tahti, wa nuran fi sam'i, wa nuran fi basari, wa nuran fi sha'ri, wa nuran fi bashari, wa nuran fi lahmi, wa nuran fi dami, wa nuran fi mukhkhi, wa nuran fi 'izami. Allahumma a'zim li nuran, wa a'tini nuran, waj'al li nuran, wa zidni nuran, wa zidni nuran.\nSubhana lladhi ta'attafa bil-'izzi wa qala bih; subhana lladhi labisa l-majda wa takarrama bih; subhana lladhi la yanbaghi t-tasbihu illa lah; subhana man ahsa kulla shay'in bi-'ilmih; subhana dhi l-fadli wat-tawl; subhana dhi l-manni wan-ni'am; subhana dhi l-majdi wal-karam; subhana dhi l-jalali wal-ikram.","en":"O Allah, place light in my heart and light in my grave. Place light in front of me and behind me, on my right and on my left, above me and below me. Place light in my hearing and my sight, in my hair and my skin, in my flesh and my blood, in my marrow and my bones. O Allah, make my light great, give me light, place light for me, increase me in light, and increase me in light.\nGlory be to the One who wrapped Himself in might and rules by it. Glory be to the One who put on majesty and is generous with it. Glory be to the One to whom alone glorification is due. Glory be to the One who knows the number of all things. Glory be to the Possessor of bounty and abundance, of favour and blessings, of glory and generosity, of majesty and honour.","ref":null,"q":null,"source":"no separate note (continues no. 27).","page":"88–89","status":"draft"},
{"n":36,"ar":"اللَّهُمَّ لَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَلَا تَنْزِعْ مِنِّي صَالِحَ مَا أَعْطَيْتَنِي.","tr":"Allahumma la takilni ila nafsi tarfata 'ayn, wa la tanzi' minni saliha ma a'taytani.","en":"O Allah, do not leave me to myself for the blink of an eye, and do not take from me the good You have given me.","ref":null,"q":null,"source":"al-Bazzar (from Ibn ʿUmar).","page":"89","status":"draft"},
{"n":37,"ar":"اللَّهُمَّ إِنَّكَ لَسْتَ بِإِلَهٍ اسْتَحْدَثْنَاهُ، وَلَا بِرَبٍّ يَبِيدُ ذِكْرُهُ ابْتَدَعْنَاهُ، وَلَا عَلَيْكَ شُرَكَاءُ يَقْضُونَ مَعَكَ، وَلَا كَانَ لَنَا قَبْلَكَ مِنْ إِلَهٍ نَلْجَأُ إِلَيْهِ وَنَذَرُكَ، وَلَا أَعَانَكَ عَلَى خَلْقِنَا أَحَدٌ فَنُشْرِكَهُ فِيكَ، تَبَارَكْتَ وَتَعَالَيْتَ، فَنَسْأَلُكَ لَا إِلَهَ إِلَّا أَنْتَ اغْفِرْ لِي.","tr":"Allahumma innaka lasta bi-ilahin istahdathnah, wa la bi-rabbin yabidu dhikruhu ibtada'nah, wa la 'alayka shuraka'u yaqduna ma'ak, wa la kana lana qablaka min ilahin nalja'u ilayhi wa nadharuk, wa la a'anaka 'ala khalqina ahadun fa-nushrikahu fik; tabarakta wa ta'alayt; fa-nas'aluka, la ilaha illa ant, ighfir li.","en":"O Allah, You are not a god we brought into being, nor a lord whose memory fades that we invented. You have no partners who judge alongside You. We had no god before You to run to and leave You for, and no one helped You create us that we might make him Your partner. Blessed and exalted are You. So we ask You (there is no god but You): forgive me.","ref":null,"q":null,"source":"al-Tabarani (al-Kabir); Ibn ʿAsakir (from Suhayb).","page":"90","status":"draft"},
{"n":38,"ar":"اللَّهُمَّ إِنَّكَ تَسْمَعُ كَلَامِي، وَتَرَى مَكَانِي، وَتَعْلَمُ سِرِّي وَعَلَانِيَتِي، لَا يَخْفَى عَلَيْكَ شَيْءٌ مِنْ أَمْرِي، وَأَنَا الْبَائِسُ الْفَقِيرُ، الْمُسْتَغِيثُ الْمُسْتَجِيرُ، الْوَجِلُ الْمُشْفِقُ، الْمُقِرُّ الْمُعْتَرِفُ بِذَنْبِي، أَسْأَلُكَ مَسْأَلَةَ الْمِسْكِينِ، وَأَبْتَهِلُ إِلَيْكَ ابْتِهَالَ الْمُذْنِبِ الذَّلِيلِ، وَأَدْعُوكَ دُعَاءَ الْخَائِفِ الضَّرِيرِ، وَدُعَاءَ مَنْ خَضَعَتْ لَكَ رَقَبَتُهُ، وَفَاضَتْ لَكَ عَبْرَتُهُ، وَذَلَّ لَكَ جِسْمُهُ، وَرَغِمَ لَكَ أَنْفُهُ.","tr":"Allahumma innaka tasma'u kalami, wa tara makani, wa ta'lamu sirri wa 'alaniyati, la yakhfa 'alayka shay'un min amri; wa ana l-ba'isu l-faqir, al-mustaghithu l-mustajir, al-wajilu l-mushfiq, al-muqirru l-mu'tarifu bi-dhanbi; as'aluka mas'alata l-miskin, wa abtahilu ilayka btihala l-mudhnibi dh-dhalil, wa ad'uka du'a'a l-kha'ifi d-darir, wa du'a'a man khada'at laka raqabatuh, wa fadat laka 'abratuh, wa dhalla laka jismuh, wa raghima laka anfuh.","en":"O Allah, You hear my words and see where I am. You know what I hide and what I show, and nothing of my affairs is hidden from You. I am the wretched and the poor. I cry for help and seek refuge, afraid and anxious, admitting and confessing my sin.\n- I ask You as the destitute ask.\n- I plead with You as the lowly sinner pleads.\n- I call on You as the frightened and stricken call, as one calls whose neck is bowed before You, whose tears flow for You, whose body is humbled before You, and whose nose is in the dust for You.","ref":null,"q":null,"source":"al-Tabarani (al-Kabir), from Ibn ʿAbbas. No. 39 continues it.","page":"90–91","status":"draft"},
{"n":39,"ar":"اللَّهُمَّ لَا تَجْعَلْنِي بِدُعَائِكَ شَقِيًّا، وَكُنْ لِي رَءُوفًا رَحِيمًا، يَا خَيْرَ الْمَسْئُولِينَ، وَيَا خَيْرَ الْمُعْطِينَ.","tr":"Allahumma la taj'alni bi-du'a'ika shaqiyya, wa kun li ra'ufan rahima, ya khayra l-mas'ulin, wa ya khayra l-mu'tin.","en":"O Allah, do not let me come away disappointed from calling on You. Be kind and merciful to me, O Best of those who are asked and Best of those who give.","ref":null,"q":null,"source":"no separate note (continues no. 38).","page":"91","status":"draft"},
{"n":40,"ar":"اللَّهُمَّ إِلَيْكَ أَشْكُو ضَعْفَ قُوَّتِي، وَقِلَّةَ حِيلَتِي، وَهَوَانِي عَلَى النَّاسِ، يَا أَرْحَمَ الرَّاحِمِينَ، إِلَى مَنْ تَكِلُنِي؟ إِلَى عَدُوٍّ يَتَجَهَّمُنِي، أَمْ إِلَى قَرِيبٍ مَلَّكْتَهُ أَمْرِي؟ إِنْ لَمْ تَكُنْ سَاخِطًا عَلَيَّ فَلَا أُبَالِي، غَيْرَ أَنَّ عَافِيَتَكَ أَوْسَعُ لِي، أَعُوذُ بِنُورِ وَجْهِكَ الْكَرِيمِ الَّذِي أَضَاءَتْ لَهُ السَّمَاوَاتُ، وَأَشْرَقَتْ لَهُ الظُّلُمَاتُ، وَصَلَحَ عَلَيْهِ أَمْرُ الدُّنْيَا وَالْآخِرَةِ، أَنْ تُحِلَّ عَلَيَّ غَضَبَكَ، وَتُنْزِلَ عَلَيَّ سَخَطَكَ، وَلَكَ الْعُتْبَى حَتَّى تَرْضَى، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِكَ.","tr":"Allahumma ilayka ashku da'fa quwwati, wa qillata hilati, wa hawani 'ala n-nas; ya arhama r-rahimin, ila man takiluni? ila 'aduwwin yatajahhamuni, am ila qaribin mallaktahu amri? in lam takun sakhitan 'alayya fa-la ubali, ghayra anna 'afiyataka awsa'u li; a'udhu bi-nuri wajhika l-karimi lladhi ada'at lahu s-samawat, wa ashraqat lahu z-zulumat, wa saluha 'alayhi amru d-dunya wal-akhirah, an tuhilla 'alayya ghadabak, wa tunzila 'alayya sakhatak; wa laka l-'utba hatta tarda, wa la hawla wa la quwwata illa bik.","en":"O Allah, to You I complain of my weakness, my lack of means and how little people think of me. O Most Merciful of the merciful, to whom will You hand me over? To an enemy who frowns at me, or to a relative whom You have put in charge of my affairs? If You are not angry with me, I do not mind, though Your protection would be easier for me. I seek refuge in the light of Your noble Face, by which the heavens are lit and the darknesses shine, and by which the affairs of this world and the next are set right. I seek refuge from Your anger coming down on me and Your displeasure descending on me. I will keep seeking Your pleasure until You are pleased. There is no power and no strength except through You.","ref":null,"q":null,"source":"al-Tabarani (al-Kabir), from ʿAbd Allah ibn Jaʿfar; Ibn ʿAdi and Ibn ʿAsakir.","page":"91–92","status":"draft"},
{"n":41,"ar":"اللَّهُمَّ وَاقِيَةً كَوَاقِيَةِ الْوَلِيدِ.","tr":"Allahumma waqiyatan ka-waqiyati l-walid.","en":"O Allah, [grant me] protection like the protection given to a newborn child.","ref":null,"q":null,"source":"Abu Ya'la (from Ibn ʿUmar); al-Bukhari (al-Tarikh).","page":"92","status":"draft"},
{"n":42,"ar":"اللَّهُمَّ إِنَّا نَسْأَلُكَ قُلُوبًا أَوَّاهَةً مُخْبِتَةً مُنِيبَةً فِي سَبِيلِكَ.","tr":"Allahumma inna nas'aluka quluban awwahatan mukhbitatan munibatan fi sabilik.","en":"O Allah, we ask You for hearts that sigh often, that are humble, and that turn back to You, in Your path.","ref":null,"q":null,"source":"al-Hakim (al-Mustadrak).","page":"92","status":"draft"},
{"n":43,"ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ إِيمَانًا يُبَاشِرُ قَلْبِي، وَيَقِينًا صَادِقًا، حَتَّى أَعْلَمَ أَنَّهُ لَا يُصِيبُنِي إِلَّا مَا كَتَبْتَ لِي، وَرِضًا مِنَ الْمَعِيشَةِ بِمَا قَسَمْتَ لِي.","tr":"Allahumma inni as'aluka imanan yubashiru qalbi, wa yaqinan sadiqan, hatta a'lama annahu la yusibuni illa ma katabta li, wa ridan mina l-ma'ishati bima qasamta li.","en":"O Allah, I ask You for faith that settles deep in my heart, and true certainty, so that I know nothing will reach me except what You have written for me. And I ask You for contentment with the living You have allotted me.","ref":null,"q":null,"source":"al-Bazzar (from Ibn ʿUmar).","page":"92","status":"draft"},
{"n":44,"ar":"اللَّهُمَّ لَكَ الْحَمْدُ كَالَّذِي نَقُولُ، وَخَيْرًا مِمَّا نَقُولُ.","tr":"Allahumma laka l-hamdu ka-lladhi naqul, wa khayran mimma naqul.","en":"O Allah, Yours is the praise, as we say it, and better than what we say.","ref":null,"q":null,"source":"al-Tirmidhi; al-Bayhaqi (Shuʿab al-Iman), from ʿAli. Nos. 45–47 continue this hadith.","page":"92","status":"draft"},
{"n":45,"ar":"اللَّهُمَّ لَكَ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي، وَإِلَيْكَ مَآبِي، وَلَكَ رَبِّ تُرَاثِي.","tr":"Allahumma laka salati wa nusuki wa mahyaya wa mamati, wa ilayka ma'abi, wa laka rabbi turathi.","en":"O Allah, my prayer and my worship, my life and my death are for You. To You is my return, and what I leave behind is Yours, my Lord.","ref":null,"q":null,"source":"no separate note (continues no. 44).","page":"93","status":"draft"},
{"n":46,"ar":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَوَسْوَسَةِ الصَّدْرِ، وَشَتَاتِ الْأَمْرِ.","tr":"Allahumma inni a'udhu bika min 'adhabi l-qabr, wa waswasati s-sadr, wa shatati l-amr.","en":"O Allah, I seek refuge in You from the punishment of the grave, from the whispering in the breast, and from my affairs falling apart.","ref":null,"q":null,"source":"no separate note (continues no. 44).","page":"93","status":"draft"},
{"n":47,"ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ خَيْرِ مَا تَجِيءُ بِهِ الرِّيَاحُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا تَجِيءُ بِهِ الرِّيَاحُ.","tr":"Allahumma inni as'aluka min khayri ma taji'u bihi r-riyah, wa a'udhu bika min sharri ma taji'u bihi r-riyah.","en":"O Allah, I ask You for the good the winds bring, and I seek refuge in You from the evil the winds bring.","ref":null,"q":null,"source":"no separate note (continues no. 44).","page":"93","status":"draft"},
{"n":48,"ar":"اللَّهُمَّ اجْعَلْنِي أُعَظِّمُ شُكْرَكَ، وَأُكْثِرُ ذِكْرَكَ، وَأَتَّبِعُ نَصِيحَتَكَ، وَأَحْفَظُ وَصِيَّتَكَ.","tr":"Allahumma j'alni u'azzimu shukrak, wa ukthiru dhikrak, wa attabi'u nasihatak, wa ahfazu wasiyyatak.","en":"O Allah, make me one who gives great thanks to You, remembers You often, follows Your counsel and keeps Your instructions.","ref":null,"q":null,"source":"al-Tirmidhi (from Abu Hurayra).","page":"93","status":"draft"},
{"n":49,"ar":"اللَّهُمَّ إِنَّ قُلُوبَنَا وَنَوَاصِيَنَا وَجَوَارِحَنَا بِيَدِكَ، لَمْ تُمَلِّكْنَا مِنْهَا شَيْئًا، فَإِذَا فَعَلْتَ ذَلِكَ بِنَا فَكُنْ أَنْتَ وَلِيَّنَا، وَاهْدِنَا إِلَى سَوَاءِ السَّبِيلِ.","tr":"Allahumma inna qulubana wa nawasiyana wa jawarihana bi-yadik, lam tumallikna minha shay'a; fa-idha fa'alta dhalika bina fa-kun anta waliyyana, wahdina ila sawa'i s-sabil.","en":"O Allah, our hearts, our forelocks and our limbs are in Your hand; You have given us control over none of them. Since You have done this with us, be our Protector and guide us to the right way.","ref":null,"q":null,"source":"Abu Nuʿaym (al-Hilya), from Jabir.","page":"93","status":"draft"},
{"n":50,"ar":"اللَّهُمَّ اجْعَلْ حُبَّكَ أَحَبَّ الْأَشْيَاءِ إِلَيَّ، وَاجْعَلْ خَشْيَتَكَ أَخْوَفَ الْأَشْيَاءِ عِنْدِي، وَاقْطَعْ عَنِّي حَاجَاتِ الدُّنْيَا بِالشَّوْقِ إِلَى لِقَائِكَ، وَإِذَا أَقْرَرْتَ أَعْيُنَ أَهْلِ الدُّنْيَا مِنْ دُنْيَاهُمْ فَأَقْرِرْ عَيْنِي مِنْ عِبَادَتِكَ.","tr":"Allahumma j'al hubbaka ahabba l-ashya'i ilayy, waj'al khashyataka akhwafa l-ashya'i 'indi, waqta' 'anni hajati d-dunya bish-shawqi ila liqa'ik, wa idha aqrarta a'yuna ahli d-dunya min dunyahum fa-aqrir 'ayni min 'ibadatik.","en":"O Allah, make love of You the dearest thing to me, and fear of You the thing I fear most. Free me from the needs of this world through longing to meet You. When You delight the eyes of worldly people with their world, delight my eyes with worshipping You.","ref":null,"q":null,"source":"Abu Nuʿaym (al-Hilya), from al-Haytham ibn Malik al-Taʾi.","page":"94","status":"draft"},
{"n":51,"ar":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ الْأَعْمَيَيْنِ: السَّيْلِ وَالْبَعِيرِ الصَّئُولِ.","tr":"Allahumma inni a'udhu bika min sharri l-a'mayayn: as-sayli wal-ba'iri s-sa'ul.","en":"O Allah, I seek refuge in You from the evil of the two blind things: the flood and the charging camel.","ref":null,"q":null,"source":"al-Tabarani (al-Kabir), from ʿA'isha bint Qudama.","page":"94","status":"draft"},
{"n":52,"ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ الصِّحَّةَ، وَالْعِفَّةَ، وَالْأَمَانَةَ، وَحُسْنَ الْخُلُقِ، وَالرِّضَا بِالْقَدَرِ.","tr":"Allahumma inni as'aluka s-sihhah, wal-'iffah, wal-amanah, wa husna l-khuluq, war-rida bil-qadar.","en":"O Allah, I ask You for health, chastity, trustworthiness, good character, and contentment with what is decreed.","ref":null,"q":null,"source":"al-Bazzar; al-Tabarani (al-Kabir), from Ibn ʿUmar.","page":"94","status":"draft"},
{"n":53,"ar":"اللَّهُمَّ لَكَ الْحَمْدُ شُكْرًا، وَلَكَ الْمَنُّ فَضْلًا.","tr":"Allahumma laka l-hamdu shukra, wa laka l-mannu fadla.","en":"O Allah, Yours is the praise, in thanks; and Yours is the favour, out of Your bounty.","ref":null,"q":null,"source":"al-Tabarani (al-Kabir), from Kaʿb ibn ʿUjra.","page":"94","status":"draft"},
{"n":54,"ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ التَّوْفِيقَ لِمَحَابِّكَ مِنَ الْأَعْمَالِ، وَصِدْقَ التَّوَكُّلِ عَلَيْكَ، وَحُسْنَ الظَّنِّ بِكَ.","tr":"Allahumma inni as'aluka t-tawfiqa li-mahabbika mina l-a'mal, wa sidqa t-tawakkuli 'alayk, wa husna z-zanni bik.","en":"O Allah, I ask You for help to do the deeds You love, for true reliance on You, and for a good opinion of You.","ref":null,"q":null,"source":"Abu Nuʿaym (al-Hilya), from al-Awzaʿi; al-Hakim al-Tirmidhi, from Abu Hurayra.","page":"94–95","status":"draft"},
{"n":55,"ar":"اللَّهُمَّ افْتَحْ مَسَامِعَ قَلْبِي لِذِكْرِكَ، وَارْزُقْنِي طَاعَتَكَ، وَطَاعَةَ رَسُولِكَ، وَعَمَلًا بِكِتَابِكَ.","tr":"Allahumma ftah masami'a qalbi li-dhikrik, warzuqni ta'atak, wa ta'ata rasulik, wa 'amalan bi-kitabik.","en":"O Allah, open the ears of my heart to Your remembrance, and grant me obedience to You, obedience to Your Messenger, and acting on Your Book.","ref":null,"q":null,"source":"al-Tabarani (al-Awsat), from ʿAli.","page":"95","status":"draft"},
{"n":56,"ar":"اللَّهُمَّ اجْعَلْنِي أَخْشَاكَ كَأَنِّي أَرَاكَ أَبَدًا حَتَّى أَلْقَاكَ، وَأَسْعِدْنِي بِتَقْوَاكَ، وَلَا تُشْقِنِي بِمَعْصِيَتِكَ، وَخِرْ لِي فِي قَضَائِكَ، وَبَارِكْ لِي فِي قَدَرِكَ، حَتَّى لَا أُحِبَّ تَعْجِيلَ مَا أَخَّرْتَ، وَلَا تَأْخِيرَ مَا عَجَّلْتَ، وَاجْعَلْ غِنَايَ فِي نَفْسِي.","tr":"Allahumma j'alni akhshaka ka-anni araka abadan hatta alqak, wa as'idni bi-taqwak, wa la tushqini bi-ma'siyatik, wa khir li fi qada'ik, wa barik li fi qadarik, hatta la uhibba ta'jila ma akhkharta wa la ta'khira ma 'ajjalt, waj'al ghinaya fi nafsi.","en":"O Allah, make me fear You as though I see You, always, until I meet You. Make me happy through being mindful of You, and do not make me wretched by disobeying You. Choose what is good for me in Your decree and bless me in what You have measured out, so that I do not wish to hasten what You have delayed, or to delay what You have hastened. And put my sufficiency in my own self.","ref":null,"q":null,"source":"al-Tabarani (al-Awsat), from Abu Hurayra.","page":"95","status":"draft"},
{"n":57,"ar":"اللَّهُمَّ الْطُفْ بِي فِي تَيْسِيرِ كُلِّ عَسِيرٍ، فَإِنَّ تَيْسِيرَ كُلِّ عَسِيرٍ عَلَيْكَ يَسِيرٌ، وَأَسْأَلُكَ الْيُسْرَ وَالْمُعَافَاةَ فِي الدُّنْيَا وَالْآخِرَةِ.","tr":"Allahumma ltuf bi fi taysiri kulli 'asir, fa-inna taysira kulli 'asirin 'alayka yasir, wa as'aluka l-yusra wal-mu'afata fi d-dunya wal-akhirah.","en":"O Allah, be gentle with me by making every hard thing easy, for making every hard thing easy is easy for You. And I ask You for ease and well-being in this world and the Hereafter.","ref":null,"q":null,"source":"al-Tabarani (al-Awsat), from Abu Hurayra.","page":"95","status":"draft"},
{"n":58,"ar":"اللَّهُمَّ اعْفُ عَنِّي، فَإِنَّكَ عَفُوٌّ كَرِيمٌ.","tr":"Allahumma 'fu 'anni, fa-innaka 'afuwwun karim.","en":"O Allah, pardon me, for You are Pardoning and Generous.","ref":null,"q":null,"source":"al-Tabarani (al-Awsat), from Abu Saʿid.","page":"95","status":"draft"}]},{"manzil":5,"day":"Wednesday","dayAr":"يوم الأربعاء","duas":[{"n":1,"ar":"اللَّهُمَّ طَهِّرْ قَلْبِي مِنَ النِّفَاقِ، وَعَمَلِي مِنَ الرِّيَاءِ، وَلِسَانِي مِنَ الْكَذِبِ، وَعَيْنِي مِنَ الْخِيَانَةِ، فَإِنَّكَ تَعْلَمُ خَائِنَةَ الْأَعْيُنِ وَمَا تُخْفِي الصُّدُورُ.","tr":"Allahumma tahhir qalbi minan-nifaq, wa ʿamali minar-riya', wa lisani minal-kadhib, wa ʿayni minal-khiyanah, fa innaka taʿlamu kha'inatal-aʿyuni wa ma tukhfis-sudur.","en":"O Allah, purify my heart of hypocrisy, my deeds of showing off, my tongue of lying, and my eyes of treachery. For You know the treachery of the eyes and what the breasts conceal.","ref":"«خَائِنَةَ الْأَعْيُنِ وَمَا تُخْفِي الصُّدُورُ» is from Ghafir 40:19.","q":null,"source":"al-Hakim al-Tirmidhi, *Nawadir al-Usul*; al-Khatib, *Tarikh Baghdad* (Umm Maʿbad).","page":"96","status":"draft"},
{"n":2,"ar":"اللَّهُمَّ ارْزُقْنِي عَيْنَيْنِ هَطَّالَتَيْنِ تَسْقِيَانِ الْقَلْبَ بِذُرُوفِ الدَّمْعِ مِنْ خَشْيَتِكَ، قَبْلَ أَنْ تَكُونَ الدُّمُوعُ دَمًا وَالْأَضْرَاسُ جَمْرًا.","tr":"Allahumma-rzuqni ʿaynayni hattalatayni tasqiyanil-qalba bi dhurufid-damʿi min khashyatik, qabla an takunad-dumuʿu daman wal-adrasu jamra.","en":"O Allah, grant me two eyes that pour freely and water the heart with flowing tears out of fear of You, before tears become blood and molars become embers.","ref":null,"q":null,"source":"Ibn ʿAsakir (Ibn ʿUmar).","page":"96","status":"draft"},
{"n":3,"ar":"اللَّهُمَّ عَافِنِي فِي قُدْرَتِكَ، وَأَدْخِلْنِي فِي رَحْمَتِكَ، وَاقْضِ أَجَلِي فِي طَاعَتِكَ، وَاخْتِمْ لِي بِخَيْرِ عَمَلِي، وَاجْعَلْ ثَوَابَهُ الْجَنَّةَ.","tr":"Allahumma ʿafini fi qudratik, wa adkhilni fi rahmatik, waqdi ajali fi taʿatik, wakhtim li bi khayri ʿamali, wajʿal thawabahul-jannah.","en":"O Allah, keep me well by Your power, bring me into Your mercy, let my life run out in obedience to You, seal my life with the best of my deeds, and make its reward Paradise.","ref":null,"q":null,"source":"Ibn ʿAsakir; al-Bayhaqi, *Sunan* (Ibn ʿUmar).","page":"96","status":"draft"},
{"n":4,"ar":"اللَّهُمَّ أَغْنِنِي بِالْعِلْمِ، وَزَيِّنِّي بِالْحِلْمِ، وَأَكْرِمْنِي بِالتَّقْوَى، وَجَمِّلْنِي بِالْعَافِيَةِ.","tr":"Allahumma aghnini bil-ʿilm, wa zayyinni bil-hilm, wa akrimni bit-taqwa, wa jammilni bil-ʿafiyah.","en":"O Allah, make me rich through knowledge, adorn me with forbearance, honour me with God-consciousness, and beautify me with well-being.","ref":null,"q":null,"source":"Ibn al-Najjar; al-Rafiʿi (Ibn ʿUmar).","page":"97","status":"draft"},
{"n":5,"ar":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ خَلِيلٍ مَاكِرٍ، عَيْنَاهُ تَرَيَانِي وَقَلْبُهُ يَرْعَانِي، إِنْ رَأَى حَسَنَةً دَفَنَهَا، وَإِنْ رَأَى سَيِّئَةً أَذَاعَهَا.","tr":"Allahumma inni aʿudhu bika min khalilin makir, ʿaynahu tarayani wa qalbuhu yarʿani, in ra'a hasanatan dafanaha, wa in ra'a sayyi'atan adhaʿaha.","en":"O Allah, I seek refuge in You from a scheming friend whose eyes watch me and whose heart keeps track of me. If he sees a good deed he buries it, and if he sees a bad one he spreads it.","ref":null,"q":null,"source":"Ibn al-Najjar (Saʿid al-Maqburi).","page":"97","status":"draft"},
{"n":6,"ar":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْبُؤْسِ وَالتَّبَاؤُسِ.","tr":"Allahumma inni aʿudhu bika minal-bu'si wat-taba'us.","en":"O Allah, I seek refuge in You from hardship and from putting on a show of hardship.","ref":null,"q":null,"source":"al-Tabarani (via al-Munawi, *Kunuz al-Haqa'iq*).","page":"97","status":"draft"},
{"n":7,"ar":"اللَّهُمَّ لَا يُدْرِكْنِي زَمَانٌ، وَلَا يُدْرِكُوا زَمَانًا لَا يُتَّبَعُ فِيهِ الْعَلِيمُ، وَلَا يُسْتَحْيَى فِيهِ مِنَ الْحَلِيمِ، قُلُوبُهُمْ قُلُوبُ الْأَعَاجِمِ، وَأَلْسِنَتُهُمْ أَلْسِنَةُ الْعَرَبِ.","tr":"Allahumma la yudrikni zaman, wa la yudriku zamanan la yuttabaʿu fihil-ʿalim, wa la yustahya fihi minal-halim, qulubuhum qulubul-aʿajim, wa alsinatuhum alsinatul-ʿArab.","en":"O Allah, let no time overtake me, and let them not live to see a time, in which the learned are not followed and the forbearing are not respected. In that time people's hearts are the hearts of foreigners and their tongues are the tongues of Arabs.","ref":null,"q":null,"source":"Ahmad, *Musnad* (Sahl b. Saʿd); al-Hakim (Abu Hurayra).","page":"97","status":"draft"},
{"n":8,"ar":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ، وَغَلَبَةِ الْعَدُوِّ، وَمِنْ بَوَارِ الْأَيِّمِ، وَمِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ.","tr":"Allahumma inni aʿudhu bika min ghalabatid-dayn, wa ghalabatil-ʿaduww, wa min bawaril-ayyim, wa min fitnatil-masihid-dajjal.","en":"O Allah, I seek refuge in You from being overwhelmed by debt and overpowered by an enemy, from a woman being left unmarried with no one seeking her, and from the trial of the False Messiah.","ref":null,"q":null,"source":"al-Daraqutni, *al-Afrad*; al-Tabarani, *al-Kabir* (Ibn ʿAbbas).","page":"97","status":"draft"},
{"n":9,"ar":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ فِتْنَةِ النِّسَاءِ، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ.","tr":"Allahumma inni aʿudhu bika min fitnatin-nisa', wa aʿudhu bika min ʿadhabil-qabr.","en":"O Allah, I seek refuge in You from the trial of women, and I seek refuge in You from the punishment of the grave.","ref":null,"q":null,"source":"al-Khara'iti, *Iʿtilal al-Qulub* (Saʿd).","page":"98","status":"draft"},
{"n":10,"ar":"اللَّهُمَّ إِنِّي أَتَّخِذُ عِنْدَكَ عَهْدًا لَنْ تُخْلِفَنِيهِ، فَإِنَّمَا أَنَا بَشَرٌ، فَأَيُّمَا مُؤْمِنٍ آذَيْتُهُ أَوْ شَتَمْتُهُ أَوْ جَلَدْتُهُ أَوْ لَعَنْتُهُ، فَاجْعَلْهَا لَهُ صَلَاةً وَزَكَاةً وَقُرْبَةً تُقَرِّبُهُ بِهَا إِلَيْكَ.","tr":"Allahumma inni attakhidhu ʿindaka ʿahdan lan tukhlifanih, fa innama ana bashar, fa ayyuma mu'minin adhaytuhu aw shatamtuhu aw jaladtuhu aw laʿantuh, fajʿalha lahu salatan wa zakatan wa qurbatan tuqarribuhu biha ilayk.","en":"O Allah, I take a promise from You that You will not break: I am only a human being. So any believer I have hurt, insulted, struck or cursed, make that for him a blessing, a purification and a means of nearness by which You bring him close to You.","ref":null,"q":null,"source":"al-Bukhari; Muslim.","page":"98","status":"draft"},
{"n":11,"ar":"اللَّهُمَّ أَنْتَ خَلَقْتَ نَفْسِي وَأَنْتَ تَوَفَّاهَا، لَكَ مَمَاتُهَا وَمَحْيَاهَا، إِنْ أَحْيَيْتَهَا فَاحْفَظْهَا بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ، وَإِنْ أَمَتَّهَا فَاغْفِرْ لَهَا وَارْحَمْهَا.","tr":"Allahumma anta khalaqta nafsi wa anta tawaffaha, laka mamatuha wa mahyaha, in ahyaytaha fahfazha bima tahfazu bihi ʿibadakas-salihin, wa in amattaha faghfir laha warhamha.","en":"O Allah, You created my soul and You will take it. Its death and its life belong to You. If You keep it alive, guard it as You guard Your righteous servants. If You cause it to die, forgive it and have mercy on it.","ref":null,"q":null,"source":"Muslim (Ibn ʿUmar).","page":"98","status":"draft"},
{"n":12,"ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ.","tr":"Allahumma inni as'alukal-ʿafiyah.","en":"O Allah, I ask You for well-being.","ref":null,"q":null,"source":null,"page":"98","status":"draft"},
{"n":13,"ar":"اللَّهُمَّ حَصِّنْ فَرْجِي، وَيَسِّرْ لِي أَمْرِي.","tr":"Allahumma hassin farji, wa yassir li amri.","en":"O Allah, keep my private parts chaste, and make my affairs easy for me.","ref":null,"q":null,"source":"Ibn Manda, *Kitab al-Wudu'*; al-Mustaghfiri, *al-Daʿawat*; Ibn al-Najjar (ʿAli).","page":"98","status":"draft"},
{"n":14,"ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ تَمَامَ الْوُضُوءِ، وَتَمَامَ الصَّلَاةِ، وَتَمَامَ رِضْوَانِكَ، وَتَمَامَ مَغْفِرَتِكَ.","tr":"Allahumma inni as'aluka tamamal-wudu', wa tamamas-salah, wa tamama ridwanik, wa tamama maghfiratik.","en":"O Allah, I ask You for a complete ablution, a complete prayer, Your complete good pleasure and Your complete forgiveness.","ref":null,"q":null,"source":"al-Harith b. Abi Usama (ʿAli).","page":"99","status":"draft"},
{"n":15,"ar":"اللَّهُمَّ أَعْطِنِي كِتَابِي بِيَمِينِي.","tr":"Allahumma aʿtini kitabi bi yamini.","en":"O Allah, give me my record in my right hand.","ref":null,"q":null,"source":"al-Nawawi, *al-Adhkar*; al-Suyuti, *Jamʿ al-Jawamiʿ* (ʿAli).","page":"99","status":"draft"},
{"n":16,"ar":"اللَّهُمَّ بَيِّضْ وَجْهِي يَوْمَ تَبْيَضُّ الْوُجُوهُ.","tr":"Allahumma bayyid wajhi yawma tabyaddul-wujuh.","en":"O Allah, brighten my face on the Day when faces are brightened.","ref":"«يَوْمَ تَبْيَضُّ وُجُوهٌ», cf. Al ʿImran 3:106.","q":null,"source":"al-Nawawi, *al-Adhkar*; *Jamʿ al-Jawamiʿ* (ʿAli).","page":"99","status":"draft"},
{"n":17,"ar":"اللَّهُمَّ غَشِّنِي بِرَحْمَتِكَ، وَجَنِّبْنِي عَذَابَكَ.","tr":"Allahumma ghashshini bi rahmatik, wa jannibni ʿadhabak.","en":"O Allah, cover me with Your mercy and keep me away from Your punishment.","ref":null,"q":null,"source":"Jamʿ al-Jawamiʿ* (ʿAli); Ibn ʿAsakir, *Amali*.","page":"99","status":"draft"},
{"n":18,"ar":"اللَّهُمَّ ثَبِّتْ قَدَمَيَّ يَوْمَ تَزِلُّ فِيهِ الْأَقْدَامُ.","tr":"Allahumma thabbit qadamayya yawma tazillu fihil-aqdam.","en":"O Allah, keep my feet firm on the Day when feet slip.","ref":null,"q":null,"source":"Ibn ʿAsakir, *Amali* (from ʿAli).","page":"100","status":"draft"},
{"n":19,"ar":"اللَّهُمَّ اجْعَلْنَا مُفْلِحِينَ.","tr":"Allahummajʿalna muflihin.","en":"O Allah, make us among those who succeed.","ref":null,"q":null,"source":"Ibn al-Sunni (Muʿawiya).","page":"100","status":"draft"},
{"n":20,"ar":"اللَّهُمَّ افْتَحْ أَقْفَالَ قُلُوبِنَا بِذِكْرِكَ، وَأَتْمِمْ عَلَيْنَا بِنِعْمَتِكَ، وَأَسْبِغْ عَلَيْنَا مِنْ فَضْلِكَ، وَاجْعَلْنَا مِنْ عِبَادِكَ الصَّالِحِينَ.","tr":"Allahummaftah aqfala qulubina bi dhikrik, wa atmim ʿalayna bi niʿmatik, wa asbigh ʿalayna min fadlik, wajʿalna min ʿibadikas-salihin.","en":"O Allah, open the locks on our hearts with Your remembrance, complete Your blessing upon us, pour Your bounty upon us in full, and make us among Your righteous servants.","ref":null,"q":null,"source":"Ibn al-Sunni (via *Jamʿ al-Jawamiʿ*).","page":"100","status":"draft"},
{"n":21,"ar":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ إِبْلِيسَ وَجُنُودِهِ.","tr":"Allahumma inni aʿudhu bika min Iblisa wa junudih.","en":"O Allah, I seek refuge in You from Iblis and his armies.","ref":null,"q":null,"source":"Ibn al-Sunni (Abu Umama), via al-Nawawi, *al-Adhkar*.","page":"100","status":"draft"},
{"n":22,"ar":"اللَّهُمَّ آتِنِي أَفْضَلَ مَا تُؤْتِي عِبَادَكَ الصَّالِحِينَ.","tr":"Allahumma atini afdala ma tu'ti ʿibadakas-salihin.","en":"O Allah, give me the best of what You give Your righteous servants.","ref":null,"q":null,"source":"al-Nasa'i; Ibn al-Sunni; al-Bukhari, *al-Tarikh* (Saʿd b. Abi Waqqas).","page":"101","status":"draft"},
{"n":23,"ar":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ تَصُدَّ عَنِّي وَجْهَكَ يَوْمَ الْقِيَامَةِ.","tr":"Allahumma inni aʿudhu bika an tasudda ʿanni wajhaka yawmal-qiyamah.","en":"O Allah, I seek refuge in You from Your turning Your Face away from me on the Day of Resurrection.","ref":null,"q":null,"source":"al-Tabarani (Samura).","page":"101","status":"draft"},
{"n":24,"ar":"اللَّهُمَّ أَحْيِنِي مُسْلِمًا، وَأَمِتْنِي مُسْلِمًا.","tr":"Allahumma ahyini musliman, wa amitni muslima.","en":"O Allah, keep me alive as a Muslim and let me die as a Muslim.","ref":null,"q":null,"source":"al-Tabarani (Samura), the same hadith as #23.","page":"101","status":"draft"},
{"n":25,"ar":"اللَّهُمَّ عَذِّبِ الْكَفَرَةَ، وَأَلْقِ فِي قُلُوبِهِمُ الرُّعْبَ، وَخَالِفْ بَيْنَ كَلِمَتِهِمْ، وَأَنْزِلْ عَلَيْهِمْ رِجْزَكَ وَعَذَابَكَ.","tr":"Allahumma ʿadhdhibil-kafarah, wa alqi fi qulubihimur-ruʿb, wa khalif bayna kalimatihim, wa anzil ʿalayhim rijzaka wa ʿadhabak.","en":"O Allah, punish the disbelievers, cast terror into their hearts, divide their word, and send down upon them Your scourge and Your punishment.","ref":null,"q":null,"source":"Muhammad b. Nasr al-Marwazi, *Kitab al-Witr* (the qunut of ʿUmar).","page":"101","status":"draft"},
{"n":26,"ar":"اللَّهُمَّ عَذِّبِ الْكَفَرَةَ أَهْلَ الْكِتَابِ وَالْمُشْرِكِينَ، الَّذِينَ يَجْحَدُونَ آيَاتِكَ، وَيُكَذِّبُونَ رُسُلَكَ، وَيَصُدُّونَ عَنْ سَبِيلِكَ، وَيَتَعَدَّوْنَ حُدُودَكَ، وَيَدْعُونَ مَعَكَ إِلٰهًا آخَرَ، لَا إِلٰهَ إِلَّا أَنْتَ، تَبَارَكْتَ وَتَعَالَيْتَ عَمَّا يَقُولُ الظَّالِمُونَ عُلُوًّا كَبِيرًا.","tr":"Allahumma ʿadhdhibil-kafarata ahlal-kitabi wal-mushrikin, alladhina yajhaduna ayatik, wa yukadhdhibuna rusulak, wa yasudduna ʿan sabilik, wa yataʿaddawna hududak, wa yadʿuna maʿaka ilahan akhar, la ilaha illa ant, tabarakta wa taʿalayta ʿamma yaquluz-zalimuna ʿuluwwan kabira.","en":"O Allah, punish the disbelievers among the People of the Book and the idolaters, who deny Your signs, call Your messengers liars, bar others from Your path, overstep Your limits and call on another god besides You. There is no god but You. Blessed and exalted are You, high above what the wrongdoers say.","ref":"the close echoes al-Isra' 17:43 («عَمَّا يَقُولُونَ عُلُوًّا كَبِيرًا»).","q":null,"source":"al-Tabarani, *Kitab al-Duʿa'* (ʿAli).","page":"101–102","status":"draft"},
{"n":27,"ar":"اللَّهُمَّ اغْفِرْ لَنَا وَلِلْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ وَالْمُسْلِمِينَ وَالْمُسْلِمَاتِ، وَأَصْلِحْهُمْ، وَأَصْلِحْ ذَاتَ بَيْنِهِمْ، وَأَلِّفْ بَيْنَ قُلُوبِهِمْ، وَاجْعَلْ فِي قُلُوبِهِمُ الْإِيمَانَ وَالْحِكْمَةَ، وَثَبِّتْهُمْ عَلَى مِلَّةِ رَسُولِكَ، وَأَوْزِعْهُمْ أَنْ يَشْكُرُوا نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيْهِمْ، وَأَنْ يُوفُوا بِعَهْدِكَ الَّذِي عَاهَدْتَهُمْ عَلَيْهِ، وَانْصُرْهُمْ عَلَى عَدُوِّكَ وَعَدُوِّهِمْ، إِلٰهَ الْحَقِّ. سُبْحَانَكَ لَا إِلٰهَ غَيْرُكَ، اغْفِرْ لِي ذَنْبِي، وَأَصْلِحْ لِي عَمَلِي، إِنَّكَ تَغْفِرُ الذُّنُوبَ لِمَنْ تَشَاءُ وَأَنْتَ الْغَفُورُ الرَّحِيمُ، يَا غَفَّارُ اغْفِرْ لِي، يَا تَوَّابُ تُبْ عَلَيَّ، يَا رَحْمٰنُ ارْحَمْنِي، يَا عَفُوُّ اعْفُ عَنِّي، يَا رَءُوفُ ارْأَفْ بِي، يَا رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ، وَطَوِّقْنِي حُسْنَ عِبَادَتِكَ، يَا رَبِّ أَسْأَلُكَ مِنَ الْخَيْرِ كُلِّهِ، يَا رَبِّ افْتَحْ لِي بِخَيْرٍ، وَاخْتِمْ لِي بِخَيْرٍ، وَآتِنِي تَشَوُّقًا إِلَى لِقَائِكَ مِنْ غَيْرِ ضَرَّاءَ مُضِرَّةٍ وَلَا فِتْنَةٍ مُضِلَّةٍ، وَقِنِي السَّيِّئَاتِ، وَمَنْ تَقِ السَّيِّئَاتِ يَوْمَئِذٍ فَقَدْ رَحِمْتَهُ، وَذٰلِكَ هُوَ الْفَوْزُ الْعَظِيمُ.","tr":"Allahummaghfir lana wa lil-mu'minina wal-mu'minati wal-muslimina wal-muslimat, wa aslihhum, wa aslih dhata baynihim, wa allif bayna qulubihim, wajʿal fi qulubihimul-imana wal-hikmah, wa thabbithum ʿala millati rasulik, wa awziʿhum an yashkuru niʿmatakal-lati anʿamta ʿalayhim, wa an yufu bi ʿahdikal-ladhi ʿahadtahum ʿalayh, wansurhum ʿala ʿaduwwika wa ʿaduwwihim, ilahal-haqq. Subhanaka la ilaha ghayruk, ighfir li dhanbi, wa aslih li ʿamali, innaka taghfirudh-dhunuba li man tasha'u wa antal-ghafurur-rahim, ya Ghaffaru-ghfir li, ya Tawwabu tub ʿalayy, ya Rahmanu-rhamni, ya ʿAfuwwu-ʿfu ʿanni, ya Ra'ufu-r'af bi, ya Rabbi awziʿni an ashkura niʿmatakal-lati anʿamta ʿalayy, wa tawwiqni husna ʿibadatik, ya Rabbi as'aluka minal-khayri kullih, ya Rabbi-ftah li bi khayr, wakhtim li bi khayr, wa atini tashawwuqan ila liqa'ika min ghayri darra'a mudirratin wa la fitnatin mudillah, wa qinis-sayyi'at, wa man taqis-sayyi'ati yawma'idhin faqad rahimtah, wa dhalika huwal-fawzul-ʿazim.","en":"O Allah, forgive us and the believing men and women and the Muslim men and women. Set them right, set right the relations between them, and join their hearts together. Put faith and wisdom in their hearts, keep them firm on the way of Your Messenger, and inspire them to give thanks for the blessing You have given them and to keep the covenant You made with them. Help them against Your enemy and theirs, O God of Truth. Glory be to You, there is no god but You. Forgive my sin and set my deeds right. You forgive sins for whom You will, and You are the Forgiving, the Merciful. O Ever-Forgiving, forgive me. O Accepter of repentance, accept my repentance. O Most Merciful, have mercy on me. O Pardoner, pardon me. O Most Kind, be kind to me. My Lord, inspire me to give thanks for the blessing You have given me, and bind me to worshipping You well. My Lord, I ask You for every kind of good. My Lord, open my affairs with good and close them with good. Give me a longing to meet You, without any harmful affliction or misleading trial. Protect me from evil deeds. Whomever You protect from evil deeds on that Day, You have shown him mercy, and that is the great triumph.","ref":"«وَقِهِمُ السَّيِّئَاتِ ۚ وَمَن تَقِ السَّيِّئَاتِ يَوْمَئِذٍ فَقَدْ رَحِمْتَهُ ۚ وَذَٰلِكَ هُوَ الْفَوْزُ الْعَظِيمُ» is from Ghafir 40:9, adapted to the first person («وَقِنِي»).","q":null,"source":"first part (to «إله الحق»): al-Marwazi, *Kitab al-Witr*; al-Nawawi, *al-Adhkar* (the qunut). From «سبحانك»: al-Tabarani, *al-Kabir* (Ibn Masʿud).","page":"102–103","status":"draft"},
{"n":28,"ar":"اللَّهُمَّ لَكَ الْحَمْدُ كُلُّهُ، وَلَكَ الشُّكْرُ كُلُّهُ، وَلَكَ الْمُلْكُ كُلُّهُ، وَلَكَ الْخَلْقُ كُلُّهُ، بِيَدِكَ الْخَيْرُ كُلُّهُ، وَإِلَيْكَ يَرْجِعُ الْأَمْرُ كُلُّهُ، أَسْأَلُكَ مِنَ الْخَيْرِ كُلِّهِ، وَأَعُوذُ بِكَ مِنَ الشَّرِّ كُلِّهِ. بِسْمِ اللّٰهِ الَّذِي لَا إِلٰهَ غَيْرُهُ.","tr":"Allahumma lakal-hamdu kulluh, wa lakash-shukru kulluh, wa lakal-mulku kulluh, wa lakal-khalqu kulluh, bi yadikal-khayru kulluh, wa ilayka yarjiʿul-amru kulluh, as'aluka minal-khayri kullih, wa aʿudhu bika minash-sharri kullih. Bismillahil-ladhi la ilaha ghayruh.","en":"O Allah, all praise is Yours, all thanks are Yours, all dominion is Yours and all creation is Yours. All good is in Your hand, and every matter returns to You. I ask You for every kind of good, and I seek refuge in You from every kind of evil. In the name of Allah, besides whom there is no god.","ref":"«وَإِلَيْهِ يُرْجَعُ الْأَمْرُ كُلُّهُ» (Hud 11:123), here addressed to Allah in the second person.","q":null,"source":"al-Daylami (Saʿd); Ahmad, *Musnad* (Hudhayfa). For «أسألك من الخير كله…»: al-Tayalisi and al-Tabarani, *al-Kabir* (Jabir b. Samura).","page":"104","status":"draft"},
{"n":29,"ar":"اللَّهُمَّ أَذْهِبْ عَنِّي الْهَمَّ وَالْحَزَنَ.","tr":"Allahumma adh-hib ʿannil-hamma wal-hazan.","en":"O Allah, take worry and grief away from me.","ref":null,"q":null,"source":"al-Bazzar; al-Tabarani, *al-Awsat*; Ibn al-Sunni; al-Khatib, *Tarikh Baghdad* (Anas).","page":"104","status":"draft"},
{"n":30,"ar":"اللَّهُمَّ بِحَمْدِكَ انْصَرَفْتُ، وَبِذَنْبِي اعْتَرَفْتُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا اقْتَرَفْتُ، وَأَعُوذُ بِكَ مِنْ جُهْدِ الْبَلَاءِ، وَمِنْ عَذَابِ الْآخِرَةِ.","tr":"Allahumma bi hamdikan-sharaftu, wa bi dhanbi-ʿtaraftu, wa aʿudhu bika min sharri maq-taraftu, wa aʿudhu bika min juhdil-bala', wa min ʿadhabil-akhirah.","en":"O Allah, I have turned away (from prayer) praising You, and I admit my sin. I seek refuge in You from the evil of what I have done, and I seek refuge in You from overwhelming trial and from the punishment of the Hereafter.","ref":null,"q":null,"source":"not traced by Nomani.","page":"104–105","status":"draft"},
{"n":31,"ar":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ كُلِّ عَمَلٍ يُخْزِينِي، وَأَعُوذُ بِكَ مِنْ كُلِّ صَاحِبٍ يُؤْذِينِي، وَأَعُوذُ بِكَ مِنْ كُلِّ أَمَلٍ يُلْهِينِي، وَأَعُوذُ بِكَ مِنْ كُلِّ فَقْرٍ يُنْسِينِي، وَأَعُوذُ بِكَ مِنْ كُلِّ غِنًى يُطْغِينِي.","tr":"Allahumma inni aʿudhu bika min kulli ʿamalin yukhzini, wa aʿudhu bika min kulli sahibin yu'dhini, wa aʿudhu bika min kulli amalin yulhini, wa aʿudhu bika min kulli faqrin yunsini, wa aʿudhu bika min kulli ghinan yutghini.","en":"O Allah, I seek refuge in You from every deed that would disgrace me, every companion who would harm me, every hope that would distract me, every poverty that would make me forget, and every wealth that would make me rebel.","ref":null,"q":null,"source":"al-Bazzar; Abu Yaʿla (Anas).","page":"105","status":"draft"},
{"n":32,"ar":"اللَّهُمَّ إِلٰهِي وَإِلٰهَ إِبْرَاهِيمَ وَإِسْحَاقَ وَيَعْقُوبَ، وَإِلٰهَ جَبْرَئِيلَ وَمِيكَائِيلَ وَإِسْرَافِيلَ، أَسْأَلُكَ أَنْ تَسْتَجِيبَ دَعْوَتِي فَإِنِّي مُضْطَرٌّ، وَتَعْصِمَنِي فِي دِينِي فَإِنِّي مُبْتَلًى، وَتَنَالَنِي بِرَحْمَتِكَ فَإِنِّي مُذْنِبٌ، وَتَنْفِيَ عَنِّي الْفَقْرَ فَإِنِّي مُتَمَسْكِنٌ.","tr":"Allahumma ilahi wa ilaha Ibrahima wa Ishaqa wa Yaʿqub, wa ilaha Jabra'ila wa Mika'ila wa Israfil, as'aluka an tastajiba daʿwati fa inni mudtarr, wa taʿsimani fi dini fa inni mubtala, wa tanalani bi rahmatika fa inni mudhnib, wa tanfiya ʿanniyal-faqra fa inni mutamaskin.","en":"O Allah, my God and the God of Ibrahim, Ishaq and Yaʿqub, and God of Jibril, Mika'il and Israfil: I ask You to answer my prayer, for I am in desperate need; to protect me in my religion, for I am being tested; to reach me with Your mercy, for I am a sinner; and to remove poverty from me, for I am humbled.","ref":null,"q":null,"source":"Ibn al-Sunni; Abu al-Shaykh; al-Daylami; Ibn ʿAsakir; Ibn al-Najjar (Anas).","page":"105","status":"draft"},
{"n":33,"ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ بِحَقِّ السَّائِلِينَ عَلَيْكَ، فَإِنَّ لِلسَّائِلِ عَلَيْكَ حَقًّا، أَيُّمَا عَبْدٍ أَوْ أَمَةٍ مِنْ أَهْلِ الْبَرِّ وَالْبَحْرِ تَقَبَّلْتَ دَعْوَتَهُمْ وَاسْتَجَبْتَ دُعَاءَهُمْ، أَنْ تُشْرِكَنَا فِي صَالِحِ مَا يَدْعُونَكَ فِيهِ، وَأَنْ تُشْرِكَهُمْ فِي صَالِحِ مَا نَدْعُوكَ (فِيهِ)، وَأَنْ تُعَافِيَنَا وَإِيَّاهُمْ، وَأَنْ تَقَبَّلَ مِنَّا وَمِنْهُمْ، وَأَنْ تَجَاوَزَ عَنَّا وَعَنْهُمْ، فَإِنَّا آمَنَّا بِمَا أَنْزَلْتَ وَاتَّبَعْنَا الرَّسُولَ فَاكْتُبْنَا مَعَ الشَّاهِدِينَ.","tr":"Allahumma inni as'aluka bi haqqis-sa'ilina ʿalayk, fa inna lis-sa'ili ʿalayka haqqa, ayyuma ʿabdin aw amatin min ahlil-barri wal-bahri taqabbalta daʿwatahum wastajabta duʿa'ahum, an tushrikana fi salihi ma yadʿunaka fih, wa an tushrikahum fi salihi ma nadʿuka fih, wa an tuʿafiyana wa iyyahum, wa an taqabbala minna wa minhum, wa an tajawaza ʿanna wa ʿanhum, fa inna amanna bima anzalta wattabaʿnar-rasula faktubna maʿash-shahidin.","en":"O Allah, I ask You by the right of those who ask of You, for the one who asks has a right with You: any servant, man or woman, of land or sea, whose call You have accepted and whose prayer You have answered. I ask You to give us a share in the good they pray to You for, and to give them a share in the good we pray to You for. Grant well-being to us and to them, accept from us and from them, and pass over our faults and theirs. We believe in what You have revealed and we follow the Messenger, so write us down among those who bear witness.","ref":"«آمَنَّا بِمَا أَنْزَلْتَ وَاتَّبَعْنَا الرَّسُولَ فَاكْتُبْنَا مَعَ الشَّاهِدِينَ» is from Al ʿImran 3:53, without its opening «رَبَّنَا».","q":null,"source":"al-Daylami (Abu Saʿid al-Khudri).","page":"106","status":"draft"},
{"n":34,"ar":"اللَّهُمَّ أَعْطِ سَيِّدَنَا مُحَمَّدًا الْوَسِيلَةَ، وَاجْعَلْ فِي الْمُصْطَفَيْنَ مَحَبَّتَهُ، وَفِي الْأَعْلَيْنَ دَرَجَتَهُ، وَفِي الْمُقَرَّبِينَ ذِكْرَهُ.","tr":"Allahumma aʿti sayyidana Muhammadanil-wasilah, wajʿal fil-mustafayna mahabbatah, wa fil-aʿlayna darajatah, wa fil-muqarrabina dhikrah.","en":"O Allah, give our master Muhammad the Wasila (the highest station). Place love for him among the chosen, his rank among the highest, and his mention among those brought near.","ref":null,"q":null,"source":"al-Tabarani (Abu Umama).","page":"106","status":"draft"},
{"n":35,"ar":"اللَّهُمَّ اهْدِنِي مِنْ عِنْدِكَ، وَأَفِضْ عَلَيَّ مِنْ فَضْلِكَ، وَأَسْبِغْ عَلَيَّ مِنْ رَحْمَتِكَ، وَأَنْزِلْ عَلَيَّ مِنْ بَرَكَاتِكَ.","tr":"Allahummahdini min ʿindik, wa afid ʿalayya min fadlik, wa asbigh ʿalayya min rahmatik, wa anzil ʿalayya min barakatik.","en":"O Allah, guide me from Your own presence, pour Your bounty upon me, give me Your mercy in full, and send down Your blessings upon me.","ref":null,"q":null,"source":"Abu al-Shaykh, *al-Thawab* (Anas).","page":"106–107","status":"draft"},
{"n":36,"ar":"اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَتُبْ عَلَيَّ، إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ.","tr":"Allahummaghfir li warhamni wa tub ʿalayy, innaka antat-tawwabur-rahim.","en":"O Allah, forgive me, have mercy on me and accept my repentance. You are the Accepter of repentance, the Merciful.","ref":null,"q":null,"source":"Abu Dawud, al-Tirmidhi, al-Nasa'i, Ibn Majah, Ibn Hibban (via Ibn al-Jazari, *al-Hisn al-Hasin*).","page":"107","status":"draft"},
{"n":37,"ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ تَوْفِيقَ أَهْلِ الْهُدَى، وَأَعْمَالَ أَهْلِ الْيَقِينِ، وَمُنَاصَحَةَ أَهْلِ التَّوْبَةِ، وَعَزْمَ أَهْلِ الصَّبْرِ، وَجِدَّ أَهْلِ الْخَشْيَةِ، وَطَلَبَ أَهْلِ الرَّغْبَةِ، وَتَعَبُّدَ أَهْلِ الْوَرَعِ، وَعِرْفَانَ أَهْلِ الْعِلْمِ، حَتَّى أَلْقَاكَ.","tr":"Allahumma inni as'aluka tawfiqa ahlil-huda, wa aʿmala ahlil-yaqin, wa munasahata ahlit-tawbah, wa ʿazma ahlis-sabr, wa jidda ahlil-khashyah, wa talaba ahlir-raghbah, wa taʿabbuda ahlil-waraʿ, wa ʿirfana ahlil-ʿilm, hatta alqak.","en":"O Allah, I ask You for the divine help given to the rightly guided, the deeds of the people of certainty, the sincerity of those who repent, the resolve of the patient, the earnestness of those who fear You, the seeking of those who long for You, the devotion of the scrupulous and the understanding of the learned, until I meet You.","ref":null,"q":null,"source":"Abu Nuʿaym, *Hilyat al-Awliya'* (Ibn ʿAbbas).","page":"107","status":"draft"},
{"n":38,"ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ مَخَافَةً تَحْجُزُنِي عَنْ مَعَاصِيكَ، حَتَّى أَعْمَلَ بِطَاعَتِكَ عَمَلًا أَسْتَحِقُّ بِهِ رِضَاكَ، وَحَتَّى أُنَاصِحَكَ بِالتَّوْبَةِ خَوْفًا مِنْكَ، وَحَتَّى أُخْلِصَ لَكَ النَّصِيحَةَ حَيَاءً مِنْكَ، وَحَتَّى أَتَوَكَّلَ عَلَيْكَ فِي الْأُمُورِ كُلِّهَا، وَحُسْنَ ظَنٍّ بِكَ، سُبْحَانَ خَالِقِ النُّورِ.","tr":"Allahumma inni as'aluka makhafatan tahjuzuni ʿan maʿasik, hatta aʿmala bi taʿatika ʿamalan astahiqqu bihi ridak, wa hatta unasihaka bit-tawbati khawfan mink, wa hatta ukhlisa lakan-nasihata haya'an mink, wa hatta atawakkala ʿalayka fil-umuri kulliha, wa husna zannin bik, subhana khaliqin-nur.","en":"O Allah, I ask You for a fear that holds me back from disobeying You, so that I do deeds of obedience that earn Your pleasure, turn to You in sincere repentance out of fear of You, and keep my devotion to You pure out of shame before You, and so that I rely on You in every matter. I also ask You for a good opinion of You. Glory be to the Creator of light.","ref":null,"q":null,"source":"the same hadith as #37.","page":"107–108","status":"draft"},
{"n":39,"ar":"اللَّهُمَّ لَا تُهْلِكْنَا فُجَاءَةً، وَلَا تَأْخُذْنَا بَغْتَةً، وَلَا تُغْفِلْنَا عَنْ حَقٍّ وَلَا وَصِيَّةٍ.","tr":"Allahumma la tuhlikna fuja'ah, wa la ta'khudhna baghtah, wa la tughfilna ʿan haqqin wa la wasiyyah.","en":"O Allah, do not destroy us suddenly, do not seize us without warning, and do not let us neglect a duty owed or a bequest.","ref":null,"q":null,"source":"al-Tabarani, *al-Awsat* (Ibn Masʿud).","page":"108","status":"draft"},
{"n":40,"ar":"اللَّهُمَّ آنِسْ وَحْشَتِي فِي قَبْرِي. اللَّهُمَّ ارْحَمْنِي بِالْقُرْآنِ الْعَظِيمِ، وَاجْعَلْهُ لِي إِمَامًا وَنُورًا وَهُدًى وَرَحْمَةً. اللَّهُمَّ ذَكِّرْنِي مِنْهُ مَا نَسِيتُ، وَعَلِّمْنِي مِنْهُ مَا جَهِلْتُ، وَارْزُقْنِي تِلَاوَتَهُ آنَاءَ اللَّيْلِ وَآنَاءَ النَّهَارِ، وَاجْعَلْهُ لِي حُجَّةً يَا رَبَّ الْعَالَمِينَ.","tr":"Allahumma anis wahshati fi qabri. Allahumma-rhamni bil-Qur'anil-ʿazim, wajʿalhu li imaman wa nuran wa hudan wa rahmah. Allahumma dhakkirni minhu ma nasit, wa ʿallimni minhu ma jahilt, warzuqni tilawatahu ana'al-layli wa ana'an-nahar, wajʿalhu li hujjatan ya Rabbal-ʿalamin.","en":"O Allah, comfort my loneliness in my grave. O Allah, have mercy on me through the Mighty Qurʾān, and make it for me a guide to follow, a light, a guidance and a mercy. O Allah, remind me of what I have forgotten of it and teach me what I do not know of it. Grant me its recitation through the hours of the night and the day, and make it a proof in my favour, O Lord of the worlds.","ref":null,"q":null,"source":"al-Daylami, *Musnad al-Firdaws* (Abu Umama), for the first sentence.","page":"108","status":"draft"},
{"n":41,"ar":"اللَّهُمَّ أَنَا عَبْدُكَ وَابْنُ عَبْدِكَ وَابْنُ أَمَتِكَ، نَاصِيَتِي بِيَدِكَ، أَتَقَلَّبُ فِي قَبْضَتِكَ، وَأُصَدِّقُ بِلِقَائِكَ، وَأُومِنُ بِوَعْدِكَ، أَمَرْتَنِي فَعَصَيْتُ، وَنَهَيْتَنِي فَأَبَيْتُ، هٰذَا مَكَانُ الْعَائِذِ بِكَ مِنَ النَّارِ، لَا إِلٰهَ إِلَّا أَنْتَ، سُبْحَانَكَ، ظَلَمْتُ نَفْسِي فَاغْفِرْ لِي، إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ.","tr":"Allahumma ana ʿabduka wabnu ʿabdika wabnu amatik, nasiyati bi yadik, ataqallabu fi qabdatik, wa usaddiqu bi liqa'ik, wa u'minu bi waʿdik, amartani fa ʿasayt, wa nahaytani fa abayt, hadha makanul-ʿa'idhi bika minan-nar, la ilaha illa ant, subhanak, zalamtu nafsi faghfir li, innahu la yaghfirudh-dhunuba illa ant.","en":"O Allah, I am Your servant, son of Your servant, son of Your handmaid. My forelock is in Your hand, and I turn about in Your grip. I believe in meeting You, and I have faith in Your promise. You commanded me and I disobeyed, You forbade me and I refused. This is the place of one who seeks refuge in You from the Fire. There is no god but You, glory be to You. I have wronged myself, so forgive me, for no one forgives sins but You.","ref":null,"q":null,"source":"not traced by Nomani.","page":"108–109","status":"draft"},
{"n":42,"ar":"اللَّهُمَّ لَكَ الْحَمْدُ، وَإِلَيْكَ الْمُشْتَكَى، وَبِكَ الْمُسْتَغَاثُ، وَأَنْتَ الْمُسْتَعَانُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللّٰهِ.","tr":"Allahumma lakal-hamd, wa ilaykal-mushtaka, wa bikal-mustaghath, wa antal-mustaʿan, wa la hawla wa la quwwata illa billah.","en":"O Allah, praise is Yours. To You is the complaint, from You comes rescue, and You are the One whose help is sought. There is no power and no strength except through Allah.","ref":null,"q":null,"source":"al-Tabarani, *al-Awsat* and *al-Saghir* (Ibn Masʿud).","page":"109","status":"draft"},
{"n":43,"ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ بِمُحَمَّدٍ (صَلَّى اللّٰهُ عَلَيْهِ وَسَلَّمَ) نَبِيِّكَ، وَإِبْرَاهِيمَ خَلِيلِكَ، وَمُوسَى نَجِيِّكَ، وَعِيسَى رُوحِكَ وَكَلِمَتِكَ، وَبِكَلَامِ مُوسَى، وَإِنْجِيلِ عِيسَى، وَزَبُورِ دَاوُدَ، وَفُرْقَانِ سَيِّدِنَا مُحَمَّدٍ (صَلَّى اللّٰهُ عَلَيْهِ وَسَلَّمَ)، وَبِكُلِّ وَحْيٍ أَوْحَيْتَهُ، أَوْ قَضَاءٍ قَضَيْتَهُ، (أَوْ سَائِلٍ أَعْطَيْتَهُ، أَوْ فَقِيرٍ أَغْنَيْتَهُ، أَوْ غَنِيٍّ أَفْقَرْتَهُ، أَوْ ضَالٍّ هَدَيْتَهُ، وَأَسْأَلُكَ بِاسْمِكَ الَّذِي أَنْزَلْتَهُ عَلَى مُوسَى، وَأَسْأَلُكَ بِاسْمِكَ الَّذِي وَضَعْتَهُ عَلَى الْأَرْضِ فَاسْتَقَرَّتْ، وَعَلَى السَّمٰوَاتِ فَاسْتَقَلَّتْ، وَعَلَى الْجِبَالِ فَرَسَتْ، وَأَسْأَلُكَ بِاسْمِكَ الَّذِي اسْتَقَرَّ بِهِ عَرْشُكَ)، وَأَسْأَلُكَ بِاسْمِكَ الطَّاهِرِ الْمُطَهَّرِ الْمُنَزَّلِ فِي كِتَابِكَ مِنْ لَدُنْكَ، وَبِاسْمِكَ الَّذِي وَضَعْتَهُ عَلَى النَّهَارِ فَاسْتَنَارَ، وَعَلَى اللَّيْلِ فَأَظْلَمَ، وَبِعَظَمَتِكَ وَكِبْرِيَائِكَ، وَبِنُورِ وَجْهِكَ، أَنْ تَرْزُقَنِي الْقُرْآنَ الْعَظِيمَ، وَتَخْلِطَهُ بِلَحْمِي وَدَمِي وَسَمْعِي وَبَصَرِي، وَتَسْتَعْمِلَ بِهِ جَسَدِي بِحَوْلِكَ وَقُوَّتِكَ، فَإِنَّهُ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِكَ.","tr":"Allahumma inni as'aluka bi Muhammadin (sallallahu ʿalayhi wa sallam) nabiyyik, wa Ibrahima khalilik, wa Musa najiyyik, wa ʿIsa ruhika wa kalimatik, wa bi kalami Musa, wa Injili ʿIsa, wa Zaburi Dawud, wa Furqani sayyidina Muhammadin (sallallahu ʿalayhi wa sallam), wa bi kulli wahyin awhaytah, aw qada'in qadaytah, (aw sa'ilin aʿtaytah, aw faqirin aghnaytah, aw ghaniyyin afqartah, aw dallin hadaytah, wa as'aluka bismikal-ladhi anzaltahu ʿala Musa, wa as'aluka bismikal-ladhi wadaʿtahu ʿalal-ardi fastaqarrat, wa ʿalas-samawati fastaqallat, wa ʿalal-jibali farasat, wa as'aluka bismikal-ladhis-taqarra bihi ʿarshuk), wa as'aluka bismikat-tahiril-mutahharil-munazzali fi kitabika min ladunk, wa bismikal-ladhi wadaʿtahu ʿalan-nahari fastanar, wa ʿalal-layli fa azlam, wa bi ʿazamatika wa kibriya'ik, wa bi nuri wajhik, an tarzuqaniyal-Qur'anal-ʿazim, wa takhlitahu bi lahmi wa dami wa samʿi wa basari, wa tastaʿmila bihi jasadi bi hawlika wa quwwatik, fa innahu la hawla wa la quwwata illa bik.","en":"O Allah, I ask You by Muhammad (peace and blessings be upon him) Your Prophet, Ibrahim Your intimate friend, Musa to whom You spoke closely, and ʿIsa Your spirit and Your word; by the speech of Musa, the Gospel of ʿIsa, the Psalms of Dawud and the Criterion of our master Muhammad (peace and blessings be upon him); and by every revelation You have sent and every decree You have made (every asker You have given to, every poor person You have made rich, every rich person You have made poor and every lost person You have guided). I ask You by Your Name that You sent down to Musa. I ask You by Your Name that You placed on the earth and it became still, on the heavens and they rose up, and on the mountains and they stood firm. I ask You by Your Name by which Your Throne is established. I ask You by Your pure and purifying Name sent down in Your Book from Your presence, and by Your Name that You placed on the day and it grew bright, and on the night and it grew dark. I ask by Your Majesty, Your Grandeur and the light of Your Face. I ask You to grant me the Mighty Qurʾān and to mix it into my flesh, my blood, my hearing and my sight, and to put my body to work by it, through Your might and power, for there is no might and no power except through You.","ref":null,"q":null,"source":"Abu al-Shaykh, *al-Thawab* (Abu Bakr).","page":"109–110","status":"draft"},
{"n":44,"ar":"بِسْمِ اللّٰهِ ذِي الشَّأْنِ، عَظِيمِ الْبُرْهَانِ، شَدِيدِ السُّلْطَانِ، مَا شَاءَ اللّٰهُ كَانَ، أَعُوذُ بِاللّٰهِ مِنَ الشَّيْطَانِ الرَّجِيمِ.","tr":"Bismillahi dhish-sha'n, ʿazimil-burhan, shadidis-sultan, ma sha'allahu kan, aʿudhu billahi minash-shaytanir-rajim.","en":"In the name of Allah, the Lord of high station, mighty in proof and severe in authority. Whatever Allah wills comes to be. I seek refuge in Allah from Satan, the accursed.","ref":null,"q":null,"source":"Ibn ʿAsakir; al-Hakim, *Tarikh Naysabur* (al-Zubayr b. al-ʿAwwam).","page":"110–111","status":"draft"},
{"n":45,"ar":"اللَّهُمَّ بَارِكْ لِي فِي الْمَوْتِ، وَفِيمَا بَعْدَ الْمَوْتِ. *(خَمْسًا وَعِشْرِينَ)","tr":"Allahumma barik li fil-mawt, wa fima baʿdal-mawt. *(25 times)","en":"O Allah, bless me in death and in what comes after death. *(Recited 25 times.)","ref":null,"q":null,"source":"al-Tabarani, *al-Awsat* (ʿA'isha).","page":"111","status":"draft"},
{"n":46,"ar":"اللَّهُمَّ لَا تُؤْمِنَّا مَكْرَكَ، وَلَا تُنْسِنَا ذِكْرَكَ، وَلَا تَهْتِكْ عَنَّا سِتْرَكَ، وَلَا تَجْعَلْنَا مِنَ الْغَافِلِينَ.","tr":"Allahumma la tu'minna makrak, wa la tunsina dhikrak, wa la tahtik ʿanna sitrak, wa la tajʿalna minal-ghafilin.","en":"O Allah, do not make us feel safe from Your plan, do not make us forget to remember You, do not tear away Your veil from over us, and do not make us among the heedless.","ref":null,"q":null,"source":"al-Daylami, *Musnad al-Firdaws*; Ibn al-Najjar (Ibn ʿAbbas).","page":"111","status":"draft"},
{"n":47,"ar":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ ضِيقِ الدُّنْيَا، وَضِيقِ يَوْمِ الْقِيَامَةِ.","tr":"Allahumma inni aʿudhu bika min diqid-dunya, wa diqi yawmil-qiyamah.","en":"O Allah, I seek refuge in You from the narrowness of this world and the narrowness of the Day of Resurrection.","ref":null,"q":null,"source":"Abu Dawud.","page":"111","status":"draft"},
{"n":48,"ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ تَعْجِيلَ عَافِيَتِكَ، وَدَفْعَ بَلَائِكَ، وَخُرُوجًا مِنَ الدُّنْيَا إِلَى رَحْمَتِكَ. يَا مَنْ يَكْفِي عَنْ كُلِّ أَحَدٍ، وَلَا يَكْفِي مِنْهُ أَحَدٌ، يَا أَحَدَ مَنْ لَا أَحَدَ لَهُ، يَا سَنَدَ مَنْ لَا سَنَدَ لَهُ، انْقَطَعَ الرَّجَاءُ إِلَّا مِنْكَ، نَجِّنِي مِمَّا أَنَا فِيهِ، وَأَعِنِّي عَلَى مَا أَنَا عَلَيْهِ مِمَّا نَزَلَ بِي، بِجَاهِ وَجْهِكَ الْكَرِيمِ، وَبِحَقِّ سَيِّدِنَا مُحَمَّدٍ عَلَيْكَ، آمِينَ.","tr":"Allahumma inni as'aluka taʿjila ʿafiyatik, wa dafʿa bala'ik, wa khurujan minad-dunya ila rahmatik. Ya man yakfi ʿan kulli ahad, wa la yakfi minhu ahad, ya ahada man la ahada lah, ya sanada man la sanada lah, inqataʿar-raja'u illa mink, najjini mimma ana fih, wa aʿinni ʿala ma ana ʿalayhi mimma nazala bi, bi jahi wajhikal-karim, wa bi haqqi sayyidina Muhammadin ʿalayk, amin.","en":"O Allah, I ask You for well-being soon, for the removal of trial, and for a departure from this world into Your mercy. O You who suffice in place of everyone, while no one can stand in place of You. O the only one of the one who has no one. O support of the one who has no support. All hope is cut off except hope in You. Rescue me from what I am in, and help me with what has come down upon me, by the standing of Your Noble Face and by the right of our master Muhammad with You. Amin.","ref":null,"q":null,"source":"Ibn Hibban, al-Hakim (ʿA'isha). From «يا من يكفي»: al-Daylami (ʿUmar and ʿAli).","page":"112","status":"draft"},
{"n":49,"ar":"اللَّهُمَّ احْرُسْنِي بِعَيْنِكَ الَّتِي لَا تَنَامُ، وَاكْنُفْنِي بِرُكْنِكَ الَّذِي لَا يُرَامُ، وَارْحَمْنِي بِقُدْرَتِكَ عَلَيَّ، فَلَا أَهْلِكُ وَأَنْتَ رَجَائِي، فَكَمْ مِنْ نِعْمَةٍ أَنْعَمْتَ بِهَا عَلَيَّ قَلَّ لَكَ بِهَا شُكْرِي، وَكَمْ مِنْ بَلِيَّةٍ ابْتَلَيْتَنِي بِهَا قَلَّ لَكَ بِهَا صَبْرِي، فَيَا مَنْ قَلَّ عِنْدَ نِعْمَتِهِ شُكْرِي فَلَمْ يَحْرِمْنِي، وَيَا مَنْ قَلَّ عِنْدَ بَلِيَّتِهِ صَبْرِي فَلَمْ يَخْذُلْنِي، وَيَا مَنْ رَآنِي عَلَى الْخَطَايَا فَلَمْ يَفْضَحْنِي، يَا ذَا الْمَعْرُوفِ الَّذِي لَا يَنْقَضِي أَبَدًا، وَيَا ذَا النَّعْمَاءِ الَّتِي لَا تُحْصَى أَبَدًا، أَسْأَلُكَ أَنْ تُصَلِّيَ عَلَى (سَيِّدِنَا) مُحَمَّدٍ (صَلَّى اللّٰهُ عَلَيْهِ وَسَلَّمَ) وَعَلَى آلِ (سَيِّدِنَا) مُحَمَّدٍ (صَلَّى اللّٰهُ عَلَيْهِ وَسَلَّمَ)، وَبِكَ أَدْرَأُ فِي نُحُورِ الْأَعْدَاءِ وَالْجَبَابِرَةِ. اللَّهُمَّ أَعِنِّي عَلَى دِينِي بِالدُّنْيَا، وَعَلَى آخِرَتِي بِالتَّقْوَى، وَاحْفَظْنِي فِيمَا غِبْتُ عَنْهُ، وَلَا تَكِلْنِي إِلَى نَفْسِي فِيمَا حَضَرْتُهُ، يَا مَنْ لَا تَضُرُّهُ الذُّنُوبُ، وَلَا تَنْقُصُهُ الْمَغْفِرَةُ، هَبْ لِي مَا لَا يَنْقُصُكَ، وَاغْفِرْ لِي مَا لَا يَضُرُّكَ، إِنَّكَ أَنْتَ الْوَهَّابُ، أَسْأَلُكَ فَرَجًا قَرِيبًا، وَصَبْرًا جَمِيلًا، وَرِزْقًا وَاسِعًا، وَالْعَافِيَةَ مِنْ جَمِيعِ الْبَلَاءِ، وَأَسْأَلُكَ تَمَامَ الْعَافِيَةِ، وَأَسْأَلُكَ دَوَامَ الْعَافِيَةِ، وَأَسْأَلُكَ الشُّكْرَ عَلَى الْعَافِيَةِ، وَأَسْأَلُكَ الْغِنَى عَنِ النَّاسِ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللّٰهِ الْعَلِيِّ الْعَظِيمِ، يَا رَبِّ، يَا رَبِّ، يَا رَبِّ.","tr":"Allahumma-hrusni bi ʿaynikal-lati la tanam, waknufni bi ruknikal-ladhi la yuram, warhamni bi qudratika ʿalayy, fa la ahliku wa anta raja'i, fa kam min niʿmatin anʿamta biha ʿalayya qalla laka biha shukri, wa kam min baliyyatin-ibtalaytani biha qalla laka biha sabri, fa ya man qalla ʿinda niʿmatihi shukri fa lam yahrimni, wa ya man qalla ʿinda baliyyatihi sabri fa lam yakhdhulni, wa ya man ra'ani ʿalal-khataya fa lam yafdahni, ya dhal-maʿrufil-ladhi la yanqadi abada, wa ya dhan-naʿma'il-lati la tuhsa abada, as'aluka an tusalliya ʿala sayyidina Muhammadin (sallallahu ʿalayhi wa sallam) wa ʿala ali sayyidina Muhammadin (sallallahu ʿalayhi wa sallam), wa bika adra'u fi nuhuril-aʿda'i wal-jababirah. Allahumma aʿinni ʿala dini bid-dunya, wa ʿala akhirati bit-taqwa, wahfazni fima ghibtu ʿanh, wa la takilni ila nafsi fima hadartuh, ya man la tadurruhudh-dhunub, wa la tanqusuhul-maghfirah, hab li ma la yanqusuk, waghfir li ma la yadurruk, innaka antal-wahhab, as'aluka farajan qariba, wa sabran jamila, wa rizqan wasiʿa, wal-ʿafiyata min jamiʿil-bala', wa as'aluka tamamal-ʿafiyah, wa as'aluka dawamal-ʿafiyah, wa as'alukash-shukra ʿalal-ʿafiyah, wa as'alukal-ghina ʿanin-nas, wa la hawla wa la quwwata illa billahil-ʿaliyyil-ʿazim, ya Rabb, ya Rabb, ya Rabb.","en":"O Allah, guard me with Your eye that never sleeps, shelter me in Your stronghold that no one can reach, and have mercy on me by Your power over me, so that I do not perish while You are my hope. How many blessings You have given me for which my thanks were small! How many trials You have tested me with in which my patience was small! O You before whose blessing my thanks were small, yet who did not deprive me; O You before whose trial my patience was small, yet who did not abandon me; O You who saw me in my sins and did not expose me; O Owner of kindness that never ends, and Owner of favours that can never be counted: I ask You to send blessings on (our master) Muhammad (peace and blessings be upon him) and on the family of (our master) Muhammad (peace and blessings be upon him). Through You I push back against enemies and tyrants. O Allah, help me in my religion by means of this world, and in my Hereafter by means of God-consciousness. Guard me in what I am absent from, and do not leave me to myself in what I am present at. O You whom sins do not harm and whom forgiving does not diminish: grant me what does not diminish You, and forgive me what does not harm You. You are the Giver. I ask You for relief that comes soon, beautiful patience, ample provision and well-being from every trial. I ask You for complete well-being, lasting well-being and gratitude for well-being. I ask You to make me need no one but You. There is no power and no strength except through Allah, the Most High, the Mighty. O Lord, O Lord, O Lord.","ref":null,"q":null,"source":"al-Daylami (ʿAli); Ibn al-Najjar (Jaʿfar al-Sadiq). For «يا رب» three times: al-Daylami (Abu Hurayra) and Ibn Abi al-Dunya, *Kitab al-Duʿa'* (ʿA'isha).","page":"112–114","status":"draft"}]},{"manzil":6,"day":"Thursday","dayAr":"يوم الخميس","duas":[{"n":1,"ar":"اللّٰهُمَّ يَا كَبِيرُ يَا سَمِيعُ يَا بَصِيرُ، يَا مَنْ لَا شَرِيكَ لَهُ وَلَا وَزِيرَ لَهُ، وَيَا خَالِقَ الشَّمْسِ وَالْقَمَرِ الْمُنِيرِ، وَيَا عِصْمَةَ الْبَائِسِ الْخَائِفِ الْمُسْتَجِيرِ، وَيَا رَازِقَ الطِّفْلِ الصَّغِيرِ، وَيَا جَابِرَ الْعَظْمِ الْكَسِيرِ، أَدْعُوكَ دُعَاءَ الْبَائِسِ الْفَقِيرِ، كَدُعَاءِ الْمُضْطَرِّ الضَّرِيرِ، أَسْأَلُكَ بِمَعَاقِدِ الْعِزِّ مِنْ عَرْشِكَ، وَبِمَفَاتِيحِ الرَّحْمَةِ مِنْ كِتَابِكَ، وَبِالْأَسْمَاءِ الثَّمَانِيَةِ الْمَكْتُوبَةِ عَلَى قَرْنِ الشَّمْسِ، أَنْ تَجْعَلَ الْقُرْآنَ رَبِيعَ قَلْبِي وَجَلَاءَ حُزْنِي، رَبَّنَا آتِنَا فِي الدُّنْيَا كَذَا وَكَذَا.","tr":"Allāhumma yā Kabīru yā Samīʿu yā Baṣīr, yā man lā sharīka lahū wa lā wazīra lah, wa yā khāliqa sh-shamsi wal-qamari l-munīr, wa yā ʿiṣmata l-bāʾisi l-khāʾifi l-mustajīr, wa yā rāziqa ṭ-ṭifli ṣ-ṣaghīr, wa yā jābira l-ʿaẓmi l-kasīr, adʿūka duʿāʾa l-bāʾisi l-faqīr, ka-duʿāʾi l-muḍṭarri ḍ-ḍarīr, asʾaluka bi-maʿāqidi l-ʿizzi min ʿarshik, wa bi-mafātīḥi r-raḥmati min kitābik, wa bil-asmāʾi th-thamāniyati l-maktūbati ʿalā qarni sh-shams, an tajʿala l-Qurʾāna rabīʿa qalbī wa jalāʾa ḥuznī, rabbanā ātinā fi d-dunyā kadhā wa kadhā.","en":"O Allah, O Most Great, O All-Hearing, O All-Seeing, O You who have no partner and no helper; O Creator of the sun and the shining moon; O Protector of the wretched, the fearful and the one who seeks refuge; O Provider for the small child; O Setter of the broken bone. I call on You with the call of the wretched and needy, like the call of the desperate and afflicted. I ask You by the places where glory is bound to Your Throne, by the keys of mercy from Your Book, and by the eight names written on the rim of the sun, to make the Qurʾān the spring of my heart and the remover of my grief. Our Lord, give us in this world such-and-such (here one names one's need).","ref":null,"q":null,"source":"Abū al-Shaykh al-Iṣbahānī, from Anas.","page":null,"status":"draft"},
{"n":2,"ar":"يَا مُؤْنِسَ كُلِّ وَحِيدٍ، وَيَا صَاحِبَ كُلِّ فَرِيدٍ، وَيَا قَرِيبًا غَيْرَ بَعِيدٍ، وَيَا شَاهِدًا غَيْرَ غَائِبٍ، وَيَا غَالِبًا غَيْرَ مَغْلُوبٍ، يَا حَيُّ يَا قَيُّومُ، يَا ذَا الْجَلَالِ وَالْإِكْرَامِ، يَا نُورَ السَّمٰوٰتِ وَالْأَرْضِ، يَا زَيْنَ السَّمٰوٰتِ وَالْأَرْضِ، يَا جَبَّارَ السَّمٰوٰتِ وَالْأَرْضِ، يَا عِمَادَ السَّمٰوٰتِ وَالْأَرْضِ، يَا بَدِيعَ السَّمٰوٰتِ وَالْأَرْضِ، يَا قَيَّامَ السَّمٰوٰتِ وَالْأَرْضِ، يَا ذَا الْجَلَالِ وَالْإِكْرَامِ، يَا صَرِيخَ الْمُسْتَصْرِخِينَ، وَمُنْتَهَى الْعَائِذِينَ، وَالْمُفَرِّجَ عَنِ الْمَكْرُوبِينَ، وَالْمُرَوِّحَ عَنِ الْمَغْمُومِينَ، وَمُجِيبَ دُعَاءِ الْمُضْطَرِّينَ، وَيَا كَاشِفَ الْكُرَبِ، يَا إِلٰهَ الْعَالَمِينَ، وَيَا أَرْحَمَ الرَّاحِمِينَ، مَنْزُولٌ بِكَ كُلُّ حَاجَةٍ.","tr":"Yā mūnisa kulli waḥīd, wa yā ṣāḥiba kulli farīd, wa yā qarīban ghayra baʿīd, wa yā shāhidan ghayra ghāʾib, wa yā ghāliban ghayra maghlūb, yā Ḥayyu yā Qayyūm, yā Dha l-Jalāli wal-Ikrām, yā Nūra s-samāwāti wal-arḍ, yā Zayna s-samāwāti wal-arḍ, yā Jabbāra s-samāwāti wal-arḍ, yā ʿImāda s-samāwāti wal-arḍ, yā Badīʿa s-samāwāti wal-arḍ, yā Qayyāma s-samāwāti wal-arḍ, yā Dha l-Jalāli wal-Ikrām, yā Ṣarīkha l-mustaṣrikhīn, wa muntaha l-ʿāʾidhīn, wal-mufarrija ʿani l-makrūbīn, wal-murawwiḥa ʿani l-maghmūmīn, wa mujība duʿāʾi l-muḍṭarrīn, wa yā kāshifa l-kurab, yā Ilāha l-ʿālamīn, wa yā Arḥama r-rāḥimīn, manzūlun bika kullu ḥājah.","en":"O Companion of everyone who is alone, O Friend of everyone who is solitary, O You who are near and never far, present and never absent, victorious and never overcome. O Ever-Living, O Self-Subsisting, O Lord of Majesty and Honour. O Light of the heavens and the earth, O Adornment of the heavens and the earth, O Compeller of the heavens and the earth, O Pillar of the heavens and the earth, O Originator of the heavens and the earth, O Sustainer of the heavens and the earth, O Lord of Majesty and Honour. O Helper of those who cry for help, final refuge of those who seek refuge, Reliever of the distressed, Comforter of the grieving, Answerer of the call of the desperate, and Remover of hardships. O God of the worlds, O Most Merciful of the merciful: every need is brought to You.","ref":null,"q":null,"source":"al-Daylamī, *Musnad al-Firdaws*, from Anas.","page":null,"status":"draft"},
{"n":3,"ar":"اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ مَوْتِ الْهَمِّ، وَأَعُوذُ بِكَ مِنْ مَوْتِ الْغَمِّ، وَأَعُوذُ بِكَ مِنَ الْجُوعِ فَإِنَّهُ بِئْسَ الضَّجِيعُ، وَأَعُوذُ بِكَ مِنَ الْخِيَانَةِ فَإِنَّهَا بِئْسَتِ الْبِطَانَةُ.","tr":"Allāhumma innī aʿūdhu bika min mawti l-hamm, wa aʿūdhu bika min mawti l-ghamm, wa aʿūdhu bika mina l-jūʿi fa-innahū biʾsa ḍ-ḍajīʿ, wa aʿūdhu bika mina l-khiyānati fa-innahā biʾsati l-biṭānah.","en":"O Allah, I seek refuge in You from dying in worry, and from dying in grief. I seek refuge in You from hunger, for it is an evil bedfellow, and from treachery, for it is an evil inner trait.","ref":null,"q":null,"source":"Ibn al-Najjār, from Abū Hurayra.","page":null,"status":"draft"},
{"n":4,"ar":"اللّٰهُمَّ اجْعَلْ سَرِيرَتِي خَيْرًا مِنْ عَلَانِيَتِي، وَاجْعَلْ عَلَانِيَتِي صَالِحَةً.","tr":"Allāhumma jʿal sarīratī khayran min ʿalāniyatī, wajʿal ʿalāniyatī ṣāliḥah.","en":"O Allah, make my inner self better than my outward self, and make my outward self righteous.","ref":null,"q":null,"source":"al-Tirmidhī (one note covers duʿas 4 and 5).","page":null,"status":"draft"},
{"n":5,"ar":"اللّٰهُمَّ إِنِّي أَسْأَلُكَ مِنْ صَالِحِ مَا تُؤْتِي النَّاسَ مِنَ الْمَالِ وَالْأَهْلِ وَالْوَلَدِ، غَيْرِ ضَالٍّ وَلَا مُضِلٍّ.","tr":"Allāhumma innī asʾaluka min ṣāliḥi mā tuʾti n-nāsa mina l-māli wal-ahli wal-walad, ghayri ḍāllin wa lā muḍill.","en":"O Allah, I ask You for the good of what You give people in wealth, family and children, neither astray nor leading others astray.","ref":null,"q":null,"source":"al-Tirmidhī.","page":null,"status":"draft"},
{"n":6,"ar":"اللّٰهُمَّ اجْعَلْنَا مِنْ عِبَادِكَ الْمُنْتَخَبِينَ، الْغُرِّ الْمُحَجَّلِينَ، الْوَفْدِ الْمُتَقَبَّلِينَ.","tr":"Allāhumma jʿalnā min ʿibādika l-muntakhabīn, al-ghurri l-muḥajjalīn, al-wafdi l-mutaqabbalīn.","en":"O Allah, make us among Your chosen servants: those whose faces and limbs shine bright, the welcomed company of guests.","ref":null,"q":null,"source":"Aḥmad, *Musnad*.","page":null,"status":"draft"},
{"n":7,"ar":"اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ أَنْ أُشْرِكَ بِكَ شَيْئًا وَأَنَا أَعْلَمُ بِهِ، وَأَسْتَغْفِرُكَ لِمَا لَا أَعْلَمُ بِهِ.","tr":"Allāhumma innī aʿūdhu bika min an ushrika bika shayʾan wa ana aʿlamu bih, wa astaghfiruka limā lā aʿlamu bih.","en":"O Allah, I seek refuge in You from knowingly associating anything with You, and I ask Your forgiveness for what I do unknowingly.","ref":null,"q":null,"source":"al-Ṭabarānī.","page":null,"status":"draft"},
{"n":8,"ar":"اللّٰهُمَّ إِنِّي أَعُوذُ بِوَجْهِكَ الْكَرِيمِ، وَبِاسْمِكَ الْعَظِيمِ، مِنَ الْكُفْرِ وَالْفَقْرِ.","tr":"Allāhumma innī aʿūdhu bi-wajhika l-karīm, wa bismika l-ʿaẓīm, mina l-kufri wal-faqr.","en":"O Allah, I seek refuge in Your noble Face and Your mighty Name from disbelief and poverty.","ref":null,"q":null,"source":"al-Ṭabarānī, *Kitāb al-Sunna*, from ʿAbd al-Raḥmān ibn Abī Bakr.","page":null,"status":"draft"},
{"n":9,"ar":"اللّٰهُمَّ قِنِي شَرَّ نَفْسِي، وَاعْزِمْ لِي عَلَى أَرْشَدِ أَمْرِي.","tr":"Allāhumma qinī sharra nafsī, waʿzim lī ʿalā arshadi amrī.","en":"O Allah, protect me from the evil of my own self, and make me resolute in the most rightly guided of my affairs.","ref":null,"q":null,"source":"al-Ḥākim (*al-Mustadrak*), al-Nasāʾī, Ibn Ḥibbān (via Ibn al-Jazarī, *al-Ḥiṣn*).","page":null,"status":"draft"},
{"n":10,"ar":"اللّٰهُمَّ لَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَلَا تَنْزِعْ مِنِّي صَالِحَ مَا أَعْطَيْتَنِي، فَإِنَّهُ لَا نَازِعَ لِمَا أَعْطَيْتَ، وَلَا يَعْصِمُ ذَا الْجَدِّ مِنْكَ الْجَدُّ.","tr":"Allāhumma lā takilnī ilā nafsī ṭarfata ʿayn, wa lā tanziʿ minnī ṣāliḥa mā aʿṭaytanī, fa-innahū lā nāziʿa limā aʿṭayt, wa lā yaʿṣimu dha l-jaddi minka l-jadd.","en":"O Allah, do not leave me to myself for the blink of an eye, and do not take from me the good You have given me. No one can take away what You give, and a man's fortune does not protect him from You.","ref":null,"q":null,"source":"al-Bazzār, from Ibn ʿUmar.","page":null,"status":"draft"},
{"n":11,"ar":"اللّٰهُمَّ إِنِّي أَسْأَلُكَ غِنَى الْأَهْلِ وَالْمَوْلَى، وَأَعُوذُ بِكَ أَنْ يَدْعُوَ عَلَيَّ رَحِمٌ قَطَعْتُهَا.","tr":"Allāhumma innī asʾaluka ghina l-ahli wal-mawlā, wa aʿūdhu bika an yadʿuwa ʿalayya raḥimun qaṭaʿtuhā.","en":"O Allah, I ask You for sufficiency for my family and my kin, and I seek refuge in You from being cursed by a relative whose ties I have cut.","ref":null,"q":null,"source":"al-Ṭabarānī, from Zayd ibn Thābit.","page":null,"status":"draft"},
{"n":12,"ar":"اللّٰهُمَّ إِنِّي أَسْأَلُكَ نَفْسًا بِكَ مُطْمَئِنَّةً، تُؤْمِنُ بِلِقَائِكَ، وَتَرْضَى بِقَضَائِكَ، وَتَقْنَعُ بِعَطَائِكَ.","tr":"Allāhumma innī asʾaluka nafsan bika muṭmaʾinnah, tuʾminu bi-liqāʾik, wa tarḍā bi-qaḍāʾik, wa taqnaʿu bi-ʿaṭāʾik.","en":"O Allah, I ask You for a soul at peace with You, one that believes in meeting You, accepts Your decree and is content with what You give.","ref":null,"q":null,"source":"al-Ṭabarānī (*al-Kabīr*) and al-Ḍiyāʾ al-Maqdisī, from Abū Umāma.","page":null,"status":"draft"},
{"n":13,"ar":"اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَنْ يَمْشِي عَلَى بَطْنِهِ، وَمِنْ شَرِّ مَنْ يَمْشِي عَلَى رِجْلَيْنِ، وَمِنْ شَرِّ مَنْ يَمْشِي عَلَى أَرْبَعٍ.","tr":"Allāhumma innī aʿūdhu bika min sharri man yamshī ʿalā baṭnih, wa min sharri man yamshī ʿalā rijlayn, wa min sharri man yamshī ʿalā arbaʿ.","en":"O Allah, I seek refuge in You from the evil of what crawls on its belly, of what walks on two legs, and of what walks on four.","ref":null,"q":null,"source":"al-Ṭabarānī (*al-Kabīr*), from Ibn ʿAbbās.","page":null,"status":"draft"},
{"n":14,"ar":"اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنِ امْرَأَةٍ تُشَيِّبُنِي قَبْلَ الْمَشِيبِ، وَأَعُوذُ بِكَ مِنْ وَلَدٍ يَكُونُ عَلَيَّ وَبَالًا، وَأَعُوذُ بِكَ مِنْ مَالٍ يَكُونُ عَلَيَّ عَذَابًا، وَأَعُوذُ بِكَ مِنْ صَاحِبِ خَدِيعَةٍ، إِنْ رَأَى حَسَنَةً دَفَنَهَا، وَإِنْ رَأَى سَيِّئَةً أَفْشَاهَا.","tr":"Allāhumma innī aʿūdhu bika mini mraʾatin tushayyibunī qabla l-mashīb, wa aʿūdhu bika min waladin yakūnu ʿalayya wabālā, wa aʿūdhu bika min mālin yakūnu ʿalayya ʿadhābā, wa aʿūdhu bika min ṣāḥibi khadīʿah, in raʾā ḥasanatan dafanahā, wa in raʾā sayyiʾatan afshāhā.","en":"O Allah, I seek refuge in You from a wife who makes me grey before my time, from a child who becomes a burden on me, from wealth that becomes a torment for me, and from a deceitful companion who buries any good he sees and spreads any wrong he sees.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":15,"ar":"اللّٰهُمَّ إِنَّكَ تَعْلَمُ سِرِّي وَعَلَانِيَتِي فَاقْبَلْ مَعْذِرَتِي، وَتَعْلَمُ حَاجَتِي فَأَعْطِنِي سُؤْلِي، وَتَعْلَمُ مَا فِي نَفْسِي فَاغْفِرْ لِي ذُنُوبِي.","tr":"Allāhumma innaka taʿlamu sirrī wa ʿalāniyatī faqbal maʿdhiratī, wa taʿlamu ḥājatī fa-aʿṭinī suʾlī, wa taʿlamu mā fī nafsī faghfir lī dhunūbī.","en":"O Allah, You know what I hide and what I show, so accept my excuse. You know my need, so grant my request. You know what is in my soul, so forgive my sins.","ref":null,"q":null,"source":"al-Ṭabarānī (*al-Awsaṭ*) and Ibn ʿAsākir, from ʿĀʾisha.","page":null,"status":"draft"},
{"n":16,"ar":"اللّٰهُمَّ إِنِّي أَسْأَلُكَ إِيمَانًا يُبَاشِرُ قَلْبِي، وَيَقِينًا صَادِقًا، حَتَّى أَعْلَمَ أَنَّهُ لَا يُصِيبُنِي إِلَّا مَا كَتَبْتَ لِي، وَرِضًا بِمَا قَسَمْتَ لِي، إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ.","tr":"Allāhumma innī asʾaluka īmānan yubāshiru qalbī, wa yaqīnan ṣādiqā, ḥattā aʿlama annahū lā yuṣībunī illā mā katabta lī, wa riḍan bimā qasamta lī, innaka ʿalā kulli shayʾin qadīr.","en":"O Allah, I ask You for faith that fills my heart and for true certainty, so that I know nothing will befall me except what You have written for me. I ask You also for contentment with what You have allotted me. You have power over all things.","ref":null,"q":null,"source":"al-Ṭabarānī (*al-Awsaṭ*) and Ibn ʿAsākir, from ʿĀʾisha (the same note as 15).","page":null,"status":"draft"},
{"n":17,"ar":"اللّٰهُمَّ لَكَ الْحَمْدُ حَمْدًا دَائِمًا مَعَ دَوَامِكَ، وَلَكَ الْحَمْدُ حَمْدًا خَالِدًا مَعَ خُلُودِكَ، وَلَكَ الْحَمْدُ حَمْدًا لَا مُنْتَهَى لَهُ دُونَ مَشِيئَتِكَ، وَلَكَ الْحَمْدُ حَمْدًا دَائِمًا لَا يُرِيدُ قَائِلُهُ إِلَّا رِضَاكَ، وَلَكَ الْحَمْدُ حَمْدًا عِنْدَ كُلِّ طَرْفَةِ عَيْنٍ وَتَنَفُّسِ كُلِّ نَفْسٍ.","tr":"Allāhumma laka l-ḥamdu ḥamdan dāʾiman maʿa dawāmik, wa laka l-ḥamdu ḥamdan khālidan maʿa khulūdik, wa laka l-ḥamdu ḥamdan lā muntahā lahū dūna mashīʾatik, wa laka l-ḥamdu ḥamdan dāʾiman lā yurīdu qāʾiluhū illā riḍāk, wa laka l-ḥamdu ḥamdan ʿinda kulli ṭarfati ʿaynin wa tanaffusi kulli nafs.","en":"O Allah, to You belongs praise that lasts as long as You last, praise that endures as long as You endure, and praise that has no limit short of what You will. To You belongs lasting praise by which the one who says it seeks only Your pleasure, and praise at every blink of an eye and every breath of every soul.","ref":null,"q":null,"source":"al-Rāfiʿī, from ʿAlī.","page":null,"status":"draft"},
{"n":18,"ar":"اللّٰهُمَّ أَقْبِلْ بِقَلْبِي إِلَى دِينِكَ، وَاحْفَظْ مِنْ وَرَائِنَا بِرَحْمَتِكَ.","tr":"Allāhumma aqbil bi-qalbī ilā dīnik, waḥfaẓ min warāʾinā bi-raḥmatik.","en":"O Allah, turn my heart towards Your religion, and guard us from behind with Your mercy.","ref":null,"q":null,"source":"Abū Yaʿlā al-Mawṣilī, from Anas.","page":null,"status":"draft"},
{"n":19,"ar":"اللّٰهُمَّ ثَبِّتْنِي أَنْ أَزِلَّ، وَاهْدِنِي أَنْ أَضِلَّ.","tr":"Allāhumma thabbitnī an azill, wahdinī an aḍill.","en":"O Allah, keep me firm so that I do not slip, and guide me so that I do not go astray.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":20,"ar":"اللّٰهُمَّ كَمَا حُلْتَ بَيْنِي وَبَيْنَ قَلْبِي، فَحُلْ بَيْنِي وَبَيْنَ الشَّيْطَانِ وَعَمَلِهِ.","tr":"Allāhumma kamā ḥulta baynī wa bayna qalbī, fa-ḥul baynī wa bayna sh-shayṭāni wa ʿamalih.","en":"O Allah, just as You come between me and my heart, come between me and Satan and his work.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":21,"ar":"اللّٰهُمَّ ارْزُقْنَا مِنْ فَضْلِكَ، وَلَا تَحْرِمْنَا رِزْقَكَ، وَبَارِكْ لَنَا فِيمَا رَزَقْتَنَا، وَاجْعَلْ غِنَانَا فِي أَنْفُسِنَا، وَاجْعَلْ رَغْبَتَنَا فِيمَا عِنْدَكَ.","tr":"Allāhumma rzuqnā min faḍlik, wa lā taḥrimnā rizqak, wa bārik lanā fīmā razaqtanā, wajʿal ghinānā fī anfusinā, wajʿal raghbatanā fīmā ʿindak.","en":"O Allah, provide for us from Your bounty and do not deprive us of Your provision. Bless what You have given us, place our wealth in our hearts, and direct our desire towards what is with You.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":22,"ar":"اللّٰهُمَّ إِنَّكَ خَلَّاقٌ عَظِيمٌ، إِنَّكَ سَمِيعٌ عَلِيمٌ، إِنَّكَ غَفُورٌ رَحِيمٌ، إِنَّكَ رَبُّ الْعَرْشِ الْعَظِيمِ.","tr":"Allāhumma innaka khallāqun ʿaẓīm, innaka samīʿun ʿalīm, innaka ghafūrun raḥīm, innaka rabbu l-ʿarshi l-ʿaẓīm.","en":"O Allah, You are the mighty Creator; You are All-Hearing, All-Knowing; You are Forgiving, Merciful; You are Lord of the mighty Throne.","ref":null,"q":null,"source":"al-Daylamī, from Jābir.","page":null,"status":"draft"},
{"n":23,"ar":"اللّٰهُمَّ إِنَّكَ الْبَرُّ الْجَوَادُ الْكَرِيمُ، اغْفِرْ لِي وَارْحَمْنِي، وَعَافِنِي وَارْزُقْنِي، وَاسْتُرْنِي وَاجْبُرْنِي، وَارْفَعْنِي وَاهْدِنِي، وَلَا تُضِلَّنِي، وَأَدْخِلْنِي الْجَنَّةَ بِرَحْمَتِكَ يَا أَرْحَمَ الرَّاحِمِينَ. إِلَيْكَ رَبِّ فَحَبِّبْنِي، وَفِي نَفْسِي لَكَ رَبِّ فَذَلِّلْنِي، وَفِي أَعْيُنِ النَّاسِ فَعَظِّمْنِي، وَمِنْ سَيِّئِ الْأَخْلَاقِ فَجَنِّبْنِي.","tr":"Allāhumma innaka l-Barru l-Jawādu l-Karīm, ighfir lī warḥamnī, wa ʿāfinī warzuqnī, wastturnī wajburnī, warfaʿnī wahdinī, wa lā tuḍillanī, wa adkhilni l-jannata bi-raḥmatika yā Arḥama r-rāḥimīn. Ilayka rabbi fa-ḥabbibnī, wa fī nafsī laka rabbi fa-dhallilnī, wa fī aʿyuni n-nāsi fa-ʿaẓẓimnī, wa min sayyiʾi l-akhlāqi fa-jannibnī.","en":"O Allah, You are the Good, the Generous, the Noble. Forgive me and have mercy on me; keep me well and provide for me; cover my faults and mend my state; raise me and guide me, and do not let me go astray; and admit me to Paradise by Your mercy, O Most Merciful of the merciful. My Lord, make me beloved to You; my Lord, make me humble before You in my own eyes; make me honoured in the eyes of people; and keep me away from bad character.","ref":null,"q":null,"source":"Ibn Lāl, from Ibn Masʿūd.","page":null,"status":"draft"},
{"n":24,"ar":"اللّٰهُمَّ إِنَّكَ سَأَلْتَنَا مِنْ أَنْفُسِنَا مَا لَا نَمْلِكُهُ إِلَّا بِكَ، فَأَعْطِنَا مِنْهَا مَا يُرْضِيكَ عَنَّا.","tr":"Allāhumma innaka saʾaltanā min anfusinā mā lā namlikuhū illā bik, fa-aʿṭinā minhā mā yurḍīka ʿannā.","en":"O Allah, You have asked of us, from our own selves, what we cannot possess except through You. So give us from it what will make You pleased with us.","ref":null,"q":null,"source":"Ibn ʿAsākir, from Abū Hurayra.","page":null,"status":"draft"},
{"n":25,"ar":"اللّٰهُمَّ إِنِّي أَسْأَلُكَ إِيمَانًا دَائِمًا، وَأَسْأَلُكَ قَلْبًا خَاشِعًا، وَأَسْأَلُكَ يَقِينًا صَادِقًا، وَأَسْأَلُكَ دِينًا قَيِّمًا، وَأَسْأَلُكَ الْعَافِيَةَ مِنْ كُلِّ بَلِيَّةٍ، وَأَسْأَلُكَ دَوَامَ الْعَافِيَةِ، وَأَسْأَلُكَ الشُّكْرَ عَلَى الْعَافِيَةِ، وَأَسْأَلُكَ الْغِنَى عَنِ النَّاسِ.","tr":"Allāhumma innī asʾaluka īmānan dāʾimā, wa asʾaluka qalban khāshiʿā, wa asʾaluka yaqīnan ṣādiqā, wa asʾaluka dīnan qayyimā, wa asʾaluka l-ʿāfiyata min kulli baliyyah, wa asʾaluka dawāma l-ʿāfiyah, wa asʾaluka sh-shukra ʿala l-ʿāfiyah, wa asʾaluka l-ghinā ʿani n-nās.","en":"O Allah, I ask You for lasting faith, a humble heart, true certainty and an upright religion. I ask You for well-being from every affliction, for lasting well-being, for gratitude for well-being, and for independence from people.","ref":null,"q":null,"source":"al-Ḥakīm al-Tirmidhī, *Nawādir al-Uṣūl*, from Abū Dharr.","page":null,"status":"draft"},
{"n":26,"ar":"اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ بَطَرِ الْغِنَى وَمَذَلَّةِ الْفَقْرِ، يَا مَنْ وَعَدَ فَوَفَى، وَأَوْعَدَ فَعَفَا، اغْفِرْ لِمَنْ ظَلَمَ وَأَسَاءَ، يَا مَنْ يَسُرُّهُ طَاعَتِي وَلَا تَضُرُّهُ مَعْصِيَتِي، هَبْ لِي مَا يَسُرُّكَ، وَاغْفِرْ لِي مَا لَا يَضُرُّكَ.","tr":"Allāhumma innī aʿūdhu bika min baṭari l-ghinā wa madhallati l-faqr, yā man waʿada fa-wafā, wa awʿada fa-ʿafā, ighfir liman ẓalama wa asāʾ, yā man yasurruhū ṭāʿatī wa lā taḍurruhū maʿṣiyatī, hab lī mā yasurruk, waghfir lī mā lā yaḍurruk.","en":"O Allah, I seek refuge in You from the arrogance that wealth brings and from the humiliation of poverty. O You who promised and kept Your promise, and threatened and then pardoned: forgive the one who has wronged and done evil. O You whom my obedience pleases and my disobedience does not harm: grant me what pleases You, and forgive me what does not harm You.","ref":null,"q":null,"source":"al-Ṭayālisī, for the first sentence only. Nomani says he did not trace the rest.","page":null,"status":"draft"},
{"n":27,"ar":"اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الشَّكِّ فِي الْحَقِّ بَعْدَ الْيَقِينِ، وَأَعُوذُ بِكَ مِنَ الشَّيْطَانِ الرَّجِيمِ، وَأَعُوذُ بِكَ مِنْ شَرِّ يَوْمِ الدِّينِ.","tr":"Allāhumma innī aʿūdhu bika mina sh-shakki fi l-ḥaqqi baʿda l-yaqīn, wa aʿūdhu bika mina sh-shayṭāni r-rajīm, wa aʿūdhu bika min sharri yawmi d-dīn.","en":"O Allah, I seek refuge in You from doubting the truth after having certainty. I seek refuge in You from Satan the accursed, and from the evil of the Day of Judgement.","ref":null,"q":null,"source":"an *Amālī*, from al-Barāʾ. The compiler's name is unclear in the scan; see the uncertain readings.","page":null,"status":"draft"},
{"n":28,"ar":"اللّٰهُمَّ إِنِّي أَسْتَغْفِرُكَ لِمَا تُبْتُ إِلَيْكَ مِنْهُ ثُمَّ عُدْتُ فِيهِ، وَأَسْتَغْفِرُكَ لِمَا أَعْطَيْتُكَ مِنْ نَفْسِي ثُمَّ لَمْ أُوفِ لَكَ بِهِ، وَأَسْتَغْفِرُكَ لِلنِّعَمِ الَّتِي تَقَوَّيْتُ بِهَا عَلَى مَعْصِيَتِكَ، وَأَسْتَغْفِرُكَ لِكُلِّ خَيْرٍ أَرَدْتُ بِهِ وَجْهَكَ فَخَالَطَنِي فِيهِ مَا لَيْسَ لَكَ.","tr":"Allāhumma innī astaghfiruka limā tubtu ilayka minhu thumma ʿudtu fīh, wa astaghfiruka limā aʿṭaytuka min nafsī thumma lam ūfi laka bih, wa astaghfiruka lin-niʿami llatī taqawwaytu bihā ʿalā maʿṣiyatik, wa astaghfiruka li-kulli khayrin aradtu bihī wajhaka fa-khālaṭanī fīhi mā laysa lak.","en":"O Allah, I ask Your forgiveness for every sin I repented of and then returned to; for every pledge I made to You from myself and then did not keep; for the blessings I used as strength to disobey You; and for every good deed I meant for Your sake into which something not for You crept in.","ref":null,"q":null,"source":"al-Daylamī, *Musnad al-Firdaws*, from Ibn ʿUmar.","page":null,"status":"draft"},
{"n":29,"ar":"اللّٰهُمَّ لَا تُخْزِنِي فَإِنَّكَ بِي عَالِمٌ، وَلَا تُعَذِّبْنِي فَإِنَّكَ عَلَيَّ قَادِرٌ.","tr":"Allāhumma lā tukhzinī fa-innaka bī ʿālim, wa lā tuʿadhdhibnī fa-innaka ʿalayya qādir.","en":"O Allah, do not disgrace me, for You know me well; and do not punish me, for You have full power over me.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":30,"ar":"اللّٰهُمَّ اجْعَلْنِي مِمَّنْ تَوَكَّلَ عَلَيْكَ فَكَفَيْتَهُ، وَاسْتَهْدَاكَ فَهَدَيْتَهُ، وَاسْتَنْصَرَكَ فَنَصَرْتَهُ.","tr":"Allāhumma jʿalnī mimman tawakkala ʿalayka fa-kafaytah, wastahdāka fa-hadaytah, wastanṣaraka fa-naṣartah.","en":"O Allah, make me one of those who relied on You and You sufficed him, who asked You for guidance and You guided him, and who asked You for help and You helped him.","ref":null,"q":null,"source":"Ibn Abī al-Dunyā, *Kitāb al-Tawakkul*, from Anas.","page":null,"status":"draft"},
{"n":31,"ar":"اللّٰهُمَّ اجْعَلْ وَسَاوِسَ قَلْبِي خَشْيَتَكَ وَذِكْرَكَ، وَاجْعَلْ هِمَّتِي وَهَوَايَ فِيمَا تُحِبُّ وَتَرْضَى.","tr":"Allāhumma jʿal wasāwisa qalbī khashyataka wa dhikrak, wajʿal himmatī wa hawāya fīmā tuḥibbu wa tarḍā.","en":"O Allah, let the thoughts that stir in my heart be fear of You and remembrance of You, and set my ambition and my desire on what You love and are pleased with.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":32,"ar":"اللّٰهُمَّ وَمَا ابْتَلَيْتَنِي بِهِ مِنْ رَخَاءٍ وَشِدَّةٍ، فَمَسِّكْنِي بِسُنَّةِ الْحَقِّ وَشَرِيعَةِ الْإِسْلَامِ.","tr":"Allāhumma wa mā btalaytanī bihī min rakhāʾin wa shiddah, fa-massiknī bi-sunnati l-ḥaqqi wa sharīʿati l-islām.","en":"O Allah, in whatever ease or hardship You test me with, keep me holding fast to the way of truth and the law of Islam.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":33,"ar":"اللّٰهُمَّ إِنِّي أَسْأَلُكَ تَمَامَ النِّعْمَةِ فِي الْأَشْيَاءِ كُلِّهَا، وَالشُّكْرَ لَكَ عَلَيْهَا حَتَّى تَرْضَى وَبَعْدَ الرِّضَا، وَالْخِيَرَةَ فِي جَمِيعِ مَا يَكُونُ فِيهِ الْخِيَرَةُ، وَبِجَمِيعِ مَيْسُورِ الْأُمُورِ كُلِّهَا لَا بِمَعْسُورِهَا، يَا كَرِيمُ.","tr":"Allāhumma innī asʾaluka tamāma n-niʿmati fi l-ashyāʾi kullihā, wash-shukra laka ʿalayhā ḥattā tarḍā wa baʿda r-riḍā, wal-khiyarata fī jamīʿi mā yakūnu fīhi l-khiyarah, wa bi-jamīʿi maysūri l-umūri kullihā lā bi-maʿsūrihā, yā Karīm.","en":"O Allah, I ask You for complete blessing in all things, and for gratitude to You for it until You are pleased and after You are pleased. I ask You to choose the best for me in everything where there is a choice, and to bring all matters about with ease and not with hardship, O Generous One.","ref":null,"q":null,"source":"Ibn Abī al-Dunyā, *Kitāb al-Shukr* (as a duʿa of Abū Bakr).","page":null,"status":"draft"},
{"n":34,"ar":"اللّٰهُمَّ فَالِقَ الْإِصْبَاحِ، وَجَاعِلَ اللَّيْلِ سَكَنًا، وَالشَّمْسِ وَالْقَمَرِ حُسْبَانًا، اقْضِ عَنِّي الدَّيْنَ، وَأَغْنِنِي مِنَ الْفَقْرِ، وَقَوِّنِي عَلَى الْجِهَادِ فِي سَبِيلِكَ.","tr":"Allāhumma fāliqa l-iṣbāḥ, wa jāʿila l-layli sakanā, wash-shamsi wal-qamari ḥusbānā, iqḍi ʿanni d-dayn, wa aghninī mina l-faqr, wa qawwinī ʿala l-jihādi fī sabīlik.","en":"O Allah, Splitter of the dawn, who made the night for rest and the sun and moon for reckoning: settle my debts, free me from poverty, and strengthen me to strive in Your way.","ref":"the opening phrases echo al-Anʿām 6:96 (فَالِقُ الْإِصْبَاحِ وَجَعَلَ اللَّيْلَ سَكَنًا وَالشَّمْسَ وَالْقَمَرَ حُسْبَانًا), reworded as a vocative. This is not a direct quotation, so the translation below is ours.","q":null,"source":"Ibn Abī Shayba, from Muslim ibn Yasār.","page":null,"status":"draft"},
{"n":35,"ar":"اللّٰهُمَّ لَكَ الْحَمْدُ فِي بَلَائِكَ وَصَنِيعِكَ إِلَى خَلْقِكَ، وَلَكَ الْحَمْدُ فِي بَلَائِكَ وَصَنِيعِكَ إِلَى أَهْلِ بُيُوتِنَا، وَلَكَ الْحَمْدُ فِي بَلَائِكَ وَصَنِيعِكَ إِلَى أَنْفُسِنَا خَاصَّةً، وَلَكَ الْحَمْدُ بِمَا هَدَيْتَنَا، وَلَكَ الْحَمْدُ بِمَا أَكْرَمْتَنَا، وَلَكَ الْحَمْدُ بِمَا سَتَرْتَنَا، وَلَكَ الْحَمْدُ بِالْقُرْآنِ، وَلَكَ الْحَمْدُ بِالْأَهْلِ وَالْمَالِ، وَلَكَ الْحَمْدُ بِالْمُعَافَاةِ، وَلَكَ الْحَمْدُ حَتَّى تَرْضَى، وَلَكَ الْحَمْدُ إِذَا رَضِيتَ، يَا أَهْلَ التَّقْوَى وَأَهْلَ الْمَغْفِرَةِ.","tr":"Allāhumma laka l-ḥamdu fī balāʾika wa ṣanīʿika ilā khalqik, wa laka l-ḥamdu fī balāʾika wa ṣanīʿika ilā ahli buyūtinā, wa laka l-ḥamdu fī balāʾika wa ṣanīʿika ilā anfusinā khāṣṣah, wa laka l-ḥamdu bimā hadaytanā, wa laka l-ḥamdu bimā akramtanā, wa laka l-ḥamdu bimā satartanā, wa laka l-ḥamdu bil-Qurʾān, wa laka l-ḥamdu bil-ahli wal-māl, wa laka l-ḥamdu bil-muʿāfāh, wa laka l-ḥamdu ḥattā tarḍā, wa laka l-ḥamdu idhā raḍīt, yā ahla t-taqwā wa ahla l-maghfirah.","en":"O Allah, praise be to You for how You test Your creation and for what You do for them. Praise be to You for this towards the people of our homes, and towards ourselves in particular. Praise be to You for guiding us, for honouring us and for covering our faults. Praise be to You for the Qurʾān, for family and wealth, and for well-being. Praise be to You until You are pleased, and praise be to You when You are pleased, O You who alone are worthy to be feared and who alone forgive.","ref":null,"q":null,"source":"al-Ṭabarānī, *Kitāb al-Duʿāʾ*, and al-Daylamī, from Anas.","page":null,"status":"draft"},
{"n":36,"ar":"اللّٰهُمَّ وَفِّقْنِي لِمَا تُحِبُّ وَتَرْضَى مِنَ الْقَوْلِ وَالْعَمَلِ وَالْفِعْلِ وَالنِّيَّةِ وَالْهُدَى، إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ.","tr":"Allāhumma waffiqnī limā tuḥibbu wa tarḍā mina l-qawli wal-ʿamali wal-fiʿli wan-niyyati wal-hudā, innaka ʿalā kulli shayʾin qadīr.","en":"O Allah, enable me to do what You love and are pleased with, in speech, in work, in deed, in intention and in guidance. You have power over all things.","ref":null,"q":null,"source":"al-Daylamī, from Ibn ʿUmar.","page":null,"status":"draft"},
{"n":37,"ar":"اللّٰهُمَّ رَبَّ السَّمٰوٰتِ السَّبْعِ وَرَبَّ الْعَرْشِ الْعَظِيمِ، اللّٰهُمَّ اكْفِنِي كُلَّ مُهِمٍّ مِنْ حَيْثُ شِئْتَ وَمِنْ أَيْنَ شِئْتَ، حَسْبِيَ اللّٰهُ لِدِينِي، حَسْبِيَ اللّٰهُ لِمَا أَهَمَّنِي، حَسْبِيَ اللّٰهُ لِمَنْ بَغَى عَلَيَّ، حَسْبِيَ اللّٰهُ لِمَنْ حَسَدَنِي، حَسْبِيَ اللّٰهُ لِمَنْ كَادَنِي بِسُوءٍ، حَسْبِيَ اللّٰهُ عِنْدَ الْمَوْتِ، حَسْبِيَ اللّٰهُ عِنْدَ الْمَسْأَلَةِ فِي الْقَبْرِ، حَسْبِيَ اللّٰهُ عِنْدَ الْمِيزَانِ، حَسْبِيَ اللّٰهُ عِنْدَ الصِّرَاطِ، حَسْبِيَ اللّٰهُ لَا إِلٰهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ.","tr":"Allāhumma rabba s-samāwāti s-sabʿi wa rabba l-ʿarshi l-ʿaẓīm, Allāhumma kfinī kulla muhimmin min ḥaythu shiʾta wa min ayna shiʾt, ḥasbiya llāhu li-dīnī, ḥasbiya llāhu limā ahammanī, ḥasbiya llāhu liman baghā ʿalayy, ḥasbiya llāhu liman ḥasadanī, ḥasbiya llāhu liman kādanī bi-sūʾ, ḥasbiya llāhu ʿinda l-mawt, ḥasbiya llāhu ʿinda l-masʾalati fi l-qabr, ḥasbiya llāhu ʿinda l-mīzān, ḥasbiya llāhu ʿinda ṣ-ṣirāṭ, ḥasbiya llāhu lā ilāha illā huwa ʿalayhi tawakkaltu wa huwa rabbu l-ʿarshi l-ʿaẓīm.","en":"O Allah, Lord of the seven heavens and Lord of the mighty Throne, O Allah, spare me every worry, in whatever way and from wherever You will. Allah is enough for me for my religion, for whatever troubles me, against whoever wrongs me, against whoever envies me, and against whoever plots evil against me. Allah is enough for me at death, at the questioning in the grave, at the Scale and at the Bridge. *[9:129, Pickthall:]* \"Allah sufficeth me. There is no God save Him. In Him have I put my trust, and He is Lord of the Tremendous Throne.\"","ref":"the closing words «حَسْبِيَ اللّٰهُ لَا إِلٰهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ» are from al-Tawba 9:129. Nomani quotes only the end of the verse; the mushaf verse begins «فَإِنْ تَوَلَّوْا فَقُلْ». The 9:129 portion uses the Qurʾān translation from Pickthall; the rest is ours.","q":null,"source":"- first part: al-Kharāʾiṭī, *Makārim al-Akhlāq*, from ʿAlī; - the *ḥasbiya llāh* part: al-Ḥakīm al-Tirmidhī, *Nawādir al-Uṣūl*, from Burayda.","page":null,"status":"draft"},
{"n":38,"ar":"اللّٰهُمَّ حَبِّبِ الْمَوْتَ إِلَى مَنْ يَعْلَمُ أَنَّ سَيِّدَنَا مُحَمَّدًا صَلَّى اللّٰهُ عَلَيْهِ وَسَلَّمَ رَسُولُكَ.","tr":"Allāhumma ḥabbibi l-mawta ilā man yaʿlamu anna sayyidanā Muḥammadan ṣalla llāhu ʿalayhi wa sallama rasūluk.","en":"O Allah, make death beloved to everyone who knows that our master Muhammad (Allah bless him and give him peace) is Your Messenger.","ref":null,"q":null,"source":"al-Ṭabarānī, from Abū Mālik al-Ashʿarī.","page":null,"status":"draft"},
{"n":39,"ar":"اللّٰهُمَّ إِنَّكَ رَبٌّ عَظِيمٌ، لَا يَسَعُكَ شَيْءٌ مِمَّا خَلَقْتَ، وَأَنْتَ تَرَى وَلَا تُرَى، وَأَنْتَ بِالْمَنْظَرِ الْأَعْلَى، وَأَنَّ لَكَ الْآخِرَةَ وَالْأُولَى، وَلَكَ الْمَمَاتُ وَالْمَحْيَا، وَإِلَيْكَ الْمُنْتَهَى وَالرُّجْعَى، نَعُوذُ بِكَ أَنْ نَذِلَّ وَنَخْزَى.","tr":"Allāhumma innaka rabbun ʿaẓīm, lā yasaʿuka shayʾun mimmā khalaqt, wa anta tarā wa lā turā, wa anta bil-manẓari l-aʿlā, wa anna laka l-ākhirata wal-ūlā, wa laka l-mamātu wal-maḥyā, wa ilayka l-muntahā war-rujʿā, naʿūdhu bika an nadhilla wa nakhzā.","en":"O Allah, You are a mighty Lord; nothing You have created can contain You. You see and are not seen, and You are at the highest vantage. To You belong the Hereafter and this world, death and life, and to You is the final end and the return. We seek refuge in You from being humiliated and disgraced.","ref":null,"q":null,"source":"al-Daylamī, from Abū Hurayra.","page":null,"status":"draft"},
{"n":40,"ar":"اللّٰهُمَّ إِنِّي أَسْأَلُكَ ثَوَابَ الشَّاكِرِينَ، وَنُزُلَ الْمُقَرَّبِينَ، وَمُرَافَقَةَ النَّبِيِّينَ، وَيَقِينَ الصِّدِّيقِينَ، وَذِلَّةَ الْمُتَّقِينَ، وَإِخْبَاتَ الْمُوقِنِينَ، حَتَّى تَوَفَّانِي عَلَى ذٰلِكَ يَا أَرْحَمَ الرَّاحِمِينَ.","tr":"Allāhumma innī asʾaluka thawāba sh-shākirīn, wa nuzula l-muqarrabīn, wa murāfaqata n-nabiyyīn, wa yaqīna ṣ-ṣiddīqīn, wa dhillata l-muttaqīn, wa ikhbāta l-mūqinīn, ḥattā tawaffānī ʿalā dhālika yā Arḥama r-rāḥimīn.","en":"O Allah, I ask You for the reward of the grateful, the welcome given to those brought near, the company of the prophets, the certainty of the truthful, the humility of the God-fearing and the submissiveness of those with sure faith, until You take my soul in that state, O Most Merciful of the merciful.","ref":null,"q":null,"source":"al-Daylamī, from Abū Hurayra.","page":null,"status":"draft"},
{"n":41,"ar":"اللّٰهُمَّ إِنِّي أَسْأَلُكَ بِنِعْمَتِكَ السَّابِقَةِ عَلَيَّ، وَبَلَائِكَ الْحَسَنِ الَّذِي ابْتَلَيْتَنِي بِهِ، وَفَضْلِكَ الَّذِي فَضَّلْتَ عَلَيَّ، أَنْ تُدْخِلَنِي الْجَنَّةَ بِمَنِّكَ وَفَضْلِكَ وَرَحْمَتِكَ.","tr":"Allāhumma innī asʾaluka bi-niʿmatika s-sābiqati ʿalayy, wa balāʾika l-ḥasani lladhi btalaytanī bih, wa faḍlika lladhī faḍḍalta ʿalayy, an tudkhilani l-jannata bi-mannika wa faḍlika wa raḥmatik.","en":"O Allah, I ask You, by the blessings You have already given me, by the good trials You have tested me with, and by the favour You have shown me, to admit me to Paradise through Your grace, Your favour and Your mercy.","ref":null,"q":null,"source":"al-Daylamī, from Ibn Masʿūd.","page":null,"status":"draft"},
{"n":42,"ar":"اللّٰهُمَّ إِنِّي أَسْأَلُكَ بِوَجْهِكَ الْكَرِيمِ، وَأَمْرِكَ الْعَظِيمِ، أَنْ تُجِيرَنِي مِنَ النَّارِ وَالْكُفْرِ وَالْفَقْرِ.","tr":"Allāhumma innī asʾaluka bi-wajhika l-karīm, wa amrika l-ʿaẓīm, an tujīranī mina n-nāri wal-kufri wal-faqr.","en":"O Allah, I ask You, by Your noble Face and Your mighty command, to protect me from the Fire, from disbelief and from poverty.","ref":null,"q":null,"source":"al-Daylamī, from Abū Bakr.","page":null,"status":"draft"},
{"n":43,"ar":"اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ مَوْتِ الْفُجَاءَةِ، وَمِنْ لَدْغَةِ الْحَيَّةِ، وَمِنَ السَّبُعِ، وَمِنَ الْغَرَقِ، وَمِنَ الْحَرَقِ، وَمِنْ أَنْ أَخِرَّ عَلَى شَيْءٍ، وَمِنَ الْقَتْلِ عِنْدَ فِرَارِ الزَّحْفِ.","tr":"Allāhumma innī aʿūdhu bika min mawti l-fujāʾah, wa min ladghati l-ḥayyah, wa mina s-sabuʿ, wa mina l-gharaq, wa mina l-ḥaraq, wa min an akhirra ʿalā shayʾ, wa mina l-qatli ʿinda firāri z-zaḥf.","en":"O Allah, I seek refuge in You from sudden death, from snakebite, from wild beasts, from drowning, from burning, from falling onto something, and from being killed while fleeing the battle line.","ref":null,"q":null,"source":"Aḥmad, *Musnad*, from Ibn ʿUmar.","page":null,"status":"draft"},
{"n":44,"ar":"اللّٰهُمَّ إِنِّي أَسْأَلُكَ إِيمَانًا دَائِمًا، وَهُدًى قَيِّمًا، وَعِلْمًا نَافِعًا.","tr":"Allāhumma innī asʾaluka īmānan dāʾimā, wa hudan qayyimā, wa ʿilman nāfiʿā.","en":"O Allah, I ask You for lasting faith, upright guidance and beneficial knowledge.","ref":null,"q":null,"source":"Abū Nuʿaym, *Ḥilyat al-Awliyāʾ*, from Anas.","page":null,"status":"draft"},
{"n":45,"ar":"اللّٰهُمَّ لَا تَجْعَلْ لِفَاجِرٍ عِنْدِي نِعْمَةً أُكَافِئُهُ بِهَا فِي الدُّنْيَا وَالْآخِرَةِ.","tr":"Allāhumma lā tajʿal li-fājirin ʿindī niʿmatan ukāfiʾuhū bihā fi d-dunyā wal-ākhirah.","en":"O Allah, do not let any wicked person do me a favour that I would have to repay him for, in this world or the next.","ref":null,"q":null,"source":"al-Daylamī, from Muʿādh.","page":null,"status":"draft"},
{"n":46,"ar":"اللّٰهُمَّ اغْفِرْ لِي ذَنْبِي، وَوَسِّعْ لِي خُلُقِي، وَطَيِّبْ لِي كَسْبِي، وَقَنِّعْنِي بِمَا رَزَقْتَنِي، وَلَا تُذْهِبْ طَلَبِي إِلَى شَيْءٍ صَرَفْتَهُ عَنِّي.","tr":"Allāhumma ghfir lī dhanbī, wa wassiʿ lī khuluqī, wa ṭayyib lī kasbī, wa qanniʿnī bimā razaqtanī, wa lā tudhhib ṭalabī ilā shayʾin ṣaraftahū ʿannī.","en":"O Allah, forgive my sins, broaden my character, make my earnings pure, make me content with what You have provided, and do not let my desire chase anything You have turned away from me.","ref":null,"q":null,"source":"Ibn al-Najjār, from ʿAlī.","page":null,"status":"draft"},
{"n":47,"ar":"اللّٰهُ أَكْبَرُ، اللّٰهُ أَكْبَرُ، اللّٰهُ أَكْبَرُ. بِسْمِ اللّٰهِ عَلَى نَفْسِي وَدِينِي، بِسْمِ اللّٰهِ عَلَى أَهْلِي وَمَالِي، بِسْمِ اللّٰهِ عَلَى كُلِّ شَيْءٍ أَعْطَانِي رَبِّي، بِسْمِ اللّٰهِ خَيْرِ الْأَسْمَاءِ، بِسْمِ اللّٰهِ رَبِّ الْأَرْضِ وَالسَّمَاءِ، بِسْمِ اللّٰهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ دَاءٌ، بِسْمِ اللّٰهِ افْتَتَحْتُ، وَعَلَى اللّٰهِ تَوَكَّلْتُ، اللّٰهُ اللّٰهُ رَبِّي لَا أُشْرِكُ بِهِ أَحَدًا، أَسْأَلُكَ اللّٰهُمَّ بِخَيْرِكَ مِنْ خَيْرِكَ الَّذِي لَا يُعْطِيهِ غَيْرُكَ، عَزَّ جَارُكَ، وَجَلَّ ثَنَاؤُكَ، وَلَا إِلٰهَ إِلَّا أَنْتَ، اجْعَلْنِي فِي عِيَاذِكَ وَجِوَارِكَ مِنْ سُوءٍ، وَمِنَ الشَّيْطَانِ الرَّجِيمِ.","tr":"Allāhu akbar, Allāhu akbar, Allāhu akbar. Bismi llāhi ʿalā nafsī wa dīnī, bismi llāhi ʿalā ahlī wa mālī, bismi llāhi ʿalā kulli shayʾin aʿṭānī rabbī, bismi llāhi khayri l-asmāʾ, bismi llāhi rabbi l-arḍi was-samāʾ, bismi llāhi lladhī lā yaḍurru maʿa smihī dāʾ, bismi llāhi ftataḥtu, wa ʿala llāhi tawakkalt, Allāhu Allāhu rabbī lā ushriku bihī aḥadā, asʾaluka llāhumma bi-khayrika min khayrika lladhī lā yuʿṭīhi ghayruk, ʿazza jāruk, wa jalla thanāʾuk, wa lā ilāha illā ant, ijʿalnī fī ʿiyādhika wa jiwārika min sūʾ, wa mina sh-shayṭāni r-rajīm.","en":"Allah is the Greatest (three times). In the name of Allah upon my self and my religion; upon my family and my wealth; upon everything my Lord has given me. In the name of Allah, the best of names; in the name of Allah, Lord of the earth and the sky; in the name of Allah, with whose name no illness can harm. In the name of Allah I begin, and in Allah I put my trust. Allah, Allah is my Lord; I associate no one with Him. I ask You, O Allah, by Your goodness, for that goodness of Yours which no one but You can give. Mighty is the one You protect, and exalted is Your praise; there is no god but You. Keep me in Your refuge and protection from evil, and from Satan the accursed.","ref":null,"q":null,"source":"Ibn Saʿd, *al-Ṭabaqāt*, and Ibn al-Sunnī, *ʿAmal al-Yawm wa al-Layla*, from Anas; also al-Ḥākim, *al-Mustadrak*.","page":null,"status":"draft"},
{"n":48,"ar":"اللّٰهُمَّ إِنِّي أَسْتَجِيرُكَ مِنْ جَمِيعِ كُلِّ شَيْءٍ خَلَقْتَ، وَأَحْتَرِسُ بِكَ مِنْهُنَّ، وَأُقَدِّمُ بَيْنَ يَدَيَّ: بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيمِ، قُلْ هُوَ اللّٰهُ أَحَدٌ ۝ اللّٰهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ ۝ مِنْ أَمَامِي، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي، وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَمِنْ تَحْتِي.","tr":"Allāhumma innī astajīruka min jamīʿi kulli shayʾin khalaqt, wa aḥtarisu bika minhunn, wa uqaddimu bayna yadayy: bismi llāhi r-raḥmāni r-raḥīm, qul huwa llāhu aḥad, Allāhu ṣ-ṣamad, lam yalid wa lam yūlad, wa lam yakun lahū kufuwan aḥad, min amāmī, wa min khalfī, wa ʿan yamīnī, wa ʿan shimālī, wa min fawqī, wa min taḥtī.","en":"O Allah, I seek Your protection from every single thing You have created, and I guard myself through You against them. I place before me: In the name of Allah, the Beneficent, the Merciful. *[112:1–4, Qurʾān translation from Pickthall:]* \"Say: He is Allah, the One! Allah, the eternally Besought of all! He begetteth not nor was begotten. And there is none comparable unto Him.\" [I place this] in front of me, behind me, on my right, on my left, above me and below me.","ref":"Sūrat al-Ikhlāṣ 112:1–4, quoted in full.","q":null,"source":"the same report as 47 (Anas). Nomani's note says the Ikhlāṣ is recited within it.","page":null,"status":"draft"},
{"n":49,"ar":"خَلَقْتَ رَبَّنَا فَسَوَّيْتَ، وَقَدَّرْتَ رَبَّنَا فَقَضَيْتَ، وَعَلَى عَرْشِكَ اسْتَوَيْتَ، وَأَمَتَّ فَأَحْيَيْتَ، وَأَطْعَمْتَ فَأَشْبَعْتَ، وَأَسْقَيْتَ فَأَرْوَيْتَ، وَحَمَلْتَ فِي بَرِّكَ وَبَحْرِكَ عَلَى فُلْكِكَ وَعَلَى دَوَابِّكَ وَعَلَى أَنْعَامِكَ، فَاجْعَلْ لِي عِنْدَكَ وَلِيجَةً، وَاجْعَلْ لِي عِنْدَكَ زُلْفَى وَحُسْنَ مَآبٍ، وَاجْعَلْنِي مِمَّنْ يَخَافُ مَقَامَكَ وَوَعِيدَكَ، وَيَرْجُو لِقَاءَكَ، وَاجْعَلْنِي مِمَّنْ يَتُوبُ إِلَيْكَ تَوْبَةً نَصُوحًا، وَأَسْأَلُكَ عَمَلًا مُتَقَبَّلًا، وَعِلْمًا نَجِيحًا، وَسَعْيًا مَشْكُورًا، وَتِجَارَةً لَنْ تَبُورَ.","tr":"Khalaqta rabbanā fa-sawwayt, wa qaddarta rabbanā fa-qaḍayt, wa ʿalā ʿarshika stawayt, wa amatta fa-aḥyayt, wa aṭʿamta fa-ashbaʿt, wa asqayta fa-arwayt, wa ḥamalta fī barrika wa baḥrika ʿalā fulkika wa ʿalā dawābbika wa ʿalā anʿāmik, fajʿal lī ʿindaka walījah, wajʿal lī ʿindaka zulfā wa ḥusna maʾāb, wajʿalnī mimman yakhāfu maqāmaka wa waʿīdak, wa yarjū liqāʾak, wajʿalnī mimman yatūbu ilayka tawbatan naṣūḥā, wa asʾaluka ʿamalan mutaqabbalā, wa ʿilman najīḥā, wa saʿyan mashkūrā, wa tijāratan lan tabūr.","en":"You created, our Lord, and gave due proportion. You decreed, our Lord, and carried it out. You established Yourself upon Your Throne. You gave death and gave life, You fed and satisfied, You gave drink and quenched, and You carried us over Your land and Your sea on Your ships, Your mounts and Your cattle. So grant me close intimacy with You, nearness to You and a good place of return. Make me one of those who fear standing before You and fear Your warning, and who hope to meet You. Make me one of those who turn to You in sincere repentance. I ask You for accepted deeds, successful knowledge, effort that is rewarded, and a trade that will never fail.","ref":null,"q":null,"source":"al-Daylamī, from Abū Hurayra.","page":null,"status":"draft"},
{"n":50,"ar":"اللّٰهُمَّ إِنِّي أُشْهِدُكَ بِمَا شَهِدْتَ بِهِ عَلَى نَفْسِكَ، وَشَهِدَتْ بِهِ مَلَائِكَتُكَ وَأَنْبِيَاؤُكَ وَأُولُو الْعِلْمِ، وَمَنْ لَمْ يَشْهَدْ بِمَا شَهِدْتَ بِهِ فَاكْتُبْ شَهَادَتِي مَكَانَ شَهَادَتِهِ، أَنْتَ السَّلَامُ وَمِنْكَ السَّلَامُ، تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ.","tr":"Allāhumma innī ushhiduka bimā shahidta bihī ʿalā nafsik, wa shahidat bihī malāʾikatuka wa anbiyāʾuka wa ulu l-ʿilm, wa man lam yashhad bimā shahidta bihī faktub shahādatī makāna shahādatih, anta s-Salāmu wa minka s-salām, tabārakta yā Dha l-Jalāli wal-Ikrām.","en":"O Allah, I call You to witness that I bear witness to what You have testified about Yourself, and what Your angels, Your prophets and the people of knowledge have testified. Whoever does not bear witness to what You have testified, write my testimony in place of his. You are Peace, and from You comes peace. Blessed are You, O Lord of Majesty and Honour.","ref":null,"q":null,"source":"Ibn Turkān (?), *Kitāb al-Duʿāʾ*, and al-Daylamī, from Anas.","page":null,"status":"draft"},
{"n":51,"ar":"اللّٰهُمَّ إِنِّي أَسْأَلُكَ فَكَاكَ رَقَبَتِي مِنَ النَّارِ.","tr":"Allāhumma innī asʾaluka fakāka raqabatī mina n-nār.","en":"O Allah, I ask You to free my neck from the Fire.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":52,"ar":"اللّٰهُمَّ أَعِنِّي عَلَى غَمَرَاتِ الْمَوْتِ وَسَكَرَاتِ الْمَوْتِ.","tr":"Allāhumma aʿinnī ʿalā ghamarāti l-mawti wa sakarāti l-mawt.","en":"O Allah, help me through the agonies of death and the pangs of death.","ref":null,"q":null,"source":"al-Tirmidhī, Ibn Mājah and al-Ḥākim, from ʿĀʾisha.","page":null,"status":"draft"},
{"n":53,"ar":"اللّٰهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَأَلْحِقْنِي بِالرَّفِيقِ الْأَعْلَى.","tr":"Allāhumma ghfir lī warḥamnī wa alḥiqnī bir-rafīqi l-aʿlā.","en":"O Allah, forgive me, have mercy on me, and join me to the Highest Companion.","ref":null,"q":null,"source":"al-Bukhārī, Muslim, al-Tirmidhī.","page":null,"status":"draft"},
{"n":54,"ar":"سُبْحَانَ رَبِّكَ رَبِّ الْعِزَّةِ عَمَّا يَصِفُونَ ۝ وَسَلَامٌ عَلَى الْمُرْسَلِينَ ۝ وَالْحَمْدُ لِلّٰهِ رَبِّ الْعٰلَمِينَ ۝","tr":"Subḥāna rabbika rabbi l-ʿizzati ʿammā yaṣifūn, wa salāmun ʿala l-mursalīn, wal-ḥamdu lillāhi rabbi l-ʿālamīn.","en":"Qurʾān translation from Pickthall: \"Glorified be thy Lord, the Lord of Majesty, from that which they attribute (unto Him). And peace be unto those sent (to warn). And praise be to Allah, Lord of the Worlds!\"","ref":"al-Ṣāffāt 37:180–182 (the same extent in Nomani and Dawud).","q":null,"source":"al-Ṭabarānī, from Ibn ʿAbbās, among other reports he cites.","page":null,"status":"draft"}]},{"manzil":7,"day":"Friday","dayAr":"يوم الجمعة","duas":[{"n":1,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ وَّعَلٰى اٰلِ سَيِّدِنَا مُحَمَّدٍ كَمَا صَلَّيْتَ عَلٰى إِبْرَاهِيْمَ وَعَلٰى اٰلِ إِبْرَاهِيْمَ إِنَّكَ حَمِيْدٌ مَّجِيْدٌ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadin wa ʿalā āli sayyidinā Muḥammad, kamā ṣallayta ʿalā Ibrāhīma wa ʿalā āli Ibrāhīm, innaka Ḥamīdun Majīd.","en":"O Allah, send blessings on our master Muhammad and on the family of our master Muhammad, as You sent blessings on Ibrahim and on the family of Ibrahim. You are the Praiseworthy, the Glorious.","ref":null,"q":null,"source":"al-Sakhawi, *al-Qawl al-Badiʿ*.","page":null,"status":"draft"},
{"n":2,"ar":"اَللّٰهُمَّ بَارِكْ عَلٰى سَيِّدِنَا مُحَمَّدٍ وَّعَلٰى اٰلِ سَيِّدِنَا مُحَمَّدٍ كَمَا بَارَكْتَ عَلٰى إِبْرَاهِيْمَ وَعَلٰى اٰلِ إِبْرَاهِيْمَ إِنَّكَ حَمِيْدٌ مَّجِيْدٌ. وَفِيْ بَعْضِ الرِّوَايَاتِ: اَللّٰهُمَّ وَتَرَحَّمْ عَلٰى سَيِّدِنَا مُحَمَّدٍ وَّعَلٰى اٰلِ سَيِّدِنَا مُحَمَّدٍ كَمَا تَرَحَّمْتَ عَلٰى إِبْرَاهِيْمَ وَعَلٰى اٰلِ إِبْرَاهِيْمَ إِنَّكَ حَمِيْدٌ مَّجِيْدٌ.","tr":"Allāhumma bārik ʿalā sayyidinā Muḥammadin wa ʿalā āli sayyidinā Muḥammad, kamā bārakta ʿalā Ibrāhīma wa ʿalā āli Ibrāhīm, innaka Ḥamīdun Majīd. (Wa fī baʿḍi r-riwāyāt:) Allāhumma wa taraḥḥam ʿalā sayyidinā Muḥammadin wa ʿalā āli sayyidinā Muḥammad, kamā taraḥḥamta ʿalā Ibrāhīma wa ʿalā āli Ibrāhīm, innaka Ḥamīdun Majīd.","en":"O Allah, bless our master Muhammad and the family of our master Muhammad, as You blessed Ibrahim and the family of Ibrahim. You are the Praiseworthy, the Glorious. (In some narrations:) O Allah, and have mercy on our master Muhammad and the family of our master Muhammad, as You had mercy on Ibrahim and the family of Ibrahim. You are the Praiseworthy, the Glorious.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":3,"ar":"اَللّٰهُمَّ وَتَحَنَّنْ عَلٰى سَيِّدِنَا مُحَمَّدٍ وَّعَلٰى اٰلِ سَيِّدِنَا مُحَمَّدٍ كَمَا تَحَنَّنْتَ عَلٰى إِبْرَاهِيْمَ وَعَلٰى اٰلِ إِبْرَاهِيْمَ إِنَّكَ حَمِيْدٌ مَّجِيْدٌ.","tr":"Allāhumma wa taḥannan ʿalā sayyidinā Muḥammadin wa ʿalā āli sayyidinā Muḥammad, kamā taḥannanta ʿalā Ibrāhīma wa ʿalā āli Ibrāhīm, innaka Ḥamīdun Majīd.","en":"O Allah, show tender affection to our master Muhammad and the family of our master Muhammad, as You showed tender affection to Ibrahim and the family of Ibrahim. You are the Praiseworthy, the Glorious.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":4,"ar":"اَللّٰهُمَّ وَسَلِّمْ عَلٰى سَيِّدِنَا مُحَمَّدٍ وَّعَلٰى اٰلِ سَيِّدِنَا مُحَمَّدٍ كَمَا سَلَّمْتَ عَلٰى إِبْرَاهِيْمَ وَعَلٰى اٰلِ إِبْرَاهِيْمَ إِنَّكَ حَمِيْدٌ مَّجِيْدٌ.","tr":"Allāhumma wa sallim ʿalā sayyidinā Muḥammadin wa ʿalā āli sayyidinā Muḥammad, kamā sallamta ʿalā Ibrāhīma wa ʿalā āli Ibrāhīm, innaka Ḥamīdun Majīd.","en":"O Allah, and send peace on our master Muhammad and the family of our master Muhammad, as You sent peace on Ibrahim and the family of Ibrahim. You are the Praiseworthy, the Glorious.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":5,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدِ النَّبِيِّ الْأُمِّيِّ وَأَزْوَاجِهٖ أُمَّهَاتِ الْمُؤْمِنِيْنَ وَذُرِّيَّتِهٖ وَأَهْلِ بَيْتِهٖ كَمَا صَلَّيْتَ عَلٰى إِبْرَاهِيْمَ وَعَلٰى اٰلِ إِبْرَاهِيْمَ، وَبَارِكْ عَلٰى سَيِّدِنَا مُحَمَّدِ النَّبِيِّ الْأُمِّيِّ وَعَلٰى اٰلِ سَيِّدِنَا مُحَمَّدٍ وَّأَزْوَاجِهٖ وَأَهْلِ بَيْتِهٖ وَذُرِّيَّتِهٖ كَمَا بَارَكْتَ عَلٰى إِبْرَاهِيْمَ وَعَلٰى اٰلِ إِبْرَاهِيْمَ فِي الْعٰلَمِيْنَ إِنَّكَ حَمِيْدٌ مَّجِيْدٌ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadini n-nabiyyi l-ummiyyi wa azwājihī ummahāti l-muʾminīna wa dhurriyyatihī wa ahli baytihī, kamā ṣallayta ʿalā Ibrāhīma wa ʿalā āli Ibrāhīm; wa bārik ʿalā sayyidinā Muḥammadini n-nabiyyi l-ummiyyi wa ʿalā āli sayyidinā Muḥammadin wa azwājihī wa ahli baytihī wa dhurriyyatihī, kamā bārakta ʿalā Ibrāhīma wa ʿalā āli Ibrāhīma fi l-ʿālamīn, innaka Ḥamīdun Majīd.","en":"O Allah, send blessings on our master Muhammad, the unlettered Prophet, and on his wives, the Mothers of the Believers, his descendants and his household, as You sent blessings on Ibrahim and the family of Ibrahim. And bless our master Muhammad, the unlettered Prophet, and the family of our master Muhammad, his wives, his household and his descendants, as You blessed Ibrahim and the family of Ibrahim among all the worlds. You are the Praiseworthy, the Glorious.","ref":null,"q":null,"source":"Abu Dawud, *Sunan* (via *al-Qawl al-Badiʿ*).","page":null,"status":"draft"},
{"n":6,"ar":"اَللّٰهُمَّ أَنْزِلْهُ الْمَقْعَدَ الْمُقَرَّبَ عِنْدَكَ يَوْمَ الْقِيَامَةِ.","tr":"Allāhumma anzilhu l-maqʿada l-muqarraba ʿindaka yawma l-qiyāmah.","en":"O Allah, give him the seat of nearness with You on the Day of Resurrection.","ref":null,"q":null,"source":"al-Qawl al-Badiʿ* (Ahmad, al-Bazzar, al-Tabarani and others), from Ruwayfiʿ b. Thabit.","page":null,"status":"draft"},
{"n":7,"ar":"اَللّٰهُمَّ اجْعَلْ صَلَوَاتِكَ وَبَرَكَاتِكَ وَرَحْمَتَكَ عَلٰى سَيِّدِ الْمُرْسَلِيْنَ وَإِمَامِ الْمُتَّقِيْنَ وَخَاتَمِ النَّبِيِّيْنَ سَيِّدِنَا مُحَمَّدٍ ﷺ عَبْدِكَ وَرَسُوْلِكَ إِمَامِ الْخَيْرِ وَقَائِدِ الْخَيْرِ وَرَسُوْلِ الرَّحْمَةِ.","tr":"Allāhumma jʿal ṣalawātika wa barakātika wa raḥmataka ʿalā sayyidi l-mursalīna wa imāmi l-muttaqīna wa khātami n-nabiyyīna sayyidinā Muḥammadin ﷺ ʿabdika wa rasūlika, imāmi l-khayri wa qāʾidi l-khayri wa rasūli r-raḥmah.","en":"O Allah, place Your blessings, Your grace and Your mercy on the master of the messengers, the leader of the God-fearing and the Seal of the Prophets, our master Muhammad ﷺ, Your servant and Messenger: leader in good, guide to good, and Messenger of mercy.","ref":null,"q":null,"source":"al-Sakhawi, *al-Qawl al-Badiʿ*.","page":null,"status":"draft"},
{"n":8,"ar":"اَللّٰهُمَّ ابْعَثْهُ مَقَامًا مَّحْمُوْدًا يَّغْبِطُهٗ بِهِ الْأَوَّلُوْنَ وَالْاٰخِرُوْنَ.","tr":"Allāhumma bʿath-hu maqāman maḥmūdan yaghbiṭuhū bihi l-awwalūna wa l-ākhirūn.","en":"O Allah, raise him to a praised station for which the first and the last will hold him in holy envy.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":9,"ar":"اَللّٰهُمَّ اجْعَلْ صَلَوَاتِكَ وَبَرَكَاتِكَ وَرَحْمَتَكَ عَلٰى سَيِّدِنَا مُحَمَّدٍ وَّعَلٰى اٰلِ سَيِّدِنَا مُحَمَّدٍ ﷺ كَمَا جَعَلْتَهَا عَلٰى إِبْرَاهِيْمَ وَعَلٰى اٰلِ إِبْرَاهِيْمَ إِنَّكَ حَمِيْدٌ مَّجِيْدٌ.","tr":"Allāhumma jʿal ṣalawātika wa barakātika wa raḥmataka ʿalā sayyidinā Muḥammadin wa ʿalā āli sayyidinā Muḥammadin ﷺ, kamā jaʿaltahā ʿalā Ibrāhīma wa ʿalā āli Ibrāhīm, innaka Ḥamīdun Majīd.","en":"O Allah, place Your blessings, Your grace and Your mercy on our master Muhammad and the family of our master Muhammad ﷺ, as You placed them on Ibrahim and the family of Ibrahim. You are the Praiseworthy, the Glorious.","ref":null,"q":null,"source":"al-Qawl al-Badiʿ* (Abu al-ʿAbbas al-Sarraj, Ahmad b. Manīʿ, Ahmad, ʿAbd b. Humayd and others), from Burayda.","page":null,"status":"draft"},
{"n":10,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ وَّأَبْلِغْهُ الْوَسِيْلَةَ وَالدَّرَجَةَ الرَّفِيْعَةَ مِنَ الْجَنَّةِ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadin ﷺ wa ablighhu l-wasīlata wa d-darajata r-rafīʿata mina l-jannah.","en":"O Allah, send blessings on our master Muhammad ﷺ, and bring him to the Wasila and the lofty rank in Paradise.","ref":null,"q":null,"source":"al-Qawl al-Badiʿ* (Ibn Abi ʿAsim), from Ibn Masʿud.","page":null,"status":"draft"},
{"n":11,"ar":"اَللّٰهُمَّ اجْعَلْ فِي الْمُصْطَفَيْنَ مَحَبَّتَهٗ، وَفِي الْمُقَرَّبِيْنَ مَوَدَّتَهٗ، وَفِي الْأَعْلَيْنَ ذِكْرَهٗ، وَالسَّلَامُ عَلَيْهِ وَرَحْمَةُ اللّٰهِ وَبَرَكَاتُهٗ.","tr":"Allāhumma jʿal fi l-muṣṭafayna maḥabbatahū, wa fi l-muqarrabīna mawaddatahū, wa fi l-aʿlayna dhikrahū, wa s-salāmu ʿalayhi wa raḥmatu llāhi wa barakātuh.","en":"O Allah, place love for him among the chosen ones, affection for him among those brought near, and his remembrance among the most exalted. Peace be on him, and the mercy of Allah and His blessings.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":12,"ar":"اَللّٰهُمَّ دَاحِيَ الْمَدْحُوَّاتِ، وَبَارِئَ الْمَسْمُوْكَاتِ، وَجَبَّارَ الْقُلُوْبِ عَلٰى فِطْرَتِهَا شَقِيِّهَا وَسَعِيْدِهَا، اجْعَلْ شَرَائِفَ صَلَوَاتِكَ، وَنَوَامِيَ بَرَكَاتِكَ، وَرَأْفَةَ تَحَنُّنِكَ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ عَبْدِكَ وَرَسُوْلِكَ، الْخَاتِمِ لِمَا سَبَقَ، وَالْفَاتِحِ لِمَا أُغْلِقَ، وَالْمُعْلِنِ الْحَقَّ بِالْحَقِّ، وَالدَّامِغِ لِجَيْشَاتِ الْأَبَاطِيْلِ، كَمَا حُمِّلَ فَاضْطَلَعَ بِأَمْرِكَ لِطَاعَتِكَ، مُسْتَوْفِزًا فِيْ مَرْضَاتِكَ، بِغَيْرِ نُكْلٍ عَنْ قُدُمٍ، وَّلَا وَهْنٍ فِيْ عَزْمٍ، وَّاعِيًا لِّوَحْيِكَ، حَافِظًا لِّعَهْدِكَ، مَاضِيًا عَلٰى نَفَاذِ أَمْرِكَ، حَتّٰى أَوْرٰى قَبَسًا لِّقَابِسٍ، (اٰلَاءُ اللّٰهِ تَصِلُ بِأَهْلِهٖ أَسْبَابَهٗ)، بِهٖ هُدِيَتِ الْقُلُوْبُ بَعْدَ خَوْضَاتِ الْفِتَنِ وَالْإِثْمِ، وَأَبْهَجَ مُوْضِحَاتِ الْأَعْلَامِ، وَمُنِيْرَاتِ الْإِسْلَامِ، وَنَائِرَاتِ الْأَحْكَامِ، فَهُوَ أَمِيْنُكَ الْمَأْمُوْنُ، وَخَازِنُ عِلْمِكَ الْمَخْزُوْنِ، وَشَهِيْدُكَ يَوْمَ الدِّيْنِ، وَبَعِيْثُكَ نِعْمَةً، وَّرَسُوْلُكَ بِالْحَقِّ رَحْمَةً.","tr":"Allāhumma dāḥiya l-madḥuwwāti, wa bāriʾa l-masmūkāti, wa jabbāra l-qulūbi ʿalā fiṭratihā shaqiyyihā wa saʿīdihā, ijʿal sharāʾifa ṣalawātika, wa nawāmiya barakātika, wa raʾfata taḥannunika ʿalā sayyidinā Muḥammadin ﷺ ʿabdika wa rasūlika, al-khātimi limā sabaqa, wa l-fātiḥi limā ughliqa, wa l-muʿlini l-ḥaqqa bi l-ḥaqqi, wa d-dāmighi li jayshāti l-abāṭīl, kamā ḥummila fa-ḍṭalaʿa bi amrika li ṭāʿatika, mustawfizan fī marḍātika, bi ghayri nukl(in) ʿan qudum(in), wa lā wahnin fī ʿazm, wāʿiyan li waḥyika, ḥāfiẓan li ʿahdika, māḍiyan ʿalā nafādhi amrika, ḥattā awrā qabasan li qābis, (ālāʾu llāhi taṣilu bi ahlihī asbābahū), bihī hudiyati l-qulūbu baʿda khawḍāti l-fitani wa l-ithm, wa abhaja mūḍiḥāti l-aʿlāmi, wa munīrāti l-islāmi, wa nāʾirāti l-aḥkām; fa huwa amīnuka l-maʾmūn, wa khāzinu ʿilmika l-makhzūn, wa shahīduka yawma d-dīn, wa baʿīthuka niʿmatan, wa rasūluka bi l-ḥaqqi raḥmah.","en":"O Allah, Spreader of the spread-out earths, Maker of the raised-up heavens, who set hearts upon their nature, the wretched and the blessed alike: place the noblest of Your blessings, the ever-growing of Your graces and the gentleness of Your tender affection on our master Muhammad ﷺ, Your servant and Messenger. He sealed what came before and opened what had been locked. He proclaimed the truth by the truth and crushed the surging armies of falsehood. As he was charged, so he took up Your command in obedience to You, eager to please You, never shrinking from going forward and never weak in resolve. He kept Your revelation in mind, guarded Your covenant and pressed on to carry out Your command, until he kindled a flame for whoever sought light (Allah's favours join His people to their means). Through him hearts were guided after plunging into trials and sin, and he made bright the clear signposts, the lights of Islam and the shining rulings. So he is Your trusted one, the keeper of Your hidden knowledge, Your witness on the Day of Judgement, the one You sent as a favour, and Your Messenger with the truth as a mercy.","ref":null,"q":null,"source":"al-Qawl al-Badiʿ* (al-Tabarani, Ibn Abi ʿAsim, Saʿid b. Mansur, al-Tabari and others), from ʿAli.","page":null,"status":"draft"},
{"n":13,"ar":"اَللّٰهُمَّ افْسَحْ لَهٗ مَفْسَحًا فِيْ عَدْنِكَ، وَاجْزِهٖ مُضَاعَفَاتِ الْخَيْرِ مِنْ فَضْلِكَ، مُهَنَّآتٍ لَّهٗ غَيْرَ مُكَدَّرَاتٍ، مِّنْ وُّفُوْرِ ثَوَابِكَ الْمَضْنُوْنِ، وَجَزِيْلِ عَطَائِكَ الْمَخْزُوْنِ.","tr":"Allāhumma fsaḥ lahū mafsaḥan fī ʿadnika, wa jzihī muḍāʿafāti l-khayri min faḍlika, muhannaʾātin lahū ghayra mukaddarāt, min wufūri thawābika l-maḍnūni, wa jazīli ʿaṭāʾika l-makhzūn.","en":"O Allah, make wide room for him in Your Eden, and reward him from Your bounty with good multiplied many times over, pleasant to him and unclouded, from the abundance of Your treasured reward and the fullness of Your stored-up gifts.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":14,"ar":"اَللّٰهُمَّ أَعْلِ عَلٰى بِنَاءِ الْبَانِيْنَ بِنَاءَهٗ، وَأَكْرِمْ مَثْوَاهُ لَدَيْكَ وَنُزُلَهٗ، وَأَتْمِمْ لَهٗ نُوْرَهٗ، وَاجْزِهٖ مِنِ انْبِعَاثِكَ لَهٗ مَقْبُوْلَ الشَّهَادَةِ، وَمَرْضِيَّ الْمَقَالَةِ، ذَا مَنْطِقٍ عَدْلٍ، وَّخُطَّةٍ فَصْلٍ، وَّحُجَّةٍ وَّبُرْهَانٍ عَظِيْمٍ.","tr":"Allāhumma aʿli ʿalā bināʾi l-bānīna bināʾahū, wa akrim mathwāhu ladayka wa nuzulahū, wa atmim lahū nūrahū, wa jzihī mini nbiʿāthika lahū maqbūla sh-shahādati, wa marḍiyya l-maqālati, dhā manṭiqin ʿadl, wa khuṭṭatin faṣl, wa ḥujjatin wa burhānin ʿaẓīm.","en":"O Allah, raise his building above the building of all who build. Honour his abode and his welcome with You, and complete his light for him. For Your sending him, reward him by making his testimony accepted and his word pleasing, a man of just speech and decisive judgement, with a mighty proof and evidence.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":15,"ar":"اَللّٰهُمَّ اجْعَلْنَا سَامِعِيْنَ مُطِيْعِيْنَ، وَأَوْلِيَاءَ مُخْلِصِيْنَ، وَرُفَقَاءَ مُصَاحِبِيْنَ.","tr":"Allāhumma jʿalnā sāmiʿīna muṭīʿīn, wa awliyāʾa mukhliṣīn, wa rufaqāʾa muṣāḥibīn.","en":"O Allah, make us those who hear and obey, sincere friends, and companions who keep him company.","ref":null,"q":null,"source":"al-Qawl al-Badiʿ* (Ibn ʿAbd al-Barr).","page":null,"status":"draft"},
{"n":16,"ar":"اَللّٰهُمَّ أَبْلِغْهُ مِنَّا السَّلَامَ، وَارْدُدْ عَلَيْنَا مِنْهُ السَّلَامَ.","tr":"Allāhumma ablighhu minna s-salām, wa rdud ʿalaynā minhu s-salām.","en":"O Allah, convey our greeting of peace to him, and return to us his greeting of peace.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":17,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدِ النَّبِيِّ عَدَدَ مَنْ صَلّٰى عَلَيْهِ مِنْ خَلْقِكَ، وَصَلِّ عَلٰى سَيِّدِنَا مُحَمَّدِ النَّبِيِّ ﷺ كَمَا يَنْبَغِيْ لَنَا أَنْ نُّصَلِّيَ عَلَيْهِ، وَصَلِّ عَلٰى سَيِّدِنَا مُحَمَّدِ النَّبِيِّ ﷺ كَمَا أَمَرْتَنَا أَنْ نُّصَلِّيَ عَلَيْهِ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadini n-nabiyyi ʿadada man ṣallā ʿalayhi min khalqik, wa ṣalli ʿalā sayyidinā Muḥammadini n-nabiyyi ﷺ kamā yanbaghī lanā an nuṣalliya ʿalayh, wa ṣalli ʿalā sayyidinā Muḥammadini n-nabiyyi ﷺ kamā amartanā an nuṣalliya ʿalayh.","en":"O Allah, send blessings on our master Muhammad the Prophet as many times as there are those of Your creation who have sent blessings on him. Send blessings on our master Muhammad the Prophet ﷺ in the way it befits us to send blessings on him, and send blessings on our master Muhammad the Prophet ﷺ in the way You commanded us to send blessings on him.","ref":null,"q":null,"source":"al-Bayhaqi, from al-Shafiʿi (similar wording).","page":null,"status":"draft"},
{"n":18,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ حَتّٰى لَا يَبْقٰى مِنْ صَلَوَاتِكَ شَيْءٌ، وَّبَارِكْ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ حَتّٰى لَا يَبْقٰى مِنْ بَرَكَاتِكَ شَيْءٌ، وَّسَلِّمْ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ حَتّٰى لَا يَبْقٰى مِنَ السَّلَامِ شَيْءٌ، وَّارْحَمْ سَيِّدَنَا مُحَمَّدًا ﷺ حَتّٰى لَا يَبْقٰى مِنْ رَّحْمَتِكَ شَيْءٌ. جَزَى اللّٰهُ عَنَّا سَيِّدَنَا مُحَمَّدًا ﷺ بِمَا هُوَ أَهْلُهٗ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadin ﷺ ḥattā lā yabqā min ṣalawātika shayʾ, wa bārik ʿalā sayyidinā Muḥammadin ﷺ ḥattā lā yabqā min barakātika shayʾ, wa sallim ʿalā sayyidinā Muḥammadin ﷺ ḥattā lā yabqā mina s-salāmi shayʾ, wa rḥam sayyidanā Muḥammadan ﷺ ḥattā lā yabqā min raḥmatika shayʾ. Jazā llāhu ʿannā sayyidanā Muḥammadan ﷺ bimā huwa ahluh.","en":"O Allah, send blessings on our master Muhammad ﷺ until none of Your blessings remain. Bless our master Muhammad ﷺ until none of Your grace remains. Send peace on our master Muhammad ﷺ until no peace remains. Have mercy on our master Muhammad ﷺ until none of Your mercy remains. May Allah reward our master Muhammad ﷺ on our behalf as he deserves.","ref":null,"q":null,"source":"al-Suyuti, *Jamʿ al-Jawamiʿ*: al-Tabarani, *Kitab al-Duʿa*, and al-Daylami. For «جزى الله عنا…»: *al-Qawl al-Badiʿ* (al-Tabarani), from Ibn ʿAbbas.","page":null,"status":"draft"},
{"n":19,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى رُوْحِ سَيِّدِنَا مُحَمَّدٍ ﷺ فِي الْأَرْوَاحِ، وَصَلِّ عَلٰى جَسَدِ سَيِّدِنَا مُحَمَّدٍ فِي الْأَجْسَادِ، وَصَلِّ عَلٰى قَبْرِ سَيِّدِنَا مُحَمَّدٍ ﷺ فِي الْقُبُوْرِ.\n﴿إِنَّ اللّٰهَ وَمَلٰٓئِكَتَهٗ يُصَلُّوْنَ عَلَى النَّبِيِّ ۚ يٰٓأَيُّهَا الَّذِيْنَ اٰمَنُوْا صَلُّوْا عَلَيْهِ وَسَلِّمُوْا تَسْلِيْمًا﴾","tr":"Allāhumma ṣalli ʿalā rūḥi sayyidinā Muḥammadin ﷺ fi l-arwāḥ, wa ṣalli ʿalā jasadi sayyidinā Muḥammadin fi l-ajsād, wa ṣalli ʿalā qabri sayyidinā Muḥammadin ﷺ fi l-qubūr. — Inna llāha wa malāʾikatahū yuṣallūna ʿala n-nabiyy; yā ayyuha lladhīna āmanū ṣallū ʿalayhi wa sallimū taslīmā.","en":"O Allah, send blessings on the soul of our master Muhammad ﷺ among the souls, on the body of our master Muhammad among the bodies, and on the grave of our master Muhammad ﷺ among the graves. — For the verse, use the Qurʾān translation from Pickthall.","ref":"the verse is al-Ahzab 33:56, quoted in full. Nomani places it after this du'a, before number 20, and Dawud places it the same way.","q":null,"source":"al-Qawl al-Badiʿ*.","page":null,"status":"draft"},
{"n":20,"ar":"لَبَّيْكَ اللّٰهُمَّ رَبِّيْ وَسَعْدَيْكَ، صَلَوَاتُ اللّٰهِ الْبَرِّ الرَّحِيْمِ، وَالْمَلٰٓئِكَةِ الْمُقَرَّبِيْنَ، وَالنَّبِيِّيْنَ وَالصِّدِّيْقِيْنَ وَالشُّهَدَاءِ وَالصّٰلِحِيْنَ، وَمَا سَبَّحَ لَكَ مِنْ شَيْءٍ يَّا رَبَّ الْعٰلَمِيْنَ، عَلٰى سَيِّدِنَا مُحَمَّدِ بْنِ عَبْدِ اللّٰهِ خَاتَمِ النَّبِيِّيْنَ، وَسَيِّدِ الْمُرْسَلِيْنَ، وَإِمَامِ الْمُتَّقِيْنَ، وَرَسُوْلِ رَبِّ الْعٰلَمِيْنَ، الشَّاهِدِ الْبَشِيْرِ، الدَّاعِيْٓ إِلَيْكَ بِإِذْنِكَ السِّرَاجِ الْمُنِيْرِ، وَعَلَيْهِ السَّلَامُ.","tr":"Labbayka llāhumma rabbī wa saʿdayk. Ṣalawātu llāhi l-barri r-raḥīm, wa l-malāʾikati l-muqarrabīn, wa n-nabiyyīna wa ṣ-ṣiddīqīna wa sh-shuhadāʾi wa ṣ-ṣāliḥīn, wa mā sabbaḥa laka min shayʾin yā rabba l-ʿālamīn, ʿalā sayyidinā Muḥammadi bni ʿAbdi llāh, khātami n-nabiyyīn, wa sayyidi l-mursalīn, wa imāmi l-muttaqīn, wa rasūli rabbi l-ʿālamīn, ash-shāhidi l-bashīr, ad-dāʿī ilayka bi idhnika s-sirāji l-munīr, wa ʿalayhi s-salām.","en":"Here I am, O Allah my Lord, at Your service. May the blessings of Allah, the Good, the Merciful, and of the angels brought near, the prophets, the truthful, the martyrs and the righteous, and of everything that glorifies You, O Lord of the worlds, be upon our master Muhammad son of ʿAbd Allah: Seal of the Prophets, master of the messengers, leader of the God-fearing, Messenger of the Lord of the worlds, the witness, the bearer of good news, the one who calls to You by Your leave, the light-giving lamp. And upon him be peace.","ref":null,"q":null,"source":"al-Qawl al-Badiʿ*; al-Qadi ʿIyad, *al-Shifaʾ*, from ʿAli.","page":null,"status":"draft"},
{"n":21,"ar":"اَللّٰهُمَّ تَقَبَّلْ شَفَاعَةَ سَيِّدِنَا مُحَمَّدِ الْكُبْرٰى، وَارْفَعْ دَرَجَتَهُ الْعُلْيَا، وَأَعْطِهٖ سُؤْلَهٗ فِي الْاٰخِرَةِ وَالْأُوْلٰى، كَمَآ اٰتَيْتَ إِبْرَاهِيْمَ وَمُوْسٰى.","tr":"Allāhumma taqabbal shafāʿata sayyidinā Muḥammadini l-kubrā, wa rfaʿ darajatahu l-ʿulyā, wa aʿṭihī suʾlahū fi l-ākhirati wa l-ūlā, kamā ātayta Ibrāhīma wa Mūsā.","en":"O Allah, accept the great intercession of our master Muhammad, raise his rank to the highest, and give him what he asks in the Hereafter and in this world, as You gave to Ibrahim and Musa.","ref":null,"q":null,"source":"al-Qawl al-Badiʿ* (ʿAbd b. Humayd, ʿAbd al-Razzaq, Ismaʿil al-Qadi), from Ibn ʿAbbas.","page":null,"status":"draft"},
{"n":22,"ar":"اَللّٰهُمَّ اجْعَلْ سَيِّدَنَا مُحَمَّدًا ﷺ مِنْ أَكْرَمِ عِبَادِكَ عَلَيْكَ كَرَامَةً، وَّمِنْ أَرْفَعِهِمْ عِنْدَكَ دَرَجَةً، وَّمِنْ أَعْظَمِهِمْ عِنْدَكَ خَطَرًا، وَّمِنْ أَمْكَنِهِمْ عِنْدَكَ شَفَاعَةً.","tr":"Allāhumma jʿal sayyidanā Muḥammadan ﷺ min akrami ʿibādika ʿalayka karāmah, wa min arfaʿihim ʿindaka darajah, wa min aʿẓamihim ʿindaka khaṭarā, wa min amkanihim ʿindaka shafāʿah.","en":"O Allah, make our master Muhammad ﷺ among the most honoured of Your servants with You, the highest of them in rank with You, the greatest of them in standing with You, and the most firmly heard of them in intercession with You.","ref":null,"q":null,"source":"al-Qawl al-Badiʿ* (al-Numayri), from al-Hasan al-Basri.","page":null,"status":"draft"},
{"n":23,"ar":"اَللّٰهُمَّ أَتْبِعْهُ مِنْ أُمَّتِهٖ وَذُرِّيَّتِهٖ مَا تَقَرُّ بِهٖ عَيْنُهٗ، وَاجْزِهٖ عَنَّا خَيْرَ مَا جَزَيْتَ نَبِيًّا عَنْ أُمَّتِهٖ، وَاجْزِ الْأَنْبِيَاءَ كُلَّهُمْ خَيْرًا، وَّسَلَامٌ عَلَى الْمُرْسَلِيْنَ، وَالْحَمْدُ لِلّٰهِ رَبِّ الْعٰلَمِيْنَ.","tr":"Allāhumma atbiʿhu min ummatihī wa dhurriyyatihī mā taqarru bihī ʿaynuh, wa jzihī ʿannā khayra mā jazayta nabiyyan ʿan ummatih, wa jzi l-anbiyāʾa kullahum khayrā, wa salāmun ʿala l-mursalīn, wa l-ḥamdu lillāhi rabbi l-ʿālamīn.","en":"O Allah, let follow him, from his community and his descendants, those who will be the delight of his eyes. Reward him on our behalf with the best reward You have given any prophet on behalf of his community, and reward all the prophets well. Peace be on the messengers, and praise be to Allah, Lord of the worlds.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":24,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ وَعَلٰى اٰلِ سَيِّدِنَا مُحَمَّدٍ ﷺ وَّأَصْحَابِهٖ وَأَوْلَادِهٖ وَأَهْلِ بَيْتِهٖ وَذُرِّيَّتِهٖ وَمُحِبِّيْهِ وَأَتْبَاعِهٖ وَأَشْيَاعِهٖ، وَعَلَيْنَا مَعَهُمْ أَجْمَعِيْنَ يَآ أَرْحَمَ الرّٰحِمِيْنَ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadin ﷺ wa ʿalā āli sayyidinā Muḥammadin ﷺ wa aṣḥābihī wa awlādihī wa ahli baytihī wa dhurriyyatihī wa muḥibbīhi wa atbāʿihī wa ashyāʿih, wa ʿalaynā maʿahum ajmaʿīn, yā arḥama r-rāḥimīn.","en":"O Allah, send blessings on our master Muhammad ﷺ and on the family of our master Muhammad ﷺ, his Companions, his children, his household, his descendants, those who love him, his followers and his partisans, and on us along with all of them, O Most Merciful of the merciful.","ref":null,"q":null,"source":"al-Qawl al-Badiʿ* (al-Numayri), from al-Hasan al-Basri.","page":null,"status":"draft"},
{"n":25,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ مِلْءَ الدُّنْيَا وَمِلْءَ الْاٰخِرَةِ، وَبَارِكْ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ مِلْءَ الدُّنْيَا وَمِلْءَ الْاٰخِرَةِ، وَارْحَمْ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ مِلْءَ الدُّنْيَا وَمِلْءَ الْاٰخِرَةِ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadin ﷺ milʾa d-dunyā wa milʾa l-ākhirah, wa bārik ʿalā sayyidinā Muḥammadin ﷺ milʾa d-dunyā wa milʾa l-ākhirah, wa rḥam ʿalā sayyidinā Muḥammadin ﷺ milʾa d-dunyā wa milʾa l-ākhirah.","en":"O Allah, send blessings on our master Muhammad ﷺ enough to fill this world and the Hereafter. Bless our master Muhammad ﷺ enough to fill this world and the Hereafter. Have mercy on our master Muhammad ﷺ enough to fill this world and the Hereafter.","ref":null,"q":null,"source":"al-Qawl al-Badiʿ* (al-Numayri, Ibn Bashkuwal), from Abu al-Hasan al-Karkhi. Nomani's note says that a final clause, «وسلّم على محمد ملء الدنيا وملء الآخرة», is in the source but missing from the Hizb.","page":null,"status":"draft"},
{"n":26,"ar":"اَللّٰهُمَّ إِنِّيْٓ أَسْأَلُكَ يَآ اَللّٰهُ يَا رَحْمٰنُ يَا رَحِيْمُ، يَا جَارَ الْمُسْتَجِيْرِيْنَ، يَآ أَمَانَ الْخَآئِفِيْنَ، يَا عِمَادَ مَنْ لَّا عِمَادَ لَهٗ، يَا سَنَدَ مَنْ لَّا سَنَدَ لَهٗ، يَا ذُخْرَ مَنْ لَّا ذُخْرَ لَهٗ، يَا حِرْزَ الضُّعَفَاءِ، يَا كَنْزَ الْفُقَرَاءِ، يَا عَظِيْمَ الرَّجَاءِ، يَا مُنْقِذَ الْهَلْكٰى، يَا مُنْجِيَ الْغَرْقٰى، يَا مُحْسِنُ يَا مُجْمِلُ، يَا مُنْعِمُ يَا مُفْضِلُ، يَا جَبَّارُ يَا مُنِيْرُ، أَنْتَ الَّذِيْ سَجَدَ لَكَ سَوَادُ اللَّيْلِ، وَضَوْءُ النَّهَارِ، وَشُعَاعُ الشَّمْسِ، وَنُوْرُ الْقَمَرِ، وَخَفِيْقُ الشَّجَرِ، وَدَوِيُّ الْمَاءِ، يَآ اَللّٰهُ أَنْتَ اللّٰهُ لَا شَرِيْكَ لَكَ، أَسْأَلُكَ أَنْ تُصَلِّيَ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ عَبْدِكَ وَرَسُوْلِكَ وَعَلٰى اٰلِ سَيِّدِنَا مُحَمَّدٍ ﷺ.","tr":"Allāhumma innī asʾaluka yā Allāhu yā Raḥmānu yā Raḥīm, yā jāra l-mustajīrīn, yā amāna l-khāʾifīn, yā ʿimāda man lā ʿimāda lah, yā sanada man lā sanada lah, yā dhukhra man lā dhukhra lah, yā ḥirza ḍ-ḍuʿafāʾ, yā kanza l-fuqarāʾ, yā ʿaẓīma r-rajāʾ, yā munqidha l-halkā, yā munjiya l-gharqā, yā Muḥsinu yā Mujmil, yā Munʿimu yā Mufḍil, yā Jabbāru yā Munīr, anta lladhī sajada laka sawādu l-layli, wa ḍawʾu n-nahāri, wa shuʿāʿu sh-shamsi, wa nūru l-qamari, wa khafīqu sh-shajari, wa dawiyyu l-māʾ; yā Allāhu anta llāhu lā sharīka lak, asʾaluka an tuṣalliya ʿalā sayyidinā Muḥammadin ﷺ ʿabdika wa rasūlika wa ʿalā āli sayyidinā Muḥammadin ﷺ.","en":"O Allah, I ask You, O Allah, O Most Gracious, O Most Merciful: Protector of those who seek protection, Safety of the fearful, Support of those who have no support, Mainstay of those who have no mainstay, Treasure of those who have no treasure, Guard of the weak, Wealth of the poor, Great Hope, Rescuer of the perishing, Saviour of the drowning, O Doer of good, O Giver of beauty, O Bestower of favour, O Giver of bounty, O Compeller, O Giver of light. You are the One to whom the blackness of night, the brightness of day, the rays of the sun, the light of the moon, the rustling of the trees and the roar of the water have prostrated. O Allah, You are Allah, You have no partner. I ask You to send blessings on our master Muhammad ﷺ, Your servant and Messenger, and on the family of our master Muhammad ﷺ.","ref":null,"q":null,"source":"al-Qawl al-Badiʿ* (al-Daylami, *Musnad al-Firdaws*), from Ibn ʿAbbas.","page":null,"status":"draft"},
{"n":27,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ وَّعَلٰى اٰلِ سَيِّدِنَا مُحَمَّدٍ ﷺ فِي الْأَوَّلِيْنَ وَالْاٰخِرِيْنَ، وَفِي الْمَلَإِ الْأَعْلٰى إِلٰى يَوْمِ الدِّيْنِ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadin ﷺ wa ʿalā āli sayyidinā Muḥammadin ﷺ fi l-awwalīna wa l-ākhirīn, wa fi l-malaʾi l-aʿlā ilā yawmi d-dīn.","en":"O Allah, send blessings on our master Muhammad ﷺ and the family of our master Muhammad ﷺ among the first and the last, and in the highest assembly, until the Day of Judgement.","ref":null,"q":null,"source":"al-Qawl al-Badiʿ* (Abu al-Faraj).","page":null,"status":"draft"},
{"n":28,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ وَّعَلٰى اٰلِ سَيِّدِنَا مُحَمَّدٍ ﷺ كَمَا تُحِبُّ وَتَرْضٰى لَهٗ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadin ﷺ wa ʿalā āli sayyidinā Muḥammadin ﷺ kamā tuḥibbu wa tarḍā lah.","en":"O Allah, send blessings on our master Muhammad ﷺ and the family of our master Muhammad ﷺ as You love and are pleased with for him.","ref":null,"q":null,"source":"al-Qawl al-Badiʿ*, citing al-Qadi ʿIyad, *al-Shifaʾ*.","page":null,"status":"draft"},
{"n":29,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ وَعَلٰى اٰلِ سَيِّدِنَا مُحَمَّدٍ ﷺ صَلٰوةً تَكُوْنُ لَكَ رِضًا، وَّلِحَقِّهٖ أَدَاءً، وَّأَعْطِهِ الْوَسِيْلَةَ وَالْمَقَامَ الْمَحْمُوْدَ الَّذِيْ وَعَدْتَّهٗ، وَاجْزِهٖ عَنَّا مَا هُوَ أَهْلُهٗ، وَاجْزِهٖ عَنَّا أَفْضَلَ مَا جَزَيْتَ نَبِيًّا عَنْ أُمَّتِهٖ، وَصَلِّ عَلٰى جَمِيْعِ إِخْوَانِهٖ مِنَ النَّبِيِّيْنَ وَالصّٰلِحِيْنَ يَآ أَرْحَمَ الرّٰحِمِيْنَ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadin ﷺ wa ʿalā āli sayyidinā Muḥammadin ﷺ ṣalātan takūnu laka riḍā, wa li ḥaqqihī adāʾā, wa aʿṭihi l-wasīlata wa l-maqāma l-maḥmūda lladhī waʿadtah, wa jzihī ʿannā mā huwa ahluh, wa jzihī ʿannā afḍala mā jazayta nabiyyan ʿan ummatih, wa ṣalli ʿalā jamīʿi ikhwānihī mina n-nabiyyīna wa ṣ-ṣāliḥīn, yā arḥama r-rāḥimīn.","en":"O Allah, send blessings on our master Muhammad ﷺ and the family of our master Muhammad ﷺ, a blessing that pleases You and fulfils his due. Give him the Wasila and the praised station You promised him. Reward him on our behalf as he deserves, and reward him on our behalf with the best reward You have given any prophet on behalf of his community. And send blessings on all his brothers among the prophets and the righteous, O Most Merciful of the merciful.","ref":null,"q":null,"source":"al-Qawl al-Badiʿ* (Ibn Abi ʿAsim).","page":null,"status":"draft"},
{"n":30,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ فِي الْأَوَّلِيْنَ، وَصَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ فِي الْاٰخِرِيْنَ، وَصَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ فِي النَّبِيِّيْنَ، وَصَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ فِي الْمُرْسَلِيْنَ، وَصَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ فِي الْمَلَإِ الْأَعْلٰى إِلٰى يَوْمِ الدِّيْنِ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadin ﷺ fi l-awwalīn, wa ṣalli ʿalā sayyidinā Muḥammadin ﷺ fi l-ākhirīn, wa ṣalli ʿalā sayyidinā Muḥammadin ﷺ fi n-nabiyyīn, wa ṣalli ʿalā sayyidinā Muḥammadin fi l-mursalīn, wa ṣalli ʿalā sayyidinā Muḥammadin fi l-malaʾi l-aʿlā ilā yawmi d-dīn.","en":"O Allah, send blessings on our master Muhammad ﷺ among the first, among the last, among the prophets, among the messengers, and in the highest assembly, until the Day of Judgement.","ref":null,"q":null,"source":"al-Qawl al-Badiʿ*, reported from Zayn al-ʿAbidin ʿAli b. al-Husayn.","page":null,"status":"draft"},
{"n":31,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ حَتّٰى تَرْضٰى، وَصَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ بَعْدَ الرِّضٰى، وَصَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ أَبَدًا أَبَدًا.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadin ﷺ ḥattā tarḍā, wa ṣalli ʿalā sayyidinā Muḥammadin ﷺ baʿda r-riḍā, wa ṣalli ʿalā sayyidinā Muḥammadin ﷺ abadan abadā.","en":"O Allah, send blessings on our master Muhammad ﷺ until You are pleased, send blessings on him after You are pleased, and send blessings on him for ever and ever.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":32,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ كَمَآ أَمَرْتَ بِالصَّلٰوةِ عَلَيْهِ، وَصَلِّ عَلٰى مُحَمَّدٍ ﷺ كَمَا تُحِبُّ أَنْ يُّصَلّٰى عَلَيْهِ، وَصَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ كَمَآ أَرَدْتَّ أَنْ يُّصَلّٰى عَلَيْهِ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadin ﷺ kamā amarta bi ṣ-ṣalāti ʿalayh, wa ṣalli ʿalā Muḥammadin ﷺ kamā tuḥibbu an yuṣallā ʿalayh, wa ṣalli ʿalā sayyidinā Muḥammadin kamā aradta an yuṣallā ʿalayh.","en":"O Allah, send blessings on our master Muhammad ﷺ as You commanded blessings to be sent on him. Send blessings on Muhammad ﷺ as You love blessings to be sent on him, and send blessings on our master Muhammad as You willed blessings to be sent on him.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":33,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ عَدَدَ خَلْقِكَ، وَصَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ رِضَاءَ نَفْسِكَ، وَصَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ زِنَةَ عَرْشِكَ، وَصَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ مِدَادَ كَلِمَاتِكَ الَّتِيْ لَا تَنْفَدُ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadin ﷺ ʿadada khalqik, wa ṣalli ʿalā sayyidinā Muḥammadin ﷺ riḍāʾa nafsik, wa ṣalli ʿalā sayyidinā Muḥammadin ﷺ zinata ʿarshik, wa ṣalli ʿalā sayyidinā Muḥammadin ﷺ midāda kalimātika llatī lā tanfad.","en":"O Allah, send blessings on our master Muhammad ﷺ as many times as the number of Your creation, as much as pleases You, as much as the weight of Your Throne, and as much as the ink of Your words, which never run out.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":34,"ar":"اَللّٰهُمَّ وَأَعْطِ سَيِّدَنَا مُحَمَّدًا ﷺ الْوَسِيْلَةَ (وَالْفَضْلَ) وَالْفَضِيْلَةَ وَالدَّرَجَةَ الرَّفِيْعَةَ.","tr":"Allāhumma wa aʿṭi sayyidanā Muḥammadan ﷺ al-wasīlata (wa l-faḍla) wa l-faḍīlata wa d-darajata r-rafīʿah.","en":"O Allah, and give our master Muhammad ﷺ the Wasila, (the bounty,) the special excellence and the lofty rank.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":35,"ar":"اَللّٰهُمَّ عَظِّمْ بُرْهَانَهٗ، وَأَفْلِجْ حُجَّتَهٗ، وَأَبْلِغْهُ مَأْمُوْلَهٗ فِيْ أَهْلِ بَيْتِهٖ وَأُمَّتِهٖ.","tr":"Allāhumma ʿaẓẓim burhānah, wa aflij ḥujjatah, wa ablighhu maʾmūlahū fī ahli baytihī wa ummatih.","en":"O Allah, make his proof great, make his argument prevail, and grant him what he hopes for in his household and his community.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":36,"ar":"اَللّٰهُمَّ اجْعَلْ صَلَوَاتِكَ وَبَرَكَاتِكَ وَرَأْفَتَكَ وَرَحْمَتَكَ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ حَبِيْبِكَ وَصَفِيِّكَ، وَعَلٰىٓ أَهْلِ بَيْتِهِ الطَّيِّبِيْنَ الطَّاهِرِيْنَ.","tr":"Allāhumma jʿal ṣalawātika wa barakātika wa raʾfataka wa raḥmataka ʿalā sayyidinā Muḥammadin ﷺ ḥabībika wa ṣafiyyik, wa ʿalā ahli baytihi ṭ-ṭayyibīna ṭ-ṭāhirīn.","en":"O Allah, place Your blessings, Your grace, Your gentleness and Your mercy on our master Muhammad ﷺ, Your beloved and Your chosen one, and on his good and pure household.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":37,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ بِأَفْضَلِ مَا صَلَّيْتَ عَلٰىٓ أَحَدٍ مِّنْ خَلْقِكَ، وَبَارِكْ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ مِثْلَ ذٰلِكَ، وَارْحَمْ سَيِّدَنَا مُحَمَّدًا ﷺ مِثْلَ ذٰلِكَ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadin ﷺ bi afḍali mā ṣallayta ʿalā aḥadin min khalqik, wa bārik ʿalā sayyidinā Muḥammadin ﷺ mithla dhālik, wa rḥam sayyidanā Muḥammadan ﷺ mithla dhālik.","en":"O Allah, send blessings on our master Muhammad ﷺ with the best blessing You have sent on anyone of Your creation. Bless our master Muhammad ﷺ in the same way, and have mercy on our master Muhammad ﷺ in the same way.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":38,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ فِي اللَّيْلِ إِذَا يَغْشٰى، وَصَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ فِي النَّهَارِ إِذَا تَجَلّٰى، وَصَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ فِي الْاٰخِرَةِ وَالْأُوْلٰى.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadin ﷺ fi l-layli idhā yaghshā, wa ṣalli ʿalā sayyidinā Muḥammadin ﷺ fi n-nahāri idhā tajallā, wa ṣalli ʿalā sayyidinā Muḥammadin ﷺ fi l-ākhirati wa l-ūlā.","en":"O Allah, send blessings on our master Muhammad ﷺ in the night when it covers, in the day when it shines forth, and in the Hereafter and in this world.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":39,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدِ الصَّلٰوةَ التَّآمَّةَ، وَبَارِكْ عَلٰى سَيِّدِنَا مُحَمَّدِ الْبَرَكَةَ التَّآمَّةَ، وَسَلِّمْ عَلٰى سَيِّدِنَا مُحَمَّدِ السَّلَامَ التَّآمَّ. اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ إِمَامِ الْخَيْرِ وَقَائِدِ الْخَيْرِ وَرَسُوْلِ الرَّحْمَةِ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadini ṣ-ṣalāta t-tāmmah, wa bārik ʿalā sayyidinā Muḥammadini l-barakata t-tāmmah, wa sallim ʿalā sayyidinā Muḥammadini s-salāma t-tāmm. Allāhumma ṣalli ʿalā sayyidinā Muḥammadin ﷺ imāmi l-khayri wa qāʾidi l-khayri wa rasūli r-raḥmah.","en":"O Allah, send on our master Muhammad the complete blessing, bless him with the complete grace, and send on him the complete peace. O Allah, send blessings on our master Muhammad ﷺ, leader in good, guide to good, and Messenger of mercy.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":40,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ أَبَدَ الْاٰبِدِيْنَ، وَصَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ دَهْرَ الدَّاهِرِيْنَ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadin ﷺ abada l-ābidīn, wa ṣalli ʿalā sayyidinā Muḥammadin dahra d-dāhirīn.","en":"O Allah, send blessings on our master Muhammad ﷺ for all eternity, and send blessings on our master Muhammad for all the ages.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":41,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدِ النَّبِيِّ الْأُمِّيِّ الْقُرَشِيِّ الْهَاشِمِيِّ الْأَبْطَحِيِّ التِّهَامِيِّ الْمَكِّيِّ، صَاحِبِ التَّاجِ وَالْهِرَاوَةِ وَالْجِهَادِ (وَالْكَرَامَةِ) وَالْمَغْنَمِ (وَالْمَقْسَمِ)، صَاحِبِ الْخَيْرِ وَالْمَيْرِ، صَاحِبِ السَّرَايَا وَالْعَطَايَا، وَالْاٰيَاتِ الْمُعْجِزَاتِ، وَالْعَلَامَاتِ الْبَاهِرَاتِ، وَالْمَقَامِ الْمَشْهُوْدِ، وَالْحَوْضِ الْمَوْرُوْدِ، وَالشَّفَاعَةِ، وَالسُّجُوْدِ لِلرَّبِّ الْمَحْمُوْدِ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadini n-nabiyyi l-ummiyyi l-qurashiyyi l-hāshimiyyi l-abṭaḥiyyi t-tihāmiyyi l-makkiyy, ṣāḥibi t-tāji wa l-hirāwati wa l-jihādi (wa l-karāmati) wa l-maghnami (wa l-maqsam), ṣāḥibi l-khayri wa l-mayr, ṣāḥibi s-sarāyā wa l-ʿaṭāyā, wa l-āyāti l-muʿjizāt, wa l-ʿalāmāti l-bāhirāt, wa l-maqāmi l-mashhūd, wa l-ḥawḍi l-mawrūd, wa sh-shafāʿati, wa s-sujūdi li r-rabbi l-maḥmūd.","en":"O Allah, send blessings on our master Muhammad, the unlettered Prophet, of Quraysh and of Hashim, of the Batha, of Tihama, of Makka. He is the man of the crown, the staff and the striving, (of honour,) of the spoils (and their division). He is the man of goodness and provision, of the expeditions and the gifts, of the miraculous signs and the dazzling tokens, of the witnessed station, the Pool to which all come, the intercession, and prostration to the Lord who is praised.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":42,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ بِعَدَدِ مَنْ صَلّٰى عَلَيْهِ، وَصَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ بِعَدَدِ مَنْ لَّمْ يُصَلِّ عَلَيْهِ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadin ﷺ bi ʿadadi man ṣallā ʿalayh, wa ṣalli ʿalā sayyidinā Muḥammadin ﷺ bi ʿadadi man lam yuṣalli ʿalayh.","en":"O Allah, send blessings on our master Muhammad ﷺ as many times as the number of those who have sent blessings on him, and as many times as the number of those who have not.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":43,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدِ الَّذِيْٓ أَشْرَقَتْ بِنُوْرِهِ الظُّلَمُ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadini lladhī ashraqat bi nūrihi ẓ-ẓulam.","en":"O Allah, send blessings on our master Muhammad, by whose light the darknesses were lit up.","ref":null,"q":null,"source":"al-Qawl al-Badiʿ*, citing al-Fakihani. This footnote seems to cover the whole series 43–52.","page":null,"status":"draft"},
{"n":44,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدِ الْمَبْعُوْثِ رَحْمَةً لِّكُلِّ الْأُمَمِ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadini l-mabʿūthi raḥmatan li kulli l-umam.","en":"O Allah, send blessings on our master Muhammad, sent as a mercy to all nations.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":45,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدِ الْمُخْتَارِ لِلسِّيَادَةِ وَالرِّسَالَةِ قَبْلَ خَلْقِ اللَّوْحِ وَالْقَلَمِ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadini l-mukhtāri li s-siyādati wa r-risālati qabla khalqi l-lawḥi wa l-qalam.","en":"O Allah, send blessings on our master Muhammad, chosen for leadership and messengership before the Tablet and the Pen were created.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":46,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدِ الْمَوْصُوْفِ بِأَفْضَلِ الْأَخْلَاقِ وَالشِّيَمِ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadini l-mawṣūfi bi afḍali l-akhlāqi wa sh-shiyam.","en":"O Allah, send blessings on our master Muhammad, described by the finest character and qualities.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":47,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ الْمَخْصُوْصِ بِجَوَامِعِ الْكَلِمِ وَخَوَاصِّ الْحِكَمِ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadin ﷺ al-makhṣūṣi bi jawāmiʿi l-kalimi wa khawāṣṣi l-ḥikam.","en":"O Allah, send blessings on our master Muhammad ﷺ, singled out for words of comprehensive meaning and choice wisdom.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":48,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدِ الَّذِيْ كَانَ لَا تُنْتَهَكُ فِيْ مَجَالِسِهِ الْحُرَمُ، وَلَا يُغْضِيْ عَنْ مَّنْ ظَلَمَ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadini lladhī kāna lā tuntahaku fī majālisihi l-ḥuram, wa lā yughḍī ʿan man ẓalam.","en":"O Allah, send blessings on our master Muhammad, in whose gatherings nothing sacred was violated, and who did not look away from anyone who did wrong.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":49,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدِ الَّذِيْ كَانَ إِذَا مَشٰى تُظِلُّهُ الْغَمَامَةُ حَيْثُ مَا يَمَّمَ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadini lladhī kāna idhā mashā tuẓilluhu l-ghamāmatu ḥaythu mā yammam.","en":"O Allah, send blessings on our master Muhammad, who was shaded by a cloud wherever he walked, in whatever direction he went.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":50,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدِ الَّذِي انْشَقَّ لَهُ الْقَمَرُ، وَكَلَّمَهُ الْحَجَرُ، وَأَقَرَّ بِرِسَالَتِهٖ وَصَمَّمَ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadini lladhi nshaqqa lahu l-qamar, wa kallamahu l-ḥajar, wa aqarra bi risālatihī wa ṣammam.","en":"O Allah, send blessings on our master Muhammad, for whom the moon was split, to whom the stone spoke, affirming his messengership and holding firm to it.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":51,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدِ الَّذِيْٓ أَثْنٰى عَلَيْهِ رَبُّ الْعِزَّةِ رِضًا فِيْ سَالِفِ الْقِدَمِ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadini lladhī athnā ʿalayhi rabbu l-ʿizzati riḍan fī sālifi l-qidam.","en":"O Allah, send blessings on our master Muhammad, whom the Lord of Might praised with good pleasure in the bygone ages of eternity.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":52,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدِ الَّذِيْ صَلّٰى عَلَيْهِ رَبُّنَا فِيْ مُحْكَمِ كِتَابِهٖ، وَأَمَرَ أَنْ يُّصَلّٰى عَلَيْهِ وَيُسَلَّمَ، صَلَّى اللّٰهُ عَلَيْهِ وَعَلٰىٓ اٰلِهٖ وَأَصْحَابِهٖ وَأَزْوَاجِهٖ مَا انْهَلَّتِ الدِّيَمُ، وَمَا جُرَّتْ عَلَى الْمُذْنِبِيْنَ أَذْيَالُ الْكَرَمِ، وَسَلَّمَ تَسْلِيْمًا وَّشَرَّفَ وَكَرَّمَ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadini lladhī ṣallā ʿalayhi rabbunā fī muḥkami kitābih, wa amara an yuṣallā ʿalayhi wa yusallam; ṣalla llāhu ʿalayhi wa ʿalā ālihī wa aṣḥābihī wa azwājihī ma nhallati d-diyam, wa mā jurrat ʿala l-mudhnibīna adhyālu l-karam, wa sallama taslīman wa sharrafa wa karram.","en":"O Allah, send blessings on our master Muhammad, on whom our Lord sent blessings in His clear Book, and whom He commanded to be blessed and greeted with peace. May Allah bless him, his family, his Companions and his wives for as long as the steady rains pour down and the trains of generosity are drawn over sinners. May He send him abundant peace, and ennoble and honour him.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":53,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدِ السَّابِقِ لِلْخَلْقِ نُوْرُهٗ، وَالرَّحْمَةِ لِلْعٰلَمِيْنَ ظُهُوْرُهٗ، عَدَدَ مَنْ مَّضٰى مِنْ خَلْقِكَ وَمَنْ بَقِيَ، وَمَنْ سَعِدَ مِنْهُمْ وَمَنْ شَقِيَ، صَلٰوةً تَسْتَغْرِقُ الْعَدَّ وَتُحِيْطُ بِالْحَدِّ، صَلٰوةً لَّا غَايَةَ لَهَا وَلَا انْتِهَاءَ، وَلَآ أَمَدَ لَهَا وَلَا انْقِضَاءَ، صَلٰوةً دَآئِمَةً بِدَوَامِكَ، وَعَلٰىٓ اٰلِهٖ وَأَصْحَابِهٖ كَذٰلِكَ، وَالْحَمْدُ لِلّٰهِ عَلٰى ذٰلِكَ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadini s-sābiqi li l-khalqi nūruh, wa r-raḥmati li l-ʿālamīna ẓuhūruh, ʿadada man maḍā min khalqika wa man baqiy, wa man saʿida minhum wa man shaqiy, ṣalātan tastaghriqu l-ʿadda wa tuḥīṭu bi l-ḥadd, ṣalātan lā ghāyata lahā wa la ntihāʾ, wa lā amada lahā wa la nqiḍāʾ, ṣalātan dāʾimatan bi dawāmik, wa ʿalā ālihī wa aṣḥābihī kadhālik, wa l-ḥamdu lillāhi ʿalā dhālik.","en":"O Allah, send blessings on our master Muhammad, whose light came before creation and whose appearing was a mercy to the worlds. Send them as many times as there are of Your creation who have passed and who remain, the blessed among them and the wretched: a blessing that exhausts all counting and encompasses every limit, a blessing without end or term, without limit or expiry, a blessing lasting as long as You last. And the same on his family and Companions. Praise be to Allah for that.","ref":null,"q":null,"source":"al-Qawl al-Badiʿ*.","page":null,"status":"draft"},
{"n":54,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ عَبْدِكَ وَرَسُوْلِكَ، وَصَلِّ عَلَى الْمُؤْمِنِيْنَ وَالْمُؤْمِنَاتِ وَالْمُسْلِمِيْنَ وَالْمُسْلِمَاتِ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadin ﷺ ʿabdika wa rasūlik, wa ṣalli ʿala l-muʾminīna wa l-muʾmināti wa l-muslimīna wa l-muslimāt.","en":"O Allah, send blessings on our master Muhammad ﷺ, Your servant and Messenger, and send blessings on the believing men and women and the Muslim men and women.","ref":null,"q":null,"source":"al-Qawl al-Badiʿ* (Ibn Wahb, Ibn Bashkuwal, Ibn Hibban, Abu al-Shaykh, al-Daylami), from Abu Saʿid al-Khudri.","page":null,"status":"draft"},
{"n":55,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ وَّعَلٰى اٰلِ سَيِّدِنَا مُحَمَّدٍ ﷺ، وَهَبْ لَنَا اَللّٰهُمَّ وَارْزُقْنَا مِنْ رِّزْقِكَ الْحَلَالِ الطَّيِّبِ الْمُبَارَكِ مَا تَصُوْنُ بِهٖ وُجُوْهَنَا عَنِ التَّعَرُّضِ إِلٰىٓ أَحَدٍ مِّنْ خَلْقِكَ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadin wa ʿalā āli sayyidinā Muḥammadin ﷺ, wa hab lanā llāhumma wa rzuqnā min rizqika l-ḥalāli ṭ-ṭayyibi l-mubāraki mā taṣūnu bihī wujūhanā ʿani t-taʿarruḍi ilā aḥadin min khalqik.","en":"O Allah, send blessings on our master Muhammad and the family of our master Muhammad ﷺ. Grant us, O Allah, and provide us from Your lawful, good and blessed provision with enough to keep our faces from turning to any of Your creation in need.","ref":null,"q":null,"source":"al-Qawl al-Badiʿ*, a dream account related by al-Qastallani.","page":null,"status":"draft"},
{"n":56,"ar":"اَللّٰهُمَّ اجْعَلْ لَّنَآ إِلَيْكَ طَرِيْقًا سَهْلًا مِّنْ غَيْرِ تَعَبٍ وَّلَا نَصَبٍ وَّلَا مِنَّةٍ وَّلَا تَبِعَةٍ، وَّجَنِّبْنَا اللّٰهُمَّ الْحَرَامَ حَيْثُ كَانَ وَأَيْنَ كَانَ وَعِنْدَ مَنْ كَانَ، وَحُلْ بَيْنَنَا وَبَيْنَ أَهْلِهٖ، وَاقْبِضْ عَنَّآ أَيْدِيَهُمْ، وَاصْرِفْ عَنَّا قُلُوْبَهُمْ، حَتّٰى لَا نَتَقَلَّبَ إِلَّا فِيْمَا يُرْضِيْكَ، وَلَا نَسْتَعِيْنَ بِنِعْمَتِكَ إِلَّا عَلٰى مَا تُحِبُّ يَآ أَرْحَمَ الرّٰحِمِيْنَ.","tr":"Allāhumma jʿal lanā ilayka ṭarīqan sahlan min ghayri taʿabin wa lā naṣabin wa lā minnatin wa lā tabiʿah, wa jannibna llāhumma l-ḥarāma ḥaythu kāna wa ayna kāna wa ʿinda man kān, wa ḥul baynanā wa bayna ahlih, wa qbiḍ ʿannā aydiyahum, wa ṣrif ʿannā qulūbahum, ḥattā lā nataqallaba illā fīmā yurḍīk, wa lā nastaʿīna bi niʿmatika illā ʿalā mā tuḥibbu, yā arḥama r-rāḥimīn.","en":"O Allah, make for us an easy road to You, free of weariness and toil, of obligation to anyone, and of any lasting liability. Keep us away, O Allah, from what is unlawful, wherever it is, in whatever place, and in whoever's hands. Stand between us and those who deal in it, hold back their hands from us and turn their hearts away from us, so that we move only in what pleases You and use Your blessings only for what You love, O Most Merciful of the merciful.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":57,"ar":"اَللّٰهُمَّ إِنِّيْٓ أَسْأَلُكَ بِأَفْضَلِ مَسَآئِلِكَ، وَبِأَحَبِّ أَسْمَآئِكَ إِلَيْكَ وَأَكْرَمِهَا عَلَيْكَ، وَبِمَا مَنَنْتَ بِهٖ عَلَيْنَا بِمُحَمَّدٍ نَّبِيِّنَا ﷺ، وَاسْتَنْقَذْتَنَا بِهٖ مِنَ الضَّلَالَةِ، وَأَمَرْتَنَا بِالصَّلٰوةِ عَلَيْهِ، وَجَعَلْتَ صَلٰوتَنَا عَلَيْهِ دَرَجَةً وَّكَفَّارَةً وَّلُطْفًا وَّمَنًّا مِّنْ إِعْطَآئِكَ، فَأَدْعُوْكَ تَعْظِيْمًا لِّأَمْرِكَ، وَاتِّبَاعًا لِّوَصِيَّتِكَ، وَتَنَجُّزًا لِّمَوْعِدِكَ، بِمَا يَجِبُ لِنَبِيِّنَا ﷺ عَلَيْنَا فِيْٓ أَدَاءِ حَقِّهٖ قِبَلَنَا، وَأَمَرْتَ الْعِبَادَ بِالصَّلٰوةِ عَلَيْهِ فَرِيْضَةً افْتَرَضْتَهَا عَلَيْهِمْ، فَنَسْأَلُكَ بِجَلَالِ وَجْهِكَ وَنُوْرِ عَظَمَتِكَ أَنْ تُصَلِّيَ أَنْتَ وَمَلٰٓئِكَتُكَ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ عَبْدِكَ وَرَسُوْلِكَ وَنَبِيِّكَ وَصَفِيِّكَ أَفْضَلَ مَا صَلَّيْتَ بِهٖ عَلٰىٓ أَحَدٍ مِّنْ خَلْقِكَ إِنَّكَ حَمِيْدٌ مَّجِيْدٌ.","tr":"Allāhumma innī asʾaluka bi afḍali masāʾilik, wa bi aḥabbi asmāʾika ilayka wa akramihā ʿalayk, wa bimā mananta bihī ʿalaynā bi Muḥammadin nabiyyinā ﷺ, wa stanqadhtanā bihī mina ḍ-ḍalālah, wa amartanā bi ṣ-ṣalāti ʿalayh, wa jaʿalta ṣalātanā ʿalayhi darajatan wa kaffāratan wa luṭfan wa mannan min iʿṭāʾik; fa adʿūka taʿẓīman li amrik, wa ttibāʿan li waṣiyyatik, wa tanajjuzan li mawʿidik, bimā yajibu li nabiyyinā ﷺ ʿalaynā fī adāʾi ḥaqqihī qibalanā, wa amarta l-ʿibāda bi ṣ-ṣalāti ʿalayhi farīḍatan iftaraḍtahā ʿalayhim; fa nasʾaluka bi jalāli wajhika wa nūri ʿaẓamatika an tuṣalliya anta wa malāʾikatuka ʿalā sayyidinā Muḥammadin ﷺ ʿabdika wa rasūlika wa nabiyyika wa ṣafiyyika afḍala mā ṣallayta bihī ʿalā aḥadin min khalqik, innaka Ḥamīdun Majīd.","en":"O Allah, I ask You by the best of what You are asked by, by the dearest of Your names to You and the most honoured with You, and by the favour You did us through Muhammad, our Prophet ﷺ. Through him You rescued us from misguidance. You commanded us to send blessings on him, and You made our blessings on him a rank, an expiation, a kindness and a gift from Your giving. So I call on You to honour Your command, to follow Your charge and to claim Your promise, for what we owe our Prophet ﷺ in fulfilling his right over us. You commanded Your servants to send blessings on him as an obligation You laid on them. So we ask You, by the majesty of Your Face and the light of Your greatness, that You and Your angels send blessings on our master Muhammad ﷺ, Your servant, Messenger, Prophet and chosen one, with the best blessing You have sent on anyone of Your creation. You are the Praiseworthy, the Glorious.","ref":null,"q":null,"source":"al-Qawl al-Badiʿ*, from ʿAli b. ʿAbd Allah b. ʿAbbas.","page":null,"status":"draft"},
{"n":58,"ar":"اَللّٰهُمَّ ارْفَعْ دَرَجَتَهٗ، وَأَكْرِمْ مَقَامَهٗ، وَثَقِّلْ مِيْزَانَهٗ، وَأَجْزِلْ ثَوَابَهٗ، وَأَفْلِجْ حُجَّتَهٗ، وَأَظْهِرْ مِلَّتَهٗ، وَأَضِئْ نُوْرَهٗ، وَأَدِمْ (كَرَامَتَهٗ) مِنْ ذُرِّيَّتِهٖ وَأَهْلِ بَيْتِهٖ مَا تَقَرُّ بِهٖ عَيْنُهٗ، وَعَظِّمْهُ فِي النَّبِيِّيْنَ الَّذِيْنَ خَلَوْا قَبْلَهٗ.","tr":"Allāhumma rfaʿ darajatah, wa akrim maqāmah, wa thaqqil mīzānah, wa ajzil thawābah, wa aflij ḥujjatah, wa aẓhir millatah, wa aḍiʾ nūrah, wa adim (karāmatahū) min dhurriyyatihī wa ahli baytihī mā taqarru bihī ʿaynuh, wa ʿaẓẓimhu fi n-nabiyyīna lladhīna khalaw qablah.","en":"O Allah, raise his rank, honour his station, make his scale heavy, make his reward abundant, make his argument prevail, make his religion manifest and make his light shine. Keep up (his honour), and from his descendants and household whatever will delight his eyes, and make him great among the prophets who passed before him.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":59,"ar":"اَللّٰهُمَّ اجْعَلْ سَيِّدَنَا مُحَمَّدًا ﷺ أَكْثَرَ النَّبِيِّيْنَ تَبَعًا، وَّأَكْثَرَهُمْ أَزْرًا، وَّأَفْضَلَهُمْ كَرَامَةً وَّنُوْرًا، وَّأَعْلَاهُمْ دَرَجَةً، وَّأَفْسَحَهُمْ فِي الْجَنَّةِ مَنْزِلًا، وَّأَزْيَدَهُمْ ثَوَابًا، وَّأَقْرَبَهُمْ مَجْلِسًا، وَّأَثْبَتَهُمْ مَقَامًا، وَّأَصْوَبَهُمْ كَلَامًا، وَّأَنْجَحَهُمْ مَسْأَلَةً، وَّ(أَوْفَرَهُمْ) لَدَيْكَ نَصِيْبًا، وَّأَقْوَاهُمْ فِيْمَا عِنْدَكَ رَغْبَةً، وَّأَنْزِلْهُ فِيْٓ أَعْلٰى (غُرَفِ) الْفِرْدَوْسِ مِنَ الدَّرَجَاتِ الْعُلٰى.","tr":"Allāhumma jʿal sayyidanā Muḥammadan ﷺ akthara n-nabiyyīna tabaʿā, wa aktharahum azrā, wa afḍalahum karāmatan wa nūrā, wa aʿlāhum darajah, wa afsaḥahum fi l-jannati manzilā, wa azyadahum thawābā, wa aqrabahum majlisā, wa athbatahum maqāmā, wa aṣwabahum kalāmā, wa anjaḥahum masʾalah, wa (awfarahum) ladayka naṣībā, wa aqwāhum fīmā ʿindaka raghbah, wa anzilhu fī aʿlā (ghurafi) l-firdawsi mina d-darajāti l-ʿulā.","en":"O Allah, make our master Muhammad ﷺ the prophet with the most followers and the most support, the most excellent in honour and light, the highest in rank, the most spacious in his dwelling in Paradise, the greatest in reward, the nearest in sitting, the firmest in standing, the most right in speech, the most successful in what he asks, (the richest) in his share with You, and the strongest in longing for what is with You. Give him a home in the highest (chambers) of Firdaws, among the lofty ranks.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":60,"ar":"اَللّٰهُمَّ اجْعَلْ سَيِّدَنَا مُحَمَّدًا ﷺ أَصْدَقَ قَآئِلٍ، وَّأَنْجَحَ سَآئِلٍ، وَّأَوَّلَ شَافِعٍ، وَّأَفْضَلَ مُشَفَّعٍ، وَّشَفِّعْهُ فِيْٓ أُمَّتِهٖ بِشَفَاعَةٍ يَّغْبِطُهٗ بِهَا الْأَوَّلُوْنَ وَالْاٰخِرُوْنَ، وَإِذَا مَيَّزْتَ بَيْنَ عِبَادِكَ بِفَصْلِ الْقَضَآءِ فَاجْعَلْ سَيِّدَنَا مُحَمَّدًا ﷺ فِي الْأَصْدَقِيْنَ قِيْلًا، وَّ(فِي) الْأَحْسَنِيْنَ عَمَلًا، وَّفِي الْمَهْدِيِّيْنَ سَبِيْلًا.","tr":"Allāhumma jʿal sayyidanā Muḥammadan ﷺ aṣdaqa qāʾil, wa anjaḥa sāʾil, wa awwala shāfiʿ, wa afḍala mushaffaʿ, wa shaffiʿhu fī ummatihī bi shafāʿatin yaghbiṭuhū bihā l-awwalūna wa l-ākhirūn; wa idhā mayyazta bayna ʿibādika bi faṣli l-qaḍāʾ, fa jʿal sayyidanā Muḥammadan ﷺ fi l-aṣdaqīna qīlā, wa (fi) l-aḥsanīna ʿamalā, wa fi l-mahdiyyīna sabīlā.","en":"O Allah, make our master Muhammad ﷺ the most truthful of speakers, the most successful of askers, the first to intercede and the best whose intercession is accepted. Accept his intercession for his community, an intercession for which the first and the last will hold him in holy envy. And when You separate Your servants with the final judgement, place our master Muhammad ﷺ among the most truthful in word, (among) the best in deeds, and among the rightly guided in their path.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":61,"ar":"اَللّٰهُمَّ اجْعَلْ نَبِيَّنَا لَنَا فَرَطًا، وَّحَوْضَهٗ لَنَا مَوْرِدًا.","tr":"Allāhumma jʿal nabiyyanā lanā faraṭā, wa ḥawḍahū lanā mawridā.","en":"O Allah, make our Prophet the one who goes ahead of us, and his Pool the place we come to drink.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":62,"ar":"اَللّٰهُمَّ احْشُرْنَا فِيْ زُمْرَتِهٖ، وَاسْتَعْمِلْنَا بِسُنَّتِهٖ، وَتَوَفَّنَا عَلٰى مِلَّتِهٖ، وَاجْعَلْنَا مِنْ حِزْبِهٖ.","tr":"Allāhumma ḥshurnā fī zumratih, wa staʿmilnā bi sunnatih, wa tawaffanā ʿalā millatih, wa jʿalnā min ḥizbih.","en":"O Allah, gather us in his company, make us act by his Sunna, take our souls in his religion, and make us of his party.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":63,"ar":"اَللّٰهُمَّ اجْمَعْ بَيْنَنَا وَبَيْنَهٗ كَمَآ اٰمَنَّا بِهٖ وَلَمْ نَرَهٗ، (اَللّٰهُمَّ) لَا تُفَرِّقْ بَيْنَنَا وَبَيْنَهٗ حَتّٰى تُدْخِلَنَا مُدْخَلَهٗ، وَ(اجْعَلْنَا) مِنْ رُّفَقَآئِهٖ مَعَ النَّبِيِّيْنَ وَالصِّدِّيْقِيْنَ وَالشُّهَدَآءِ وَالصّٰلِحِيْنَ، وَحَسُنَ أُولٰٓئِكَ رَفِيْقًا.","tr":"Allāhumma jmaʿ baynanā wa baynahū kamā āmannā bihī wa lam narah, (Allāhumma) lā tufarriq baynanā wa baynahū ḥattā tudkhilanā mudkhalah, wa (jʿalnā) min rufaqāʾihī maʿa n-nabiyyīna wa ṣ-ṣiddīqīna wa sh-shuhadāʾi wa ṣ-ṣāliḥīn, wa ḥasuna ulāʾika rafīqā.","en":"O Allah, bring us together with him, just as we believed in him without seeing him. (O Allah,) do not separate us from him until You admit us where he is admitted, and (make us) among his companions, with the prophets, the truthful, the martyrs and the righteous. The closing words, «with the prophets… what a fine company they are», follow al-Nisaʾ 4:69: Qurʾān translation from Pickthall.","ref":"the closing clause «مَعَ النَّبِيِّيْنَ … وَحَسُنَ أُولٰٓئِكَ رَفِيْقًا» is al-Nisaʾ 4:69, end of the verse, adapted. The mushaf reads «مِنَ النَّبِيِّينَ وَالصِّدِّيقِينَ…».","q":null,"source":null,"page":null,"status":"draft"},
{"n":64,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ نُوْرِ الْهُدٰى، وَالْقَآئِدِ إِلَى الْخَيْرِ، وَالدَّاعِيْٓ إِلَى الرُّشْدِ، نَبِيِّ الرَّحْمَةِ، (وَكَاشِفِ الْغُمَّةِ)، وَإِمَامِ الْمُتَّقِيْنَ، وَرَسُوْلِ رَبِّ الْعٰلَمِيْنَ، كَمَا بَلَّغَ رِسَالَتَكَ، وَتَلَآ اٰيَاتِكَ، وَنَصَحَ لِعِبَادِكَ، وَأَقَامَ حُدُوْدَكَ، وَوَفٰى بِعُهُوْدِكَ، وَأَنْفَذَ حُكْمَكَ، وَأَمَرَ بِطَاعَتِكَ، وَنَهٰى عَنْ مَّعْصِيَتِكَ، وَوَالٰى وَلِيَّكَ الَّذِيْ تُحِبُّ أَنْ تُوَالِيَهٗ، وَعَادٰى عَدُوَّكَ الَّذِيْ تُحِبُّ أَنْ تُعَادِيَهٗ، وَصَلَّى اللّٰهُ عَلٰى سَيِّدِنَا مُحَمَّدٍ وَّسَلَّمَ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadin ﷺ nūri l-hudā, wa l-qāʾidi ila l-khayr, wa d-dāʿī ila r-rushd, nabiyyi r-raḥmah, (wa kāshifi l-ghummah), wa imāmi l-muttaqīn, wa rasūli rabbi l-ʿālamīn, kamā ballagha risālatak, wa talā āyātik, wa naṣaḥa li ʿibādik, wa aqāma ḥudūdak, wa wafā bi ʿuhūdik, wa anfadha ḥukmak, wa amara bi ṭāʿatik, wa nahā ʿan maʿṣiyatik, wa wālā waliyyaka lladhī tuḥibbu an tuwāliyah, wa ʿādā ʿaduwwaka lladhī tuḥibbu an tuʿādiyah; wa ṣalla llāhu ʿalā sayyidinā Muḥammadin wa sallam.","en":"O Allah, send blessings on our master Muhammad ﷺ, the light of guidance, the leader to good, the caller to right conduct, the Prophet of mercy, (the remover of distress,) the leader of the God-fearing and Messenger of the Lord of the worlds. Send them because he conveyed Your message, recited Your verses, gave sincere counsel to Your servants, upheld Your limits, kept Your covenants, carried out Your judgement, commanded obedience to You and forbade disobedience to You. He befriended Your friend whom You love to befriend, and opposed Your enemy whom You love to oppose. May Allah bless our master Muhammad and grant him peace.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":65,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى جَسَدِهٖ فِي الْأَجْسَادِ، وَعَلٰى رُوْحِهٖ فِي الْأَرْوَاحِ، وَعَلٰى مَوْقِفِهٖ فِي الْمَوَاقِفِ، وَعَلٰى مَشْهَدِهٖ فِي الْمَشَاهِدِ، وَعَلٰى ذِكْرِهٖٓ إِذَا ذُكِرَ، صَلٰوةً مِّنَّا عَلٰى نَبِيِّنَا.","tr":"Allāhumma ṣalli ʿalā jasadihī fi l-ajsād, wa ʿalā rūḥihī fi l-arwāḥ, wa ʿalā mawqifihī fi l-mawāqif, wa ʿalā mashhadihī fi l-mashāhid, wa ʿalā dhikrihī idhā dhukir, ṣalātan minnā ʿalā nabiyyinā.","en":"O Allah, send blessings on his body among the bodies, on his soul among the souls, on his standing among the standings, on his presence among the gatherings, and on his mention whenever he is mentioned: a blessing from us on our Prophet.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":66,"ar":"اَللّٰهُمَّ أَبْلِغْهُ مِنَّا السَّلَامَ كُلَّمَا ذُكِرَ (السَّلَامُ)، وَالسَّلَامُ عَلَى النَّبِيِّ وَرَحْمَةُ اللّٰهِ وَبَرَكَاتُهٗ.","tr":"Allāhumma ablighhu minna s-salāma kullamā dhukira (s-salām), wa s-salāmu ʿala n-nabiyyi wa raḥmatu llāhi wa barakātuh.","en":"O Allah, convey our greeting of peace to him whenever (peace) is mentioned. Peace be on the Prophet, and the mercy of Allah and His blessings.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":67,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى مَلٰٓئِكَتِكَ الْمُقَرَّبِيْنَ، وَعَلٰىٓ أَنْبِيَآئِكَ الْمُطَهَّرِيْنَ، وَعَلٰى رُسُلِكَ الْمُرْسَلِيْنَ، وَعَلٰى حَمَلَةِ عَرْشِكَ أَجْمَعِيْنَ، وَعَلٰى جِبْرَئِيْلَ وَمِيْكَآئِيْلَ وَإِسْرَافِيْلَ وَمَلَكِ الْمَوْتِ وَرِضْوَانَ وَمَالِكٍ، وَصَلِّ عَلَى الْكِرَامِ الْكَاتِبِيْنَ، وَعَلٰىٓ أَهْلِ بَيْتِ نَبِيِّنَا ﷺ أَفْضَلَ مَآ اٰتَيْتَ أَحَدًا مِّنْ أَهْلِ بُيُوْتِ الْمُرْسَلِيْنَ، وَاجْزِ أَصْحَابَ نَبِيِّكَ ﷺ أَفْضَلَ مَا جَزَيْتَ أَحَدًا مِّنْ أَصْحَابِ الْمُرْسَلِيْنَ.","tr":"Allāhumma ṣalli ʿalā malāʾikatika l-muqarrabīn, wa ʿalā anbiyāʾika l-muṭahharīn, wa ʿalā rusulika l-mursalīn, wa ʿalā ḥamalati ʿarshika ajmaʿīn, wa ʿalā Jibraʾīla wa Mīkāʾīla wa Isrāfīla wa malaki l-mawti wa Riḍwāna wa Mālik, wa ṣalli ʿala l-kirāmi l-kātibīn, wa ʿalā ahli bayti nabiyyinā ﷺ afḍala mā ātayta aḥadan min ahli buyūti l-mursalīn, wa jzi aṣḥāba nabiyyika ﷺ afḍala mā jazayta aḥadan min aṣḥābi l-mursalīn.","en":"O Allah, send blessings on Your angels brought near, on Your purified prophets, on Your sent messengers, on all the bearers of Your Throne, and on Jibril, Mikaʾil, Israfil, the Angel of Death, Ridwan and Malik. Send blessings on the noble scribes, and on the household of our Prophet ﷺ, better than anything You have given to any of the households of the messengers. And reward the Companions of Your Prophet ﷺ with the best reward You have given any of the companions of the messengers.","ref":null,"q":null,"source":null,"page":null,"status":"draft"},
{"n":68,"ar":"اَللّٰهُمَّ اغْفِرْ لِيْ وَلِلْمُؤْمِنِيْنَ وَالْمُؤْمِنَاتِ وَالْمُسْلِمِيْنَ وَالْمُسْلِمَاتِ الْأَحْيَآءِ مِنْهُمْ وَالْأَمْوَاتِ، وَلِإِخْوَانِنَا الَّذِيْنَ سَبَقُوْنَا بِالْإِيْمَانِ، وَلَا تَجْعَلْ فِيْ قُلُوْبِنَا غِلًّا لِّلَّذِيْنَ اٰمَنُوْا رَبَّنَآ إِنَّكَ رَءُوْفٌ رَّحِيْمٌ.","tr":"Allāhumma ghfir lī wa li l-muʾminīna wa l-muʾmināti wa l-muslimīna wa l-muslimāti l-aḥyāʾi minhum wa l-amwāt, wa li ikhwāninā lladhīna sabaqūnā bi l-īmān, wa lā tajʿal fī qulūbinā ghillan li lladhīna āmanū, rabbanā innaka raʾūfun raḥīm.","en":"O Allah, forgive me and the believing men and women and the Muslim men and women, the living among them and the dead. The rest, from «and our brothers who came before us in faith…», is al-Hashr 59:10: Qurʾān translation from Pickthall.","ref":"the second half adapts al-Hashr 59:10. The mushaf reads «رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالْإِيمَانِ وَلَا تَجْعَلْ فِي قُلُوبِنَا غِلًّا لِّلَّذِينَ آمَنُوا رَبَّنَا إِنَّكَ رَءُوفٌ رَّحِيمٌ». Nomani quotes from «وَلِإِخْوَانِنَا» to the end, joined to the opening du'a.","q":null,"source":null,"page":null,"status":"draft"},
{"n":69,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ عَبْدِكَ وَنَبِيِّكَ وَرَسُوْلِكَ النَّبِيِّ الْأُمِّيِّ وَعَلٰىٓ اٰلِهٖ وَصَحْبِهٖ وَسَلِّمْ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadin ﷺ ʿabdika wa nabiyyika wa rasūlika n-nabiyyi l-ummiyyi wa ʿalā ālihī wa ṣaḥbihī wa sallim.","en":"O Allah, send blessings on our master Muhammad ﷺ, Your servant, Your Prophet and Your Messenger, the unlettered Prophet, and on his family and Companions, and grant them peace.","ref":null,"q":null,"source":"al-Qawl al-Badiʿ* (al-Khatib), from Anas. This is the salawat for Friday.","page":null,"status":"draft"},
{"n":70,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ كُلَّمَا ذَكَرَهُ الذَّاكِرُوْنَ، وَصَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ كُلَّمَا غَفَلَ عَنْ ذِكْرِهِ الْغَافِلُوْنَ.","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadin ﷺ kullamā dhakarahu dh-dhākirūn, wa ṣalli ʿalā sayyidinā Muḥammadin ﷺ kullamā ghafala ʿan dhikrihi l-ghāfilūn.","en":"O Allah, send blessings on our master Muhammad ﷺ whenever those who remember mention him, and send blessings on our master Muhammad ﷺ whenever the heedless neglect to mention him.","ref":null,"q":null,"source":"al-Qawl al-Badiʿ*, from Imam al-Shafiʿi.","page":null,"status":"draft"},
{"n":71,"ar":"اَللّٰهُمَّ صَلِّ عَلٰى سَيِّدِنَا مُحَمَّدٍ ﷺ عَبْدِكَ وَرَسُوْلِكَ النَّبِيِّ الْأُمِّيِّ الَّذِيْٓ اٰمَنَ بِكَ وَبِكِتَابِكَ، وَأَعْطِهٖ أَفْضَلَ رَحْمَتِكَ، وَاٰتِهِ الشَّرَفَ عَلٰى خَلْقِكَ يَوْمَ الْقِيٰمَةِ، وَاجْزِهٖ خَيْرَ الْجَزَآءِ، وَالسَّلَامُ عَلَيْهِ وَرَحْمَةُ اللّٰهِ وَبَرَكَاتُهٗ.\n﴿سُبْحٰنَ رَبِّكَ رَبِّ الْعِزَّةِ عَمَّا يَصِفُوْنَ ۝ وَسَلٰمٌ عَلَى الْمُرْسَلِيْنَ ۝ وَالْحَمْدُ لِلّٰهِ رَبِّ الْعٰلَمِيْنَ﴾\nتَمَّتْ","tr":"Allāhumma ṣalli ʿalā sayyidinā Muḥammadin ﷺ ʿabdika wa rasūlika n-nabiyyi l-ummiyyi lladhī āmana bika wa bi kitābik, wa aʿṭihī afḍala raḥmatik, wa ātihi sh-sharafa ʿalā khalqika yawma l-qiyāmah, wa jzihī khayra l-jazāʾ, wa s-salāmu ʿalayhi wa raḥmatu llāhi wa barakātuh. — Subḥāna rabbika rabbi l-ʿizzati ʿammā yaṣifūn, wa salāmun ʿala l-mursalīn, wa l-ḥamdu lillāhi rabbi l-ʿālamīn.","en":"O Allah, send blessings on our master Muhammad ﷺ, Your servant and Messenger, the unlettered Prophet, who believed in You and in Your Book. Give him the best of Your mercy, give him honour above Your creation on the Day of Resurrection, and reward him with the best reward. Peace be on him, and the mercy of Allah and His blessings. — For the verses, use the Qurʾān translation from Pickthall.","ref":"the closing verses are al-Saffat 37:180–182, in full and in standard wording.","q":null,"source":"the note says the first half was traced above. Nomani names no source for the second half.","page":null,"status":"draft"}]}];
export const manzilDuas = n => HIZB[n - 1]?.duas || [];
